\section{Additional Proofs}\label{sec:proofglobal}
The proof of \Thm{globalconverge} (ii) and \Thm{locallinear} follow arguments in \cite{Wen2018APD}, with the main distinction being that our arguments are built around the induced norm $\|\cdot\|_H$. 
\subsection{Proof of \Thm{globalconverge} (ii)}
\begin{proof}
We note that $E(x^k, x^{k-1})$ is the same as $E_k$ which we defined earlier, so that it converges to $\zeta = \lim_{{k\rightarrow \infty}} f(x^k)$. In the meantime, it is not hard to see that the set of accumulation points sequence $\{(x^k,x^{k-1})\}$ is $\Omega\times\Omega$, where 
$\Omega$ is defined in \Prop{constantcluster}. Consider any $\hat{x}\in \Omega$, we have $E(\hat{x},\hat{x}) = f(\hat{x}) =\zeta$. Thus $E(x,y)\equiv\zeta$ on $\Omega\times \Omega$. 

Next, due to \Thm{subsequenceconverge}, we only need to show that $\{x^k\}$ is a convergent sequence. We first remark on an edge case where $E(x^k,x^{k-1})=\zeta$ for some finite $\bar{k}$. Since $E(x^k,x^{k-1})$ is non-decreasing and convergent to $\zeta$, we conclude that for any $k\ge \bar{k}$, $E(x^k,x^{k-1})=\zeta$, and $x^k = x^{\bar{k}}$ for any $k\ge \bar{k}$.

Next, we consider the case where $E(x^k,x^{k-1})>\zeta$ for all $k$. Under \As{bound}, we know that all level sets of $f$ are bounded, then we have
\begin{eqnarray*}
f(x^k) & \le & f(x^k)+\frac{1}{2}\|x^k-x^{k-1}\|_H^2\le f(x^1)+\frac{1}{2}\|x^1-x^{0}\|_H^2 =  f(x^1),
\end{eqnarray*}
which allows us to conclude that the sequence $\{x^k\}$ is bounded. Then, the set of accumulation points $\Omega$ is compact. Due to \Lem{uniformKL}, there exists $\epsilon,a>0$, and a concave continuous function $\phi$ such that 
\begin{eqnarray*}
\phi'(E(x,y)-\zeta)\text{dist} ((0,0),\partial E(x,y)) & \ge & 1, 
\end{eqnarray*}
for all $(x,y)\in U$, where
\begin{eqnarray*}
U = \{(x,y) \in \Real^n \times \Real^n| \text{dist}((x,y),\Omega\times \Omega)<\epsilon\}\cap \{(x,y) \in \Real^n \times \Real^n|\zeta<E(x,y)<\zeta+a\}.
\end{eqnarray*}
Using the fact that $\{x^k\}$ is bounded and $\Omega\times \Omega$ is the set of accumulation points of $(x^k,x^{k-1})$, we have $\lim_{{k\rightarrow \infty}} \text{dist}((x^k,x^{k-1}),\Omega\times\Omega)=0$. Additionally, $E(x^k,x^{k-1})$ is non-increasing and convergent to $\zeta$. Thus there exists $k_0$ such that for all $k\ge k_0$, we have $(x^k,x^{k-1})\in U$. so that
\begin{eqnarray*}
\forall k\ge k_0, && \phi'(E(x^k,x^{k-1})-\zeta)\text{dist}((0,0),\partial E(x^k,x^{k-1})) \ge 1.
\end{eqnarray*}
Using the concavity of $\phi$, we have for any $k\ge k_0$, 
\begin{align*}
&[(\phi (E(x^k,x^{k-1})-\zeta)-(\phi (E(x^{k+1},x^{k})-\zeta)]\text{dist}((0,0),\partial E(x^k,x^{k-1}))\\
&\ge\phi' (E(x^k,x^{k-1})-\zeta) \text{dist}((0,0),\partial E(x^k,x^{k-1})) [E(x^k,x^{k-1})-E(x^{k+1},x^{k})]\\
& \ge E(x^k,x^{k-1})-E(x^{k+1},x^{k})
\end{align*}
Due to \Eqn{diffofE}, there exists a positive number $D$ such that
\begin{eqnarray*}
E(x^k,x^{k-1})-E(x^{k+1},x^{k}) &\ge& D \|x^k -x^{k-1}\|_H^2, 
\end{eqnarray*}
then we have
\begin{align*}
\|x^k -x^{k-1}\|_H^2 \le \frac{C}{D}(\phi (E(x^k,x^{k-1})-\zeta)-(\phi (E(x^{k+1},x^{k})-\zeta)) (\|x^k - x^{k-1}\|_H+\|x^{k-1}-x^{k-2}\|_H)
\end{align*}
Taking square roots on both sides and using the AM-GM inequality, we have
\begin{eqnarray*}
\|x^k -x^{k-1}\|_H &\le & \sqrt{\frac{2C}{D}(\phi (E(x^k,x^{k-1})-\zeta)-(\phi (E(x^{k+1},x^{k})-\zeta))}\\
&&\cdot\sqrt{\frac{\|x^k - x^{k-1}\|_H+\|x^{k-1}-x^{k-2}\|_H}{2}}\\
& \le &\frac{C}{D}(\phi (E(x^k,x^{k-1})-\zeta)-(\phi (E(x^{k+1},x^{k})-\zeta))\\&&+\frac{\|x^k - x^{k-1}\|_H+\|x^{k-1}-x^{k-2}\|_H}{4},
\end{eqnarray*}
so that
\begin{eqnarray*}
\frac{1}{2} \|x^k -x^{k-1}\|_H  &\le  \frac{C}{D}(\phi (E(x^k,x^{k-1})-\zeta)-(\phi (E(x^{k+1},x^{k})-\zeta))\\
&+ \frac{1}{4} (\|x^{k-1}-x^{k-2}\|_H -\|x^{k}-x^{k-1}\|_H),
\end{eqnarray*}
which implies that 
\begin{eqnarray*}
\sum_{k=k_0}^\infty \| x^k - x^{k-1}\|_H & \le & \frac{2C}{D}\phi (E(x^{k_0},x^{{k_0}-1})-\zeta) + \frac{1}{2}\|x^{{k_0}-1}-x^{{k_0}-2}\|_H< \infty,
\end{eqnarray*}
which implies the convergence of $x^k$. 
\end{proof}
\subsection{Proof of \Thm{locallinear}}\label{sec:locallinear}
\begin{proof}
Following the proof of \Thm{globalconverge} (ii), denote $\sum_{i=k}^\infty \| x^{i+1}- x^{i}\|_H$ as $S_k$,   for any $k\ge k_0$ we have
\begin{eqnarray}\label{eq:Strelation}
S_k \le S_{k-1}& \le & \frac{2C}{D}\phi (E(x^{k},x^{{k}-1})-\zeta) + \frac{1}{2}\|x^{{k}-1}-x^{{k}-2}\|_H \nonumber \\
& =  &\frac{2C}{D}\phi (E(x^{k},x^{{k}-1})-\zeta) +  \frac{1}{2} (S_{k-2}-S_{k-1}) \nonumber\\
& \le & \frac{2C}{D}\phi (E(x^{k},x^{{k}-1})-\zeta) +  \frac{1}{2} (S_{k-2}-S_{k})
\end{eqnarray}
Using the KL inequlaity for $E(x,y)$, we have
\begin{eqnarray*}
 \frac{1}{\sqrt{2\mu_E}} (E(x^{k},x^{{k}-1})-\zeta)^{-1/2}\text{dist}((0,0),\partial E(x^k,x^{k-1})) &\ge & 1.
\end{eqnarray*}
Due to \Eqn{distancebound}, for sufficiently large $k$,
\begin{eqnarray*}
\text{dist}((0,0),\partial E(x^k,x^{k-1}))&\le& C(S_{k-2}-S_{k}),
\end{eqnarray*}
thus, for sufficiently large $k$,
\begin{eqnarray*}
(E(x^{k},x^{{k}-1})-\zeta)^{1/2} & \le &\frac{1}{\sqrt{2\mu_E}} \cdot C \cdot (S_{k-2}-S_{k}).
\end{eqnarray*}
Plugging into \Eqn{Strelation}, recall that the KL function is \(\phi(s) = \frac{\sqrt{2}}{\sqrt{\mu_E}} s^{1/2}\), so that for sufficiently large $k$, 
\begin{eqnarray*}
S_k & \le & \frac{2C^2}{D\mu_E} (S_{k-2}-S_{k}) + S_{k-2}-S_{k} = (\frac{2C^2}{D\mu_E}+1)( S_{k-2}-S_{k}),
\end{eqnarray*}
Let $C_1 = \frac{2C^2}{D\mu_E}$, there exists $k_1>0$ such that for all $k\ge k_1$
\begin{eqnarray*}
S_k & \le & \frac{C_1+1}{C_1+2} S_{k-2},
\end{eqnarray*}
Then for all $k\ge k_1$
\begin{eqnarray*}
\|x^k - \bar{x}\|_H \le \sum_{i=k}^\infty \|x^{k+1} - x^k\|_H = S_{k}&\le &S_{k_1-2}\left(\sqrt{\frac{C_1+1}{C_1+2}}\right)^{k-k_1+1},
\end{eqnarray*}
so that
\begin{eqnarray*}
\|x^k - \bar{x}\| & \le & \frac{S_{k_1-2}}{\sqrt{\sigma_{\min}(H)}}\left(\sqrt{\frac{C_1+1}{C_1+2}}\right)^{k-k_1+1}.
\end{eqnarray*}

\end{proof}
\section{Generalization to Composite Optimization}
In this section, we generalize the QMME framework to minimize composite functions of the form $F(x) = f(x)+g(x)$. $f(x)$ satisfies the same assumptions we make for smooth optimization, while $g(x)$ is lower semicontinuous and convex but possibly non-smooth. QMME for minimizing $F(x)$ proceeds via the following iterations:
\begin{eqnarray}\label{eq:MMextrapolate2}
y^k & = &x^k + \beta_k (x^k - x^{k-1}),\nonumber\\
x^{k+1} & = &\underset{x\in \Real^n}{\text{argmin}} \quad \langle \nabla f(y^k) , x\rangle +\frac{1}{2}\| y^k - x \|_H^2 + g(x).
\end{eqnarray}
The update in \Eqn{MMextrapolate2} corresponds to a generalized proximal operator, and the resulting QMME scheme is closely related to proximal Newton methods \citep{lee2014proximal}. Evaluating this generalized proximal operator is generally nontrivial and typically requires an iterative subroutine, such as coordinate descent for $\ell_1$-penalized generalized linear models \citep{friedman2010regularization}. 

Although the algorithm and theory developed for \Eqn{MMextrapolate} generalize to the composite case, the practical advantages of QMME over classical proximal Newton methods warrant further investigation. In particular, the use of a quadratic surrogate with fixed curvature matrix $H$ in \Eqn{MMextrapolate2} may not lead to substantially cheaper iterations compared to directly using the original Hessian. However, the QMME framework may enjoy more robust convergence. We leave the empirical comparison between QMME and Proximal-Newton as future work. In what follows, we sketch the convergence analysis, highlighting only the components that differ from the smooth setting.

Unlike smooth optimization, the optimal set $\mathcal{X}$ changes to $\{x\in \Real^n|0\in \nabla f(x)+\partial g(x)\}$. The statement and proof for \Lem{strongconvexity} need to be adapted as follows:
\begin{lemma}
We have for any $z\in \Real^n$,
\begin{eqnarray}\label{eq:strongconvexity2}
&& \langle \nabla f(y^k),x^{k+1}\rangle + \frac{1}{2} \| y^k - x^{k+1} \|_H^2  + g(x^{k+1}) +\frac{1}{2} \| z - x^{k+1} \|_H^2    \nonumber\\& \le & \langle \nabla f(y^k) , z\rangle +\frac{1}{2}\| y^k - z \|_H^2 + g(z).
\end{eqnarray}
\end{lemma}

\begin{proof}
Due the optimality condition of minimization problem \Eqn{MMextrapolate2}, we have
\begin{eqnarray*}
0 \in \nabla f (y^k) + H(x^{k+1} - y^k) + \partial g(x^{k+1}),
\end{eqnarray*}
in other words there exists $v\in \partial g(x^{k+1})$ such that
\begin{eqnarray*}
\nabla f (y^k) + H(x^{k+1} - y^k) + v = 0.
\end{eqnarray*}
Using the subgradient inequality for $g$ at $x^{k+1}$, we have
\begin{eqnarray*}
g(z) &\ge & g(x^{k+1}) + \langle v, z - x^{k+1}).
\end{eqnarray*}
Sustitute $v = - \nabla  f (y^k) - H(x^{k+1} - y^k)$ into the inequality gives us 
\begin{eqnarray}\label{eq:subgrad}
g(z) \ge g(x^{k+1}) + \langle - \nabla  f (y^k) - H(x^{k+1} - y^k), z - x^{k+1})
\end{eqnarray}
Adding \Eqn{subgrad} and \Eqn{expand} gives us 
\begin{eqnarray}\label{eq:rearrange2}
g(z) + \frac{1}{2}\|y^k -z\|_H^2 & \ge & g(x^{k+1}) + \langle - \nabla  f (y^k), z - x^{k+1}\rangle + \frac{1}{2} \| y^k - x^{k+1} \|_H^2\\&& + \frac{1}{2}\| x^{k+1}-z\|_H^2. \nonumber
\end{eqnarray}
Rearranging terms of \Eqn{rearrange2} gives us exactly \Eqn{strongconvexity2}. 
\end{proof}
The auxillary sequence $E_k$ should now be defined as $E_k = F(x^k)+\frac{1}{2} \|x^k - x^{k-1}\|_H^2$ and we can prove \Lem{aux} simply by replacing $f(x)$ with $F(x)$ in \Eqn{boundnext}, \Eqn{boundf},\Eqn{difff},\Eqn{diffofE}. In the statement of \Thm{subsequenceconverge}, $f$ should be replaced with $F$. The proof of  (ii) is now:
\begin{proof}
Due to the optimality condition of \Eqn{MMextrapolate2}, we have
\begin{eqnarray*}
0 \in \nabla f(y^{k_i}) + H (x^{k_i+1} - y^{k_i}) + \partial g(x^{k_i+1}). 
\end{eqnarray*}
Combined with the definition of $y^{k_i}$, we have
\begin{eqnarray*}
-H (x^{k_i+1} - x^{k_i}-\beta_k (x^{k_i} - x^{k_i-1})) & \in & \nabla f(y^{k_i}) + \partial g(x^{k_i+1})
\end{eqnarray*}
Taking $i$ to the limit, due to the Lipschitz continuity of $\nabla f$ and the closedness of the multifunction $\partial g$ (see page 80, Exercise 8 of \cite{jonathan2006convex}), we have
\begin{eqnarray*}
0 &\in& \nabla f(\bar{x}) + \partial g(\bar{x}). 
\end{eqnarray*}
Thus, any accumulation point of $\{x^k\}$ is a stationary point for $F$.
\end{proof}
Similarly, $f$ should become $F$ in \Prop{constantcluster} and the proof of (ii) becomes slightly more involved.
\begin{proof}
For any $\hat{x}\in \Omega$, there is a subsequence $\{x^{k_i}\}$ such that $x^{k_i}\rightarrow \hat{x}$. Since $x^{k_i+1}$ is the minimizer of \Eqn{MMextrapolate}, one has
\begin{eqnarray}\label{eq:minimizer}
&&g(x^{k_i}) + \langle \nabla f(y^{k_i-1}), x^{k_i}\rangle  + \frac{1}{2}\|x^{k_i} - y^{k_i-1}\|_H^2\\&\le& g(\hat{x}) + \langle \nabla f(y^{k_i-1}), \hat{x}\rangle  + \frac{1}{2}\|\hat{x} - y^{k_i-1}\|_H^2. \nonumber
\end{eqnarray}
We note that due to \Thm{subsequenceconverge}, $x^{k_i} - y^{k_i-1} = x^{k_i}- x^{k_i-1} - \beta^{k_i-1}(x^{k_i-1}- x^{k_i-2}) \rightarrow 0$, and $\hat{x} - y^{k_i-1} = \hat{x}- x^{k_i-1} - \beta^{k_i-1}(x^{k_i-1}- x^{k_i-2}) \rightarrow 0$. Taking $i$ to infinity on both sides of \Eqn{minimizer} gives us
\begin{eqnarray*}\label{eq:minimizer2}
\zeta & = & \underset{i\rightarrow \infty}\lim f(x^{k_i})+ g(x^{k_i})\\
      & = & \underset{i\rightarrow \infty}\lim f(x^{k_i})+ g(x^{k_i}) + \langle \nabla f(y^{k_i-1}), x^{k_i}-\hat{x}\rangle  + \frac{1}{2}\|x^{k_i} - y^{k_i-1}\|_H^2\\
      & \le & \underset{i\rightarrow \infty}\limsup f(x^{k_i}) + g(\hat{x}) +  \frac{1}{2}\|\hat{x} - y^{k_i-1}\|_H^2 = F(\hat{x}) \le\underset{i\rightarrow \infty}\liminf F(x^{k_i}) = \zeta.
\end{eqnarray*}
where the first inequality follows from the \Eqn{minimizer} and the second inequality follows from the lower semicontinuity of $F$. 
\end{proof}
Finally, for \Thm{globalconverge}, $f$ should again be replaced with $F$. The proof sketch is given as follows:
\begin{proof}
To establish the result, we need to change the definition of $E(x,y)$ to $E(x,y) = F(x)+\frac{1}{2}\|x-y\|_H^2+g(x)$. Then $\partial E(x^k, x^{k-1}) = (\nabla f(x^k)+H(x^k-x^{k-1})+\partial g(x^k), - H(x^k - x^{k-1}))$. Using the optimality condition of \Eqn{MMextrapolate2} we have
\begin{eqnarray*}
0 &\in &\nabla f(y^{k-1}) + H (x^{k} - y^{k-1}) + \partial g(x^{k}). 
\end{eqnarray*}
so that
\begin{eqnarray*}
 (\nabla f(x^k) - \nabla f(y^{k-1}) -H(x^{k-1}-y^{k-1}), - H(x^k - x^{k-1}) ) & \in & \partial E(x^k,x^{k-1}).
\end{eqnarray*}
The remaining parts of the proof are nearly identical.
\end{proof}

