	\begin{definition}[Monotone induction]\label{def:MonInduction}
		Let $\imcons$ be a monotone operator on a cpo $\CS$ then a \emph{monotone induction} is an increasing sequence $(x_i)_{i\leq\beta}$ satisfying 
		\begin{compactitem}
			\item $x_i \leq x_{i+1}\leq \imcons(x_i)$ , for successor ordinals $i+1\leq \beta$,
			\item $x_\lambda=\lub(\{x_i\mid i<\lambda\})$, for limit ordinals $\lambda\leq \beta$  (in particular, $x_0=\bot$).
		\end{compactitem}
	\end{definition}
	%We say a monotone induction $(x_i)_{i\leq\beta}$ is the fastest if for every successor ordinal $i+1 \leq \beta$, $x_{i+1} = \imcons(x_i)$. 
	A monotone induction is terminal if its limit can not be refined further, i.e., if the limit is a prefixpoint of $\imcons$. %Note that the fastest monotone induction is terminal and i
	It has been shown that all terminal monotone inductions converge to the same limit \cite[Corollary 3.7]{ai/BogaertsVD18}. 
	%\bart{Ik zou die discussi over ``the fastests'' weglaten. Er zijn heel veel fastest inudctions, met een andere $\beta$. Die zijn niet allemaal terminal (enkel als beta groot genoeg is). }
	\begin{theorem}[Knaster-Tarski theorem \cite{Tarski}]
		Given a cpo $\CS = \langle \cpo, \leq \rangle$, if $\imcons$ is a monotone operator on $\CS$, then $\imcons$ has a least fixpoint. In particular, the least fixpoint of $\imcons$ is the least pre-fixpoint of $\imcons$ and can be constructed as the limit of a terminal monotone induction of $\imcons$.
	\end{theorem}

	The Knaster-Tarski theorem provides a constructive way to obtain the least fixpoint of a monotone operator, \AFT generalizes this theorem to non-monotonic operators by using approximations. Given that $\CS$ is a complete lattice, we can construct the bilattice $\AbS = \langle \cpo^2, \leqp \rangle$% is the \emph{approximation space}
	, where for every $x_1, x_2, y_1, y_2 \in \CS$, $(x_1, x_2) \leqp (y_1, y_2)$ iff $x_1 \leq y_1$ and $y_2 \leq x_2$. It is easy to see that $\leqp$ is a partial order. In natural language we call this order the \emph{precision order}. Similarly, we define the \emph{truth order} $\leqt$ such that for every $x_1, x_2, y_1, y_2 \in \CS$, $(x_1, x_2) \leqt (y_1, y_2)$ if $x_1 \leq y_1$ and $x_2 \leq y_2$. Since we focus on consistent \AFT \cite{DeneckerMT04}, which is in general more natural and provides sufficient expressiveness, we use the consistent subspace\footnote{To limit the the number of symbols, we will in often use the same symbol for an order projected on a subspace, here $\leqp$ is used as a binary relation on the consistent subspace as well as the bigger bilattice.} $\AbS^c = \langle \cpo^c, \leqp \rangle$, where $\cpo^c = \{(x_1, x_2) \in \cpo^2 \mid x_1 \leq x_2\}$.

	\begin{definition}[Approximating Operator (Approximator)]
		%Let $\AbS$ be an approximation space, then $\aop: \AbS \to \AbS$ is an \emph{approximating operator} if $\aop$ is $\leqp$-monotone. We denote the set of approximating operators on an approximation space $\AbS$ by $\appr$.
		An operator $\aop: \AbS^c \to \AbS^c$ is an \emph{approximating operator} if $\aop$ is $\leqp$-monotone. We denote the set of approximating operators on  $\AbS^c$ by $\appr[{\AbS^c}]$. We will often use the shorted term \emph{approximator} instead of approximating operator.
	\end{definition}
%	\bart{Het is wat verwarrend dat je in de prelims al over ``an approximation space'' spreekt. Dat is nog niet echt gedefinieerd; je hebt daar precies twee voorbeelden van gegeven. 
%	Ik zou hier gewoon spreken over een approximator $A: C^c\to C^c$}

	We call any $(x_1, x_2) \in \AbS^c$ an \emph{approximant}, and we say that an approximant $(x_1, x_2)$ approximates an element $y \in \CS$ if $x_1 \leq y \leq x_2$. An approximant $(x_1, x_2) \in \AbS^c$ is exact if it approximates exactly one element, \ie if $x_1 = x_2$. An approximator $\aop$ approximates an operator $\imcons: \CS \to \CS$ if for every $(x_1, x_2) \in \AbS^c$ and $y \in \CS$, $\imcons(y)$ is approximated by $\aop(x_1, x_2)$ whenever $y$ is approximated by $(x_1, x_2)$. An approximator $\aop[1]$ is \emph{less precise} than an approximator $\aop[2]$, denoted by $\aop[1] \leqp \aop[2]$, if for every approximant $(x_1, x_2)$, $\aop[1](x_1, x_2) \leqp \aop[2](x_1, x_2)$. The most precise approximator $\ult[\imcons]$ which approximates an operator $\imcons$ is called the \emph{ultimate approximator}\footnote{When the operator is clear from the context, we will drop the subscript-notation.} of $\imcons$ and is given by $\ult[\imcons](x_1, x_2) = (\glb_{\CS}\{\imcons(y) \mid y \in [x_1, x_2]\}, \lub_{\CS}\{\imcons(y) \mid y \in [x_1, x_2]\})$, where $[x_1, x_2] = \{y \in \CS \mid x_1 \leq y \leq x_2\}$.

	\begin{definition}[Stable Revision Operator]
		Let $\aop$ be an approximator, then the \emph{stable revision operator} is given by $\sto: \AbS^c \to \AbS^c$ which maps any $(x_1, x_2) \in \AbS^c$ to $(\lfp(\aoplx{x}), \lfp(\aopux{x}))$, where $\aoplx{x}(y_1)$ is the projection of $\aop(y_1, x_2)$ on its first component and $\aopux{x}(y_2)$ is the projection of $\aop(x_1, y_2)$ on its second component.
		%\bart{$x_2$ wordt plots $x^2$}
	\end{definition}

	Given an approximator $\aop$, we say an approximant $(x_1, x_2)$ is $\aop$-reliable if $(x_1, x_2) \leqp \aop(x_1, x_2)$. Moreover, $(x_1, x_2)$ is $\aop$-prudent if $x_1 \leq \lfp(\aoplx{x})$. The following theorem summarizes an important result for the subspace of $\aop$-reliable and $\aop$-prudent elements of $\AbS^c$.

	\begin{theorem}[\cite{DeneckerMT04} Theorem 3.11]
		Let $\AbS^c = \langle \cpo^c, \leqp \rangle$ be a consistent approximation space with approximator $\aop$. The set of $\aop$-reliable and $\aop$-prudent elements of $\AbS^c$ is a cpo under the precision order $\leqp$ with least element $(\bot, \top)$. The stable revision operator is a well-defined, increasing and monotone operator in this poset.
	\end{theorem}

	Since $\aop$ is $\leqp$-monotone on $\AbS^c$, it has a least (precise) fixpoint, this is the \emph{Kripke-Kleene fixpoint} of $\aop$, denoted by $\KK(\aop)$. The set of \emph{supported fixpoints} of $\aop$, denoted by $\SUP(\aop)$, is defined as $\{x \in \CS \mid \aop(x, x) = (x, x)\}$, \ie the exact fixpoints of $\aop$. Similarly, $\sto$ is $\leqp$-monotone on the set of $\aop$-reliable and -prudent elements of $\AbS^c$. Therefore, it has a least (precise) fixpoint in that space, \ie the \emph{Well-founded fixpoint} of $\aop$, denoted by $\WF(\aop)$. The set of \emph{$\aop$-stable fixpoints}, denoted by $\ST(\aop)$, is defined as $\{x \in \CS \mid \sto(x, x) = (x, x)\}$, \ie the exact fixpoints of $\sto$. In many case, e.g., in the case of logic programming, these fixpoints correspond to the eponymous semantics. In other words, for any non-monotonic reasoning formalism we can determine the Kripke-Kleene, supported, Well-founded and stable semantics for free once we have defined a suitable approximator. Usually this approximator naturally follows from the application. 

