\begin{thm}
A kernel $K$ satisfies \eqref{eq:a1} if and only if it factors as
\[
K\left(s,t\right)\left(a\right)=V\left(s\right)^{*}\pi\left(a\right)V\left(t\right),
\]
for all $s,t\in X$ and $a\in\mathfrak{A}$, where $V\left(t\right)\colon H\rightarrow\mathscr{L}$
is an operator from $H$ into some Hilbert space $\mathscr{L}$, and
$\pi\colon\mathfrak{A}\rightarrow L\left(\mathscr{L}\right)$ is a
representation of $\mathfrak{A}$. 

Moreover, if $\mathscr{L}$ is minimal, i.e., 
\[
\mathscr{L}=\overline{span}\left\{ \pi\left(a\right)V\left(t\right)u:a\in\mathfrak{A},t\in X,u\in H\right\} 
\]
then $\mathscr{L}\simeq H_{\tilde{K}}$, and so $\mathscr{L}$ is
unique up to unitary equivalence.
\end{thm}

\begin{proof}
Let $K$, $\tilde{K}$ and $H_{\tilde{K}}$ be as above. For each
$t\in X$, let $V\left(t\right)\colon H\rightarrow H_{\tilde{K}}$
be the operator 
\[
v\mapsto V\left(t\right)v=\tilde{K}_{\left(t,1_{\mathfrak{A}},v\right)}.
\]
By \eqref{eq:a4}, $V\left(t\right)$ is linear and 
\begin{eqnarray*}
\left\Vert V\left(t\right)v\right\Vert _{H}^{2} & = & \left\langle \tilde{K}_{\left(t,1_{\mathfrak{A}},v\right)},\tilde{K}_{\left(t,1_{\mathfrak{A}},v\right)}\right\rangle _{H}\\
 & \underset{\left(\ref{eq:2}\right)}{=} & \left\langle v,K\left(t,t\right)\left(1_{\mathfrak{A}}\right)v\right\rangle _{H}<\infty.
\end{eqnarray*}

Since 
\begin{eqnarray*}
\left\langle V\left(t\right)v,\tilde{K}_{\left(s,a,u\right)}\right\rangle _{H_{\tilde{K}}} & = & \left\langle \tilde{K}_{\left(t,1_{\mathfrak{A}},v\right)},\tilde{K}_{\left(s,a,u\right)}\right\rangle _{H_{\tilde{K}}}\\
 & = & \left\langle v,K\left(t,s\right)\left(a\right)u\right\rangle _{H}
\end{eqnarray*}
and $\left\{ \pi\left(a\right)V\left(t\right)u:a\in\mathfrak{A},t\in X,u\in H\right\} $
is dense in $H_{\tilde{K}}$ (by definition \eqref{eq:a3}), it follows
that 
\begin{equation}
V\left(t\right)^{*}\tilde{K}_{\left(s,a,u\right)}=K\left(t,s\right)\left(a\right)u\label{eq:4}
\end{equation}
for all $s,t\in X$, $a\in\mathfrak{A}$, $u\in H$.

Let $\pi\colon\mathfrak{A}\rightarrow H_{\tilde{K}}$ be the map 
\begin{equation}
\pi\left(a\right)\tilde{K}_{\left(t,b,v\right)}=\tilde{K}_{\left(t,ab,v\right)},\label{eq:5}
\end{equation}
for all $t\in X$, $a,b\in\mathfrak{A}$, $v\in H$, extended to all
$H_{\tilde{K}}$. It is clear that $\pi$ is a representation of $\mathfrak{A}$
in $H_{\tilde{K}}$. Indeed, 
\begin{align*}
\left\langle \tilde{K}_{\left(s,c,u\right)},\pi\left(a\right)\tilde{K}_{\left(t,b,v\right)}\right\rangle _{H_{\tilde{K}}} & =\left\langle u,K\left(s,t\right)\left(c^{*}ab\right)v\right\rangle _{H}\\
 & =\left\langle u,K\left(s,t\right)\left(\left(a^{*}c\right)^{*}b\right)v\right\rangle _{H}\\
 & =\left\langle \tilde{K}_{\left(s,a^{*}c,u\right)},\tilde{K}_{\left(t,b,v\right)}\right\rangle _{H_{\tilde{K}}}\\
 & =\left\langle \pi\left(a^{*}\right)\tilde{K}_{\left(s,c,u\right)},\tilde{K}_{\left(t,b,v\right)}\right\rangle _{H_{\tilde{K}}}
\end{align*}
so that $\pi\left(a\right)^{*}=\pi\left(a^{*}\right)$. 

Finally, one checks that 
\begin{eqnarray*}
V\left(s\right)^{*}\pi\left(a\right)V\left(t\right)u & = & V\left(s\right)^{*}\pi\left(a\right)\tilde{K}_{\left(t,1_{\mathfrak{A}},v\right)}\\
 & \underset{\left(\ref{eq:5}\right)}{=} & V\left(s\right)^{*}\tilde{K}_{\left(t,a,v\right)}\\
 & \underset{\left(\ref{eq:4}\right)}{=} & K\left(s,t\right)\left(a\right)v.
\end{eqnarray*}

The rest of the theorem follows from standard arguments in the literature,
and the details are omitted here. 
\end{proof}

\section{A partial order on operator-kernel spaces, and its use in an analysis
of families of non-commuting kernels}

The set $\mathcal{M}$ carries a natural partial order: 
\begin{defn}
For two kernels $K,L$ in $\mathcal{M}$, it is said that $L$ dominates
$K$, or $K\leq L$, if $L-K\in\mathcal{M}$. 
\end{defn}

\begin{thm}
\label{thm:4}Let $K,L\in\mathcal{M}$, such that
\begin{align*}
K\left(s,t\right)\left(a\right) & =V_{K}^{*}\left(s\right)\pi_{K}\left(a\right)V_{K}\left(t\right)\\
L\left(s,t\right)\left(a\right) & =V_{L}^{*}\left(s\right)\pi_{L}\left(a\right)V_{L}\left(t\right).
\end{align*}
Then $K\leq L$ if and only if there is a positive operator $A\colon H_{\tilde{L}}\rightarrow H_{\tilde{L}}$,
$0\leq A\leq I_{H_{\tilde{L}}}$, such that $A\in\pi_{L}\left(\mathfrak{A}\right)'$,
and 
\begin{equation}
K\left(s,t\right)\left(a\right)=V_{L}^{*}\left(s\right)\pi_{L}\left(a\right)AV_{L}\left(t\right).\label{eq:7}
\end{equation}
\end{thm}

\begin{proof}
The identify \eqref{eq:7} follows from a basic fact for scalar-valued
kernels (see, e.g., \cite{MR0051437,MR24065}). Recall that for $K,L:X\times X\rightarrow\mathbb{C}$
p.d., $K\leq L\Longleftrightarrow L-K\geq0$, which is equivalent
to $H_{K}\subset H_{L}$, where the containment of the respective
RKHSs is contractive. In particular, the map $T\colon L\left(\cdot,t\right)\mapsto K\left(\cdot,t\right)\in H_{K}\subset H_{L}$
extends by density to a positive operator on $H_{L}$, with $0\leq T\leq I_{H_{L}}$. 

Now apply this to $\tilde{K}$ and $\tilde{L}$: By assumption, $\tilde{K}\leq\tilde{L}$
as scalar-valued kernels. Therefore, the map
\[
T:\tilde{L}_{\left(t,a,v\right)}\mapsto\tilde{K}_{\left(t,a,v\right)}\in H_{\tilde{K}}\subset H_{\tilde{L}}
\]
extends to a positive operator in $H_{\tilde{L}}$ with $0\leq T\leq I_{H_{\tilde{L}}}$.
Note that $\pi_{K}=\pi_{L}\big|_{H_{\tilde{K}}}$, and so 
\begin{align*}
T\pi_{L}\left(a\right)V_{L}\left(t\right)v & =T\tilde{L}_{\left(t,a,v\right)}=\tilde{K}_{\left(t,a,v\right)}\\
 & =\pi_{K}\left(a\right)V_{K}\left(t\right)v=\pi_{L}\left(a\right)TV_{L}\left(t\right)v.
\end{align*}
This implies that $T\in\pi_{L}\left(\mathfrak{A}\right)'$. Then,
\begin{align*}
K\left(s,t\right)\left(a,b\right) & =\left(\pi_{K}\left(a\right)V_{K}\left(s\right)\right)^{*}\left(\pi_{K}\left(b\right)V_{K}\left(t\right)\right)\\
 & =\left(T\pi_{L}\left(a\right)V_{L}\left(t\right)\right)^{*}\left(T\pi_{L}\left(b\right)V_{L}\left(t\right)\right)\\
 & =V_{L}\left(t\right)^{*}T^{2}\pi\left(a^{*}b\right)V_{L}\left(t\right),
\end{align*}
with $A\coloneqq T^{2}$, and this is \eqref{eq:7}. 
\end{proof}
\begin{defn}
In the case of \eqref{eq:7}, $A$ is said to be the Radon-Nikodym
derivative of $K$ with respect to $L$, denoted by 
\[
A=dK/dL.
\]

\end{defn}

\begin{cor}
The following are equivalent: 
\begin{enumerate}
\item $\pi_{L}$ is irreducible.
\item $K\leq L$ $\Longleftrightarrow$ $K=\lambda L$ for some constant
$\lambda\in\mathbb{C}$. 
\item $dK/dL=\lambda I_{H_{\tilde{L}}}$ for some constant $\lambda\in\mathbb{C}$. 
\end{enumerate}
\end{cor}

\begin{rem}
This corollary closely mirrors the classical correspondence in the
Gelfand--Naimark--Segal (GNS) construction, where pure states on
a $C^{*}$-algebra correspond to irreducible representations. In our
setting, the map
\[
\Phi_{K}\left(a\right):X\times X\rightarrow L\left(H\right),\quad\Phi_{K}\left(a\right)\coloneqq K\left(s,t\right)\left(a\right)
\]
where $K\in\mathcal{M}$, generalize classical states by taking values
not in scalars, but in $L(H)$-valued positive definite kernels. 

Historically, this conceptual shift dates back to the early 1950s,
when Segal asked Stinespring to extend the GNS construction. Stinespring's
answer was his famous dilation theorem, which replaced scalar-valued
states with completely positive (CP) maps into operator algebras.
In this way, the passage from classical states to operator-valued
kernels such as $K$ may be viewed as a continuation of this line
of thought---trading scalar positivity for operator positivity, and
classical irreducibility for that of the associated representation
$\pi_{K}$. In other words, $\Phi_{K}$ is a pure state (in the generalized
sense) if and only if $\pi_{K}$ is irreducible. 

This analogy extends further. Every state on a unital $C^{*}$-algebra
is a Choquet integral applied to the pure states. The non-pure states
are called mixed states. In the context of quantum mechanics, pure
states represent a system with complete knowledge, while mixed states
represent a system with some degree of uncertainty or incomplete information.
The Choquet boundary captures the idea that pure states are the extreme
points of the convex set of all possible quantum states; see, e.g.,
\cite{MR1151615,MR660825,MR149258,MR729530}. In our generalized setting,
irreducibility of the associated representation $\pi_{K}$ plays the
role of extremality, imitating the structure of classical state space
decompositions.

For the benefit of readers, we include the following relevant citations
on operator algebras, \cite{MR1276162,MR512360,MR442701,MR1468230}.
\end{rem}

\begin{cor}[Quantum Channel Simulation]
\label{cor:8}Let $K,L\in\mathcal{M}$ be positive definite kernels
associated to quantum systems, with factorizations:
\[
K(s,t)(a)=V_{K}(s)^{*}\pi_{K}(a)V_{K}(t),\quad L(s,t)(a)=V_{L}(s)^{*}\pi_{L}(a)V_{L}(t),
\]
where $\pi_{K},\pi_{L}$ are $*$-representations of a $C^{*}$-algebra
$\mathfrak{A}$, and the factorizations are minimal.

Suppose $K\leq L$, i.e., the kernel $K$ is dominated by $L$ via:
\[
K(s,t)(a)=V_{L}(s)^{*}\pi_{L}(a)AV_{L}(t),
\]
for some $0\leq A\leq I_{H_{\tilde{L}}}$ in $\pi_{L}(\mathfrak{A})'$.

Then there exists a completely positive trace-nonincreasing map (i.e.,
a quantum operation)
\[
\Phi:\pi_{L}(\mathfrak{A})\to\pi_{L}(\mathfrak{A})
\]
such that
\[
K(s,t)(a)=V_{L}(s)^{*}\Phi(\pi_{L}(a))V_{L}(t),
\]
where $\Phi$ is of the form:
\[
\Phi(T)=A^{1/2}TA^{1/2},\quad T\in\pi_{L}(\mathfrak{A}),
\]
which corresponds to post-processing by a quantum effect (POVM element)
$A$.
\end{cor}

\begin{rem}
The proof of \prettyref{cor:8} follows immediate from \prettyref{thm:4}.
There is a rich literature on positive operator valued measures (POVM).
Of special relevance is \cite{MR4862902,MR4557727,MR4555558,MR4760560}.

In the language of quantum information, the kernel $K$ may be viewed
as modeling a quantum process---such as a generalized quantum channel---that
can be simulated or degraded from the process described by $L$. The
operator $A\in\pi_{L}(\mathfrak{A})'$, which mediates the dominance
relation $K\leq L$, plays the role of a quantum effect or filter
in the Heisenberg picture, transforming observables via a completely
positive trace-nonincreasing map. This structure mirrors the notion
of quantum sufficiency, wherein one statistical experiment (or quantum
measurement model) is derivable from another via post-processing.
Notably, if $\pi_{L}$ is irreducible, then $A$ must lie in $\mathbb{C}\cdot I$,
implying that $K\leq L$ entails a scalar attenuation of the kernel---resembling
a fidelity degradation between quantum operations.

More precisely, the dependence of $V_{L}(t)\colon H\to\mathscr{L}$
on the parameter $t\in X$ reflects a family of quantum states or
embeddings labeled by classical data. Each $V_{L}(t)$ can be interpreted
as preparing the system in a quantum state associated with input $t$.
The kernel expression
\[
K(s,t)(a)=V_{L}(s)^{*}\,\pi_{L}(a)\,A\,V_{L}(t)
\]
then represents a generalized transition amplitude: prepare the system
at $t$, apply observable $\pi_{L}(a)$, attenuate with $A$, and
compare with the preparation at $s$. The operator $A$ acts as a
quantum effect or post-processing filter. This structure appears in
quantum learning and quantum instruments, where classical inputs are
encoded into quantum states and kernels track correlations or similarities
between them through observables. The variation in $V_{L}(t)$ encodes
how classical parameters affect quantum behavior.

The non-commutative framework forming the setting for our present
factorization results is both natural; and it is also motivated by
questions that are central in the context of quantum information,
e.g., in consideration of open quantum systems. Indeed, in the recent
literature in quantum information, there is a variety of such new
developments. Full details will be beyond the scope of our present
paper, and so for our present purpose, we limit ourselves to the following
citations to the literature \cite{MR4760335,MR4619365,MR3390587,MR4719025,MR4230450}.
\end{rem}

\begin{rem}
One may replace the $C^{*}$-algebra $\mathfrak{A}$ in \prettyref{def:1}
by a group algebra $\mathbb{C}[G]$, then all essential ingredients
from the above general $C^{*}$-algebraic framework carry over: positivity,
sesquilinearity, factorization and minimality are preserved. Note
that the positive-definiteness assumption \eqref{eq:a1} becomes:
\[
\sum_{i,j=1}^{N}\left\langle u_{i},K\left(s_{i},s_{j}\right)\left(g_{i}^{-1}g_{j}\right)u_{j}\right\rangle _{H}\geq0
\]
for all $\left(u_{i}\right)_{i=1}^{N}\subset H,\left(s_{i}\right)_{i=1}^{N}\subset X,\left(g_{i}\right)_{i=1}^{N}\subset G$,
and all $N\in\mathbb{N}.$ 

The group setting provides a concrete and symmetric structure that
is particularly natural in harmonic analysis, representation theory,
and quantum information, where groups often encode symmetries, conserved
quantities, or control operations. The kernel factorization thus becomes
a bridge between abstract operator algebra methods and classical constructions
involving group actions and unitary dynamics.
\end{rem}

