\section{Simulated data\label{secA2}}

\subsection{Details of computation\label{subsecA21}}
\subsubsection{Data generation process 1\label{subsubsecA211}}
In this section, we introduce the calculation to obtain the theoretical survival values from the oracle model in the simulation data generation process 1.

To simulate survival times from a Weibull distribution, the following relationship can be used \citep{Bender2005}:
\begin{equation}
    T = H_{0}^{-1}[-\log(1-U)]\exp(\beta(X))
     \nonumber
\end{equation}
with $U\sim\mathcal{U}[0,1]$. In the case of a Weibull risk function, $\lambda>0$ is the scale parameter, $\kappa$ is the shape parameter, and the cumulative risk function is written as: 
\begin{equation}
     H_{0}(t) = \left(\frac{t}{\lambda}\right)^{\kappa}
      \nonumber
\end{equation}

The inverse of $H_{0}$ is then written:
\begin{equation}
    H^{-1}_{0}(u)=\lambda u^{1/\kappa} \nonumber
\end{equation}
We obtain: 

\begin{equation}
   \boxed{ T = \lambda [-\log(1-U)]^{1/\kappa}\exp(\beta X)}
   \nonumber
\end{equation}

 The basis risk function $h_{0}(t)$ is known and follows a certain probability distribution. In this case, we   use the Weibull distribution. The risk function is then written as:  

 \begin{equation}
   h(t|X) = \frac{\kappa}{\lambda}\left(\frac{t}{\lambda}\right)^{\kappa-1} \exp(\beta X) \nonumber
\end{equation}
 with $h_{0}(t)=\frac{\kappa}{\lambda}(\frac{t}{\lambda})^{\kappa-1}$ the risk at baseline and $\beta$ the coefficients vector.  We then obtain the survival function from the instantaneous risk :  
\begin{align}
    S(t|X) &= \exp(-\int_{0}^{t}h(s|X)ds  \nonumber \\
    &= \exp(-H_{0}(t)\exp(\beta X)). \nonumber
\end{align}

\subsubsection{Data generation process 2\label{subsubsecA212}}


In this section, we introduce the calculation to obtain the theoretical survival values from the oracle model in the simulation data generation process 2.

To simulate survival times from an AFT model and a random generator based on Friedman's function, the following relationship can be used \citep{Leemis1990}:
\begin{equation}
    T = \frac{H_{0}^{-1}[-\log(1-U)]}{\exp(m_{1}(X) + \tau\times m_{2}(X))}, \nonumber
\end{equation}
with $U\sim\mathcal{U}[0,1]$. In the case of a lognormal risk function, the cumulative risk function is written as :
\begin{equation}
    H_{0}(t) = -\log\left[1-\phi\left(\frac{\log(t)-\mu}{\sigma}\right)\right]. \nonumber
\end{equation}
The inverse of $H_{0}$ is then written:
\begin{equation}
    H_{0}^{-1}(u) = \exp(\sigma \phi^{-1}(1-exp(-u))+\mu). \nonumber
\end{equation}
We obtain:
\begin{equation}
   \boxed{ T = \frac{1}{\exp(m_{1}(X) + \tau\times m_{2}(X))}\exp(\sigma \phi^{-1}(U)+\mu)}. \nonumber
\end{equation}

 The basis risk function $h_{0}(t)$ is known and follows a certain probability distribution. In this case, we   use the log-normal distribution. The risk function is then written as:  
\begin{equation}
   h(t|X) = \exp(m_{1}(X) + \tau\times m_{2}(X))h_{0}(t \exp(m_{1}(X) + \tau\times m_{2}(X))), \nonumber
\end{equation}
with $h_{0}(t)$ the risk at baseline and $\beta$ the coefficients vector.  We then obtain the survival function from the instantaneous risk :  
\begin{align}
    S(t|X) &= \exp(-\int_{0}^{t}h(s|X)ds  \nonumber \\
    &= \exp(-H_{0}(t\exp(m_{1}(X) + \tau\times m_{2}(X))). \nonumber
\end{align}


