	\section{Fading Channel with I-CSIT and QFC}\label{s1}
	\subsection{Model Formulation and Main Results}

The quasi-static fading channel with I-CSIT and QFC is shown in Figure \ref{fig1}, and at
time $i\in\left\lbrace 1,2,\dots,N\right\rbrace $, the channel inputs and outputs are given by

	\begin{equation}\label{model}
		\begin{array}{l}
			Y_i=hX_i+W_i, \\
\widetilde{Y}_{i}=\widetilde{X}_{i}+Z_{i},	
		\end{array}
	\end{equation}
	where $X_i$ is the channel input at time $i$ subject to an average power constraint {\small $\frac{1}{N}\sum\nolimits_{i=1}^{N}E({X}_{i}^2)\leq P$}, $h$ is a fixed non-zero channel fading coefficient
	%\footnote{Assume that the channel is static fading (block fading), i.e., the channel coefficient stays constant during the transmission.},
	\footnote{Such an assumption holds for the scenario with large coherence bandwidth or coherence time, e.g., indoor scenarios with small delay and Doppler spread \cite{H_1}~-\cite{H_2}.},
	which is perfectly known by the receiver,
	$W_i\sim\mathcal{N}(0,\sigma^{2})$ is the Gaussian noise which is
	independent and identically distributed (i.i.d.) across the time index $i$,
	$\widetilde{X}_i$ is the receiver's feedback codeword with average power constraint
	{\small $\frac{1}{N}\sum\nolimits_{i=1}^{N}E(\widetilde{X}_{i}^2)\leq \widetilde{P}$}, $Y_i$
	and $\widetilde{Y}_i$ are the outputs of the forward and feedback channels, respectively, and
	$Z_i=\mathbb{M}_{2\sigma_z}[\widetilde{X}_{i}]$ is the QFC noise which is generated by the local quantizer at the receiver \cite{JS11}, $\mathbb{M}_{2\sigma_z}[\cdot]$ is the lattice $\wedge_{2\sigma_z}$ in $\mathbb{R}$ spanned by a constant  $G=2\sigma_z$ such that
	\begin{equation}
		\wedge_{2\sigma_z}=\left\lbrace t=Ga:a\in \mathbb{Z}\right\rbrace.
	\end{equation}
	Denote the nearest neighbor quantizer associated with the lattice $\wedge_{2\sigma_z}$
	by
	\begin{equation}
		\mathbf{Q}_{\wedge_{2\sigma_z}}(x)\stackrel{\text {def}}{=}\text{arg} \min\limits_{t\in \wedge_{2\sigma_z}}\|x-t\|,
	\end{equation}
	where $\mathbb{M}_{\wedge_{2\sigma_z}}[\cdot]$ is the modulo-$\wedge_{2\sigma_z}$ function \cite{JS10} which is defined as
	\begin{equation}\label{sigma_z}
		\mathbb{M}_{\wedge_{2\sigma_z}}[x] \stackrel{\text {def}}{=} x-\mathbf{Q}_{\wedge_{2\sigma_z}}(x).
	\end{equation}
	The size of $\sigma_z$ measures the fineness of the quantizer, and  (\ref{sigma_z}) indicates that $\Pr\left\lbrace |Z_i|\leq\sigma_z\right\rbrace =1$.

	The signal-to-noise ratios (SNR) of the forward channel is denoted as	{\small $\text{SNR}\mathop{=}\limits^{\rm{def}}\frac{P}{\sigma^2}$}.




	%	\begin{definition} \label{de1}
		%		Given a positive real parameter $\sigma_{z}$, a uniform quantizer with sensitivity is a function \cite{JS11} $\Phi_{\sigma_{z}}: \mathbb{R} \rightarrow \mathbb{R}$ defined as
		%		\begin{equation}\label{model}
			%			\Phi_{\sigma_{z}}(\widetilde{X}_i)=2\sigma_{z}\left\lfloor \frac{\widetilde{X}_i+\sigma_{z}}{2\sigma_{z}}\right\rfloor,
			%		\end{equation}
		%		where $\left\lfloor x \right\rfloor$ denotes the largest integer that is smaller than $x$.
		%		
		%		The quantization noise is given by the following function:
		%		\begin{equation}\label{zi}
			%			Z_i(\widetilde{X}_i)=\Phi_{\sigma_{z}}(\widetilde{X}_i)-\widetilde{X}_i,
			%		\end{equation} 	
		%		which satisfies the following bound:
		%		\begin{equation}\label{model}
			%			Pr\left\{|Z_i|\leq\sigma_z\right\}=1.
			%		\end{equation}
		%	\end{definition}		

	Define $\widehat{h}$ as the transmitter's estimation about $h$ via channel feedback, and
	the corresponding distortion of the estimation is denoted by the norm-bounded mode \footnote{In channel with quantized feedback \cite{JS11}, the norm-bounded model is commonly used as a measure of estimation error.
}
	\begin{equation}
		\bigtriangleup\mathop{=}\limits^{\rm{def}} \|h-\hat{h}\|_2. 	
	\end{equation} 			
	\emph{Channel coding}:
	\begin{itemize}
		\item 	The message $W$ is uniformly drawn from $\mathcal{W} = \left\lbrace 1, 2, . . . , M\right\rbrace $.
		\item 	At time index $i$ ($i \in\left\lbrace 1, 2, \dots , N\right\rbrace $),
		the codeword $X_i=g_i(W,\widetilde{Y}^{i-1},\widehat{h},\bigtriangleup)$, where
		$g_i$ is the transmitter's encoding function, and $\widetilde{Y}^{i-1}=(\widetilde{Y}_1,\dots,\widetilde{Y}_{i-1}) $ is the feedback signal at previous time instants.

		\item At time index $i$, the feedback codeword \footnote{Here note that in \cite{JS11},
$h$ is perfectly known by the transceiver, and passive feedback (no feedback encoder) is sufficient for SK-type coding. While in this paper, I-CSIT yields additional error in the SK-type encoding-decoding procedure, hence the active feedback (allowing feedback encoder) is needed to eliminate this type of error.}	$\widetilde{X}_{i}=\widetilde{g}_i(Y^{i},h,\widehat{h},\bigtriangleup,Z^{i-1})$, where $\widetilde{g}_i$ is the receiver's encoding function, ${Y}^{i}=({Y}_1,\dots,{Y}_{i})$ is the output of the forward channel at previous time instants and ${Z}^{i-1}=({Z}_1,\dots,{Z}_{i-1})$ is the QFC noise.

		\item At time $N$, the output of the decoder is {\small $\hat{W}=\psi(Y^{N},h,\widehat{h},\bigtriangleup,Z^{N-1})$}, where $\psi$ is the decoding function. The average decoding error probability is defined as
{\small 		\begin{equation}\label{pe}
			P_{e}=\frac{1}{M}\sum\limits_{w = 1}^{M}\Pr\{\hat{W}\neq w|
			w\;\mbox{was sent}\}.
		\end{equation}}
	\end{itemize}

	The rate $R$ is said to be $(N,\varepsilon,D)$-achievable if for a given coding blocklength  $N$, error probability $\varepsilon$  and a targeted estimation distortion $D$ about $h$, there exist encoders and decoders such that
	\begin{align}\label{rac}
		\frac{1}{N}\log M\geq {R}-\varepsilon, \,\,\,\, P_{e}\leq \varepsilon, \,\,\,\, \bigtriangleup \leq D.
	\end{align}

	The $(N,\varepsilon,D)$-capacity of the model of Figure \ref{fig1} is the supremum over all $(N,\varepsilon,D)$-achievable rates defined above, and it is denoted by $\mathcal{C}_{fd}$.

	\subsection{ Main Result}\label{sec5-12}
	\begin{theorem}\label{th1}
		For blocklength $N$, error probability $\varepsilon$ and distortion $D$ about $h$, the $(N,\varepsilon,D)$-capacity $\mathcal{C}_{fd}$ of the model of Figure \ref{fig1} is lower bounded by
{\small 		\begin{align}\label{t111}
			&\mathcal{C}_{fd}\ge \mathcal{R}(N,\varepsilon,D)\nonumber\\
			&=\frac{1}{2N}\log \left( 1+\frac{H^{2}\cdot\text{SNR}\cdot(1+H^2\cdot\text{SNR}\cdot\frac{A}{B})^{N-1}}{L}\right),\nonumber
		\end{align}}
		where
{\small 		\begin{eqnarray*}\label{D2}
			&&A=\left(( \sqrt{3\widetilde{P}}-\sigma_z)[Q^{-1}(\frac{p_m}{2})]^{-1}\right) ^2,\nonumber\\
			&&B=\left( \left| \sqrt{3\widetilde{P}}-\sigma_z\right|[Q^{-1}(\frac{p_m}{2})]^{-1} +\sigma_z \right)^2,\nonumber\\
			&&L=\frac{1}{3}\left[Q^{-1}\left(\frac{\varepsilon}{4}\right)\right]^2,\,\,\,\,
			p_m=\frac{\varepsilon}{2(N-1)},\nonumber\\
			&&H=\max(\mid \hat{h}\mid-{D},0).\nonumber
		\end{eqnarray*}
		}
		\begin{IEEEproof}
			See Section \ref{TH1}.
		\end{IEEEproof}
	\end{theorem}	
