		\subsubsection{Encoding-decoding procedure} \hfil \\		
		$\textbf{Initialization:}$	
		At time instant $1$, first, map the message $M$ to a pulse amplitude modulation (PAM) point $\Theta$, and then
		the transmitter  encodes $\Theta$ as
		\begin{equation}
			X_{1}=\sqrt{{P}}\Theta.
		\end{equation}
		Once receiving
		\begin{equation}
			Y_{1}=hX_{1}+W_{1},
		\end{equation}
		the receiver computes his first estimation $\hat{\Theta}_{1}$ of $\Theta$ by
		\begin{equation}
			\begin{split}
				\hat{\Theta}_{1}&=\frac{Y_{1}}{h\cdot\sqrt{P}}=\Theta+\frac{W_{1}}{h\cdot\sqrt{P}},
			\end{split}
		\end{equation}
		then the receiver sends
		\begin{equation}
			\widetilde{X}_{1}=\mathbb{M}_{\widetilde{d}}[\gamma_{1}\hat{\Theta}_{1}+V_1],
		\end{equation}
		where $\widetilde{d}=\sqrt{12\widetilde{P}}$, $V_{1}$
		is a dither signal uniformly distributed in $[-\frac{\widetilde{d}}{2},\frac{\widetilde{d}}{2})$, $\gamma_{1}$ will be defined later.
		The feedback signal received by the transmitter is denote by
		\begin{equation}
			\widetilde{Y}_{1}=\widetilde{X}_{1}+Z_{{1}}.
		\end{equation}
		At time instant $2$, the transmitter sends
		{	\begin{equation}
				\begin{split}
					X_{2}=\alpha\mathbb{M}_{\widetilde{d}}[\widetilde{Y}_{1}-\gamma_{1}\Theta-V_1]
					\mathop{=}\limits^{\text{(a)}}\alpha\mathbb{M}_{\widetilde{d}}[\gamma_{1}\epsilon_{1}+Z_{1}],\label{X1_1}
				\end{split}
		\end{equation}}%
		where (a) follows from the properties of the modulo-lattice function as shown in~\cite{JS10}, $\epsilon_1=\hat{\Theta}_1-\Theta$, and $\alpha$ will be defined later.
		Once receiving
		\begin{equation}
			Y_{2}=hX_{2}+W_{2},
		\end{equation}
		the receiver calculates an auxiliary signal
		{      \begin{equation}
				\dot{Y}_{2}=Y_{2}-h\alpha\cdot Z_{1},
		\end{equation}}%
		and then the receiver updates his estimation  $\hat{\Theta}_{2}$ of $\Theta$ by using this auxiliary signal, i.e.,
		\begin{equation}
			\hat{\Theta}_{2}=\hat{\Theta}_{1}-\beta_{1}\dot{Y}_{2}\label{A},
		\end{equation}
		where $\beta_{1}$ is the coefficient of MMSE and  will be defined later.	The receiver sends
		\begin{equation}
			\widetilde{X}_{2}=\mathbb{M}_{\widetilde{d}}[\gamma_{2}\hat{\Theta}_{2}+V_2].
		\end{equation}
		where $V_{2}$
		is a dither signal defined the same as $V_{1}$, and $\gamma_{2}$ will be defined later.

		$\textbf{Iteration:}$	
		At time instant $i \in \left\lbrace {2},\ldots,N\right\rbrace$, after the transmitter receives the feedback $\widetilde{Y}_{i-1}$, he sends
{\small 		 	\begin{equation}
				\begin{split}	
					X_{i}=\alpha \mathbb{M}_{\widetilde{d}}[\widetilde{Y}_{i-1}-\gamma_{i-1}\Theta-V_{i-1}]
					\mathop{=}\limits^{\text{(b)}}\alpha\mathbb{M}_{\widetilde{d}}[\gamma_{i-1}\epsilon_{i-1}+Z_{i-1}],
				\end{split}\label{X1}
		\end{equation}}
		where (b) follows from the properties of the modulo-lattice function as shown in~\cite{JS10}, and $V_{i-1}$
		is a dither signal uniformly distributed in $[-\frac{\widetilde{d}}{2},\frac{\widetilde{d}}{2})$.

		Once receiving
		\begin{equation}
			Y_{i}=hX_{i}+W_{i},
		\end{equation}
		the receiver calculates the auxiliary signal
		{ 		\begin{equation}
				\dot{Y}_{i}=Y_{i}-h\alpha\cdot Z_{i-1}.\label{Y1}
		\end{equation}}%
		Then receiver updates his estimation  $\hat{\Theta}_{i}$ of $\Theta$ by
		\begin{equation}
			\hat{\Theta}_{i}=\hat{\Theta}_{i-1}-\beta_{i-1}\dot{Y}_{i}\label{e1}.
		\end{equation}
		Define $\epsilon_{i}=\hat{\Theta}_{i}-\Theta$, then (\ref{e1}) yields that
		\begin{equation}
			\epsilon_{i}=\epsilon_{i-1}-\beta_{i-1}\dot{Y}_{i}.
		\end{equation}

		The receiver sends $\widetilde{X}_i$ back to the transmitter via the QFC, where
		\begin{equation}
			\widetilde{X}_i=\mathbb{M}_{\widetilde{d}}[\gamma_{i}\hat{\Theta}_{i}+V_{i}].
		\end{equation}

		$\textbf{Decoding:}$
		At time $N$,  the receiver decodes the message using a minimum distance decoder for $\widehat{\Theta}_{N}$ with respect to the PAM constellation.	


