		For $i \in \left\lbrace {1},\ldots,N-1\right\rbrace$, define $E_i$ as the event where a modulo-aliasing error occurs, i.e
		{\small 	\begin{eqnarray}\label{Ei_1}
				E_i\mathop{=}\limits^{\rm{def}}\left\lbrace \gamma_{i}\epsilon_{i}+Z_{i}\notin [-\frac{\widetilde{d}}{2},\frac{\widetilde{d}}{2})\right\rbrace.
		\end{eqnarray}}%	
		Furthermore, we define $E_{N}$ as the PAM decoding error event
		\begin{eqnarray}
			E_{N}\mathop{=}\limits^{\rm{def}}\left\lbrace \epsilon_{N} \notin [-\frac{{d_{\min}}}{2},\frac{{d_{\min}}}{2})\right\rbrace,
		\end{eqnarray}%
		where $d_{\min}$ is the minimal distance of the PAM.

