	\end{align}}

	\subsection{Determination of $\gamma_i$}\label{a-3}	
	Letting { $\Pr\left\lbrace E_{N}^{'}\right\rbrace=\frac{\varepsilon}{2} $, $\Pr\left\lbrace E_1^{'}\right\rbrace = \cdots = \Pr\left\lbrace E_{N-1}^{'}\right\rbrace=\frac{\varepsilon}{2(N-1)} =p_m$}, and using the definition of the event $E_i^{'}$ in (\ref{Ei_1}) and $\widetilde{d}=\sqrt{12\widetilde{P}}$, we conclude that
	\begin{align}				
\Pr\left\lbrace E_i^{'}\right\rbrace  &=\Pr\left\{\gamma_i{\epsilon}_i^{'}+Z_i\notin\left[-\frac{\widetilde{d}}{2},\frac{\widetilde{d}}{2}\right)\right\} \nonumber\\
&=\Pr\left\{\arrowvert\gamma_i{\epsilon}_i^{'}+Z_i\arrowvert\geq\sqrt{3\widetilde{P}}\right\}\nonumber\\
&\mathop{\leq}\limits^{(a)} \Pr\left\{\arrowvert\gamma_i{\epsilon}_i^{'}\arrowvert+\sigma_z\geq\sqrt{3\widetilde{P}}\right\}\nonumber\\
&= 2Q\left(\frac{\sqrt{3\widetilde{P}}-\sigma_z }{ \sqrt{E\left( \gamma_i{\epsilon}_i^{'}\right)^{2}}} \right) \nonumber\\
&\mathop{\leq}\limits^{(b)} 2Q\left(\frac{\sqrt{3\widetilde{P}}-\sigma_z }{ \sqrt{\gamma_i^2{\sigma}_i^{2}(H)}} \right)\mathop{=}\limits^{(c)}p_m,									
\end{align}
where (a) follows from the fact that the quantized noise $Z_i$ is upper bounded by $\sigma_z$, (b) follows from  $Q(x)$-function  is monotonically decreasing while $x$ is increasing,
and (c) follows from choosing
\begin{align}
\gamma_i=\sqrt{\frac{A}{\sigma^{2}_i(H)}},
\end{align}
where
\begin{align}
A\mathop{=}\limits^{\text{def}}\left(( \sqrt{3\widetilde{P}}-\sigma_z)[Q^{-1}(\frac{p_m}{2})]^{-1}\right) ^2.
\end{align}


\subsection{Determination of $\alpha$}\label{a-4}	

We choose $\alpha$ to ensure the actual transmitting power does not exceed the average power constraint $P$, namely,	
\begin{eqnarray}\label{dsb-1}
&&E(X_{i+1})^2=E(\alpha(\gamma_i\epsilon^{'}_i+Z_i))^2\nonumber\\
&&=\alpha^2E(\gamma_i\epsilon^{'}_i+Z_i)^2=\alpha^2\|\gamma_i\epsilon^{'}_i+Z_i\|_R^2\nonumber\\
&&\mathop{\leq}\limits^{(a)}\alpha^2(\|\gamma_i\epsilon^{'}_i\|_R+\|Z_i\|_R)^2\nonumber\\
&&=\alpha^2(\sqrt{\gamma_i^2 \sigma_i^2}+\sigma_z)^2\nonumber\\
&&\leq \alpha^2(\sqrt{\gamma_i^2 {\sigma}_i^{2}(H)}+\sigma_z)^2\mathop{=}\limits^{(b)}P,
\end{eqnarray}
where $\|X\|_R\mathop{=}\limits^{\rm{def}}(E(X^2))^{1/2}$, (a) follows from the Minkowski inequality, and (b) follows from choosing
{        { 	\begin{align}
		\alpha=\sqrt{\frac{P}{B}},
		\end{align}} }
		where
		\begin{align}
B\mathop{=}\limits^{\text{def}}\left( | \sqrt{3\widetilde{P}}-\sigma_z|[Q^{-1}(\frac{p_m}{2})]^{-1} +\sigma_z \right)^2.
\end{align}


\subsection{Decoding error probability analysis}\label{a-5}	
According to the parameters given above, we have
\begin{equation}\label{model}
\text{SNR}_i=\frac{1}{\sigma_{i}^{2}}, \ \	\text{SNR}_i(H)=\frac{1}{\sigma_{i}^{2}(H)},
%SNR_n^{'}=\frac{1}{\sigma_{n}^{'2}}
\end{equation}
where $\text{SNR}_i\geq \text{SNR}_i(H)$ for any $i\geq 1$. Then (\ref{E12}) can be re-written by
{ 	\begin{align}
	P_{e}	&\leq  \sum_{i=1}^{N} \Pr\left\lbrace E_i^{'}\right\rbrace \nonumber\\
	&\leq (N-1)p_m+\Pr\left\lbrace E_{N}^{'}\right\rbrace \nonumber\\
	&\leq \frac{\varepsilon}{2}+\Pr\left\lbrace E_{N}^{'}\right\rbrace \nonumber\\
	&\mathop{\leq}\limits^{(a)}\frac{\varepsilon}{2}+2Q\left( \sqrt{\frac{3\cdot\text{SNR}_{N}}{2^{2N{R}}-1}}\right) \nonumber\\
	%&\leq\frac{\varepsilon}{2}+2Q\left( \sqrt{\frac{3SNR_N^{'}}{2^{2NR}-1}}\right)
	&\leq\frac{\varepsilon}{2}+2Q\left( \sqrt{\frac{3\cdot\text{SNR}_{N}}{2^{2N{R}}}}\right)\nonumber\\
	&\leq\frac{\varepsilon}{2}+2Q\left( \sqrt{\frac{3\cdot\text{SNR}_{N}(H)}{2^{2N{R}}}}\right)\mathop{=}\limits^{(b)}\varepsilon,
	\end{align}}%
	where (a) follows from the detection error probability of PAM in \cite{JS10}, and (b) follows from choosing
	\begin{equation}\label{model}
%Q\left( \sqrt{\frac{3SNR_N^{'}}{2^{2NR}-1}}\right)=\frac{\delta}{4}
Q\left( \sqrt{\frac{3\cdot\text{SNR}_{N}(H)}{2^{2N{R}}}}\right)=\frac{\varepsilon}{4},
\end{equation}
which indicates that
