	& \mathcal{R}(N,\varepsilon,D)=\frac{1}{2N}\log\left(\frac{\text{SNR}_{N}(H)}{L} \right) \nonumber \\
	& =\frac{1}{2N}\log \left( \frac{H^{2}\text{SNR}(1+H^2\text{SNR}\frac{A}{B})^{N-1}}{L}\right),
