\begin{title}
{\Large\bf Integrated Analysis for Electronic Health Records with Structured and Sporadic Missingness}

\author{Jianbin Tan\thanks{Department of Biostatistics \& Bioinformatics, Duke University, NC, USA.}~$^1$, ~ Yan Zhang\thanks{Department of Biostatistics \& Bioinformatics, Duke University, NC, USA.}~$^1$, ~ Chuan Hong\thanks{Department of Biostatistics \& Bioinformatics, Duke University, NC, USA}, ~ T. Tony Cai\thanks{Department of Statistics \& Data Science, University of Pennsylvania, PA, USA},\\ ~ Tianxi Cai\thanks{Department of Biostatistics and Department of Biomedical Informatics, Harvard University.}~$^2$, ~ and ~ Anru R. Zhang\thanks{Department of Biostatistics \& Bioinformatics and Department of Computer Science, Duke University, NC, USA}~$^2$}
