	\section{Theoretical Framework of \textsc{Macomss}}\label{sec.theory}
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%% 


	Before getting into details, we define addition notations relating to theoretical analysis. Let $\mathbb{I}(\cdot)$ denote the indicator function, and $I_p$ be the identity matrix in $\mathbb{R}^{p \times p}$.
	We also denote $e_i^{(p)}$, the $i$-th canonical basis in $p$-dimensional space, as the $p$-dimensional vector with $i$-th entry as 1 and others as zero. For \( A \in \mathbb{R}^{p_1 \times p_2} \), we use \( A_{[\Omega_1, \Omega_2]} \) to represent the sub-matrix of \( A \) with row indices \( \Omega_1 \) and column indices \( \Omega_2 \). For convenience, we denote \( a:b = \{a, \ldots, b\} \) and ``:" as the entire index set. Therefore, \( A_{[:, 1:r]} \) stands for the first \( r \) columns of \( A \), while \( A_{[1:m_1, 1:m_2]} \) represents the first \( m_1 \) rows and first \( m_2 \) columns of \( A \). 
	Define the sub-Gaussian norm for any random variable $Y$ as $\|Y\|_{\phi_2} := \sup_{q\geq 1}\left(\E|Y|^q\right)^{1/q}/\sqrt{q}$, see, e.g., \cite{vershynin2010introduction}). 

	When \( A \in \mathbb{R}^{p_1 \times p_2} \), we denote \( \sigma_1(A) \geq \sigma_2(A) \geq \cdots \geq \sigma_{p_1 \wedge p_2}(A) \) as the set of all singular values of \( A \) in descending order. In particular, let \( \sigma_{\min}(A) = \sigma_{p_1 \wedge p_2}(A) \) and \( \sigma_{\max}(A) = \sigma_1(A) \) represent the minimum and maximum singular values of \( A \), respectively. Note that \( \sigma_1(A) = \|A\| \), the spectral norm of \( A \), and \( \sqrt{\sum_{r=1}^{p_1 \wedge p_2}\sigma_r^2(A)} = \|A\|_F \), the Frobenius norm of \( A \). In the analysis, orthogonal matrices will play a crucial role, we thus denote \( \mathbb{O}_{p, r} = \{U \in \mathbb{R}^{p \times r}: U^\top U = I_r\} \), the set of all \( p \)-by-\( r \) orthogonal matrices. 
	Finally, let \( C, c, C_1, C_2, \ldots \) be generic symbols for constants, whose actual values may vary from line to line.

	\begin{algorithm}
		\caption{Matrix Completion with Noise and Structured and Sporadic Missingness}
		\footnotesize
		\begin{algorithmic}[1]
			\State Input: $Y\in \mathbb{R}^{p_1\times p_2}$ with missing indicator $M\in\{0, 1\}^{p_1\times p_2}$.
			\State Estimate $\hat{\Theta} = (\Theta_{ij})_{1\leq i \leq p_1, 1\leq j\leq p_2}$ as
			\begin{equation*}
				\begin{split}
					& \hat{\Theta}^{\rm (col)} = (\hat{\Theta}_{ij}^{\rm (col)})\in \mathbb{R}^{p_1\times m_2}, \quad \hat{\Theta}^{\rm (col)}_{ij} = \left(\sum_{j'=1}^{m_2} M_{ij'} \right) \left(\sum_{i'=1}^{p_1} M_{i'j}\right) / \left(\sum_{i'=1}^{p_1}\sum_{j'=1}^{m_2} M_{i'j'}\right),\\ 
					& \hat{\Theta}^{\rm (row)} = (\hat{\Theta}_{ij}^{\rm (row)})\in \mathbb{R}^{m_1\times p_2}, \quad \hat{\Theta}^{\rm (row)}_{ij} = \left(\sum_{j'=1}^{p_2} M_{ij'} \right) \left(\sum_{i'=1}^{m_1} M_{i'j}\right) / \left(\sum_{i'=1}^{m_1}\sum_{j'=1}^{p_2} M_{i'j'}\right).
				\end{split}
			\end{equation*}
			\begin{equation*}
				\begin{split}
					& \hat{\Theta}_{ij} = \left\{\begin{array}{ll}
						\left(\frac{1}{2}(\hat{\Theta}^{\rm (col)}_{ij})^{-1} + \frac{1}{2}(\hat{\Theta}^{\rm (row)}_{ij})^{-1}\right)^{-1}, & i \in[1:m_1], j\in [1:m_2]\\
						\hat{\Theta}_{ij}^{\rm (row)}, & i\in [1:m_1], j\in [(m_2+1):p_2]\\
						\hat{\Theta}_{ij}^{\rm (col)}, & i\in [(m_1+1):p_1], j\in [1:m_2];\\
						0 & \text{otherwise}.
					\end{array}\right.
				\end{split}
			\end{equation*}
			$$\hat{\Theta}_{(11)} = (\hat{\Theta}_{ij})_{\substack{1\leq i \leq m_1\\1\leq j \leq m_2}}, \quad\hat{\Theta}_{(12)} = (\hat{\Theta}_{ij})_{\substack{1\leq i \leq m_1\\m_2+1\leq j \leq p_2}},\quad \hat{\Theta}_{(21)} = (\hat{\Theta}_{ij})_{\substack{m_1+1 \leq i \leq p_1\\1\leq j \leq m_2}}.$$
			\State Set $Y_{ij} = 0$, whenever $M_{ij}= 0$. Calculate
			$$\tilde{Y} \in \mathbb{R}^{p_1\times p_2}, \quad \tilde{Y}_{ij} = Y_{ij}/\hat{\Theta}_{ij}, \quad 1\leq i \leq p_1, 1\leq j \leq p_2.$$
			\State Calculate the SVDs for 
			$$Y^{\rm (col)} = \begin{bmatrix}
				\frac{(p_1-2m_1)\wedge 0}{p_1}\cdot \tilde{Y}_{(11)} \\
				\tilde{Y}_{(21)}
			\end{bmatrix}, \quad \text{and}\quad Y^{\rm (row)} = \left[\frac{(p_2-2m_2)\wedge 0}{p_2}\cdot \tilde{Y}_{(11)}, ~ \tilde{Y}_{(12)}\right],$$ 
			%$\tilde{Y}_{(\bullet1)}$ and $\tilde{Y}_{(\bullet1)}$ 
			Let $V^{\rm (col)}$ and $U^{\rm (row)}$ be the right singular vectors of $\tilde{Y}^{\rm (col)}$ and the left singular vectors of $\tilde{Y}^{\rm (row)}$, respectively. Then calculate
			\begin{equation*}
				B_{(11)} = \{U^{\rm (row)}\}^\top\tilde{Y}_{(11)} V^{\rm (col)},\quad B_{(12)} = \{U^{\rm (row)}\}^\top\tilde{Y}_{(12)}, \quad B_{(21)} = \tilde{Y}_{(21)} V^{\rm (col)}.
			\end{equation*}
			\For {$s = r_0: -1: 1$}
			\State {\bf if} $B_{(11), [1:s, 1:s]}$ is not singular and 
			$$\left\|B_{21, [:, 1:\hat{r}]}B_{11, [1:\hat{r}, 1:\hat{r}]}^{-1}\right\| \leq 2\sqrt{p_1/m_1}\quad \text{or}\quad \left\|B_{11, [1:\hat{r}, 1:\hat{r}]}^{-1} B_{12, [1:\hat{r}]}\right\| \leq 2\sqrt{p_2/m_2}$$ \quad~ {\bf then}
			\State \quad\quad $\hat r = s$; {\bf break} from the loop;
			\State {\bf end if}
			\EndFor		
			\State{\bf If} $\hat{r}$ is still unassigned {\bf then} $\hat{r}_t = 0$.
			\State We calculate the final estimator $\hat{A}$, where
			\begin{equation*}
				\begin{split}
					& \hat{A}_{(11)} = U^{\rm (row)}_{[:, 1:\hat{r}]}B_{(11), [1:\hat{r}, 1:\hat{r}]}V^{\rm (col)\top}_{[:, 1:\hat{r}]}, \quad \hat{A}_{(12)} = U^{\rm (row)}_{[:, 1:\hat{r}]}B_{(12), [1:\hat{r}, :]},\\
					& \hat{A}_{(21)} = B_{(21), [:, 1:\hat{r}]}V^{\rm (col)\top}_{[:, 1:\hat{r}]}, \quad\quad\qquad\quad  \hat{A}_{(22)} = B_{(21), [:, 1:\hat{r}]}B_{(11), [1:\hat{r}, 1:\hat{r}]}^{-1}B_{(12), [1:\hat{r}, :]}.
				\end{split}
		\end{equation*}	\end{algorithmic}\label{al:procedure}
	\end{algorithm}

	We propose the procedure of \textsc{Macomss} in Algorithm~\ref{al:procedure} and analyze the theoretical performance of the proposed procedure in what follows. To begin, we state the assumptions that will be used in the theoretical analysis.

	\begin{Condition}[Sub-Gaussian Observations] \label{con:sub-gaussian}
		All entries $Y_{ij}$ are independent and $\|Y_{ij}\|_{\psi_2} \leq \tau$ for some constant $\tau>0$. Here the $\|\cdot\|_{\phi_2}$ is the sub-Gaussian norm. In addition, $\sum_{i=1}^{m_1}\sum_{j=1}^{m_2} \E(Y_{ij} - A_{ij})^2 \geq \frac{1}{(m_1m_2)^c}$. 
	\end{Condition}
	Condition \ref{con:sub-gaussian} characterizes that all observations are independently sub-Gaussian distributed. The commonly used identical distribution \citep{keshavan2010matrix} or bounded assumption \citep{chatterjee2015matrix} in matrix completion literature are not necessary in our analysis. In addition, we impose a mild condition on the lower bound of noise, i.e. $\sum_{i=1}^{m_1}\sum_{j=1}^{m_2}\E(Y_{ij} - A_{ij})^2 \geq \frac{1}{(mn)^c}$, which will be used only for technical purposes. 

	\begin{Condition}[Low-rank and Incoherence Assumption]\label{con:low-rank-incoherence} 
		Suppose $\rank(A) = r$ and $A = U\Sigma V^\top$ is the SVD, where  $U\in \mathbb{O}_{p_1, r}$ and $V\in \mathbb{O}_{p_2, r}$ satisfy the incoherence condition, i.e. for constant $\rho>0$ the following inequality holds,
		\begin{equation*}
			\frac{p_1}{r}\max_{i}\left\|\mathbb{P}_{U}e_i^{(p_1)}\right\|_2^2 \leq \rho, \quad \frac{p_2}{r}\max_{j}\left\|\mathbb{P}_{V}e_j^{(p_2)}\right\|_2^2 \leq \rho. 
		\end{equation*}
	\end{Condition}
	We also assume Condition \ref{con:low-rank-incoherence}, i.e. the low-rank and incoherence assumption, holds for the matrix $A$. Especially, the incoherence condition is widely used in matrix completion literature \citep{candes2009exact,recht2011simpler,chen2015incoherence}, which guarantees that every entry of $A$ contains similar amount of information. As we will show later, the observable entries in $Y_{(11)}, Y_{(12)}$, and $Y_{(21)}$ will contain enough knowledge to infer the whole missing block of $A_{(22)}$ by assuming Condition \ref{con:low-rank-incoherence}.



	\begin{Condition}[Missingness]\label{con:missingness}
		The missing value indicators $M\in \mathbb{R}^{p_1\times p_2}$ are independently Bernoulli distributed: $M_{ij} \sim {\rm Bern}(\Theta_{ij})$, whenever $1\leq i \leq m_1$ or $1\leq j \leq m_2$. Here, 
		\[
		\theta_0 := \min \left\{\Theta_{ij}: 1\leq i\leq m_1 \text{ or } 1\leq j \leq m_2\right\} \geq Cr(m_1\wedge m_2)^{-1}\log (p_1\vee p_2)
		\] 
		and $\rank(\Theta) =1$.
	\end{Condition}


	When there are possibly sporadic missing entries in $Y_{(12)}, Y_{(21)}$, and $Y_{(11)}$, we further assume Condition \ref{con:missingness} holds. The rank-1 assumption is widely seen in matrix completion literature (see, e.g. \cite{foygel2011learning,loh2012high}). The condition that $\theta_0 \geq Cr(m_1 \wedge m_2)^{-1}\log(p_1\vee p_2)$ is also widely seen in matrix completion literature (see, e.g. \cite{candes2010power,recht2011simpler}).


	Based on these conditions, we have the following theoretical guarantees for the proposed procedure for the noisy matrix completion with structured and sporadic missingness. We particularly consider the following class of low-rank matrices,
	\begin{equation}\label{eq:class-A}
		\mathcal{A}_{p_1, p_2}(r,\lambda) = \left\{A \in \mathbb{R}^{p_1\times p_2}: \rank(A) = r, \sigma_r(A) \geq \lambda\right\}.
	\end{equation} 

	\begin{Theorem}[Upper bound]\label{th:upper_bound}
		Assume $ m_1 \wedge m_2 \geq Cr\log(er), p_1 \wedge p_2 \geq m_1 \vee m_2$.  Suppose we uniformly randomly observe $m_1$ rows and $m_2$ columns from $A$ with possible noise, and there are possible missing values in $Y_{(11)}, Y_{(12)}, Y_{(21)}$. Assume Conditions \ref{con:sub-gaussian}, \ref{con:low-rank-incoherence} and \ref{con:missingness} are met, $r_0$ is selected as \eqref{eq:selection of r_0} \eqref{eq:theta_0_tau} in Supplementary Materials, then there exists a constant $C_{gap}, \eta > 0$ such that the proposed estimator in Algorithm \ref{al:procedure} yields the following rate of convergence for $\lambda = C \left(\frac{p_1p_2\log(p_1\vee p_2)}{\theta_0(m_1\wedge m_2)}\right)^{1/2}$ with $C> C_{gap}$,
		\begin{equation}\label{ineq:upper_bound}
			\sup_{A\in \mathcal{A}_{p_1, p_2}\left(r, \lambda\right)}\E \|\hat A - A\|^2 \leq C \frac{p_1p_2\log (p_1\vee p_2)}{\theta_{0}(m_1\wedge m_2)},
		\end{equation}
		\begin{equation}
			\sup_{A\in \mathcal{A}_{p_1, p_2}\left(r, \lambda\right)}\E \|\hat A - A\|_F^2 \leq C \frac{p_1p_2r\log (p_1\vee p_2)}{\theta_{0}(m_1\wedge m_2)}.
		\end{equation}
		Moreover, when there is no sporadic missingness, i.e. $\theta_0=1$, we have the following sharper upper bound,
		\begin{equation}\label{ineq:upper_bound_no_sporadic}
			\sup_{A\in \mathcal{A}_{p_1, p_2}\left(r, \lambda\right)}\E \|\hat A - A\|^2 \leq C \frac{p_1p_2}{m_1\wedge m_2},
		\end{equation}
		\begin{equation}\label{ineq:upper_bound_no_sporadic_F}
			\sup_{A\in \mathcal{A}_{p_1, p_2}\left(r, \lambda\right)}\E \|\hat A - A\|_F^2 \leq C \frac{p_1p_2r}{m_1\wedge m_2}.
		\end{equation}
	\end{Theorem}

	Additionally, the result in Theorem \ref{th:upper_bound} is nearly rate-optimal as we have the following lower bound result.
	\begin{Theorem}[Lower bound]\label{th:lower_bound} Suppose $m_1\wedge m_2 \geq Cr\log(er); p_1 \wedge p_2 \geq 2(m_1 \vee m_2)$, $\Omega_1\subseteq \{1,\ldots, p_1\}$, $\Omega_2\subseteq\{1,\ldots, p_2\}$, such that $|\Omega_1| = m_1, |\Omega_2| = m_2$. $Y_{(11)}$, $Y_{(12)}$, and $Y_{(21)}$ are defined as \eqref{eq:Y_block}. When $\lambda = c_{gap}\left(\frac{p_1p_2}{\theta_0(m_1\wedge m_2)}\right)^{1/2}$, we have the lower bound result in the class of low-rank matrices $\tilde{\mathcal{A}}_{p_1,p_2}(r,\lambda)$:
		\begin{equation}\label{ineq:lower_bound}
			\inf_{\hat{A}} \sup_{\substack{A\in \tilde{\mathcal{A}}_{p_1, p_2}(r,\lambda)}} \E \|\hat{A} - A\|^2 \geq c\frac{p_1p_2}{\theta_{0}(m_1\wedge m_2)},\quad 
			\inf_{\hat{A}} \sup_{\substack{A\in \tilde{\mathcal{A}}_{p_1, p_2}(r,\lambda)}} \E \|\hat{A} - A\|_F^2 \geq c\frac{p_1p_2r}{\theta_{0}(m_1\wedge m_2)}.
		\end{equation}	
		where $\tilde{\mathcal{A}}_{p_1,p_2}(r,\lambda)$ is the class of matrices $\mathcal{A}_{p_1,p_2}(r,\lambda)$ satisfying Conditions \ref{con:sub-gaussian}, \ref{con:low-rank-incoherence}, and \ref{con:missingness}	

		Moreover, there exists uniform small constant $c_{gap}, c>0$, such that the following lower bound holds for the class of low-rank matrices,
		\begin{equation}\label{ineq:lower_bound_2}
			\inf_{\hat{A}} \sup_{A\in \tilde{\mathcal{A}}_{p_1, p_2}(r,\lambda)} \E \frac{\|\hat{A} - A\|^2}{\|A\|} \geq c,\quad 
			\inf_{\hat{A}} \sup_{ A\in \tilde{\mathcal{A}}_{p_1, p_2}(r,\lambda)} \E \frac{\|\hat{A} - A\|_F^2}{\|A\|_F} \geq c.
		\end{equation}


	\end{Theorem}

	\begin{remark}
		Theorem \ref{th:lower_bound} provides critical lower bound support for Theorem \ref{th:upper_bound} in two aspects: 
		first, inequality \eqref{ineq:lower_bound} demonstrates that the proposed procedure in Algorithm \ref{al:procedure} achieves rate-optimality within the given class of low-rank matrices. This confirms the statistical optimality of the method in recovering structured and sporadically missing data. Second, inequality \eqref{ineq:lower_bound_2} underscores the importance of the singular value gap condition on $\sigma_r(A)$ in the theoretical analysis for the upper bound. Failure to satisfy this condition may result in inconsistent estimates, highlighting its necessity for reliable matrix completion.
	\end{remark}

	\begin{remark}
		It is worth noting that the proposed procedure becomes a more general version of Singular Value Thresholding (SVT) for matrix completion \citep{chatterjee2015matrix} when there is no structural missingness (i.e., $m_1 = p_1$ and $m_2 = p_2$). Besides, our method reduces to structured matrix completion \citep{cai2016structured} when there is no sporadic missingness (i.e., $\Theta_{ij} = 1$), and to hard singular value thresholding (HSVT) for matrix denoising \citep{candes2013unbiased, donoho2014minimax, gavish2014optimal} when there are no missing values at all (i.e., $m_1 = p_1$, $m_2 = p_2$, and $\Theta_{ij} = 1$).
		We briefly compare them in theoretical performance here.
		\begin{itemize}
			\item When there are no sporadic missingness, i.e. $\theta_0 = 1$, the proposed method and theoretical analysis yields the following upper bound
			\[
			\E \|\hat{A} - A\|^2 \leq \frac{Cp_1p_2}{m_1\wedge m_2}.
			\]
			This result outperforms the one in Corollary 1 in \cite{cai2016structured}, which only yields $\E\|\hat{A} - A\|^2 \leq \frac{Cp_1p_2(p_1\vee p_2)}{m_1m_2}$ with high probability if we treat $Y$ as the approximate rank-$r$ matrix.
			\item When there are no structural missingness, i.e. $m_1 = p_1, m_2 = p_2$, the proposed method and theoretical analysis lead to
			\[
			\E\|\hat{A} - A\|_F^2 \leq \frac{(p_1\vee p_2)r\log(p_1\vee p_2)}{\theta_0}.
			\]
			Compared with the result in \cite{chatterjee2015matrix}, an additional logarithm terms appear in the upper bound since we impose a weaker sub-Gaussian norm bound (as described in Condition \ref{con:sub-gaussian}) comparing to their uniform boundedness condition ($|Y_{ij}|\leq M$ almost surely).
			\item When there are neither sporadic or structural missingness, we have
			\[
			\E\|\hat{A} - A\|_F^2 \leq Cr(p_1\vee p_2), 
			\]
			which is of the same rate as in \cite{donoho2014minimax,gavish2014optimal}.
		\end{itemize}
	\end{remark}

	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\section{Proofs}
	\label{sec.proofs}
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

	We collect the technical proofs to the main results of the paper in this section.
	\subsection{Proof of Theorem \ref{th:upper_bound}.} 

	There are two options when implementing Algorithm \ref{al:procedure}, here we focus on the row thresholding situation as the other case be derived similarly by symmetry. We plan to prove the theorem by steps. 

	\noindent (\emph{Step 1}) 
	We define $U_{(1)} = U_{[\Omega_1, :]}$, $V_{(1)} = V_{[\Omega_2, :]}$. For the rest of the proof, we assume that the following inequalities hold,
	\begin{equation}\label{ineq:assumption1_th1}
		\sigma_{r}(U_{(1)}) \geq 3/4(m_1/p_1)^{1/2},\quad \sigma_r(U_{(2)}) \geq 3/4(m_2/p_2)^{1/2},
	\end{equation}
	\begin{equation}\label{ineq:assumption1_th2}
		\left\|\tilde{Y}_{(11)} - A_{(11)}\right\| \leq \frac{9}{80}\left( \frac{C_{gap}(m_1+m_2)\log m}{\theta_0}\right)^{1/2},
	\end{equation}
	\begin{equation}\label{ineq:assumption1_th3}
		\left\|\tilde{Y}_{(\bullet 1)} - A_{(\bullet 1)}\right\| \leq  \frac{1}{10}\left(\frac{C_{gap}(p_1+m_2)\log p}{\theta_0}\right)^{1/2},
	\end{equation}
	\begin{equation}\label{ineq:assumption1_th4}
		\left\|\tilde{Y}_{(1 \bullet)} - A_{(1 \bullet)}\right\| \leq  \frac{1}{10}\left(\frac{C_{gap}(m_1+p_2)\log p}{\theta_0}\right)^{1/2}.
	\end{equation}

	\noindent (\emph{Step 2}) With Assumptions \eqref{ineq:assumption1_th1} - \eqref{ineq:assumption1_th4}, in this step we prove that $\hat{r} \geq r$, i.e. the stopping criterion is met when $s = r$. We only need to show that
	\begin{equation}\label{eq:B_{21, r}B_{11, r}^-1}
		\begin{split}
			\left\|B_{21, [:, 1:r]} B_{11, [1:r, 1:r]}^{-1} \right\| \leq 2\sqrt{p_1/m_1}.
		\end{split}
	\end{equation}
	First, we shall note that $A_{(11)} = U_{(1)}\Sigma V_{(1)}^\top, A_{(1\bullet)} = U_{(1)}\Sigma V^\top$, and $A_{(\bullet 1)}U\Sigma V_{(1)}^\top$, \eqref{ineq:assumption1_th1} -- \eqref{ineq:assumption1_th4} and Lemma 4 in \cite{zhang2016cross} imply that
	\begin{equation}\label{ineq:sigma_r_A_11}
		\begin{split}
			\sigma_{r}(A_{(11)}) \geq & \sigma_r(U_{(1)}\Sigma_{(1)}) \sigma_r(U_{(1)}^\top) \geq \sigma_{\min}(U_{(1)})\sigma_{\min}(\Sigma)\sigma_{\min}(V_{(1)}) \\
			\geq & \frac{9}{16}\cdot \left(\frac{m_1m_2}{p_1p_2}\right)^{1/2} \cdot \left(C_{gap}\log p\left(\frac{p_1p_2}{m_1\theta_0} + \frac{p_1p_2}{m_2\theta_0}\right)\right)^{1/2}\\
			\geq & \frac{9}{16} \left(\frac{C_{gap}\log p(m_1 + m_2)}{\theta_0}\right)^{1/2}\\
			\geq & \frac{1}{5} \left\|\tilde{Y}_{(11)} - A_{(11)}\right\|.
		\end{split}
	\end{equation}
	Similarly one can also show that
	\begin{equation}\label{ineq:sigma_r_A_bullet1}
		\begin{split}
			& \sigma_r(A_{(\bullet 1)}) \geq \frac{3}{4} \left(\frac{C_{gap}(p_1+m_2)\log p}{\theta_0}\right)^{1/2} \geq \frac{1}{5}\|\tilde{Y}_{(\bullet 1)} - A_{(\bullet 1)}\|,\\ 
			& \sigma_r(A_{(1 \bullet)}) \geq \frac{3}{4} \left(\frac{C_{gap}(m_1+p_2)\log p}{\theta_0}\right)^{1/2} \geq \frac{1}{5}\|\tilde{Y}_{(1 \bullet)} - A_{(1 \bullet)}\|.
		\end{split}
	\end{equation}
	Since $\rank(A_{(1\bullet)}) = \rank(A_{(\bullet1)}) = r$, we also have
	\begin{equation*}
		\begin{split}
			& \sigma_{r+1}(\tilde{Y}_{(\bullet 1)}) = \min_{\rank(M) \leq r} \|\tilde{Y}_{(\bullet 1)} - M\| \leq \|\tilde{Y}_{(\bullet 1)} - A_{(\bullet 1)}\|,\\
			& \sigma_{r+1}(\tilde{Y}_{(1 \bullet)}) = \min_{\rank(M) \leq r} \|\tilde{Y}_{(1 \bullet)} - M\| \leq \|\tilde{Y}_{(1 \bullet)} - A_{(1 \bullet)}\|.
		\end{split}
	\end{equation*}
	Denote $K\in \mathbb{O}_{m_1, r}, L\in \mathbb{O}_{m_2, r}$ as the left and right singular vectors of $A_{(11)}$, respectively. Clearly, $K, L$ are also the left singular subspace of $A_{(1\bullet)}$ and the right singular subspace fo $A_{(\bullet 1)}$, respectively. Also, we denote $\hat{K} = U^{(1)}_{[:, 1:r]}$ and $\hat{L} = V^{(2)}_{[:, 1:r]}$ as the first $r$ left and right singular vectors of $\tilde{Y}_{(1\bullet)}$ and $\tilde{Y}_{(\bullet  1)}$, respectively. By the perturbation bound (Proposition 1 in \cite{cai2017rate}), we have the following upper bound for $K$ and the first $r$ columns of $\hat{K}$,
	\begin{equation*}
		\left(1 - \sigma_{\min}^2(\hat{K}^\top K)\right)^{1/2} = \left\|\sin\Theta(\hat{K}, K)\right\|\leq \frac{\sigma_{r}(A_{(1\bullet)})\|\tilde{Y}_{(1\bullet)} - A_{(1\bullet)}\|}{\sigma_r^2(A_{(1\bullet)}) - \sigma_{r+1}^2(\tilde{Y}_{(1\bullet)})} \leq \frac{1/5 \cdot 1/5}{1 - 1/5^2} = \frac{1}{24}, 
	\end{equation*}
	which means $\sigma_{\min}\left(\hat{K}^\top K\right) \geq \sqrt{575/576}$. Similarly we can also show that $\sigma_{\min}\left(\hat{L}^\top L\right) \geq \sqrt{575/576}$. 

	Now we consider the following decomposition for $B_{11, [1:r, 1:r]}$ and $B_{\bullet 1, [:, 1:r]}$. According to the definition of $B_{11}$ in the proposed procedure,
	\begin{equation}\label{eq:def_bar-A}
		\begin{split}
			B_{11, [1:r, 1:r]} = & \hat{K}^\top \tilde{Y}_{(11)} \hat{L} = \hat{K}^\top A_{(11)} \hat{L} + \hat{K}^\top \left(\tilde{Y}_{(11)} - A_{(11)}\right)\hat{L} :=  \bar{A}_{(11)} + \bar{Z}_{(11)},\\
			B_{\bullet 1, [:, 1:r]} = & Y_{(\bullet 1)}\hat{L} = A_{(\bullet 1)} \hat{L} + (\tilde{Y}_{(\bullet 1)} - A_{(\bullet 1)})\hat{L} := \bar{A}_{(\bullet 1)} + \bar{Z}_{(\bullet 1)}.
		\end{split}
	\end{equation}
	For $\bar{A}_{(11)}, \bar{Z}_{(11)}, \bar{A}_{(\bullet1)}$, and $\bar{Z}_{(\bullet1)}$, we have
	\begin{equation*}
		\begin{split}
			\sigma_r\left(\bar{A}_{(11)}\right) = & \sigma_{r}\left(\hat{K}^\top A_{(11)}\hat{L}\right) = \sigma_{r}\left(\hat{K}^\top K K^\top A_{(11)} L L^\top \hat{L}\right)\\
			\geq & \sigma_{\min}(\hat{K}^\top K) \sigma_r(K^\top A_{(11)}L)\sigma_{\min}(L^\top \hat{L})\geq \frac{575}{576}\sigma_r(A_{(11)}),
		\end{split}
	\end{equation*}
	\begin{equation}\label{ineq:bar_Z11_bar_A11}
		\|\bar{Z}_{11}\| \leq \|\tilde{Y}_{(11)} - A_{(11)}\| \leq \frac{1}{5} \sigma_r(A_{(11)}),
	\end{equation}
	\begin{equation}\label{ineq:bar_Z_upper_bound}
		\|\bar{Z}_{(\bullet 1)}\| \leq \|\tilde{Y}_{(\bullet 1)} - Z_{(\bullet 1)}\| \overset{\eqref{ineq:assumption1_th3}}{\leq} \frac{1}{10}\left(\frac{C_{gap} (p_1 + m_2) \log p}{\theta_0}\right)^{1/2} \overset{\eqref{ineq:sigma_r_A_11}}{\leq}\frac{8}{45}\sqrt{\frac{p_1}{m_1}}\sigma_{r}(A_{(11)}).
	\end{equation}
	\begin{equation*}
		\begin{split}
			\bar{A}_{(\bullet 1)}\bar{A}_{(11)}^{-1} = & A_{(\bullet 1)} \hat{L}\left(\hat{K}^\top A_{(11)} \hat{L}\right)^{-1} = U\Sigma V_{(1)}^\top \hat{L} \left(\hat{K}^\top U_{(1)} \Sigma V_{(1)}^\top \hat{L}\right)^{-1}\\
			= & U\Sigma V_{(1)}^\top \hat{L}\left(V_{(1)}^\top \hat{L}_{[:, 1:r]}\right)^{-1} \Sigma^{-1} \left(\hat{K}^\top U_{(1)}\right)^{-1}\\
			= & U \left(\hat{K}^\top \mathbb{P}_K U_{(1)}\right)^{-1} \quad \text{since $U_{(1)}$  and $K$ share the same column space}\\
			\leq & U(K^\top U_{(1)})^{-1} (\hat{K}^\top K)^{-1} 
		\end{split}
	\end{equation*}
	Thus, 
	\begin{equation}\label{ineq:bar_A_bar_A_11_inverse}
		\|\bar{A}_{(\bullet 1)} \bar{A}_{(11)}^{-1}\| \leq \sigma_{\min}^{-1}(U_{(1)}) \sigma_{\min}^{-1} (\hat{K}^\top K) \leq 4/3\cdot \sqrt{575/576} \cdot (p_1/m_1)^{1/2}.
	\end{equation}
	Similarly we also 
	\begin{equation}\label{ineq:bar_A1bullet_bar_A_11_inverse}
		\|\bar{A}_{(11)}^{-1}\bar{A}_{(1\bullet)} \| \leq 4/3\cdot \sqrt{575/576} \cdot (p_2/m_2)^{1/2}.
	\end{equation}
	Now we are ready to verify \eqref{eq:B_{21, r}B_{11, r}^-1},
	\begin{equation*}
		\begin{split}
			& \left\|B_{\bullet 1, [:, 1:r]} B_{11, [1:r, 1:r]}^{-1}\right\| = \left\|(\bar{A}_{(\bullet 1)} + \bar{Z}_{\bullet 1})(\bar{A}_{(11)} + \bar{Z}_{11})^{-1}\right\|\\
			\leq & \left\|\bar{A}_{(\bullet 1)}(\bar{A}_{(11)} + \bar{Z}_{11})^{-1}\right\| + \left\|\bar{Z}_{\bullet 1}(\bar{A}_{(11)} + \bar{Z}_{11})^{-1}\right\|\\
			\leq & \left\|\bar{A}_{(\bullet 1)}\bar{A}_{(11)}^{-1}\left(I - \bar{Z}_{(11)}(\bar{A}_{(11)} + \bar{Z}_{11})^{-1}\right)\right\| + \|\bar{Z}_{(\bullet 1)}\| \cdot \left(\sigma_{\min}(\bar{A}_{(11)}) - \|\bar{Z}_{11}\|\right)^{-1}\\
			\overset{\eqref{ineq:bar_Z_upper_bound}\eqref{ineq:bar_Z11_bar_A11}}{\leq} & \left\|\bar{A}_{(\bullet 1)}\bar{A}_{(11)}^{-1}\right\| \cdot \left(1 + \|\bar{Z}_{(11)}\| \cdot \left(\sigma_{\min}(\bar{A}_{(11)}) - \|\bar{Z}_{11}\|\right)^{-1}\right)\\
			& + \frac{4}{15}\sqrt{\frac{p_1}{m_1}}\sigma_{r}(A_{(11)}) \cdot \sigma_{r}^{-1}(A_{(11)})\left(\frac{575}{576}-\frac{1}{5}\right)^{-1}  \\
			\overset{\eqref{ineq:bar_A_bar_A_11_inverse}}{\leq} & \frac{4}{3}\left(\frac{575}{576}\right)^{1/2} \sqrt{\frac{p_1}{m_1}} \left(1 +\frac{1}{5} \left(\frac{575}{576} - \frac{1}{5}\right)^{-1}\right) + \frac{8}{45}\sqrt{\frac{p_1}{m_1}}\left(\frac{575}{576}-\frac{1}{5}\right)^{-1}\\
			\leq & 2 \sqrt{\frac{p_1}{m_1}}.
		\end{split}
	\end{equation*}
	Note that $B_{21, [:, 1:r]} B_{11, [1:r, 1:r]}^{-1}$ is a sub-matrix of $B_{\bullet 1, [:, 1:r]} B_{11, [1:r, 1:r]}^{-1}$, so that $\|B_{21, [:, 1:r]} B_{11, [1:r, 1:r]}^{-1}\| \leq \|B_{\bullet 1, [:, 1:r]} B_{11, [1:r, 1:r]}^{-1}\|$, and we have finished the proof for \eqref{eq:B_{21, r}B_{11, r}^-1}. Based on the definition of the iterative algorithm, we must have $\hat{r} \geq r$.

	\ \par

	\noindent (\emph{Step 3}) In order to analyze the upper bound for $\|\hat{A} - A\|$, we introduce the following notations
	\begin{equation*}
		\begin{split}
			& B_L = B_{21, [:, 1:\hat{r}]} = \tilde{Y}_{(\bullet 1)} V^{(2)\top}_{[1:\hat{r}, :]} \in \mathbb{R}^{(p_1-m_1)\times \hat{r}}, \quad B_R = B_{12, [:, 1:\hat{r}]} =  U^{(1)}_{[1:\hat{r}, :]}\tilde{Y}_{1\bullet}\in \mathbb{R}^{\hat{r}\times (p_2-m_2)}\\
			& B_M = B_{11, [1:\hat{r}, 1:\hat{r}]} = U^{(1)}_{[1:\hat{r}, :]}\tilde{Y}_{11}V^{(2)\top}_{[1:\hat{r}, :]} \in \mathbb{R}^{\hat{r}\times \hat{r}};
		\end{split}
	\end{equation*}
	\begin{equation*}
		\begin{split}
			& A_L = A_{(21)} V^{(2)\top}_{[1:r, :]} \in \mathbb{R}^{(p_1-m_1)\times r}, \quad A_R =   U^{(1)}_{[1:r, :]}A_{(12), [1:r, 1:r]}\in \mathbb{R}^{r\times p_2}\\
			& A_M = U^{(1)}_{[1:r, :]}A_{(11), [1:r, 1:r]}V^{(2)\top}_{[1:r, :]} \in \mathbb{R}^{r\times r}.
		\end{split}
	\end{equation*}
	\begin{equation*}
		\tilde{A}_L = 
		\begin{bmatrix}
			A_L & 0_{p_1\times (\hat{r} - r)}
		\end{bmatrix},\quad \tilde{A}_M = \begin{bmatrix}
			A_M & 0_{r \times (\hat{r} - r)}\\
			0_{(\hat{r} - r)\times r} & 0_{(\hat{r} - r)\times(\hat{r} - r)}
		\end{bmatrix}, \quad \tilde{A}_R = \begin{bmatrix}
			A_R\\
			0_{(\hat{r} - r)\times p_2}
		\end{bmatrix}
	\end{equation*}
	With the assumption \eqref{ineq:assumption1_th1} -- \eqref{ineq:assumption1_th4} and the intermediate conclusion that $\hat{r} \geq r$, in this step, we plan to prove the following inequalities and then apply Lemma \ref{lm:A_LA_MA_R-Y_LY_MY_R} to develop the upper bound of \eqref{ineq:upper_bound}: 
	\begin{equation}\label{ineq:to-be-prove-1}
		\|\tilde{A}_L - B_L\| \leq C\left(\log p \left(\frac{p_1+m_2}{\theta_0}\right)\right)^{1/2}, \quad \|\tilde{A}_R - B_R\| \leq C\left(\log p \left(\frac{p_2+m_1}{\theta_0}\right)\right)^{1/2},
	\end{equation}
	\begin{equation}\label{ineq:to-be-prove-2}
		\|\tilde{A}_M - B_M\| \leq C\left(\log m \left(\frac{m_1+m_2}{\theta_0}\right)\right)^{1/2}, \quad \|\tilde{A}_M - B_M\| \leq \frac{1}{4}\sigma_{\min}(A_M).
	\end{equation}
	\begin{equation}\label{ineq:to-be-prove-3}
		\|A_LA_M^{-1}\| \leq 2\sqrt{\frac{p_1}{m_1}}, \quad \|B_LB_M^{-1}\| \leq 2\sqrt{\frac{p_1}{m_1}},\quad \|A_M^{-1}A_R\| \leq 2\sqrt{\frac{p_2}{m_2}}.
	\end{equation}
	For the first part of \eqref{ineq:to-be-prove-1}, we have
	\begin{equation*}
		\begin{split}
			& \left\|\tilde{A}_L  - B_L\right\| = \left\|\begin{bmatrix}
				\left(\tilde{Y}_{(21)} - A_{(21)}\right)\hat{L} & \tilde{Y}_{(21)} V^{(2)}_{[(r+1):\hat{r}, :]}
			\end{bmatrix}
			\right\|\\
			\leq & \left(\|\tilde{Y}_{(21)} - A_{(21)}\|^2 + \|\tilde{Y}_{(\bullet 1)} V^{(2)}_{[(r+1):\hat{r}, :]}\|^2 \right)^{1/2}\leq \left(\|\tilde{Y}_{(21)} - A_{(21)}\|^2 + \sigma_{r+1}^2(\tilde{Y}_{(\bullet 1)}) \right)^{1/2}\\
			\leq & \left(\|\tilde{Y}_{(\bullet 1)} - A_{(\bullet 1)}\|^2 + \|\tilde{Y}_{(\bullet 1)} V^{(2)}_{[(r+1):\hat{r}, :]}\|^2 \right)^{1/2}\leq \left(\|\tilde{Y}_{(21)} - A_{(21)}\|^2 + \|\tilde{Y}_{(21)} - A_{(21)}\|^2 \right)^{1/2}\\
			\overset{\eqref{ineq:assumption1_th3}}{\leq} & C\left(\frac{(p_1+m_2)\log p}{\theta_0}\right)^{1/2}
		\end{split}
	\end{equation*}
	The second part of \eqref{ineq:to-be-prove-1} and \eqref{ineq:to-be-prove-2} can be proved similarly. Next, $A_L, A_M$ are exactly $\bar{A}_{(21)}$ and $\bar{A}_{(11)}$ defined as \eqref{eq:def_bar-A}, thus $\|A_L A_M^{-1}\| \leq 2\sqrt{p_1/m_1}$. Similarly, $\|A_M^{-1} A_R\| \leq 2\sqrt{p_2/m_2}$. By the statement of assumption, we also know that $\|B_LB_M^{-1}\| = \|B_{21, [:, 1:\hat{r}]}B_{11, [:, 1:\hat{r}]}^{-1}\|\leq 2\sqrt{p_1/m_1}$. Therefore we have proved \eqref{ineq:to-be-prove-3}.

	\ \par

	\noindent (\emph{Step 4}) Combining \eqref{ineq:to-be-prove-1}, \eqref{ineq:to-be-prove-2}, and \eqref{ineq:to-be-prove-3}, Lemma \ref{lm:A_LA_MA_R-Y_LY_MY_R} implies 
	$$\|B_LB_M^{-1} B_R - A_L A_M^{-1} A_R\| \leq C\left(\frac{\log p}{\theta_0}\left(\frac{p_1p_2}{m_1}+\frac{p_1p_2}{m_2}\right)\right)^{1/2}.$$ 
	Note that $B_LB_M^{-1} B_R = \hat{A}_{(22)}$, also $A_L A_M^{-1} A_R = A_{(22)}$ by Theorem 1 in \cite{cai2016structured}. we have proved the following upper bound for $\hat{A}_{(22)} - A_{(22)}$,
	$$\|\hat{A}_{(22)} - A_{(22)}\| \leq C\left(\frac{\log p}{\theta_0}\left(\frac{p_1p_2}{m_1}+\frac{p_1p_2}{m_2}\right)\right)^{1/2}.$$ 
	Now it remains to consider the error bound $\hat{A}_{(21)} - A_{(21)}$, $\hat{A}_{(12)} - A_{(12)}$, and $\hat{A}_{(11)} - A_{(11)}$. In fact,
	\begin{equation*}
		\begin{split}
			& \|\hat{A}_{(21)} - A_{(21)}\| = \left\|\tilde{Y}_{(21)} V^{(2)}_{[:, 1:\hat{r}]}V^{(2)\top}_{[:, 1:\hat{r}]} - A_{(21)}\right\|\\
			= & \left\|\tilde{Y}_{(21)} - A_{(21)} + \tilde{Y}_{(21)} V^{(2)}_{[:, \hat{r}+1:m_2]}V^{(2)\top}_{[:, \hat{r}+1:m_2]} \right\|\\
			\leq & \|\tilde{Y}_{(21)} - A_{(21)}\| + \|\sigma_{r+1}(\tilde{Y}_{(\bullet 1)}) \|\leq 2 \|\tilde{Y}_{(21)} - A_{(21)}\| \leq C\left(\frac{\log p}{\theta} (p_1+m_2)\right).
		\end{split}
	\end{equation*}
	We can similarly derive the upper bound for $\hat{A}_{(12)} - A_{(12)}$ and $\hat{A}_{(11)} - A_{(11)}$. To sum up, under the assumptions \eqref{ineq:assumption1_th1}--\eqref{ineq:assumption1_th4}, one can prove that
	$$\|\hat{A} - A\| \leq C\left(\frac{\log p}{\theta_0}\left(\frac{p_1p_2}{m_1}+\frac{p_1p_2}{m_2}\right)\right)^{1/2}.$$ 
	for some uniform constant $C>0$.

	\ \par

	\noindent (\emph{Step 5}) In this final step, we analyze the probability that \eqref{ineq:assumption1_th1} - \eqref{ineq:assumption1_th4} hold. By Lemma \ref{lm:tilde_Y_perturbation}, \eqref{ineq:assumption1_th2} - \eqref{ineq:assumption1_th4} hold with probability at least $1 - m_1^\alpha - m_2^{\alpha}$ provided large enough $C_{gap}$. By Lemma \ref{lm:U_Omega_upper_lower_bound}, \eqref{ineq:assumption1_th1} holds with probability $1 - 2r\exp(-m_1/(64\rho r)) - 2r\exp(-m_2/(64\rho r))$. By Condition 1, i.e. sub-Gaussian observations, $|A_{ij}| = |EY_{ij}| \leq E|Y_{ij}| \leq \tau$, thus $\|A\|_F^2 \leq p_1p_2\tau^2$. On the other hand, since $\rank(A) = r$, $\|A\|_F^2 \geq r\sigma_{\min}^2(A) = C_{gap}\left(\frac{rp_1p_2}{m_1} + \frac{rp_1p_2}{m_2}\right)\log p$, thus we have $C_{gap} \log p\left(\frac{r}{m_1} + \frac{r}{m_2}\right) \leq 1,$ which implies $\min\{m_1/r, m_2/r\} \geq C_{gap} \log p$. Note that $p \geq r$,thus for large enough constant $C_{gap}$, we have
	$$1 - 2r\exp(-m_1/(64\rho r)) - 2r\exp(-m_2/(64\rho r)) \geq 1 - 4r \exp\left(\frac{C_{gap}\log p}{64\rho}\right) \geq 1 - Cp^{-\alpha}.$$
	In summary, 
	\begin{equation}
		P\left(\text{\eqref{ineq:assumption1_th1} - \eqref{ineq:assumption1_th4} all hold} \right) \geq 1 - Cp^{-\alpha}
	\end{equation}
	for some constant $C, \alpha>0$. \quad $\square$

	\subsection{Proof of Theorem \ref{th:lower_bound}.} 

	For better presentation, we prove this theorem by steps.

	\begin{enumerate}[leftmargin=*]

		\item In this step, we construct a series of $A^{(k)}\in \mathbb{R}^{p_1\times p_2}$. Without loss of generality, assume $\Omega_1 = \{1:m_1\}$, $\Omega_2 = \{1:m_2\}$. Let $r = 1$ and generate $A_0 = \frac{1}{2} 1_{p_1} 1_{p_2}^\top$, and randomly generate $\mu^{(k)} \in \mathbb{R}^{p_1}$ such that
		$$\mu^{(k)}_{[1:m_1]} = 1, \quad \mu^{(k)}_{[(m_1+1): p_1]} \overset{iid}{\sim} \left\{\begin{array}{ll}
			1 , & \text{with probability } \frac{1}{2};\\
			-1, &  \text{with probability } \frac{1}{2}.
		\end{array}\right. $$ 
		Then we construct
		\begin{equation*}
			A^{(k)} = A_0 + \lambda\mu^{(k)} 1_{p_2}^\top, \quad k = 1,\ldots, N,
		\end{equation*}
		where $\lambda>0$ is some constant to be determined later. Based on this construction, we can see for $k\neq l$,
		\begin{equation*}
			\mu^{(k)} - \mu^{(l)} = \sum_{i=m_1+1}^{p_1} \left(\mu^{(k)}_i - \mu^{(l)}_i\right)^2, \quad \left(\mu^{(k)}_i - \mu^{(l)}_i\right)\overset{iid}{\sim} \left\{\begin{array}{ll}
				4, \quad \text{w. p. } \frac{1}{2},\\
				0, \quad \text{w. p. } \frac{1}{2},\\
			\end{array}\right. \quad m_1+1 \leq i \leq p_1.
		\end{equation*}
		By Bernstein's inequality,
		\begin{equation}
			\begin{split}
				& P\left(\left\|\mu^{(k)} - \mu^{(l)}\right\|_2^2 \geq 3(p_1-m_1) \text{ or } \left\|\mu^{(k)} - \mu^{(l)}\right\|_2^2 \leq (p_1-m_1)\right)\\
				= & P\left(\left|\sum_{i=1}^{p_1} \left\{\left(\mu^{(k)}_i - \mu^{(l)}_i\right)^2 - 2\right\}\right| \geq (p_1-m_1) \right)\\
				\leq & 2\exp\left(- \frac{(p_1-m_1)^2/2}{4(p_1-m_1) + \frac{2}{3}p_2}\right) = 2\exp\left(-3(p_1-m_1)/28\right).
			\end{split}
		\end{equation}
		Therefore, whenever $N < \frac{1}{2}\exp(3(p_1-m_1)/28)$, there is a positive probability that 
		\begin{equation}\label{ineq:condition_mu^k_mu^l}
			p_1-m_1\leq \min_{1\leq k < l \leq N}\left\{\|\mu^{(k)} - \mu^{(l)}\|_2^2\right\} \leq \max_{1\leq k < l \leq N}\left\{\|\mu^{(k)} - \mu^{(l)}\|_2^2\right\} \leq  3(p_1-m_1),
		\end{equation}
		which means there exist a set of fixed $\{\mu^{(k)}\}_{k=1}^{N}$ such that \eqref{ineq:condition_mu^k_mu^l} holds. For the rest of the proof, we suppose $\{\mu^{(1)},\ldots, \mu^{(N)}\}$ are such choice, and $N = \lceil \frac{1}{2}\exp\left(3(p_1 - m_1)/28\right)\rceil - 1$. 

		\item Next, we construct the observations $Y^{(k)}\odot M^{(k)}$. We specifically set all entries of $\Theta_{(11)}$ and $\Theta_{(12)}$ to be 1, all entries of $\Theta_{(22)} = 0$, and all entries of $\Theta_{(21)}$ to be $\theta_0$. Then we construct the missingness indicators as $M_{ij} \sim \text{Bernoulli}(\Theta_{ij})$ independently, where $1\leq i \leq p_1, 1\leq j \leq p_2$, and suppose $Y^{(k)} = A^{(k)} + Z^{(k)}$, while $Z^{(k)} \overset{iid}{\sim} N(0, \frac{1}{4})$. $\{M^{(k)}\}_{k=1}^N \sim \text{Bernoulli}(\Theta)$. Our finally observations are $Y^{(k)}\odot M^{(k)}$. Moreover, we can check that $A^{(k)}$, $M^{(k)}$ and $Y^{(k)}\odot M^{(k)}$ satisfy Conditions 1, 2, 3, and 4.

		\item Now, we focus on the distribution of $Y^{(k)}\odot M^{(k)}$: $\mathcal{P}_{Y^{(k)}\odot M^{(k)}}$, where we aim to show $\mathcal{P}_{Y^{(k)}}$ are close to each other while $A^{(k)}$'s are far apart. The central technique relies on generalized Fano's lemma (see, e.g., Theorem 1 in \cite{yang1999information}).

		It is well known that the Kullback-Leibler divergence between two Gaussian vectors is 
		$$KL\left(N\left(\mu_A, \sigma^2 I\right), N\left(\mu_B, \sigma^2 I\right)\right) = \frac{1}{2\sigma^2}\left\|\mu_A - \mu_B\right\|_2^2. $$
		Then one can have the following calculation for the KL divergence of $\mathcal{P}_{\mathcal{P}_{Y^{(k)}\odot M^{(k)}}}$ and $\mathcal{P}_{Y^{(l)} \odot M^{(l)}}$ for any $1\leq k< l \leq N$,
		\begin{equation*}
			\begin{split}
				& KL\left(\mathcal{P}_{Y^{(k)}\odot M^{(k)}}, \mathcal{P}_{Y^{(l)} \odot M^{(l)}}\right) = \sum_{R \in \{0, 1\}^{p_1\times p_2}} P(M = R) \cdot KL(\mathcal{P}_{Y^{(k)}\odot R}, \mathcal{P}_{Y^{(l)}\odot R})\\
				= & \sum_{R\in \{0, 1\}^{p_1\times p_2}} P(M = R) \cdot \left\|\left(A^{(k)} - A^{(l)}\right)\odot R\right\|_F^2 \\
				= & \sum_{R\in \{0, 1\}^{p_1\times p_2}} P(M = R) \cdot \sum_{i=1}^{p_1}\sum_{j=1}^{p_2}\left(A^{(k)}_{ij} - A^{(l)}_{ij}\right)^2\cdot R_{ij}\\
				= & \sum_{i=m_1+1}^{p_1}\sum_{j=1}^{p_2} \left(A^{(k)}_{ij} - A^{(l)}_{ij}\right)^2 \E R_{ij} = \theta_0\left\|A^{(k)}_{(21)} - A^{(l)}_{(21)}\right\|_F^2\\
				= & \theta_0 \lambda^2 m_2 \|\mu_k - \mu_l\|_2^2 \leq 3\theta_0 m_2(p_1-m_1) \lambda^2.
			\end{split}
		\end{equation*}
		Here we used the fact that $A_{ij}^{(k)}$ and $A_{ij}^{(l)}$ are different only when $m_2+1\leq j \leq p_2$.

		\item Finally, we apply the generalized Fano's lemma to establish the lower bound result. For any $1\leq k < l \leq N$,
		\begin{equation}
			\begin{split}
				\left\|A^{(k)} - A^{(l)}\right\|^2 = \left\|\lambda(\mu^{(k)} - \mu^{(l)}) 1_{p_2}^\top \right\|^2 = \lambda^2 p_2 \|\mu^{(k)} - \mu^{(l)}\|_2 \geq \lambda^2 (p_1-m_1)p_2.
			\end{split}
		\end{equation}
		By generalized Fano's lemma, 
		\begin{equation}\label{ineq:generalized-Fano-intermediate}
			\inf_{\hat{A}}\max_{1\leq k \leq N} \E \|\hat{A} - A^{(k)} \| \geq \frac{\lambda^2 (p_1-m_1)p_2}{2}\left(1 - \frac{3\theta_0m_2(p_1-m_1)\lambda^2 + \log 2}{\log N}\right)
		\end{equation}
		Now we set $\lambda^2 = \frac{\frac{1}{2}\log N - \log 2}{3\theta_0m_2(p_1-m_1)}$. Whenever $m_1 \geq 25$, $p_1-m_1 \geq 2m_1 - m_2 \geq 25$, then
		$$\lambda^2 = \frac{\frac{1}{2}\log\left(\lceil \frac{1}{2}\exp(3(p_1 - m_1)/28) \rceil -1\right) - \log 2}{3\theta_0m_2(p_1-m_1)} \geq \frac{(p_1-m_1)/10}{3\theta_0m_2(p_1-m_1)} = \frac{1}{30\theta_0m_2} $$
		\eqref{ineq:generalized-Fano-intermediate} yields
		\begin{equation}
			\inf_{\hat{A}} \sup_{\substack{\text{Conditions}\\ \text{1, 2, 3, 4 are net}}} \E \|\hat{A} - A^{(k)} \| \geq \frac{\lambda^2 (p_1-m_1)p_2}{2}\cdot \frac{1}{2} \geq \frac{p_1p_2}{120m_2}.
		\end{equation}
		By symmetry, we can similarly show
		$$
		\inf_{\hat{A}} \sup_{\substack{\text{Conditions}\\ \text{1, 2, 3, 4 are net}}} \E \|\hat{A} - A^{(k)} \| \geq \frac{p_1p_2}{120 m_1}.
		$$
		Therefore, we have finished the proof of Theorem \ref{th:lower_bound}. \quad $\square$
	\end{enumerate}

	\section{Technical Lemmas}

	We collect the technical lemmas to the proofs of this paper in this section. 

	\begin{Lemma}\label{lm:rank-one-matrix-expression}
		Suppose $A\in \mathbb{R}^{m\times p}$, $\rank(A) = 1$. If $\sum_{i,j} A_{ij} \neq0$, then 
		$$A_{ij} = \left(\sum_{i'=1}^m A_{i'j}\right)\left(\sum_{j'=1}^p A_{ij'}\right)/\left(\sum_{i'j'}A_{i'j'}\right), \quad 1\leq i \leq m, 1\leq j \leq p.$$
	\end{Lemma}

	{\bf\noindent Proof of Lemma \ref{lm:rank-one-matrix-expression}.} When $A$ is of rank-1, there exist two vectors $u\in\mathbb{R}^m, v\in \mathbb{R}^p$ such that $A = uv^\top$. Since
	$$\sum_{i=1}^m\sum_{j=1}^p A_{ij} = \left(\sum_{i=1}^m u_i\right)\left(\sum_{j=1}^n v_j\right) \neq 0, $$
	we have $\sum u_i \neq 0$ or $\sum v_j \neq 0$. Therefore,
	\begin{equation*}
		\begin{split}
			\left(\sum_{i'=1}^m A_{i'j}\right)\left(\sum_{j'=1}^p A_{ij'}\right)/\left(\sum_{i'j'}A_{i'j'}\right) = \frac{u_i (\sum_{j'} v_{j'})\cdot v_j(\sum_{i'}u_{i'})}{(\sum_i u_i)\cdot(\sum_j v_j)} = u_iv_j = A_{ij},
		\end{split}
	\end{equation*}
	for all $1\leq i \leq m, 1\leq j \leq p$, which finished the proof for this lemma. \quad $\square$


	\begin{Lemma}\label{lm:tilde_Y_perturbation}
		Recall the definition of $\hat{\Theta}, \tilde{Y}$ in . Given the assumptions in the proof for Theorem \ref{th:upper_bound}, we have the following perturbation bounds for $\tilde{Y}_{(11)}$, $\tilde{Y}_{(\bullet 1)}$, and $\tilde{Y}_{(1\bullet)}$ with probability at least $1 - p^{-\alpha}$:
		\begin{equation*}
			\left\|\tilde{Y}_{(11)} - A_{(11)}\right\| \leq C\sqrt{\frac{(m_1+m_2)\log p}{\theta_0}},
		\end{equation*}
		\begin{equation*}
			\left\|\tilde{Y}_{(1\bullet)} - A_{(1\bullet)}\right\| \leq C\sqrt{\frac{(m_1+p_2)\log p}{\theta_0}},\quad \left\|\tilde{Y}_{(\bullet 1)} - A_{(\bullet 1)}\right\| \leq C\sqrt{\frac{(m_2+p_1)\log p}{\theta_0}}.
		\end{equation*}
		Furthermore, if all entries of $A_{(11)}, A_{(12)}$, and $A_{(21)}$ are observable without missing (but with possibly noise), we have the following more accurate upper bounds:
		\begin{equation*}
			\left\|\tilde{Y}_{(11)} - A_{(11)}\right\| \leq C\sqrt{\frac{m_1+m_2}{\theta_0}},
		\end{equation*}
		\begin{equation*}
			\left\|\tilde{Y}_{(1\bullet)} - A_{(1\bullet)}\right\| \leq C\sqrt{\frac{m_1+p_2}{\theta_0}},\quad \left\|\tilde{Y}_{(\bullet 1)} - A_{(\bullet 1)}\right\| \leq C\sqrt{\frac{m_2+p_1}{\theta_0}}.
		\end{equation*}
		with probability at least $1 - m_1^{-\alpha} - m_2^{-\alpha}$.
	\end{Lemma}

	{\noindent\bf Proof of Lemma \ref{lm:tilde_Y_perturbation}.} 
	For convenience, we denote $m = m_1+m_2$, $p = p_1+p_2$. First we introduce the following notations to bridge $\tilde{Y}$ and $A$:
	\begin{equation}\label{eq:def_tilde_Y^0}
		\begin{split}
			& \tilde{Y}_{ij}^0 := Y_{ij}\oslash \theta_{ij},\quad 1\leq i \leq p_1, 1\leq j\leq p_2.\\
			& \tilde{Y}_{(11)}^0 = (\tilde{Y}_{ij}^0)_{i\in \Omega_1, j\in \Omega_2}, \quad \tilde{Y}_{(12)}^0 = (\tilde{Y}_{ij}^0)_{i\in \Omega_1, j\in \Omega_2^c},\quad \tilde{Y}_{(21)}^0 = (\tilde{Y}_{ij}^0)_{i\in \Omega_1^c, j\in \Omega_2}.
		\end{split}
	\end{equation}
	Then we clearly have $\left\|\tilde{Y}_{(kl)} - A_{(kl)}\right\| \leq \left\|\tilde{Y}_{(kl)} - \tilde{Y}^0_{(kl)}\right\| + \left\|\tilde{Y}^0_{(kl)} - A_{(kl)}\right\|,$ for all $1\leq k, l\leq 2$. To develop the error bounds for $\tilde{Y}_{(11)}$, $\tilde{Y}_{(12)}$, and $\tilde{Y}_{(21)}$, it is sufficient to prove the following inequalities.
	\begin{equation}\label{ineq:Y_11^0-A_11}
		\begin{split}
			& \left\|\tilde{Y}_{(11)}^0 - A_{(11)}\right\| \leq C\sqrt{\frac{(m_1+m_2)\log p}{\theta_0}}, \\
			\left\|\tilde{Y}_{(\bullet 1)}^0 - A_{(\bullet 1)}\right\|&  \leq C\sqrt{\frac{(p_1+m_2)\log p}{\theta_0}},\quad \left\|\tilde{Y}_{(1\bullet)}^0 - A_{(1\bullet)} \right\| \leq C\sqrt{\frac{(m_1+p_2)\log p}{\theta_0}}.
		\end{split}
	\end{equation}
	\begin{equation}\label{ineq:Y_11^0-Y_11}
		\begin{split}
			& \left\|\tilde{Y}_{(11)}^0 - \tilde{Y}_{(11)}\right\| \leq \sqrt{\frac{(m_1+m_2)\log p}{\theta_0}},\\
			\left\|\tilde{Y}_{(\bullet 1)}^0 - \tilde{Y}_{(\bullet 1)}\right\|&  \leq \sqrt{\frac{(p_1+m_2)\log p}{\theta_0}},\quad \left\|\tilde{Y}_{(1\bullet)}^0 - \tilde{Y}_{(1\bullet)} \right\| \leq \sqrt{\frac{(m_1+p_2)\log p}{\theta_0}}.
		\end{split}
	\end{equation}	
	with probability at least $1 - O\left(p^{-\alpha}\right)$. 

	\begin{enumerate}[leftmargin=*]
		\item In this step, we aim to show \eqref{ineq:Y_11^0-A_11} with probability at least $1 - O(p^{-\alpha})$. We first introduce the following lemma on matrix concentration bounds provided by \cite{koltchinskii2011nuclear}.
		\begin{Proposition}[\cite{koltchinskii2011nuclear}, Proposition 2]\label{pr:matrix-concentration}
			Let $A_1,\ldots, A_n$ be independent random matrices with dimensions $p_1$-by-$p_2$ satisfying $E(A_i) = 0$ and $\|A_i\|\leq U$ almost surely for $i=1,\ldots, n$. Here $U$ is some uniform constant. Define
			$$\sigma_A = \max\left\{\left\|\frac{1}{n}\sum_{k=1}^n \E(A_kA_k^\top)\right\|^{1/2}, \left\|\frac{1}{n}\sum_{k=1}^n \E(A_k^\top A_k)\right\|^{1/2}\right\}. $$
			$$U_A^{(\alpha)} = \inf\{u>0: \E \exp(\|A\|^{\alpha}/u^\alpha) \leq 2\}, \quad \alpha \geq 1. $$
			Then for all $t>0$, with probability at least $1 - e^{-t}$ we have
			\begin{equation*}
				\left\|\frac{1}{n}\sum_{k=1}^nA_k\right\| \leq C\max\left\{\sigma_A \sqrt{\frac{t+\log(m)}{n}}, U_Z^{(\alpha)}\left(\log \frac{U_A^{(\alpha)}}{\sigma_A}\right)\frac{t+\log m}{n}\right\},
			\end{equation*}
			where $m = m_1+m_2$.
		\end{Proposition}
		Now let us consider the proof for \eqref{ineq:Y_11^0-A_11}. Denote $e_i^{(m)}$ as the $i$-th canonical basis in $m$-dimensional space, i.e. $e_i^{(m)}$ is a $m$-dimensional vector with $i$-th entry as 1 and others as 0. Then
		\begin{equation*}
			\tilde{Y}_{(11)} - A_{(11)} = \sum_{i=1}^{m_1} \sum_{j=1}^{m_2} \left(\tilde{Y}_{ij} - A_{ij}\right)e_i^{(m_1)} e_j^{(m_2)\top} := \sum_{i=1}^{m_1}\sum_{j=1}^{m_2} E_{ij},
		\end{equation*}
		where $E^{(ij)} = \left(\tilde{Y}_{ij} - A_{ij}\right)e_i^{(m_1)} e_j^{(m_2)\top} \in \mathbb{R}^{m_1\times m_2}$. For any two symmetric matrices $A, B$, we write $A \preceq B$ if and only if $B - A $ is positive semi-definite. Then
		\begin{equation*}
			\begin{split}
				& \sum_{i=1}^{m_1}\sum_{j=1}^{m_2} \E E^{(ij)} E^{(ij)\top} = \sum_{i=1}^{m_1}\sum_{j=1}^{m_2}e_i^{(m_1)}e_i^{(m_1)\top}\E(\tilde{Y}_{ij} - A_{ij})^2\\
				= & \sum_{i=1}^{m_1} e_i^{(m_1)}e_i^{(m_1)\top} \sum_{j=1}^{m_2} \left(\theta_{ij}\left(A_{ij}^2 + \sigma_{ij}^2\right) -\theta_{ij}^2A_{ij}^2 \right)/\theta_{ij}^2\\
				\preceq & \sum_{i=1}{m_1} \sum_{j=1}^{m_2} e_i^{(m_1)}e_i^{(m_1)\top} \E(A_{ij} + Z_{ij})^2 / \theta_{ij} \preceq \sum_{i=1}^{m_1} \sum_{j=1}^{m_2} e_i^{(m_1)}e_i^{(m_1)\top} \E(A_{ij} + Z_{ij})^2 / \theta_{0} \preceq \frac{m_2}{\theta_0}I_{m_1}.
			\end{split}
		\end{equation*}
		Similarly one can also show that $\sum_{i=1}^{m_1}\sum_{j=1}^{m_2} E^{(ij)\top} E^{(ij)} \preceq \frac{m_1}{\theta_0}I_{m_2}$. Moreover, 
		$$U^{(2)} = \inf\left\{u>0: \E\exp(\|E\|^2/u^2) \leq 2\right\} \leq C;$$
		$$\sigma_A = \left\|\frac{1}{m_1m_2} \sum_{i=1}^{m_1}\sum_{j=1}^{m_2} \E E^{(ij)} E^{(ij)\top}\right\| \geq \frac{c}{m_1m_2}.$$
		By Proposition \ref{pr:matrix-concentration}, where we set $n = m_1m_2$, $t = C\log(p)$, and $Z_1,\ldots, Z_n = E_{11},\ldots, E_{m_1,m_2}$ we have with probability at least $1 - p^{-\alpha}$,
		\begin{equation}
			\begin{split}
				\left\|\frac{1}{m_1m_2}\sum_{i=1}^{m_1}\sum_{j=1}^{m_2} \left(\tilde{Y}_{(11)}^{0} - A_{(11)} \right)\right\| \leq & C\max\Big\{\left(\frac{1}{m_1\theta_0} + \frac{1}{m_2\theta_0}\right)^{1/2} \cdot \sqrt{\frac{\log(p)}{m_1m_2}}, \\
				& \log\left(\frac{m_1m_2}{\theta_0}\right)\cdot \frac{\log(m_1+m_2)}{m_1m_2} \Big\}.
			\end{split}
		\end{equation}
		Therefore we have
		\begin{equation}
			\left\|\tilde{Y}_{(11)}^0 - A_{(11)}\right\|\leq  C\left(\frac{(m_1+m_2)\log p}{\theta_0}\right)^{1/2}.
		\end{equation}
		with probability at least $1 - p^{-\alpha}$. We can similarly also write down the proof for the upper bound of $\|\tilde{Y}_{(\bullet 1)}^0 - A_{(\bullet 1)}\|$ and $\|\tilde{Y}_{(1\bullet)} ^0 - A_{(1\bullet)}\|$. Thus, we have finished the proof for \eqref{ineq:Y_11^0-A_11}.

		\item We target to show \eqref{ineq:Y_11^0-Y_11} in this step. First let us focus on developing the upper bound for $\|\tilde{Y}_{(11)}^0 - \tilde{Y}_{(11)}\|$. By definition of $\tilde{Y}$ and $\tilde{Y}^0$ \eqref{eq:def_tilde_Y^0}, we have
		\begin{equation}\label{eq:tildeY^0-tildeY}
			\begin{split}
				\left\|\tilde{Y}_{(11)}^0 - \tilde{Y}_{(11)}\right\| = \left\|Y_{(11)} \odot \left(1 \oslash \hat{\Theta}_{(11)} - 1\oslash \Theta_{(11)}\right)\right\| = \left\|\tilde{Y}_{(11)}\odot \left(\Theta_{(11)}\oslash \hat{\Theta}_{(11)}- 1\right)\right\|.
			\end{split}
		\end{equation}
		For convenience, we introduce the following notation that represents the number of observed entries in each row and column and their expectation correspondingly,
		\begin{equation}\label{eq:def_M_Theta_bullet}
			\begin{split}
				& M_{i\bullet}^{(1)} = \sum_{j=1}^{p_2}M_{ij},\quad M_{\bullet j}^{(1)} = \sum_{i=1}^{m_1}M_{ij},\quad M_{\bullet \bullet}^{(1)} = \sum_{i=1}^{m_1}\sum_{j=1}^{p_2}M_{ij},\\
				& \Theta_{i\bullet}^{(1)} = \sum_{j=1}^{p_2}M_{ij},\quad \Theta_{\bullet j}^{(1)} = \sum_{i=1}^{m_1}M_{ij},\quad \Theta_{\bullet \bullet}^{(1)} = \sum_{i=1}^{m_1}\sum_{j=1}^{p_2}M_{ij}.
			\end{split}
		\end{equation}
		Particularly due to $\rank(\Theta)  =1$, it is easy to show the following fact,
		\begin{equation}
			\theta_{ij} = \frac{\Theta_{\bullet j}^{(1)}\Theta_{i\bullet}^{(1)}}{\Theta_{\bullet\bullet}^{(1)}}, \quad 1\leq i \leq m_1, 1\leq j \leq p_2.
		\end{equation}
		Since $M_{ij} \sim {\rm Bernoulli}(\theta_{ij})$, we have $\E M_{ij} = \theta_{ij}, \Var(M_{ij}) = \theta_{ij}(1-\theta_{ij})$, and $|M_{ij}-\theta_{ij}| \leq 1$. Then Bernstein's inequality yields
		\begin{equation}\label{ineq:M_bulletj_bernstein}
			P\left(M_{\bullet j}^{(1)} - \Theta^{(1)}_{\bullet j}\right) = P\left(\left|\sum_{i=1}^{m_1} M_{ij} - \sum_{i=1}^{m_1} \theta_{ij}\right| \geq t \right) \leq 2\exp\left(- \frac{t^2/2}{\sum_{i=1}^{m_1}\theta_{ij}(1-\theta_{ij}) + t/3}\right).
		\end{equation}
		Note that $\theta_{ij} \geq \frac{C_{gap}r\log p}{m_1\wedge m_2}$, we know 
		\begin{equation}\label{ineq:Theta_ibullet_lower_bound}
			\Theta_{i\bullet}^{(1)} = \sum_{j=1}^{p_2}\theta_{ij} \geq p_2\theta_0\geq C_{gap}r\log p, \quad  \Theta_{\bullet j}^{(1)} = \sum_{i=1}^{m_1}\theta_{ij} \geq m_1\theta_0 \geq C_{gap}r\log p.
		\end{equation}
		We specifically let $t = C\sqrt{\Theta_{i\bullet}^{(1)}\log p}$ for some large constant $C>0$ in \eqref{ineq:M_bulletj_bernstein}, then
		\begin{equation*}
			\begin{split}
				& P\left(|M_{i\bullet}^{(1)} - \Theta_{i\bullet}^{(1)} |\leq C\sqrt{\Theta_{i\bullet}^{(1)} \log p} \right) \geq 1 - 2\exp\left(-\frac{C^2 \Theta_{i\bullet}\log p}{\Theta_{i\bullet}^{(1)}+C\sqrt{\Theta_{i\bullet}^{(1)}\log p}/3}\right)\geq 1 - p^{-\alpha}.
			\end{split}
		\end{equation*}
		Meanwhile, we shall also note from \eqref{ineq:Theta_ibullet_lower_bound} that
		\begin{equation}\label{ineq:M_bulleti-Theta}
			|M_{i\bullet}^{(1)} - \Theta_{i\bullet}^{(1)} |\leq C\sqrt{\Theta_{i\bullet}^{(1)} \log p} \quad \Rightarrow \quad |M_{i\bullet}^{(1)} - \Theta_{i\bullet}^{(1)}| \leq \frac{1}{3}\Theta_{i\bullet}^{(1)}
		\end{equation}
		when $C_{gap}$ is a large enough constant. Similarly one can also show with probability at least $1 - p^{-\alpha}$,
		\begin{equation}\label{ineq:M_bulletj-Theta}
			|M_{\bullet j}^{(1)} - \Theta_{\bullet j}^{(1)} |\leq C\sqrt{\Theta_{\bullet j}^{(1)} \log p} \leq \frac{1}{3} \Theta_{\bullet j}^{(1)}, \quad |M_{\bullet\bullet}^{(1)} - \Theta_{\bullet\bullet}^{(1)} |\leq C\sqrt{\Theta_{\bullet\bullet}^{(1)} \log p} \leq \frac{1}{3}\Theta_{\bullet\bullet}^{(1)}. 
		\end{equation}
		Thus, with probability at least $1 - 3p^{-\alpha}$, we have \eqref{ineq:M_bulleti-Theta} and \eqref{ineq:M_bulletj-Theta} both hold, then for any $i, j$,
		\begin{equation*}
			\begin{split}
				& \left|1 - \theta_{ij}/\hat{\Theta}_{ij}^{(1)}\right| = \left|1 - \frac{M_{\bullet\bullet}^{(1)}\Theta_{\bullet j}^{(1)}\Theta_{i \bullet}^{(1)}}{M_{\bullet j}^{(1)} M_{i\bullet}^{(1)}\Theta_{\bullet\bullet}^{(1)}}\right| = \left| \frac{\Theta_{\bullet\bullet}^{(1)}M_{\bullet j}^{(1)}M_{i \bullet}^{(1)} - M_{\bullet\bullet}^{(1)}\Theta_{\bullet j}^{(1)}\Theta_{i \bullet}^{(1)}}{M_{\bullet j}^{(1)}M_{i\bullet}^{(1)}\Theta_{\bullet\bullet}^{(1)}}\right|\\
				\leq & \frac{\left|\left(M_{\bullet\bullet}^{(1)} - \Theta_{\bullet\bullet}^{(1)} \right)\Theta_{\bullet j}^{(1)}\Theta_{i\bullet}^{(1)}\right| +  \left|\Theta_{\bullet\bullet}^{(1)} \left(M_{\bullet j}^{(1)} - \Theta_{\bullet j}^{(1)}\right)\cdot M_{i\bullet}^{(1)}\right| + \left|\Theta_{\bullet\bullet}^{(1)}M_{\bullet j}^{(1)}(M_{i\bullet}^{(1)} - \Theta_{i\bullet}^{(1)})\right|}{M_{\bullet j}^{(1)} M_{i\bullet}^{(1)} \Theta_{\bullet\bullet}^{(1)}}\\
				\overset{\eqref{ineq:M_bulleti-Theta}\eqref{ineq:M_bulletj-Theta}}{\leq} & C\frac{\sqrt{\log p \Theta_{\bullet\bullet}^{(1)}} \Theta_{\bullet j}^{(1)}\Theta_{i\bullet}^{(1)} + \sqrt{\log p \Theta_{\bullet j}^{(1)}} \Theta_{\bullet\bullet}^{(1)}\Theta_{i\bullet}^{(1)} + \sqrt{\log p \Theta_{i \bullet}^{(1)}} \Theta_{\bullet j}^{(1)}\Theta_{\bullet\bullet}^{(1)}}{\Theta_{\bullet j}^{(1)} \Theta_{i\bullet}^{(1)} \Theta_{\bullet\bullet}^{(1)}}\\
				\overset{\eqref{ineq:Theta_ibullet_lower_bound}}{\leq} & C\sqrt{\frac{\log p}{\theta_0}\left(\frac{1}{m_1}+\frac{1}{p_2}\right)}.
			\end{split}
		\end{equation*}
		Similarly one can also show $|1-\theta_{ij}/\hat{\Theta}_{ij}^{(2)}| \leq C\sqrt{\frac{\log p}{\theta_0}(m_2^{-1}\wedge p_1^{-1})}$, $\forall i, j$ with probability at least $1 - p^{-\alpha}$. By Step 1 of the proof of this lemma, we also have $\|\tilde{Y}^0_{(11)} - A_{(11)}\| \leq C\sqrt{\frac{(m_1+m_2)\log p}{\theta_0}}$ with probability at least $1 - p^{-\alpha}$. Also, $\|A_{(11)}\| \leq \sqrt{\sum_{i=1}^{m_1}\sum_{j=1}^{m_2}A_{ij}^2} \leq C\sqrt{m_1m_2}$.
		Therefore, with probability at least $1 - p^{-\alpha}$,
		\begin{equation*}
			\begin{split}
				& \left\|\tilde{Y}^0_{(11)} - \tilde{Y}_{(11)}\right\| \overset{\eqref{eq:tildeY^0-tildeY}}{\leq} \|\tilde{Y}^0_{(11)}\|\cdot C\sqrt{\frac{\log p}{\theta_0}\left(\frac{1}{m_1} + \frac{1}{m_2}\right)}\\
				\leq & C\sqrt{\frac{\log p}{\theta_0}\left(\frac{1}{m_1} + \frac{1}{m_2}\right)} \left(\|A_{(11)}\| + \|\tilde{Y}^0_{(11)} - A_{(11)}\|\right)\\
				\leq & C\sqrt{\frac{\log p}{\theta_0}\left(\frac{1}{m_1} + \frac{1}{m_2}\right)} \left(C\sqrt{m_1m_2} + C\sqrt{\frac{\log p (m_1+m_2)}{\theta_0}}\right) \\
				\leq & C\sqrt{\frac{(m_1+m_2)\log p}{\theta_0}} \quad (\text{since } \theta_0\geq \frac{C_{gap}r\log p}{m_1\wedge m_2}).
			\end{split}
		\end{equation*}
		Next, one can similarly show that
		\begin{equation*}
			\left\|\tilde{Y}^0_{(\bullet 1)} - \tilde{Y}_{(\bullet 1)}\right\| \leq C\sqrt{\frac{(p_1+m_2)\log p}{\theta_0}};\quad \left\|\tilde{Y}^0_{(1\bullet)} - \tilde{Y}_{(1\bullet)}\right\| \leq C\sqrt{\frac{(m_1+p_2)\log p}{\theta_0}}.
		\end{equation*}
		with probability at least $1 - p^{-\alpha}$, which has finished the proof for \eqref{ineq:Y_11^0-Y_11}.
	\end{enumerate}

	To conclude from Steps 1 and 2, we have proved the error bound for $\tilde{Y}_{(11)}$, $\tilde{Y}_{(1\bullet)}$, and $\tilde{Y}_{(\bullet 1)}$. 
	\begin{equation*}
		\left\|\tilde{Y}_{(11)} - A_{(11)}\right\| \leq C\sqrt{\frac{(m_1+m_2)\log p}{\theta_0}},
	\end{equation*}
	\begin{equation*}
		\left\|\tilde{Y}_{(1\bullet)} - A_{(1\bullet)}\right\| \leq C\sqrt{\frac{(m_1+p_2)\log p}{\theta_0}},\quad \left\|\tilde{Y}_{(\bullet 1)} - A_{(\bullet 1)}\right\| \leq C\sqrt{\frac{(m_2+p_1)\log p}{\theta_0}}.
	\end{equation*}
	with probability at least $1 - p^{-\alpha}$. \quad $\square$

	The following lemma, as a special case of Lemma 2 in \cite{zhang2016cross}, provides the upper and lower bound for submatrix of orthogonal matrices.
	\begin{Lemma}\label{lm:U_Omega_upper_lower_bound}
		Suppose $U\in \mathbb{O}_{p, r}$ is an orthogonal matrix, and $U$ satisfies the incoherence condition with constant $\rho$, i.e. $\frac{r}{p} \|\mathbb{P}_Ue_i\| \leq \rho$, $\forall 1\leq i \leq p$. Suppose we uniformly randomly select $m$ numbers from $\{1, \ldots, p\}$ and form them as the set $\Omega$, then for any $m > r$, $0 < \varepsilon < 1$,
		\begin{equation}
			P\left(\frac{(1-\varepsilon)m}{p}\leq \sigma_{\min}(U_{[\Omega, :]}) \leq \sigma_{\max}(U_{[\Omega, :]}) \leq \frac{\varepsilon^2 m}{p} \right) \geq 1 - 2r\exp(-m\varepsilon^2/(4\rho r)).
		\end{equation}	
	\end{Lemma}

	The next Lemma \ref{lm:A_LA_MA_R-Y_LY_MY_R} provides the upper bound for $A_LA_M^{-1} A_R - B_L B_M^{-1} B_R$ when the difference of each pair of $\{A_L, B_L\}$, $\{A_M, B_M\}$, and $\{A_R, B_R\}$ are bounded.
	\begin{Lemma}\label{lm:A_LA_MA_R-Y_LY_MY_R}
		Suppose $\hat{r} \geq r$, $A_L\in \mathbb{R}^{p_1\times r}, A_M \in \mathbb{R}^{r\times r}, A_R\in \mathbb{R}^{r\times p_2},$; $B_L\in \mathbb{R}^{p_1\times \hat{r}}, B_M \in \mathbb{R}^{\hat{r}\times\hat{r}}, B_R\in \mathbb{R}^{\hat{r}\times \hat{r}}$. We further denote
		\begin{equation*}
			\tilde{A}_L = 
			\begin{bmatrix}
				A_L & 0_{p_1\times (\hat{r} - r)}
			\end{bmatrix},\quad \tilde{A}_M = \begin{bmatrix}
				A_M & 0_{r \times (\hat{r} - r)}\\
				0_{(\hat{r} - r)\times r} & 0_{(\hat{r} - r)\times(\hat{r} - r)}
			\end{bmatrix}, \quad \tilde{A}_R = \begin{bmatrix}
				A_R\\
				0_{(\hat{r} - r)\times p_2}
			\end{bmatrix}
		\end{equation*}
		and assume that $\|\tilde{A}_L - B_L\| \leq \alpha_L$, $\|\tilde{A}_M - B_M\| \leq \alpha_M$, and $\|\tilde{A}_R - B_R\| \leq \alpha_R$.
		Provided that $\|Z_M\| \leq \frac{1}{4}\sigma_{\min}(A_M)$, $\|Z_L\| \leq C\lambda_L\sigma_{\min}(A_M)$, $\|Z_R\| \leq C\lambda_R \sigma_{\min}(A_M)$, and
		\begin{equation}
			\|A_L A_M^{-1}\| \leq \lambda_L, \quad \|B_L B_M^{-1}\| \leq \lambda_L, \quad \|A_M^{-1} A_R\|\leq \lambda_R,
		\end{equation} 
		(note that there is assumption on $\|B_M^{-1}B_R\|$), for some constant $C>0$ we have
		\begin{equation*}
			\left\|A_L A_M^{-1} A_{R} - B_L B_M^{-1} B_R\right\| \leq C\left(\lambda_L\alpha_R + \lambda_R\alpha_L + \lambda_L\lambda_R\alpha_M\right).
		\end{equation*}
	\end{Lemma}

	{\bf\noindent Proof of Lemma \ref{lm:A_LA_MA_R-Y_LY_MY_R}.} The lemma can be proved in steps. For convenience, we denote $Z_L = B_L - A_L$, $Z_M = B_M - A_M$, and $Z_R = B_R - A_R$.
	\begin{enumerate}[leftmargin=*]
		\item We first assume that the SVD of $B_M$ is $B_M = U\Sigma V^\top$. Here  $$U = \begin{bmatrix}
			U_1 & U_2
		\end{bmatrix} = \begin{bmatrix}
			U_{11} & U_{12}\\
			U_{21} & U_{22}
		\end{bmatrix}, \quad \Sigma = \begin{bmatrix}
			\Sigma_1 & \\
			& \Sigma_2
		\end{bmatrix}, \quad V = \begin{bmatrix}
			V_1 & V_2
		\end{bmatrix} = \begin{bmatrix}
			V_{11} & V_{12}\\
			V_{21} & V_{22}
		\end{bmatrix},$$
		%where  $U_1\in \mathbb{O}_{\hat{r}, r}$, $U_2\in \mathbb{O}_{\hat{r}, \hat{r}-r}$, $V_1\in \mathbb{O}_{\hat{r}, \hat{r} - r}$, $V_2\in \mathbb{O}_{\hat{r}, \hat{r} - r}$, $U = [U_1~U_2], V=[V_1~V_2]$. 
		Denote 
		$$W = \begin{bmatrix}
			I_r\\
			0_{(\hat{r} - r)\times r}
		\end{bmatrix} \in \mathbb{O}_{\hat{r}, r},$$
		then $W$ is clearly the left and right singular subspaces of $\tilde{A}_M$. By the perturbation bound result in Proposition 1 of \cite{cai2017rate}, we have
		\begin{equation*}
			\begin{split}
				& \left\|\sin\Theta(U_1, W)\right\| \leq \frac{\sigma_{r+1}(B_M)\|Z_M\|}{\sigma_{\min}^2(B_M W) - \|\sigma_{r+1}(B_M)}\\
				\leq & \frac{\|Z_M\|^2}{(\sigma_{\min}(A_M) - \|Z_M\|)^2 - \|Z_M\|^2} \leq \frac{1}{3^2 - 1} = \frac{1}{8}.
			\end{split}
		\end{equation*}
		Here we used the condition that $\sigma_{\min}(A_M) > 4\|Z_M\|$. We can similarly prove that $\|\sin\Theta(V_1, W)\| \leq 1/8$. Based on the properties of $\sin\Theta$ distance (Lemma 1 in \cite{cai2016structured}), we have $\|U_{12}\| = \|U^\top W_{\perp}\| \leq 1/8$, 
		\begin{equation}
			\sigma_{\min}\left(U_{11}\right) = \sqrt{1 - \|U^\top W_{\perp}\|^2} \geq \frac{\sqrt{63}}{8}.
		\end{equation}
		\item We denote $\mathring{B}_L = B_LV_1$, $\mathring{B}_M = U_1^\top B_MV_1$, $\mathring{B}_R = U_1^\top B_R$. We can define $\mathring{A}_L, \mathring{A}_M, \mathring{A}_R, \mathring{Z}_L, \mathring{Z}_L$, and $\mathring{Z}_L$ in the same fashion. Then one can calculate that
		\begin{equation}
			\|\mathring{Z}_L\| \leq \alpha_L, \quad \|\mathring{Z}_M\| \leq \alpha_M, \quad \|\mathring{Z}_R\| \leq \alpha_R.
		\end{equation}
		\begin{equation}\label{ineq:sigma_min_A_B}
			\begin{split}
				& \sigma_{\min}\left(\mathring{A}_M\right) \geq \sigma_{\min}(U_{11})\sigma_{\min}(A_M)\sigma_{\min}(V_{11}) \geq \frac{63}{64}\sigma_{\min}(A_M) \geq \frac{63}{16}\|Z_M\|, \\
				& \sigma_{\min}\left(\mathring{B}_M\right) \geq \sigma_{\min}\left(\mathring{A}_M\right) - \|Z_M\| \geq \frac{47}{63}\sigma_{\min}(\mathring{A}_M) \geq \frac{47}{16}\|Z_M\|.
			\end{split}
		\end{equation}
		Based on that the SVD of $B_M$ is written as $B_M = U\Sigma V^\top$, we have the following forms for $B_LB_M^{-1}B_R$ and $A_LA_M^{-1}A_R$, which will be useful in our later analysis.
		\begin{equation}\label{eq:lm_decomposition_B}
			\begin{split}
				& B_LB_M^{-1}B_R = B_LV\Sigma^{-1} U^\top B_R = B_L(V_1 \Sigma_1^{-1} U_1^\top + V_2\Sigma_2^{-1} U_2^\top) B_R\\
				= & B_LV_1\Sigma_1^{-1}U_1^\top B_R + B_LV_2\Sigma_2^{-1}U_2^\top B_R\\
				= & B_LV_1\left(U_1^\top B_M V_1\right)^{-1} U_1^\top B_R + B_L V_2\left(U_2^\top B_M V_2\right)^{-1} U_2^\top B_R\\
				= & \mathring{B}_L\mathring{B}_M^{-1} \mathring{B}_R + B_L V_2\left(U_2^\top B_M V_2\right)^{-1} U_2^\top B_R.
			\end{split}
		\end{equation}
		Similarly, $A_LA_M^{-1}A_R$ can be rewritten as
		\begin{equation}\label{eq:lm_decomposition_A}
			\begin{split}
				& A_LA_M^{-1}A_R = A_LV_{11} \left(U_{11}^\top A_M V_{11}\right)^{-1} U_{11} A_R = \tilde{A}_LV_{1} \left(U_{1}^\top \tilde{A}_M V_{1}\right)^{-1} U_{1} \tilde{A}_R = \mathring{A}_L \mathring{A}_M^{-1} \mathring{A}_R.
			\end{split}
		\end{equation}
		\item In this step, we develop the following properties for $\mathring{B}_L, \mathring{B}_M, \mathring{B}_R$ and $\mathring{A}_L, \mathring{A}_M, \mathring{A}_R$:
		\begin{equation}\label{ineq:lemma-to-be-prove1}
			\|\mathring{B}_L\mathring{B}_M^{-1} \| \leq C\lambda_L, \quad \|\mathring{B}_M^{-1}\mathring{B}_R^{-1} \| \leq C\lambda_R,
		\end{equation}
		\begin{equation}\label{ineq:lemma-to-be-prove2}
			\|B_L V_2\left(U_2B_MV_2\right)^{-1} U_2^\top B_R\| \leq C\lambda_L\alpha_R + C\lambda_L\lambda_R \alpha_M,
		\end{equation}
		\begin{equation}\label{ineq:lemma-to-be-prove3}
			\|\mathring{B}_L\mathring{B}_M^{-1} \mathring{B}_R - \mathring{A}_L\mathring{A}_M^{-1} \mathring{A}_R \| \leq C\lambda_R\alpha_L + C\lambda_R\alpha_R + C\lambda_L\lambda_R \alpha_M.
		\end{equation}
		First, \eqref{ineq:lemma-to-be-prove1} can be proved by
		\begin{equation}
			\begin{split}
				& \left\|\mathring{B}_L \mathring{B}_M^{-1}\right\| = \left\|\left(\mathring{A}_L+\mathring{Z}_L\right) \left(\mathring{A}_M + \mathring{Z}_M\right)^{-1}\right\|\\
				\leq & \|\mathring{A}_L (\mathring{A}_M + \mathring{Z}_M)^{-1} \| + \|\mathring{Z}_L (\mathring{A}_M + \mathring{Z}_M)^{-1} \|\\
				\leq & \|\mathring{A}_L\mathring{A}_M^{-1} (I - \mathring{Z}_M(\mathring{A}_M+\mathring{Z}_M))\| + \|\mathring{Z}_L\| \cdot \|\mathring{B}_M^{-1}\|\\
				\overset{\eqref{ineq:sigma_min_A_B}}{\leq} & \lambda_L \left(1 + \|\mathring{Z}_M\| \cdot \frac{16}{47}\|Z_M\|^{-1}\|\right) + C\lambda_L \lambda_{\min}(A_M) \cdot \frac{64}{63} \sigma_{\min}^{-1}(A_M)\\
				\leq & C\lambda_L.
			\end{split}
		\end{equation}
		One can similarly prove that $\left\|\mathring{B}_M^{-1}\mathring{B}_R\right\| \leq C\lambda_R$, thus we have \eqref{ineq:lemma-to-be-prove1}. Next we consider the proof for \eqref{ineq:lemma-to-be-prove2}. Since
		\begin{equation}
			\begin{split}
				& \|U_2^\top B_R\| \leq \|U_2^\top Z_R\| + \|U_2^\top \tilde{A}_R\| \leq \alpha_R + \|U^\top_{2, [1:r, :]} A_R\|\\
				\leq & \alpha_R + \left\|(U_{2, [1:r, :]}^{\top} A_M) (U_{2, [1:r, :]}^\top A_M)^{-1} U^\top_{2, [1:r, :]} A_R\right\|\\
				\leq & \alpha_R + \|U_{2, [1:r, :]}^\top A_M\| \cdot \|A_M^{-1} A_R\| \leq \alpha_R + \|U_2^\top \tilde{A}_M\| \lambda_R\\
				\leq & \alpha_R + \left(\|U_2^\top (A_M + Z_M) \| + \|U_2^\top Z_M\|\right) \cdot \lambda_R\\
				\leq & \alpha_R + \lambda_R\left(\sigma_{r+1}(A_M + Z_M) + \alpha_M\right)\\
				\leq & \alpha_R + \lambda_R\left(\|Z_M\| + \alpha_M\right) = \alpha_R + 2\lambda_R \alpha_M.
			\end{split}
		\end{equation}
		\begin{equation}
			\begin{split}
				&\left\|B_LV_2 \left(U_2 B_M V_2\right)^{-1} U_2^\top\right\| = \left\|B_L V \left(U^\top  B_M V\right)^{-1} U - B_L V_1 \left(U_1^\top  B_M V_1\right)^{-1} U_1\right\|\\
				\leq & \|B_LB_M^{-1}\| + \|\mathring{B}_L \mathring{B}_M^{-1}\| \leq C\lambda_L.
			\end{split}
		\end{equation}
		The two inequalities above yield \eqref{ineq:lemma-to-be-prove2}:
		\begin{equation*}
			\|B_L V_2\left(U_2B_MV_2\right)^{-1} U_2^\top B_R\| \leq \|B_L V_2\left(U_2B_MV_2\right)^{-1} U_2^\top\| \cdot\|U_2^\top B_R\| \leq C\lambda_L\alpha_R + C\lambda_L\lambda_R\alpha_M.
		\end{equation*}
		Finally, \eqref{ineq:lemma-to-be-prove3} can be proved by
		\begin{equation}
			\begin{split}
				& \|\mathring{B}_L\mathring{B}_M^{-1} \mathring{B}_R - \mathring{A}_L\mathring{A}_M^{-1} \mathring{A}_R \| \leq \|\mathring{B}_L\mathring{B}_M^{-1}\mathring{Z}_R\| + \|\mathring{B}_L\mathring{B}_M^{-1}\mathring{A}_R - \mathring{A}_L\mathring{A}_M^{-1}\mathring{A}_R\|\\
				\leq & C\lambda_L \|\mathring{Z}_R\| + \|\mathring{Z}_L \mathring{B}_M^{-1} \mathring{A}_R\| + \|\mathring{A}_L \left(\mathring{B}_M^{-1} - \mathring{A}_M^{-1}\right) \mathring{A}_R\|\\
				\leq & C\lambda_L\alpha_R + C\lambda_R\alpha_L + \|\mathring{A}_L \left(\mathring{B}_M^{-1} - \mathring{A}_M^{-1}\right) \mathring{A}_R \|\\
				\leq & C\lambda_R\alpha_R + C\lambda_R\alpha_L + \|\mathring{A}_L \mathring{A}_M \left(\mathring{Z}_M - \mathring{Z}_M \mathring{B}_M^{-1} \mathring{Z}_M\right)\mathring{A}_M \mathring{A}_R\|\\
				\leq & C\lambda_R\alpha_L + C\lambda_L\alpha_R + \lambda_L\lambda_R\left(\|\mathring{Z}_M\| + \|\mathring{Z}_M\|^2 \|\mathring{B}_M^{-1}\|\right)\\
				\leq & C\lambda_R\alpha_L + C\lambda_L\alpha_R + C\lambda_L\lambda_R\alpha_M.
			\end{split}
		\end{equation}
		\item Now we are ready to analyze $\|B_LB_M^{-1}B_R - A_LA_M^{-1}A_R\|$ based on the previous calculations:
		\begin{equation*}
			\begin{split}
				&\|B_LB_M^{-1}B_R - A_LA_M^{-1}A_R\|\\ 
				\overset{\eqref{eq:lm_decomposition_A}\eqref{eq:lm_decomposition_B}}{\leq} & \left\|\mathring{B}_L\mathring{B}_M^{-1} \mathring{B}_R - \mathring{A}_L\mathring{A}_M^{-1} \mathring{A}_R\right\| + \left\|B_L V_2\left(U_2^\top B_M V_2\right)^{-1} U_2^\top B_R\right\|\\
				\overset{\eqref{ineq:lemma-to-be-prove2}\eqref{ineq:lemma-to-be-prove3}}{\leq} & C \lambda_L \alpha_R + C\lambda_R \alpha_L + C\lambda_L \lambda_R \alpha_M,
			\end{split}
		\end{equation*}
		which has finished the proof of Lemma \ref{lm:A_LA_MA_R-Y_LY_MY_R}. \quad $\square$
	\end{enumerate}

	\section{Upper Bound of Ranks}\label{sec: upp_rank}
	In Step 4, when there exist prior knowledge or estimations on the noise level $\tau$ and missing parameter $\theta_0$ (which will be defined later in Conditions \ref{con:sub-gaussian} and \ref{con:missingness}), say $\tilde{\tau}$ and $\tilde{\theta}_0$, we can apply hard singular value thresholding (HSVD) (see, e.g. 	\cite{donoho2014minimax,gavish2014optimal,chatterjee2015matrix}) to $B_{(\bullet 1)}$ and $B_{(1\bullet)}$ before locating $\hat{r}$:
	$$B_{(\bullet 1)} \Leftarrow HSVT_{\lambda_1} \left(B_{(\bullet 1)}\right), \quad B_{(1\bullet)} \Leftarrow HSVT_{\lambda_2}\left(B_{(1\bullet)}\right).$$
	Here, $\lambda_1 = \eta\sqrt{\frac{p_1\tilde{\tau}\log(p_1\vee p_2)}{\tilde{\theta}_0}}$, $\lambda_2 = \eta\sqrt{\frac{p_2\tilde{\tau}\log(p_1\vee p_2)}{\tilde{\theta}_0}}$, $\tilde{\tau}$ and $\tilde{\theta}_0$, $\eta>0$ is a constant; for any matrix with SVD: $D = \sum_i \sigma_i u_i v_i^\top$, $HSVD_{\lambda}(D):= \sum_i \sigma_i 1_{\{\sigma_i \geq \lambda\}}u_iv_i^\top$ is defined as the hard singular value thresholding operator. 
	Interestingly, this additional HSVT here is equivalent to starting with a smaller value $r_0$ for locating $\hat{r}$ in Step 4. To be specific, a reasonable choice of $r_0$ is
	\begin{equation}\label{eq:selection of r_0}
		r_0 = \min\left\{i: \sigma_i(\tilde{Y}_{(\bullet 1)}) \geq \eta\sqrt{\frac{p_1\tilde{\tau}\log(p_1\vee p_2)}{\tilde{\theta}_0}}, \text{ and } \sigma_i(\tilde{Y}_{(1\bullet)}) \geq \eta\sqrt{\frac{p_2\tilde{\tau}\log(p_1\vee p_2)}{\tilde{\theta}_0}}\right\}. 
	\end{equation}
	Furthermore, we also have the following ad hoc choices for $\tilde{\theta}_0$ and $\tilde{\tau}$,
	\begin{equation}\label{eq:theta_0_tau}
		\hat{\theta}_0 = \min\left\{\hat{\Theta}_{ij}, 1\leq i\leq m_1, \text{ or } 1\leq j \leq m_2\right\}; \quad \tilde{\tau} = \left(\sum_{i,j : M_{ij}=1} Y_{ij}^2\right)^{1/2} / \left(\sum_{i,j} M_{ij} \right)^{1/2}.
	\end{equation}
	We will further analyze such choice of $r_0$ in Section \ref{sec.theory}. On the other hand, when $\tau$ and $\theta_0$ are unavailable or hard to estimate, the regular choice $r_0 = m_1\wedge m_2$ without additional HSVT step will produce low-rank and good enough estimates in practice. 
	% We postpone such discussions to simulation and real data analysis in Sections \ref{sec.simulation} and \ref{sec.real_data}.

	\section{Supporting Results}



	\subsection{Additional Simulations}\label{asup_eval}
	As the low-rank assumption is essential for \textsc{Macomss} in denoising and imputation, we further examine the case where $A$ is only approximately low-rank to evaluate the robustness of this condition to our method.
	\begin{enumerate}
		\item[1.] Assume that $\Theta$ and $Z$ are generated in the same way as in our first setting. Alternatively, we construct $A = U D V^\top$, where $U \in \mathbb{O}_{p_1, (p_1 \wedge p_2)}$ and $V \in \mathbb{O}_{p_2, (p_1 \wedge p_2)}$ are uniformly randomly generated orthogonal matrices, and $D = \mathrm{diag}(\underbrace{1, \ldots, 1}_r, 1^{-\alpha}, \ldots, (p_1 \wedge p_2))$. Clearly, $\alpha$ indicates the rate of singular value decay for $A$, as larger $\alpha$ values correspond to $A$ being closer to an exact low-rank matrix. 
	\end{enumerate}

	In addition to continuous-valued datasets, we consider a special setting where the entries of the matrix are discrete count observations. Count data matrices are prevalent in applications, such as EHR data analysis \citep{beaulieu2018characterizing,hemingway2018big}, microbiome studies \citep{shi2016regression,cao2016count}, astronomical energy spectra \citep{nowak2000statistical}, and fluorescence microscopy \citep{jiang2015minimax}, where the Poisson distribution is commonly used for modeling. We consider the following setting:
	\begin{enumerate}
		\item[2.] We let $m_1 = m_2 \in \{10, 20, 50, 100\}$. The sporadic missing parameter $\Theta$ is generated in the same way as the first simulation setting. 
		The observations are generated as:
		$Y_{ij} \sim \text{Poisson}\left(\lambda \cdot A_{ij}\right)$,
		where $A = UV^\top$, with $U \in \mathbb{R}^{p_1 \times r}$ and $V \in \mathbb{R}^{p_2 \times r}$. Each entry of $U$ and $V$ is independently sampled from $|N(0, 1/p_1)|$ and $|N(0, 1/p_2)|$, respectively. 
		The intensity parameter $\lambda$ is set as: $\lambda = \lambda_0 \cdot \frac{p_1p_2}{\sum_{i,j} A_{ij}}$,
		ensuring that the average value of each entry of $Y$ is approximately $\lambda_0$. We let $\lambda_0$ vary from 1 to 10, representing different signal-to-noise ratios (SNRs).
	\end{enumerate}

