			\includegraphics[height = 2in,width=3in]{figures/simu-3-Fro.png} \includegraphics[height = 2in,width=3in]{figures/simu-3-spe.png}
			\caption{Average Frobenius and spectral loss for approximately low-rank matrix $A$.}
