    \caption{Phase-Space Portraits for $x_{\textrm{rel}}$-$v_{\textrm{rel}}$ with a fixed $\omega=5$ and varying $\alpha$ for Equation~\eqref{eq:sub_int3}. %For $v_{\textrm{rel}} = 0$, we get a straight line. 
    }
    \label{fig:phase_portrait_modified}
\end{figure}

\section{Followerstopper: Non-linear Controller for Wave Dampening}
In order to dampen the traffic waves arising as a result of the bottleneck, the velocity controller of the form provided in Equation~\eqref{eq:avcontrol_form} needs to modulate the speed of AV to close the gap between the leader and the ego gracefully so that acceleration or deceleration doesn't amplify the traffic waves along with staying at the safe distance from the leader vehicle.
The control law is defined as follows:
\begin{multiequation}
    \label{eq:followerstopper}
& f_{\textrm{FS}}(x_{\textrm{rel}}(t), v_{\textrm{rel}}(t), v_{\textrm{lead}}(t))  = \\
& \begin{cases}
    0,  &\textrm{if} (x_{\textrm{rel}},v_{\textrm{rel}}) \in \mathcal{S}_1\\
    v(v_{\textrm{lead}}) \frac{x_{\textrm{rel}}-d_1(t)}{\bar{d}_2(t)-d_1(t)}, &\textrm{if}  (x_{\textrm{rel}},v_{\textrm{rel}}) \in \mathcal{S}_2\\
    v(v_{\textrm{lead}})+(r-v(v_{\textrm{lead}}))\frac{x_{\textrm{rel}}-d_2(t)}{d_3(t)-\bar{d}_2(t)}, &\textrm{if} (x_{\textrm{rel}},v_{\textrm{rel}}) \in \mathcal{S}_3\\
    r, &\textrm{if} (x_{\textrm{rel}},v_{\textrm{rel}}) \in \mathcal{S}_4 
    \end{cases}
\end{multiequation}
where $v : \mathbb{R} \rightarrow \mathbb{R}$ is $v(v_{\textrm{lead}}) = \min\{ \max\{v_{\textrm{lead}},0\},r\}$. Four sets $\mathcal{S}_1$, $\mathcal{S}_2$, $\mathcal{S}_3$, and $\mathcal{S}_4$ divided by three safety envelopes as are defined below:
\begin{multiequation}
     \label{eq:FS_regions}
             \mathcal{S}_1 &= \big\{(x_{\textrm{rel}},v_{\textrm{rel}}) \in \mathbb{R}^2 | 
    0 < x_{\textrm{rel}} \leq d_1(v_{\textrm{rel}}) \big\}, \\
    \mathcal{S}_2 &= \big\{(x_{\textrm{rel}},v_{\textrm{rel}}) \in \mathbb{R}^2 | d_1(v_{\textrm{rel}}) < x_{\textrm{rel}} \leq d_2(v_{\textrm{rel}}) \big\}, \\
    \mathcal{S}_3 &= \big\{(x_{\textrm{rel}},v_{\textrm{rel}}) \in \mathbb{R}^2 |d_2(v_{\textrm{rel}}) < x_{\textrm{rel}} \leq d_3(v_{\textrm{rel}}) \big\}, \\
    \mathcal{S}_4 &= \big\{(x_{\textrm{rel}},v_{\textrm{rel}}) \in \mathbb{R}^2 |d_3(v_{\textrm{rel}}) < x_{\textrm{rel}} \big\}.
\end{multiequation}


The phase-portrait specified in Equation~\eqref{eq:sub_int3} separates switching region with $d_j : \mathbb{R} \rightarrow \mathbb{R}$ are:
\begin{multiequation}
    d_j(v_{\textrm{rel}}) = \omega_j + \frac{1}{2\alpha_j} \min \{0,v_{\textrm{rel}}\}^2, \quad j = 1,2,3,
    \label{eq:FS_envelopes}
\end{multiequation}
where $\omega_1 = 4.5$, $\omega_2= 5.25$, $\omega_3 = 6.0$, $\alpha_1 = 1.5$, $\alpha_2 = 1$, $\alpha_3 = 0.5$. Through our controller design, we control the velocity of the Lagrangian control vehicle (ego vehicle),
through the control input $u$ as shown in~\ref{fig:fs_block}.

