It is convenient to introduce $u_{n+1}^{(k)} = a_{n+1}^{(k)} - a_{n}^{(k)}$, i.e.
$a_{n+1}^{(k)}=\sum_{m=0}^nu_{m+1}^{(k)}$.
Thus, $a_{0}^{(0)}=0$ and $a_{n}^{(0)}=1$ for $n\geq1$ corresponds to $u_{n}^{(0)}=\delta_{n,1}$.
For $k>0$, the recurrence takes the form
\begin{equation}
  u_{n+1}^{(k)}  = \frac{\K_{n-1}}{\K_n} \, u_{n}^{(k)}  + \frac{m_{n}}{\K_n} \sum_{j=1}^n u_{j}^{(k-1)}
  \:.
\end{equation}
More clearly, we can introduce $b_{n}^{(k)}=\K_{n-1}\,u_{n}^{(k)}$ for $n>1$, which is the coefficient of the expansion of \eqref{eq:DefYn} in powers of $\lambda$~: the recurrence \eqref{eq:20} is a simple artihmetic series $b_{n+1}^{(k)}  = b_{n}^{(k)}  +  m_{n}\,a_{n}^{(k-1)} $.
The solution is 
\begin{equation}
  \label{eq:IterationU0}
  u_{n+1}^{(k)}  
  = \frac{1}{\K_n}  \sum_{j=1}^n m_j \sum_{p=1}^j u_{p}^{(k-1)}  
  = \frac{1}{\K_n}  \sum_{p=1}^n u_{p}^{(k-1)} \sum_{j=p}^n m_j 
  \:.
\end{equation}
We now remark that the first terms of the sum $\sum_p$ vanish since $u_p^{(k-1)}=0$ for $p<k$, hence we obtain the form
\begin{equation}
  \label{eq:IterationU}
    u_{n+1}^{(k)}  =  \frac{1}{\K_n}\sum_{p=k-1}^{n-1}  u_{p+1}^{(k-1)}\,\sum_{j=p+1}^{n} m_j 
    \:,
\end{equation}
 now appropriate for iteration.
 The first iterations give
\begin{align}
   u_{n+1}^{(1)}  &=  \frac{1}{\K_n} \sum_{j=1}^{n} m_j 
   \:,
   \\
   u_{n+1}^{(2)}  &=   \sum_{p=1}^{n-1}  
    \frac{1}{K_{p}} \sum_{j=1}^{p} m_j \,
    \frac{1}{\K_n} \sum_{j'=p+1}^{n} m_{j'} 
    \nonumber
    \\
  &=  
  \sum_{1\leq j_1\leq i_1<j_2\leq n}
  \frac{m_{j_1}m_{j_2}}{\K_{i_1}\K_{n}}
      \:,
 \end{align} 
 etc.
We deduce $a_{n+1}^{(k)}=\sum_{p=k}^n u_{p+1}^{(k)}$~:
\begin{equation}
  \label{eq:MainRes}
  a_{n+1}^{(k)} 
  = 
  \hspace{-0.5cm}
  \sum_{1\leq j_1 \leq i_1< j_2 \leq i_2<\cdots < j_k\leq i_k\leq n}
  \   \prod_{m=1}^k \frac{m_{j_m}}{K_{i_m}}
  \:,
\end{equation}
which is Eq.~\eqref{eq:MainResIntro2}. 
It will be useful for the following to organize the sums as 
\begin{equation}
  \label{eq:MainRes2}
  a_{n+1}^{(k)} 
  = 
  \hspace{-0.5cm}
  \sum_{1\leq i_1<\cdots<i_{k}\leq n}
   \ \prod_{m=1}^k 
   \bigg(\frac{1}{\K_{i_{m}}}\sum_{j=i_{m-1}+1}^{i_{m}} m_j \bigg)
\end{equation}
with $i_0=0$.
Similarly,
\begin{equation}
  \label{eq:MainRes1}
  a_{n+1}^{(k)} = 
  \hspace{-0.5cm}
  \sum_{1\leq j_1 <\cdots<j_{k}\leq n}  
  \ \prod_{m=1}^{k} \bigg( m_{j_{m}}  
  \sum_{i=j_{m}}^{j_{m+1}-1} \frac{1}{\K_i}\bigg)
\end{equation}
with $j_{k+1}=n$.
The coefficients are also those of the spectral determinant~\eqref{eq:SpectralDet-Neumann/Dirichlet} for the tridiagonal matrix $\Lambda$~; these expressions exhibit the symmetry between masses $m_j$'s and inverse spring constants $1/\K_i$'s discussed in the previous section.
The case of a chain pinned at the two sides is also discussed in Appendix~\ref{app:DirDir}.

So far, all is exact and we did not make any assumption on the masses and the spring constants, which can be deterministic or random.


\subsection{Symmetrization of the coefficients $a_{n+1}^{(k)}$}

The starting point of our asymptotic analysis of the coefficients is to remark that when averaging any function of $n$ i.i.d. random variables, it is possible to perform any permutation of these variables.
As a consequence we can write
\begin{align}
%   \mean{ F( \{ m_j \} ) }   = \mean{ \ \symmetriz{ F( \{ m_{\pi(j)} \} ) }_{\pi\in\mathcal{S}_n} }
%\hspace{-0.25cm}
   \mean{ F( m_1,\cdots,m_n  ) }   
   &= \mean{ F( m_{\pi(1)},\cdots,m_{\pi(n)}  )   }
   \\\nonumber
   &= \mean{ \ \symmetriz{ F( m_{\pi(1)},\cdots,m_{\pi(n)}  ) }_{\pi\in\mathcal{S}_n} }
 \end{align} 
where $\pi$ is a permutation and $\symmetriz{ \cdots }_{\pi\in\mathcal{S}_n}$ denotes full symmetrization, i.e. averaging over the symmetric group with uniform weight.
Here, we have two sets of i.i.d. random variables, $\{m_i\}$ and $\{\K_i\}$, hence we symmetrize with respect to permutations of both sets.
This observation leads to the idea to consider the coefficients symmetrized with respect to the permutations of random variables, \textit{without} disorder average.
We assume that this will provide the typical behaviour of these coefficients, which will indeed be verified on few well controlled specific cases.
We consider 
\begin{equation}
  \symmetriz{ a_{n+1}^{(k)} }_{\pi,\sigma} = 
  \symmetriz{ 
  \sum_{1\leq j_1\leq i_1 \cdots }\  \prod_{m=1}^k \frac{m_{\pi(j_m)}}{K_{\sigma(i_m)}}  
  }_{\pi,\:\sigma\in\mathcal{S}_n}
  \:.
\end{equation}
Noticing that 
\begin{equation}
  \symmetriz{ \prod_{m=1}^k m_{\pi(j_m)}  }_{\pi\in\mathcal{S}_n} 
  = \symmetriz{ \prod_{m=1}^k m_{\pi(m)}  }_{\pi\in\mathcal{S}_n} 
\end{equation}
allows to remove the dependence of the masses and spring constants in the indices of the $2k$ sums. 
This remark greatly simplifies the multiple sums~:
\begin{align}
  \label{eq:SymmetrizedCoeff}
  \symmetriz{ a_{n+1}^{(k)} }_{\pi,\sigma} = &
  \symmetriz{ \prod_{j=1}^k m_{\pi(j)}  }_{\pi\in\mathcal{S}_n} 
  \symmetriz{ \prod_{i=1}^k \K^{-1}_{\sigma(i)}  }_{\sigma\in\mathcal{S}_n} 
  \nonumber
  \\  
  &\hspace{1cm}\times
  \hspace{-0.15cm}
  \underbrace{ 
  \sum_{1\leq j_1 \leq i_1< j_2 \leq i_2<\cdots < j_k\leq i_k\leq n} 
 \hspace{-1.55cm} 
 1
 \hspace{1.25cm}
  }_{=S_k(n)}            
\end{align}
where the sum $S_k(n)$ is computed in Appendix~\ref{app:Sums}~:
\begin{equation}
  \label{eq:DefSnk}
  S_k(n) = 
  \hspace{-0.5cm}  
  \sum_{1 \leq i_1<i_2 < \cdots < i_k \leq n}\: \prod_{m=1}^{k} (i_{m}-i_{m-1})
  =
  \begin{pmatrix}
    n+k \\ 2k
  \end{pmatrix}
\end{equation}
(with $i_0=0$). %, see Eq.~\eqref{eq:SumSnk}. 
%Eq.~\eqref{eq:SymmetrizedCoeff} will play a central role.
In the next subsection, we analyze the remaining symmetrized products. 


\subsection{Symmetrized product of $k$ random variables among $n$~: a fermionic random energy model}
\label{subsec:SymmetrizedProducts}

Let us study the symmetrized product of $k$ i.i.d. random variables chosen among $n$ ones, $X_1,\ldots,X_n$ (the variables correspond either to the inverse spring constants $K_j^{-1}$'s of the masses $m_j$'s).
We have
\begin{equation}
  \label{eq:ExpressionOfProductOfkVariables}
  \symmetriz{ \prod_{j=1}^k X_{\pi(j)} }_{\pi\in\mathcal{S}_n} 
  = 
  \frac{k!(n-k)!}{n!}\, Z(k,n) 
\end{equation}
where 
\begin{equation}
  \label{eq:ZforOrderedIndices}
  Z(k,n) = 
  \sum_{1\leq i_1 < i_2 <\cdots < i_k\leq n}  \ \prod_{m=1}^k X_{i_m}
  \:.
\end{equation}
It is helpful to use the analogy with the canonical partition function for $k$ non-interacting fermions occupying $n$ random energy levels, which is clear if we write $X_i=\EXP{-\beta\varepsilon_i}$, where $\varepsilon_i$ is a single particle energy level and $\beta$ the inverse temperature.
Introducing the occupation number $n_i\in\{0,\,1\}$ of level  $\varepsilon_i$ allows to rewrite more conveniently the canonical partition function as 
\begin{equation}
  Z(k,n) = 
  \sum_{  \underset{\sum_in_i=k}{n_1,\cdots,n_n}  }
  \prod_{i=1}^n X_{i}^{n_i}
  \:.
\end{equation}
This form makes clear that $Z(k,n) = n!/\big[k!(n-k)!\big]$ when $X_i=1$, which simplifies with the factor in \eqref{eq:ExpressionOfProductOfkVariables}, as it should in this trivial case.
It is convenient to introduce the grand partition function
\begin{equation}
  \Xi(\varphi,n) = \sum_{k=0}^n \varphi^k\, Z(k,n) 
  = \prod_{i=1}^n \left(1 + \varphi\,X_{i} \right)
  \:,
\end{equation}
where $\varphi$ is the fugacity \cite{TexRou24book}.
We can go back to the canonical partition function thanks to 
\begin{equation}
  \label{eq:FromXitoZ}
  Z(k,n) 
  = \oint \frac{\D\varphi}{2\I\pi} \, \frac{\Xi(\varphi,n) }{\varphi^{k+1}}
  \:,
\end{equation}
where the contour encircles the origin once in the complex plane of $\varphi$.
In the limit $k\gg1$, we expect that the integral \eqref{eq:FromXitoZ} is dominated by a saddle point $\varphi_*$ solving
\begin{equation}
  \label{eq:SaddleForZ}
  \derivp{}{\varphi}
  %\left.
    \left[
      \ln \Xi(\varphi,n) - k \,\ln\varphi
    \right]
  \Big|_{\varphi=\varphi_*}
  =0
  \:.
\end{equation}
This equation has a clear physical meaning within the fermionic model~:
$\overline{k}^\mathrm{g}=\partial \ln \Xi(\varphi,n)/\partial\ln\varphi$ is the (grand canonical) average number of fermions,
hence the saddle point equation \eqref{eq:SaddleForZ} corresponds to express the fugacity as a function of the number of fermions 
\begin{equation}
  \label{eq:NumberOfFermions}
  k = \sum_{i=1}^n \frac{1}{1/(X_i\varphi_*)+1}
  \:,
\end{equation}
where the function in the sum is the Fermi-Dirac distribution. 
In other terms, this equation gives the canonical fugacity (fugacity as a function of the number of fermions), denoted $\varphi_*(k/n)$.
Then we deduce 
$  
\ln  Z(k,n) \simeq \ln \Xi(\varphi_*,n) - k \,\ln\varphi_*
$.
Let us now take advantage of the extensivity property, in terms of the number $n$ of levels.
In the limit of large $n$, assuming $\smean{(\ln X)^2}<\infty$, we have
\begin{equation}
  \ln \Xi(\varphi,n)  
  = \sum_{i=1}^n \ln\left(1 + \varphi\,X_{i} \right)
  = n\,\mean{ \ln(1 + \varphi\,X_i) } + \mathcal{O}(\sqrt{n})
\end{equation}
We can write a similar relation for the number of fermions, hence introducing the fraction of occupied levels $\theta = {k}/{n}$, in the limit $n\to\infty$, Eq.~\eqref{eq:NumberOfFermions} rewrites
\begin{equation}
  \label{eq:SaddleForTheta}  
 \theta = \varphi_*\,\mean{ \frac{X_i}{1+\varphi_*\,X_i} }
 \in[0,1]
 \:.
\end{equation}
The $n\to\infty$ limit of \eqref{eq:NumberOfFermions} always exists thanks to the inequality $0\leq X\varphi/\big(1+X\varphi\big)\leq1$.   
%~;
%this equation provides the canonical fugacity (fugacity as a function of the number of fermions).
This transcendental equation for $\varphi_*(\theta)$ will play a central role in the analysis. 
%Obviously $\theta\in[0,1]$. 
The $\theta\to0^+$ limit corresponds to $\varphi_*\to0$, while the $\theta\to1^-$ limit corresponds to $\varphi_*\to\infty$.
Given the fugacity, we deduce the free energy per level
\begin{equation}
  \label{eq:FreeEnergy}
  \frac{\ln Z(k,n)}{n} \simeq \mean{ \ln(1 + \varphi_* \,X_i) } - \theta\,\ln\varphi_* 
  \:.
\end{equation}
This estimation of $Z(k,n)$ thus gives the typical value (in the Physics sense) of the symmetrized product \eqref{eq:ExpressionOfProductOfkVariables}.

If we introduce the free energy per level $f(\theta)=-\ln Z(k,n)/n$, we have the ``thermodynamic identity'' $\partial f(\theta)/\partial\theta = \ln\varphi_*(\theta)$ (canonical chemical potential) \cite{TexRou24book}~;
the relation can be proven by differentiating \eqref{eq:FreeEnergy} with respect to $\theta$.
Noticing that $\ln\big[Z(0,n)\big]=0$, we can integrate this equation~:
\begin{equation}
  \label{eq:Useful1}
  \frac{\ln Z(k,n)}{n} \simeq - \int_0^{k/n} \D t\,   \ln\varphi_*(t)
  \:.
\end{equation}
Obviously $(1/n)\ln Z(n,n)=\smean{\ln X}+ \mathcal{O}(1/\sqrt{n})$, hence we have also 
\begin{equation}
  \label{eq:Useful2}
  \frac{\ln Z(k,n)}{n} \simeq  \smean{\ln X} + \int_{k/n}^1 \D t\,  \ln\varphi_*(t)
  \:.
\end{equation}
It will be more convenient to use \eqref{eq:Useful1} and \eqref{eq:Useful2} rather than \eqref{eq:FreeEnergy}.


\subsubsection{Case $\mean{X}<\infty$ and $\mean{1/X}<\infty$}

We now apply these expressions to obtain the asymptotic of $Z(k,n)$ for $n\gg k\gg1$ and for $n\gg n-k\gg 1$.
The first case requires to determine the $\theta\to0$ behaviour of the fugacity. 
Expanding \eqref{eq:SaddleForTheta} for $\varphi_*\to0$ we get 
\begin{equation}
  \label{eq:FugacitySmallNbStandardCase}
  \varphi_*(\theta) \simeq \frac{\theta}{\mean{X}} + \frac{\smean{X^2}\theta^2}{\mean{X}^3}
  \hspace{0.5cm}\mbox{for }\theta\to0
  \:. 
\end{equation}
From \eqref{eq:Useful1} we deduce 
\begin{equation}
  \label{eq:ExpansionFreeEnergySmallK}
  \frac{\ln Z(k,n)}{n} \simeq \theta\, \ln(\EXP{}\mean{X}/\theta)  -\theta^2\frac{\mean{X^2}}{2\mean{X}^2}
  + \mathcal{O}(\theta^3)
  \:.
\end{equation}
Adding the contribution of 
$(1/n)\ln\big[k!(n-k)!/n!\big]=\theta\ln\theta+(1-\theta)\ln(1-\theta)\simeq-\theta\,\ln(\EXP{}/\theta)+\theta^2/2$, we obtain the typical value
\begin{equation}
  %\label{eq:ExpansionFreeEnergySmallK}
  \label{eq:AsympSymmProductSmallk}
  \symmetriz{ \prod_{j=1}^k X_{\pi(j)}  }_{\pi\in\mathcal{S}_n} 
   \hspace{-0.25cm}
   \sim \mean{X}^k   \exp\left\{ -\frac12 \left(\frac{\smean{X^2}}{\smean{X}^2} -1 \right) \frac{k^2}{n} \right\}
\end{equation}
for $1\ll k\ll n$. 
Clearly, the factor $\mean{X}^k$ corresponds to non random variables, while the fluctuations diminish the typical value of the product.
We will also discuss cases where $\mean{X}=\infty$ or $\mean{X^2}=\infty$ in the following.

Let us now consider $\varphi_*\to\infty$ in \eqref{eq:SaddleForTheta}~:
we can write
\begin{equation}
  1-\theta = \mean{ \frac{1}{1+\varphi_*\,X} }
\end{equation}
hence we can use the symmetry $\theta\leftrightarrow1-\theta$, $\varphi\leftrightarrow1/\varphi$ and $X\leftrightarrow1/X$ in order to relate the $\theta\to1^-$ to the $\theta\to0^+$ behaviour.
As a result 
\begin{align}
  \label{eq:ExpansionFugacityLarge}
  \frac{\ln Z(k,n)}{n} \simeq 
  &\mean{\ln X} 
  + (1-\theta) \, \ln\big[\EXP{}\mean{1/X}/(1-\theta)\big]  
  \nonumber\\
  &- (1-\theta)^2 \,\frac{\mean{1/X^2}}{2\mean{1/X}^2}
  + \mathcal{O}((1-\theta)^3)
  \:.
\end{align}
%hence, for $\mean{1/X}<\infty$, we have
%$\varphi_*(\theta)\simeq\mean{1/X}/(1-\theta)$ for $\theta\to1^-$.
%For the following, this expansion will be sufficient.
%Using \eqref{eq:Useful2}, we get
%\begin{equation}
%  \label{eq:ExpansionFugacityLarge}
%  \frac{\ln Z(k,n)}{n} \simeq \mean{\ln X} + (1-\theta) \, \ln\big[\EXP{}\mean{1/X}/(1-\theta)\big]  
%  \:,
%\end{equation}
i.e.
\begin{align}
  \label{eq:AsympSymmProductLargek}
   \symmetriz{ \prod_{j=1}^k X_{\pi(j)}  }_{\pi\in\mathcal{S}_n} 
   \hspace{-0.5cm}
   &\sim \EXP{n\mean{\ln X}} \mean{1/X} ^{n-k} 
   \\\nonumber
   &\times
    \exp\left\{ -\frac12 \left(\frac{\smean{1/X^2}}{\smean{1/X}^2} -1 \right) \frac{(n-k)^2}{n} \right\}
%   \hspace{0.25cm}
%   \mbox{for }
%   1\ll n-k\ll n
%   \:.
\end{align}
for $1\ll n-k\ll n$.



\subsubsection{A case where $\mean{1/X}=\infty$}

If the distribution $q(x)$ of $X$ is such that $q(0)$ is finite, we have $\mean{1/X}=\infty$.
For example, this occurs for the exponential distribution $q(x)=a\,\EXP{-ax}$ which we will consider below. 
Then, Eq.~\eqref{eq:SaddleForTheta} takes the form 
\begin{equation}
  \label{eq:FugacityForExpVar}
  1 - \frac{a}{\varphi_*}\,\EXP{a/\varphi_*}\,E_1(a/\varphi_*) = \theta
\end{equation}
where $E_1(z)=\int_z^\infty(\D t/t)\,\EXP{-t}$ is the exponential integral \cite{DLMF}.
An expansion for $\varphi_*\to0$ leads to (\ref{eq:FugacitySmallNbStandardCase},\ref{eq:ExpansionFreeEnergySmallK}), as it should.

When $\varphi_*\to\infty$, we obtain 
$\varphi_*(\theta)\simeq a\, (1-\theta)^{-1}\ln\big[\EXP{-\mathbf{C}}/(1-\theta)\big]$ for $\theta\to1$, where $\mathbf{C}\simeq0.577216$ is the Euler-Mascheroni constant.
The behaviour obtained above for $\mean{1/X}<\infty$, receives an additional logarithmic correction. 
Using \eqref{eq:Useful2} we get
%\begin{align}
%  \label{eq:ZknForInfiniteMeanInvX}
%  Z(k,n) \sim \EXP{n\mean{\ln X}}
%  \left[
%    a\,\frac{n\, \EXP{}}{n-k}
%    \ln\left(\frac{n\, \EXP{-\mathbf{C}}}{n-k}\right)
%  \right]^{n-k}
%\end{align}
\begin{equation}
  \label{eq:ProdForInfiniteMeanInvX}
   \symmetriz{ \prod_{j=1}^k X_{\pi(j)}  }_{\pi\in\mathcal{S}_n} 
   \hspace{-0.5cm}
   \sim \EXP{n\mean{\ln X}}
  \left[
    a\, 
    \ln\left(\frac{n\, \EXP{-\mathbf{C}}}{n-k}\right)
  \right]^{n-k}
\end{equation}
for $1\ll n-k\ll n$. Here $\mean{\ln X}=-\ln a -\mathbf{C}$.



\subsubsection{Power-law distribution~: a case with $\mean{X}=\infty$}

In the paper we are mostly interested in distributions with power-law tails, like $q(x)=\mu\,x^{-1-\mu}$ for $x>1$, such that the mean value might be divergent (when $\mu\in]0,1]$).
For this distribution, the equation \eqref{eq:SaddleForTheta} takes the form 
\begin{equation}
  \label{eq:SaddleForThetaPowerLaw}
  _2F_1\left( 1 , \mu ; 1+\mu ; -1/\varphi_* \right) = \theta
\end{equation}
where $_2F_1( a , b ; c ; z )$ is the hypergeometric function \cite{gragra,DLMF}.
As a check, we first consider $\theta\to1^-$, then we can use $_2F_1( a , b ; c ; z )\simeq 1 + a\,b\,z/c$ for $z\to0$, leading to $\varphi_*(\theta)\simeq\big[\mu/(1+\mu)\big]/(1-\theta)$.
We recognize $\mean{1/X}=\mu/(1+\mu)$, hence \eqref{eq:AsympSymmProductLargek} holds with $\mean{\ln X}=1/\mu$.

Let us now discuss the behaviour for $\theta\to0^+$. 
For this purpose we use a well-known functional relation for the hypergeometric function, which takes here the form
\begin{align}
  &_2F_1\left( 1 , \mu ; 1+\mu ; -1/\varphi \right)
  \\\nonumber
   &= \Gamma(1+\mu)\Gamma(1-\mu)\,\varphi^\mu +\frac{\mu\,\varphi}{\mu-1}\,_2F_1\left( 1 , 1-\mu ; 2-\mu ; -\varphi \right) 
\end{align}
Hence the expansion for $\varphi\to0^+$ has the form of an analytic series plus the non analytic term $\mathcal{O}(\varphi^\mu)$~:
\begin{align}
  \label{eq:Expansion2F1}  
  &_2F_1\left( 1 , \mu ; 1+\mu ; -1/\varphi \right)
  \\\nonumber
  \simeq &
  \frac{\pi\mu}{\sin\pi\mu}\,\varphi^\mu
  + \frac{\mu}{\mu-1} \,\varphi 
  - \frac{\mu}{\mu-2} \,\varphi^2
  + \mathcal{O}(\varphi^3)
  \:.
\end{align}
Depending on $\mu$, the expansion is dominated by the $\mathcal{O}(\varphi)$ or the $\mathcal{O}(\varphi^\mu)$ term.
As a result, the possible limiting behaviours of the solution of \eqref{eq:SaddleForThetaPowerLaw} are
\begin{align}
  \label{eq:FugacityForSmallTheta}
  \varphi_*(\theta)
  \underset{\theta\to0}{\simeq}
  \begin{cases}
    \Big( \frac{\sin\pi\mu}{\pi\mu} \, \theta \Big)^{1/\mu}  & \mbox{for } 0<\mu<1 
    \\[0.125cm]
    \frac{\theta}{\ln(1/\theta)}                                & \mbox{for } \mu=1
    \\[0.125cm]
    \frac{\theta}{\mean{X}} - \frac{\pi\mu}{\sin\pi\mu}\, \frac{\theta^{\mu}}{\mean{X}^{\mu+1}}
                                                                & \mbox{for } 1<\mu<2
    \\[0.125cm]
    \frac{\theta}{\mean{X}} + \frac{\theta^2}{4}\,\ln(2/\theta) & \mbox{for } \mu=2   
    \\[0.125cm]
    \frac{\theta}{\mean{X}} +  \frac{\mean{X^2}\theta^2}{\mean{X}^3}      & \mbox{for } \mu>2  
  \end{cases}
\end{align}
with $\mean{X^k}=\mu/(\mu-k)$ for $k<\mu$. 
%When $\mu>2$, i.e. $\mean{X^2}<\infty$, the $\varphi^\mu$ term can be neglected, leading to \eqref {eq:FugacitySmallNbStandardCase} and \eqref{eq:AsympSymmProductSmallk}.
%In the case $1<\mu<2$, the product is $\sim\mean{X}^k$ with a non Gaussian correction in $k$ which will be determined below.
%When $\mu<1$, i.e. $\mean{X}=\infty$, the first term in \eqref{eq:Expansion2F1} dominates and we get 
%\begin{equation}
%  \varphi_*(\theta)\simeq \left( \frac{\sin\pi\mu}{\pi\mu} \, \theta \right)^{1/\mu}
%  \:.
%\end{equation}
Let us focus on the case $\mu<1$~:
%As a consequence, 
we get from \eqref{eq:Useful1} the behaviour
\begin{align}
  \label{eq:ZknForInfiniteMeanX}
  Z(k,n) \sim  
  \left( \frac{\pi\mu}{\sin\pi\mu} \, \frac{n\,\EXP{}}{k} \right)^{k/\mu}
  \hspace{0.5cm}\mbox{for }
  1\ll k\ll n
\end{align}
and 
\begin{equation}
  \label{eq:PRVForInfiniteMeanX}
   \symmetriz{ \prod_{i=1}^k X_{\pi(i)}  }_{\pi\in\mathcal{S}_n} 
  \sim \left( \frac{\pi\mu}{\sin\pi\mu}  \right)^{k/\mu} 
  \left( \, \frac{n\,\EXP{}}{k} \right)^{k(1-\mu)/\mu}
  \:.
\end{equation}

Let us also discuss the marginal case $\mu=1$, which is a bit more tricky. Eq.~\eqref{eq:SaddleForThetaPowerLaw} takes the simple form
\begin{equation}
  \varphi_*\,\ln ( 1 + 1/\varphi_* ) = \theta
  \:.
\end{equation}
Using $\mean{\ln(1+\varphi\,X)}=(1+\varphi)\,\ln(1+\varphi)-\varphi\,\ln\varphi$ we obtain
\begin{align}
  \frac{ \ln Z(k,n) }{ n } \simeq \left( \frac{1}{\varphi_*} + 1 - \ln \varphi_* \right)\theta + \ln \varphi_* 
\end{align}
leading to 
\begin{equation}
  \label{eq:ZknForMarginalCase}
   Z(k,n) \sim \left(  \frac{n\,\EXP{}}{k}\,\ln (n/k)  \right)^{k}
\end{equation}
i.e.
\begin{equation}
  \label{eq:PRVForMarginalCase}
  \symmetriz{ \prod_{i=1}^k X_{\pi(i)}  }_{\pi\in\mathcal{S}_n} 
  \sim \left( \ln \frac nk \right)^k
  \hspace{0.5cm}\mbox{for }
  1\ll k\ll n
  \:.
\end{equation}




\subsection{Asymptotics of the coefficients $a_{n+1}^{(k)}$ and the complex Lyapunov exponent}


Using the decomposition \eqref{eq:SymmetrizedCoeff}, we can now study the precise asymptotic of the coefficients $a_{n+1}^{(k)}$ from which we deduce $\Omega$.
This will lead straightforwardly to the complex Lyapunov exponent~: 
%Our analysis is based on the representations (\ref{eq:MainRes},\ref{eq:MainRes2},\ref{eq:MainRes1}).
%The main idea is to 
we identify the optimal value of the index $k$ %, denoted $k_*$, 
which solves
\begin{equation}
  \label{eq:SaddleForK}
  \deriv{}{k} \big\{ \ln a_{n+1}^{(k)} + k \ln(-\lambda) \big\}\Big|_{k=k_*}=0
\end{equation}
and dominates the sum \eqref{eq:MainRes0}~:
$x_{n+1}(\lambda)\sim a^{(k_*)}_{n+1}\,(-\lambda)^{k_*}$.
Using the bounds $a^{(k_*)}_{n+1}\,(-\lambda)^{k_*}\leq x_{n+1}(\lambda)\leq n\,a^{(k_*)}_{n+1}\,(-\lambda)^{k_*} $ we deduce the complex Lyapunov exponent 
\begin{equation}
  \label{eq:LyapFromOptimum}
  \Omega(\lambda) = \lim_{n\to\infty}\frac{\ln \big( a^{(k_*)}_{n+1}\,(-\lambda)^{k_*} \big)}{n}
  \:.
\end{equation}
We will see below that this approach provides the asymptotic behaviours (for small $\lambda$ or large $\lambda$) in a straightforward manner.
From the series representation \eqref{eq:MainRes0}, it is clear that the $\lambda\to0^-$ limit involves coefficients with small $k$, while the $\lambda\to-\infty$ limit is related to large $k$, close to $n$.

Before entering into the detailed analysis, let us make a final remark~:
the complex Lyapunov exponent \eqref{eq:DefOmega} characterizes the typical behaviour of the solution $x_{n+1}(\lambda)$ of the initial value problem, i.e. the average of $\ln x_{n+1}(\lambda)$.
Similarly, \eqref{eq:LyapFromOptimum} shows that we only need to determine the typical value of the coefficients $a^{(k)}_{n+1}$, which justifies the study of the typical value of the random product of the previous subsection.

Now consider 
\begin{align}
  \label{eq:AsymptoticOfAnp1k}
  &\frac{\ln \big( \ssymmetriz{a^{(k)}_{n+1}}_{\pi,\sigma}\,(-\lambda)^{k} \big)}{n}
  = 
  \frac{\ln S_k(n)+2\ln\big[k!(n-k)!/n!\big]}{n} 
  \nonumber\\
  &\hspace{1cm}+ \frac{k}{n}\ln(-\lambda) + \frac{\ln Z^{(1/\K)}(k,n)}{n} + \frac{\ln Z^{(m)}(k,n)}{n}
  \nonumber\\
  & 
  \underset{n\to\infty}{=}
   (1+\theta)\ln(1+\theta)+(1-\theta)\ln(1-\theta)+\theta\ln\big[(-\lambda)/4\big]
  \nonumber\\
  &\hspace{1cm}
   -\int_0^\theta\D t\, \ln \varphi_*^{(1/\K)}(t)-\int_0^\theta\D t\, \ln\varphi_*^{(m)}(t)  
\end{align}
where $Z^{(1/\K)}(k,n)$ and $Z^{(m)}(k,n)$ are related to the symmetrized products of inverse spring constants and masses, respectively, and $\varphi_*^{(1/\K)}(\theta)$, $\varphi_*^{(m)}(\theta)$ the two corresponding fugacities, solutions of the transcendental equations (\ref{eq:Transcendental-K},\ref{eq:Transcendental-m}).
Removing $(-\lambda)^k$ in Eq.~\eqref{eq:AsymptoticOfAnp1k} gives the asymptotic of the symmetrized coefficient $a^{(k)}_{n+1}$.
Assuming that we can replace the coefficient in \eqref{eq:LyapFromOptimum} by the symmetrized one, we get
\begin{align}
  \label{eq:MainResultForOmega}
  \Omega(\lambda) = - \underset{\theta}{\mathrm{min}}
  \int_0^\theta\D t\, \ln\left[
    \frac{4}{(-\lambda)}\,\frac{1-t}{1+t}\,\varphi_*^{(1/\K)}(t)\varphi_*^{(m)}(t)
  \right]
  \:.
\end{align}
The position of the minimum, which we will denote $\theta_*(\lambda)=k_*/n\in[0,1]$, is given by solving
\begin{equation}
  \label{eq:ThetaStar}
  \varphi_*^{(1/\K)}(\theta)\varphi_*^{(m)}(\theta) = \frac{(-\lambda)}{4}\,\frac{1+\theta}{1-\theta}
  \:,
\end{equation}
which is equivalent to \eqref{eq:SaddleForK}.
Eq.~\eqref{eq:MainResultForOmega} is a central result.
We stress that the only approximation which has been used to get \eqref{eq:MainResultForOmega} is the symmetrization of the coefficients, $a^{(k)}_{n+1}\simeq\ssymmetriz{a^{(k)}_{n+1}}_{\pi,\sigma}$.
From this respect, \eqref{eq:MainResultForOmega} is not an exact formula, although we will see that it provides accurate predictions.

Expressing $Z(k,n)$ with \eqref{eq:Useful2}, we get the alternative representation
\begin{align}
  \label{eq:MainResultForOmegaBis}
  \Omega(\lambda) 
  &=
  \ln(-\lambda) + \mean{\ln(m/K)}
  \\\nonumber
  &+
   \underset{\theta}{\mathrm{max}}
  \int_\theta^1\D t\, \ln\left[
    \frac{4}{(-\lambda)}\,\frac{1-t}{1+t}\,\varphi_*^{(1/\K)}(t)\varphi_*^{(m)}(t)
  \right]
  \:,
\end{align}
which will be more appropriate for the study of the $\lambda\to-\infty$ limit.


