\subsection{Marginal case $\nu=1$ with $\mu<1$ ($\mean{1/\K_n}=\infty$)}

Eq.~\eqref{eq:ThetaStar} gives 
\begin{equation}
  \theta_* \simeq \left[ d_\mu\, (-\lambda)\, \ln1/\theta_* \right]^{\eta}
\end{equation}
where $\eta=\mu/(\mu+1)$ and $d_\mu=(\pi\mu/\sin\pi\mu)^{1/\mu}/4$.
The integral \eqref{eq:MainResultForOmega} gives
\begin{equation}
  \Omega\simeq \theta_*\,
  \left\{
    \ln \left[
      d_\mu\, (-\lambda)\,\left(\frac{\EXP{}}{\theta}\right)^{1/\eta} \ln1/\theta_*
    \right]
    +\mathcal{O}(1/\ln(1/\theta_*))
  \right\}
\end{equation}
leading again to $\Omega\simeq \theta_*/\eta$, i.e
\begin{equation}
  \Omega(\lambda) \simeq 
  \eta^{\eta-1}   \left( -d_\mu\,\lambda \, \ln[1/(-\lambda\,d_\mu)] \right)^\eta
  \:.
\end{equation}



\subsection{Marginal case $\mu=1$ with $\nu<1$ ($\mean{m_n}=\infty$)}

By symmetry we have 
\begin{equation}
  \Omega(\lambda) \simeq 
  \eta^{\eta-1}   \left( -d_\nu\,\lambda \, \ln[1/(-\lambda\,d_\nu)] \right)^\eta
  \:.
\end{equation}
where $\eta=\nu/(\nu+1)$.

