\end{equation}
Analytic continuation to $\lambda>0$ contains a real part 
\begin{equation}
  \label{eq:LyapPertub}
  \gamma(\lambda) 
  \underset{ \lambda\to0^+ }{ \simeq }
  \frac{\smean{m} \smean{\K^{-1}}}{8}
