\section{Dyson's ``type I'': Anderson model with random couplings}
\label{sec:DysonTypeI}

%%%%%%%%%%%%%%%%%%%%%%


%%%%%%%%%%%%%%%%%%%%%%

  Dyson introduced the variables
  \begin{equation}
  \lambda_{2n-1} \eqdef \frac{\K_n}{m_n}
  \hspace{0.5cm}\mbox{and}\hspace{0.5cm}
  \lambda_{2n} \eqdef \frac{\K_n}{m_{n+1}}
  \end{equation}
and distinguished between ``type I'' and ``type II'' disorder \cite{Dys53,For21}.
Let us extend Dyson's classification~:
\begin{itemize}[leftmargin=*,align=left,itemsep=0.125cm]
\item
 Type I~: $\lambda_{j}$'s are i.i.d. random variables, which requires some unnatural correlations between $\K_n$'s and $m_n$'s.
 This model is the Anderson model for random couplings studied in this section. 
 It has been solved by Dyson when $\lambda_{j}$'s are distributed with a Gamma law~\cite{Dys53}.

\item
  Type II~: $\K_n=\K$ $\forall\,n$, while $m_n$'s are i.i.d. random variables. 
  Thus Dyson's parameters come in pairs as $\lambda_{2n}=\lambda_{2n+1}$.
  This case was studied by Schmidt \cite{Sch57} and many others (see Section~\ref{sec:Intro}).

\item
  Type II'~: $m_n=m$ $\forall\,n$ and $\K_n$'s are i.i.d. random variables.
  We have now  $\lambda_{2n-1}=\lambda_{2n}$.
  The spectral density was studied in \cite{BerSchWys80,AleBerSchOrb81} and the localization in~\cite{Zim82}.

\item
  Type III~: both $\K_n$'s and $m_n$'s are i.i.d. random variables. This case was considered in Refs.~\cite{Nie84,BerLeDRosTex24} and in the present article (previous sections). 
\end{itemize}

Starting with $N$ masses, Dyson's analysis for ``type I'' has relied on a mapping of the $N$ equations \eqref{eq:WaveEquation} onto the tight binding equation describing the Anderson model with random couplings~:
\begin{equation}
  \label{eq:AndersonRandomCouplings}
  - \rh_{n}^*\, \psi_{n+1}  - \rh_{n-1}\, \psi_{n-1}  = \omega\, \psi_{n}
  \:,
\end{equation}
with $n=1,\cdots,2N-1$. 
The couplings are related to the original parameters as $\rh_{n}=\I\sqrt{\lambda_n}$ \cite{Dys53}.
In the following we will rather consider Eq.~\eqref{eq:AndersonRandomCouplings} for real couplings $\rh_{n}$, as the phase plays no role.
This model has been much studied in the literature, from the perspective of quantum localization \cite{Bus75,TheCoh76,EggRie78,Dha80,Zim82}.


We now apply the combinatorial method to this case.
The spectral problem is defined by boundary conditions $\psi_0=\psi_{2N+1}=0$, which leads to $N$ pairs of eigenvalues $\pm\omega_\alpha$.
The fact that the solutions of the spectral problem \eqref{eq:AndersonRandomCouplings} come in pairs $\pm\omega_\alpha$ reflects the symmetry in (\ref{eq:WaveEquation},\ref{eq:AndersonRandomCouplings}) and explains the doubling of the number of equations~\cite{For21}.
We now study the initial value problem, i.e. we set $  \psi_0=0 $ and $\psi_1=1$ and solve the recurrence 
\begin{equation}
  \label{eq:RecurrenceAMOD}
  \psi_{n+1}(\omega)  = -\frac{\omega}{\rh_n}\, \psi_{n}(\omega) -\frac{ \rh_{n-1}}{\rh_n}\, \psi_{n-1}(\omega)
  \:.
\end{equation}
It is instructive to write the first terms (for $\lambda=-\omega$)~:
\begin{align}
  \psi_2(-\lambda) &= \frac{\lambda}{\rh_1}
  \\
  \psi_3(-\lambda) &= 
  \frac{-\rh_1}{\rh_2} + \frac{\lambda}{\rh_2}\,\frac{\lambda}{\rh_1}
  \\
  \psi_4(-\lambda) &= 
  \frac{\lambda}{\rh_3}\,\frac{-\rh_1}{\rh_2}
  +\frac{-\rh_2}{\rh_3}\,\frac{\lambda}{\rh_1}
  + \frac{\lambda}{\rh_3}\,\frac{\lambda}{\rh_2}\,\frac{\lambda}{\rh_1}
  \\
  \psi_5(-\lambda) &= 
   \frac{-\rh_3}{\rh_4}\,\frac{-\rh_1}{\rh_2}
   + \frac{\lambda}{\rh_4}\,\frac{\lambda}{\rh_3}\,\frac{-\rh_1}{\rh_2}
   + \frac{\lambda}{\rh_4}\,\frac{-\rh_2}{\rh_3}\,\frac{\lambda}{\rh_1}
   \nonumber\\
   &\hspace{1cm}
   + \frac{-\rh_3}{\rh_4}\,\frac{\lambda}{\rh_2}\,\frac{\lambda}{\rh_1}
   + \frac{\lambda}{\rh_4}\,\frac{\lambda}{\rh_3}\,\frac{\lambda}{\rh_2}\,\frac{\lambda}{\rh_1}
\end{align}
etc. 
For an even number of sites, writing \eqref{eq:AndersonRandomCouplings} as $\sum_mH_{nm}\psi_m=\omega\psi_n$ 
%with $n,\,m\in\{1,\cdots,2N\}$ and 
where $H$ is a $2N\times2N$ tridiagonal matrix, we have 
\begin{equation}
  \psi_{2N+1}(\omega) 
  = \frac{\prod_{\alpha=1}^N(\omega^2-\omega_\alpha^2)}{\prod_{j=1}^{2N}\rh_j} 
  = \frac{\det\left( \omega\,\mathbf{1}_{2N} - H \right)}{\prod_{j=1}^{2N}\rh_j}
  \:,
\end{equation}
which emphasizes once more that $\psi_{2N+1}(\omega)$ is also the spectral determinant of the tight binding Hamiltonian $H$
(see appendices of Refs.~\cite{GraTexTou14,FyoLeDRosTex18}).
For an odd number of sites, we have 
\begin{equation}
   \psi_{2N}(\omega) 
  = -\frac{\omega\prod_{\alpha=1}^{N-1}(\omega^2-\omega_\alpha^2)}{\prod_{j=1}^{2N-1}\rh_j} 
  = -\frac{\det\left( \omega\,\mathbf{1}_{2N-1} - H \right)}{\prod_{j=1}^{2N-1}\rh_j}
\end{equation}
This illustrates that for an even number of sites, eigenfrequencies comes in pairs $\pm\omega_\alpha$ with $\omega_\alpha>0$, while for an odd number of sites, there is an additional eigenvalue $\omega_0=0$ (the existence of a zero mode is a topological effect).

Given the solution, the aim is to analyze the complex Lyapunov exponent
\begin{equation}
  \Omega(\omega) = \lim_{N\to\infty} \frac{\ln \psi_{N+1}(\omega)}{N}
  \:.
\end{equation}

As before, we write the solution of the initial value problem as a polynomial in~$\omega$~:
\begin{equation}
  \psi_{n+1}(\omega) = \sum_{k=0}^n \psi_{n+1}^{(k)}\,(-\omega)^k
\end{equation}
%Example~:
%\begin{equation}
%  \psi_{5}^{(2)} = 
%  \frac{1}{\rh_4}\left( 
%    \frac{1}{\rh_3}\,\frac{-\rh_1}{\rh_2}
%   +  \frac{-\rh_2}{\rh_3}\,\frac{1}{\rh_1}
%   + (-\rh_3) \,\frac{1}{\rh_2}\,\frac{1}{\rh_1}
%    \right)
%    \:.
%\end{equation}
Inspection of the recurrence \eqref{eq:RecurrenceAMOD} (or the above determinantal representations) shows that 
$\psi_{2n+1}(-\omega)=\psi_{2n+1}(\omega)$ and $\psi_{2n}(-\omega)=-\psi_{2n}(\omega)$. 
%the coefficient $\psi_{n+1}^{(k)}$ is obtained by picking $k$ times the first term of the recurrence \eqref{eq:RecurrenceAMOD} and $n-k$ times the second term.
%Consequently for an even number of sites $\psi_{2n+1}^{(2j+1)}=0$ and for an odd number of sites $\psi_{2n}^{(2j)}=0$.
As a consequence, the odd coefficients for even number of sites vanish $\psi_{2n+1}^{(2j+1)}=0$, and similarly $\psi_{2n}^{(2j)}=0$.
We have
\begin{widetext}
\begin{align}
  \psi_{2n+1}^{(0)} & = \frac{-\rh_{2n-1}}{\rh_{2n}}\cdots\frac{-\rh_3}{\rh_4}\,\frac{-\rh_1}{\rh_2}
  = \prod_{j=1}^n \frac{-\rh_{2j-1}}{\rh_{2j}}
  \hspace{0.5cm}\mbox{and } \psi_{2n}^{(0)}=0
  \\
    \psi_{2n}^{(1)} & 
    =\sum_{j=0}^{n-1} 
    \frac{-\rh_{2n-2}}{\rh_{2n-1}} \cdots\frac{-\rh_{2j+2}}{\rh_{2j+3}}\,
    \frac{1}{\rh_{2j+1}}\,
    \frac{-\rh_{2j-1}}{\rh_{2j}}\cdots\frac{-\rh_3}{\rh_4}\,\frac{-\rh_1}{\rh_2} 
  \hspace{0.5cm}\mbox{and } \psi_{2n+1}^{(1)}=0
  \\
    \psi_{2n+1}^{(2)} & 
    =\sum_{j_1>j_2}  
    \frac{-\rh_{2n-1}}{\rh_{2n}}\cdots
    \frac{-\rh_{2j_1+1}}{\rh_{2j_1+2}}\,
    \frac{1}{\rh_{2j_1}}\,
    \frac{-\rh_{2j_1-2}}{\rh_{2j_1-1}} \cdots\frac{-\rh_{2j_2+2}}{\rh_{2j_2+3}}\,
    \frac{1}{\rh_{2j_2+1}}\,
    \frac{-\rh_{2j_2-1}}{\rh_{2j_2}}\cdots\frac{-\rh_3}{\rh_4}\,\frac{-\rh_1}{\rh_2} 
  \hspace{0.5cm}\mbox{and } \psi_{2n}^{(2)}=0
\end{align}
\end{widetext}
etc.
It is interesting to introduce the notation 
\begin{equation}
  w_n \eqdef \ln \rh_n
\end{equation}
We can rewrite
\begin{align}
  \psi_{2n+1}^{(0)} & = (-1)^n \,\EXP{ B_n }
  \\
    \psi_{2n}^{(1)} & 
    =(-1)^{n-1} \sum_{j_1=0}^{n-1} \EXP{ B_n(j_1) }
      \\
    \psi_{2n+1}^{(2)} & 
    =(-1)^n \sum_{0\leq j_2<j_1\leq n-1}   \EXP{ B_n(j_1,j_2) }
\end{align}
etc, where 
\begin{align}
 \label{eq:Bn0}
 B_n &= \sum_{k=1}^{n} (-w_{2k} + w_{2k-1})
 \\
 B_n(j_1) &= 
 \sum_{k=j_1+1}^{n-1} (-w_{2k+1} + w_{2k})
 -w_{2j_1+1}
 \nonumber\\
 &
 +\sum_{k=1}^{j_1} (-w_{2k} + w_{2k-1})
 \label{eq:Bn1}
 \\
 B_n(j_1,j_2) &=
 \sum_{k=j_1+1}^{n} (-w_{2k} + w_{2k-1})
 - w_{2j_1}
 \nonumber\\
 &
  + \sum_{k=j_2+1}^{n-1} (-w_{2k+1} + w_{2k})
 -w_{2j_2+1}
 \nonumber\\
 &
 +\sum_{k=1}^{j_2} (-w_{2k} + w_{2k-1})
 \label{eq:Bn2}
\end{align}
etc.
Considering $B_n$ as a random walk, we see that each insertion of an index $j_m$ corresponds to introduce a reflection in the random walk (see Fig.~\ref{fig:ExpB}).

Being interested in an even number of sites, we should consider random walks with $2r$ reflections
\begin{equation}
   \psi_{2n+1}^{(2r)} 
    =(-1)^{n-r} \sum_{j_{2r}<\cdots< j_2<j_1}   \EXP{ B_n(j_1,j_2,\cdots,j_{2r}) }
\end{equation}
This picture makes easy to estimate the dominant contribution to
\begin{align}
  \label{eq:Psi2N}
  &\psi_{2n+1}(-\lambda) = \sum_{r=1}^n \psi_{n+1}^{(2r)}\,\lambda^{2r}
  \\\nonumber
  = &\sum_{r=1}^n   (-1)^{n-r} \lambda^{2r}\sum_{j_{2r}<\cdots< j_2<j_1}   \EXP{ B_n(j_1,j_2,\cdots,j_{2r}) }
\end{align}
%The random walk is interrupted $2r$ times.
The term which dominates the sum is the one where the $2r$ reflections are such that the $2r$ pieces of $B_n(j_1,j_2,\cdots,j_{2r})$ are positive. 
For small $\lambda$, we expect that the sum is dominated by the terms with small~$r/n$.

\begin{figure}[!ht]
\centering
\includegraphics[scale=0.6]{fig6-Bm1m2}
\caption{\it 
The three random walks
$B_n$ (blue), $B_n(j_1)$ (orange) and $B_n(j_1,j_2)$ (green). 
The arrows indicate the positions of $j_1$ and $j_2$.
}
\label{fig:ExpB}
\end{figure}

We assume that
\begin{equation}
  \mean{(\ln \rh_j)^2} < \infty
\end{equation}
so that $B_n$ is a normal symmetric random walk, i.e. it scales as $B_n\sim\sqrt{n}$ and $\mean{B_n}=0$.
The $2r$ reflections split the random walk into $2r+1$ pieces, each piece being of order $\sim\sqrt{2n/2r}$.
Among the $2^{2r}$ trajectories obtained by introducing $2r$ reflections, there exists one optimal case for which the $2r+1$ pieces are all \textit{positive} (see Fig.~\ref{fig:ExpB})~:
\begin{equation}
  B_n(j_1,j_2,\cdots,j_{2r})\big|_{\mathrm{optimal}} \sim 2r \,\sqrt{n/r} = 2\sqrt{n\,r}
\end{equation}
Inserting this behaviour in the sum \eqref{eq:Psi2N}, we see that the sum is dominated by the optimal $r$ solution of 
\begin{equation}
  \deriv{}{r} \left(2r\,\ln(\lambda) + 2\sqrt{n\,r} \right) = 0
\end{equation}
so that $r_*\approx n/\big[4\ln^2(1/\lambda)\big]$, which is consistent with the assumption on $r$.
Correspondingly 
\begin{equation}
  \label{eq:Susy-Psi2n+1}
  \psi_{2n+1}(-\lambda)  \sim \EXP{2[r_*\,\ln(\lambda) + \sqrt{n\,r_*}]}
  \sim \exp\left\{n/\big[2\ln(1/\lambda)\big]\right\}
\end{equation}
Note that we have neglected in $B_n(j_1,\cdots,j_{2r})$ the contributions of the $2r$ ``isolated'' $-w_{2j'}$'s, cf. (\ref{eq:Bn1},\ref{eq:Bn2}). They contribute to $B_n(j_1,\cdots,j_{2r})$ typically as $-2r_*\mean{w_{j}}\sim n\mean{w_{j}}/\ln^2(\lambda)$, which is indeed negligible compared to $n/\ln(1/\lambda)$ in the exponential of Eq.~\eqref{eq:Susy-Psi2n+1}.
Finally, we deduce
\begin{equation}
  \Omega(\omega)=\gamma(\omega)\sim \frac{1}{2\ln[1/(-\omega)]}
  \hspace{0.5cm}
  \mbox{for }
  \omega\to0^-
  \:.
\end{equation}
Analytic continuation to $\omega>0$ gives 
\begin{equation}
   \gamma(\omega) \sim \frac{1}{\ln(1/\omega)}
    \hspace{0.25cm}  \mbox{and}   \hspace{0.25cm}
  \IDoS(\omega) \sim \frac{1}{\ln^2(1/\omega)}
   \hspace{0.25cm} \mbox{for }
  \omega\to0^+
  \:. 
\end{equation}
We have recovered the expected Dyson singularity $\varrho(\omega)=\IDoS'(\omega)\sim1/\big[\omega\ln^3(1/\omega)\big]$ obtained in~\cite{Dys53,TheCoh76,EggRie78,Dha80,Zim82}.


