\end{equation}
hence the solution of the initial value problem is related to the (Dirichlet/Dirichlet) spectral determinant as 
\begin{equation}
  x_{N+1}(\lambda)  =  \frac{1}{\K_0}\prod_{j=1}^N\frac{m_j}{\K_j}
  \:\det\left( \Lambda - \lambda\,\mathbf{1}_N \right)
  \:.
\end{equation}
Compared to the Neumann/Dirichlet case (when $\K_0=0$), Eq.~\eqref{eq:SpectralDet-Neumann/Dirichlet}, there is an additional factor $1/\K_0$.



\section{Continuous models}

\subsection{Elastic model}

Writing the equation \eqref{eq:WaveEquation2} under the form 
\begin{equation}
 -m_n\lambda\, y_n 
 = \K_{n}\, (y_{n+1} - y_n)  -  \K_{n-1}\, (y_n - y_{n-1}) 
\end{equation}
makes clear what is the continuum limit of the model~:
set $x=n\,\epsilon$, where $\epsilon$ is a lattice spacing, $y(x)=y_n$, $k(x)=\epsilon^2\K_n$ and $m(x)=m_n$.
Assuming that $k(x)$ and $m(x)$ are two smooth functions at the scale of $\epsilon$, in the limit $\epsilon\to0$ we get
\begin{equation}
  \label{eq:ElasticModel}
  - m(x)\lambda\, y(x) = \partial_x  k(x)\partial_x  y(x) 
  \:.
\end{equation}
We adapt the derivation of Section~\ref{sec:Combinatorics} to this continuous model.
We search the solution under the form
\begin{equation}
  y(x) = \sum_{k=0}^\infty (-\lambda)^k \, a_{k}(x)
\end{equation}
for initial conditions $y(0)=0$ and $y'(0)=1/k(0)$.
The coefficient $a_0(x)$ solves the homogeneous equation, leading to
\begin{equation}
  a_0(x) = \int_0^x\frac{\D u}{k(u)}
\end{equation}
and fulfills the two initial conditions $y(0)=a_0(0)=0$ and $y'(0)=a_0'(0)=1/k(0)$. The other coefficients solve the recurrence
\begin{equation}
  \partial_x k(x)\partial_x  a_{k}(x) = m(x)\,a_{k-1}(x)
\end{equation}
for initial condition $a_{k}(0)=a_{k}'(0)=0$.
We find 
\begin{equation}
  a_{k}(x) = \int_0^x\D t \,a_{k-1}(t)\, m(t) \int_t^x\frac{\D u}{k(u)}
  \:,
\end{equation}
hence we can write
\begin{align}
  \label{eq:CoeffElasticModel}
  a_{k}(x) &= 
  \hspace{-0.5cm}
  \int\limits_{0<t_1<\cdots<t_k<x}
  \hspace{-0.5cm}
  \D t_1\cdots\D t_k
  \prod_{p=0}^k  m(t_p)\int_{t_p}^{t_{p+1}}\frac{\D u_p}{k(u_p)} 
  \\
  & = 
 \hspace{-1.25cm}
  \int\limits_{0<u_0<t_1<u_1<\cdots<t_k<u_k<x}
  \hspace{-1.25cm}
  \D u_0\D t_1\D u_1\cdots\D t_k\D u_k
  \prod_{p=0}^k  \frac{m(t_p)}{k(u_p)} 
\end{align}
where $t_0=0$, $t_{k+1}=x$ and $m(0)=1$ have made the formula more compact.
This is the continuous version of Eq.~\eqref{eq:CoeffForDirDir}.


\subsection{Supersymmetric model}

Interesting features of the Anderson model with random hoppings \eqref{eq:AndersonRandomCouplings} occur in the band center ($E=0$).
For hoppings of the form $\rh_n=[1/\epsilon -(-1)^nm(x)]/2$ where $x=(n+/2)\epsilon$, $\epsilon\to0$ being a lattice spacing, the Anderson model for small energy is mapped onto the Dirac equation for $\widetilde{\mathcal{H}}_D=-\I\sigma_z\partial_x+\sigma_y\,m(x)$.
We prefer to consider the rotated Hamiltonian $\mathcal{H}_D=\I\sigma_y\partial_x+\sigma_x\,m(x)$, whose square involves a pair of supersymmetric partner Hamiltonians $H_+=Q^\dagger Q$ and $H_-=QQ^\dagger$, with $Q=-\partial_x+m(x)$.
Localization for the supersymmetric Hamiltonian 
\begin{equation}
  \label{eq:Hsusy}
  H_+ = Q^\dagger Q = -\EXP{U(x)}\partial_x\EXP{-2U(x)}\partial_x\EXP{U(x)} 
  \:,
\end{equation}
where $U(x)=-\int_0^x\D y\,m(y)$,
has been much studied \cite{BouComGeoLeD90,Tex00,ComTexTou11,ComTexTou13} (for reviews, cf. Refs.~\cite{ComTex98,TexHag10}).
When $\mean{m(x)}=0$, the model is well-known to present the Dyson singularity $\rho(E)\sim1/(E|\ln E|^3)$ recovered in Section~\ref{sec:DysonTypeI} for the discrete Anderson model.
We apply the method for the construction of the initial value problem
\begin{equation}
  H_+ \psi(x;E) = E \,\psi(x;E)
\end{equation}
for initial conditions $\psi(0;E)=0$ and $\psi'(0;E)=1$.
We expand the solution in powers of the spectral parameter
\begin{equation}
  \psi(x;E) = \sum_{k=0}^\infty (-E)^k \, a_{k}(x)
\end{equation}
where the coefficients obey the recurrence 
\begin{equation}
  \label{eq:Susy-Recu-ak}
  H_+ a_{k}(x) = - a_{k-1}(x)
\end{equation}
with $a_{k}(0)=0$ and $a_{k}'(0)=\delta_{k,0}$.
Using the specific structure of the Hamiltonian $H_+$, we easily obtain the two independent solutions of $H_+\psi=0$~:
\begin{equation}
  \psi_0(x) = \EXP{-U(x)} 
  \hspace{0.25cm}\mbox{and}\hspace{0.25cm}
  \psi_1(x) = \psi_0(x)\int_0^x\frac{\D y}{\psi_0(y)^2}
  \:.
\end{equation}
Clearly $Q\psi_0(x)=0$ and $Q\psi_1(x)=-1/\psi_0(x)$.
Making use of these remarks, we get $a_0(x) = \psi_1(x)$ and
\begin{equation}
%  a_0(x) = \psi_1(x)
%  \hspace{0.25cm}\mbox{and}\hspace{0.25cm}
  a_k(x) = \psi_1(x)\int_0^x\D y\,\psi_0(y)\,a_{k-1}(y)
  \:.
\end{equation}
Iteration gives 
\begin{equation}
  a_k(x) = \psi_1(x)
  \hspace{-0.5cm}
  \int\limits_{0<y_1<\cdots<y_k<x}
  \hspace{-0.5cm}
  \D y_1\cdots\D y_k\,
\prod_{p=1}^k \psi_0(y_p)\,\psi_1(y_p)
\end{equation}
with $\psi_0(y)\,\psi_1(y)=\EXP{-2U(x)}\int_0^y\D t\, \EXP{2U(t)}$. 
%Introducing the chronological ordering operator $\mathrm{T}$ defined as $\mathrm{T}\big[f(x)g(x')\big]=f(x)g(x')$ for $x>x'$ and $f(x')g(x)$ for $x'>x$, we can resum the series, leading to 
%\begin{equation}
%  \psi(x ; E ) = \psi_1(x) \, \mathrm{T}
%  \exp\left\{
%    -E \int_0^x\D y\,\psi_0(y)\,\psi_1(y)
%  \right\}
%\end{equation}
The structure of the coefficients is similar to the one of the elastic model, Eq.~\eqref{eq:CoeffElasticModel}~:
this can be understood by comparing \eqref{eq:Hsusy} with the operator 
\begin{equation}
\Lambda=-m(x)^{-1}\partial_x k(x)\partial_x
\end{equation}
 involved in the elastic model~\eqref{eq:ElasticModel}. Clearly, there is a correspondence when $m(x)=k(x)=\EXP{-2U(x)}$.

 \medskip

\paragraph*{Remark~:} 

the calculus of the coefficients $a_k(x)$ share some similarity with the problem of first passage time of a diffusive particle submitted to a drift $F(x)=-U'(x)$.
Consider such a particle starting from $x_0$.
We study the time of first passage at $x=b>x_0$. 
It is well-known that the $k$-th moment of the first passage time, denoted $T_k(x_0)$, obeys the backward Fokker-Planck equation with a source term given by the $(k-1)$-th moment
\begin{equation}
\label{eq:Recu-FirstPassage}
  \mathscr{G}_x T_k(x) = -k\,T_{k-1}(x)
\end{equation}
with boundary condition $T_k(b)=0$. 
The generator of the diffusion can be written as $\mathscr{G}_x=(1/2)\partial_x^2-U'(x)\partial_x=(1/2)\EXP{2U(x)}\partial_x\EXP{-2U(x)}\partial_x$, where  the diffusion constant is $D=1/2$.
Furthermore, choosing a reflecting boundary condition $T_k'(0)=0$ at $x=0<x_0$,  we get
\begin{equation}
  T_k(x_0) = 2k \int_{x_0}^b \D x \,\EXP{2U(x)} \int_0^x\D y\,\EXP{-2U(y)} \, T_{k-1}(y)
\end{equation}
see the monograph \cite{Gar89} (or Appendix of \cite{Tex00} for a short reminder).
These moments were studied for a disordered potential in \cite{CasLeD01}.

Interestingly, the recurrence \eqref{eq:Susy-Recu-ak} is related to the recurrence \eqref{eq:Recu-FirstPassage}.
Introducing $\tau_k(x) = (-2)^k\,k!\,\EXP{U(x)}\,a_k(x)$ we indeed get 
$\mathscr{G}_x \tau_k(x) = -k\,\tau_{k-1}(x)$.
However the difference between the two problems lies in the boundary conditions~:
the conditions given above for the coefficients $a_k(x)$'s rewrite
$\tau_k(0)=0$ and $\partial_x\big[\EXP{-U(x)}\tau_k(x)\big]\Big|_{x=0}=\delta_{k,0}$, hence there is no correspondence with the moments of the first passage time (in particular $\tau_0(x)=\EXP{U(x)}a_0(x)=\int_0^x\D y\,\EXP{2U(y)}\neq1$).


