\begin{align}
\nonumber  
S_k(n) &= \sum_{m=k}^n \oint\frac{\D s}{2\I\pi} \frac{Z_k(s)}{s^{m+1}}
=  \oint\frac{\D s}{2\I\pi}\,Z_k(s) \frac{s^{-n-1}-s^{-k}}{1-s}
  \\
%\nonumber
  &=\oint\frac{\D s}{2\I\pi}\frac{1}{(1-s)^{2k+1}} \left[\frac{1}{s^{n-k+1}} - 1 \right]
\end{align}
Because the second term is analytic at $s=0$, its contribution to the integral vanishes.
Using  $(1-s)^{-\alpha}=\sum_{n=0}^\infty\big[(\alpha)_n/n!\big]\,s^n$, 
where $(\alpha)_n=\Gamma(\alpha+n)/\Gamma(\alpha)$ is the Pochhammer symbol, we finally obtain
\begin{equation}
  \label{eq:SumSnk}
  S_k(n) = \frac{(n+k)!}{(n-k)!(2k)!}
  =\begin{pmatrix}
    n+k \\ 2k
  \end{pmatrix}
\end{equation}
%(to get the result, it is more easy to use 
%$(1-s)^{-\alpha}=\sum_{n=0}^\infty\big[(\alpha)_n/n!\big]\,s^n$
%where $(\alpha)_n=\Gamma(\alpha+n)/\Gamma(\alpha)$ is the Pochhammer symbol).
Asymptotics for $n\gg k\gg1$ is easily found from the Stirling formula
\begin{equation}
  \label{eq:SumSnkAsymp}
  S_k(n)   \simeq \frac{1}{\sqrt{4\pi k}} \left(\frac{n\,\EXP{}}{2k}\right)^{2k}
  \:.
\end{equation}


\subsection{General method}
\label{app:ComputationOfNiceSums}

We generalize the method of the previous subsection in order to deal with other sums involved in the paper.
We consider a sum of the form 
\begin{equation}
  \Sigma_{k}(n) =\sum_{1\leq i_1 < i_2 < \cdots < i_{k} \leq n}  \prod_{m=1}^{k} f(i_{m}-i_{m-1}) 
\end{equation}
with $i_0=0$, where $f(x)$ is some function.

(i)
In a first step, we rewrite the sum under the form
\begin{equation}
  \Sigma_{k}(n) = \sum_{m=k}^n \sigma_{k}(m)
\end{equation}
where 
\begin{equation}
   \sigma_{k}(n) =  \sum_{q_1=1}^\infty\cdots\sum_{q_k=1}^\infty  \delta_{n,q_1+\cdots+q_k} \prod_{m=1}^{k} f(q_m)
\end{equation}
Note that this expression shows that $\sigma_{k}(n)=0$ for $n<k$.

(ii)
In a second step we introduce the generating function 
\begin{equation}
  Z_{k}(s) = \sum_n s^n \sigma_{k}(n) =  \big[ \check{f}(s) \big]^k  
\end{equation}
where
\begin{equation}
  \check{f}(s) = \sum_{j=1}^\infty f(j) \, s^j
\end{equation}
The function $f$ should be such that the series is convergent at least in a small domain around $s=0$.
In the continuum, $\check{f}$ would be the Mellin transform of~$f$.

(iii)
We represent $\sigma_{k}(m)$ in term of the contour integral and sum over $m$ to get $\Sigma_{k}(n) $~:
\begin{align}
  \Sigma_{k}(n)  = \sum_{m=k}^n \oint\frac{\D s}{2\I\pi} \frac{Z_{k}(s)}{s^{m+1}}
  = \oint\frac{\D s}{2\I\pi} \frac{\big[ \check{f}(s) \big]^k(s^{-n-1}-s^{-k})}{1-s}
\end{align}
where the contour of integration encircles once the origin, in the complex plane.
Since $\check{f}(s)\sim s$ for $s\to0$, the function $[ \check{f}(s)]^k s^{-k}/(1-s)$ is analytic at $s=0$, hence do not contribute to the contour integral, thus  
\begin{align}
  \Sigma_{k}(n) = \oint\frac{\D s}{2\I\pi}\, \frac{\big[ \check{f}(s) \big]^k}{s^{n+1}(1-s)}
  \:.
\end{align}

(iv) The last step~: asymptotic of the sum for large $n$ is obtained thanks to some saddle point approximation~:
\begin{equation}
  \label{eq:SigmaknAsymp}
   \Sigma_{k}(n) \sim \frac{\big[ \check{f}(s_*) \big]^k}{s_*^{n+1}(1-s_*)}
   \hspace{0.25cm}\mbox{for } n\to\infty
   \:,
\end{equation} 
 where $s_*$ is the solution of 
\begin{equation}
  \label{eq:SaddlePoint}
  \deriv{}{s}
  \big[
    (n+1)\ln(1/s) - \ln(1-s) + k\,\ln \check{f}(s)
  \big]   =0
  \:.
\end{equation} 
In the limit $n\gg k,\:1$, we expect the sum to be dominated by a saddle point $s_*$ close to $1$.


\subsubsection{First illustration}

We compute the sum
\begin{equation}
  \label{eq:DefRnk}
  R_{k,\mu}(n) = 
  \hspace{-0.5cm}  
  \sum_{1\leq i_1<i_2 <\cdots<i_{k}\leq n} \prod_{m=1}^{k} (i_{m}-i_{m-1})^{1/\mu}
  \:.
\end{equation}
We follow the method of the paragraph~\ref{app:ComputationOfNiceSums}.
In this case the function is $f(x)=x^{1/\mu}$, hence
\begin{equation}
  \check{f}(s) = \sum_{j=1}^\infty j ^ {1/\mu} \, s^j
  = \mathrm{Li}_{1/\mu}(s)
\end{equation}
is the polylogarithm function \cite{DLMF}. Because we need $\check{f}(s)$ in the $s\to1^-$ limit, we can more simply write
\begin{equation}
  \label{eq:intB13}
  \check{f}(s)\simeq \int_0^\infty \D t\, t^ {1/\mu} s^t
  = \frac{\Gamma(1/\eta)}{[\ln(1/s)]^{1/\eta}}
\end{equation}
with $\eta=\mu/(1+\mu)$.
The saddle point equation~\eqref{eq:SaddlePoint} takes the explicit form 
\begin{equation}
  n+1  - \frac{s_*}{1-s_*} - \frac{k}{\eta}\frac{1}{\ln(1/s_*)} \simeq0
  \:,
\end{equation}
hence 
\begin{equation}
  s_* \simeq 1 -\frac{1}{n} \left( 1 + k/\eta \right)
  \hspace{0.5cm}\mbox{for }
  n\gg1
  \:.
\end{equation}
(the validity of the assumption $s_*\to1^-$ also requires $n\gg k$).
%for $n\gg1$. 
Finally, from \eqref{eq:SigmaknAsymp}, we get 
\begin{equation}
  \label{eq:RknAsymp}
  R_{k,\mu}(n) \sim
  \Gamma(1/\eta)^k \left(  \frac{ n \, \EXP{}}{1+k/\eta}  \right)^{k/\eta}
\end{equation}
for $\eta=\mu/(1+\mu)$.
As a check, we can consider the case $\mu=1$ ($\eta=1/2$), when $R_{k,1}(n)=S_k(n)$.
We check that the asymptotic $R_{k,1}(n)\sim[n\EXP{}/(2k)]^{2k}$ coincides with the one deduced in the first paragraph from the exact form of $S_k(n)$, Eq.~\eqref{eq:SumSnkAsymp}.


\subsubsection{Second illustration}

We now analyze the sum
\begin{equation}
  \label{eq:DefStilde-nk}
  \widetilde{S}_k(n) = 
  \hspace{-0.5cm}  
  \sum_{1\leq i_1 <\cdots<i_k \leq n} \prod_{m=1}^{k} (i_{m}-i_{m-1})\,\ln(i_{m}-i_{m-1})
  \:.
\end{equation}
We apply the method of Subsection~\ref{app:ComputationOfNiceSums} for $f(x)=x\,\ln x$, hence we consider (for $s\to1^-$)
\begin{equation}
 \check{f}(s) = \sum_{j=1}^\infty j\,s^j\,\ln j
  \simeq 
  \int_0^\infty\D t\,\ln t\,s^t
  =\frac{1-\mathbf{C}-\ln\ln(1/s)}{[\ln(1/s)]^2}
\end{equation}
where $\mathbf{C}\simeq0.577$ is the Euler-Mascheroni constant (we can obtain this integral from \eqref{eq:intB13} by setting $1/\eta=2+\epsilon$, eventually identifying the $\mathcal{O}(\epsilon)$ term).
It is convenient to introduce $b=\EXP{1-\mathbf{C}}\simeq1.526$.
The saddle point equation~\eqref{eq:SaddlePoint} takes the form 
\begin{equation}
  n+1  - \frac{s_*}{1-s_*} - \frac{k}{\ln(1/s_*)\ln(b/\ln(1/s_*))} -\frac{2k}{\ln(1/s_*)} \simeq0
\end{equation}
leading to 
\begin{equation}
  s_* \simeq 1 - \frac{1}{n}\left( 2k+1 + \frac{k}{\ln(bn/2k)} \right)
\end{equation}
for $n\gg1 $.
Finally we obtain 
\begin{align}
  \widetilde{S}_k(n) \sim
  &
  \left(\frac{n}{ 2k+1+\frac{k}{\ln(bn/2k)} }\right)^{2k+1}
  \left(\ln \frac{b\,n}{2k}\right)^k
  \nonumber\\
  &\times\exp\left\{ 2k+1+\frac{k}{\ln(bn/2k)} \right\}
\end{align}
For $n\gg k\gg1$, it simplifies as 
\begin{equation}
  \label{eq:AsympStilde}
  \widetilde{S}_k(n) \sim \left(\frac{n\,\EXP{}}{2k}\right)^{2k} \left(\ln \frac{b\,n}{2k}\right)^k
  \:.
\end{equation}



