\section{The $\lambda\to-\infty$ limit for exponential distributions}
\label{app:ExpCase-ExpansionOmega-Large}

As we have noticed, for exponential distribution of $\K_n^{-1}$ and $m_n$, the two fugacities coincide. 
Then \eqref{eq:MainResultForOmegaBis} can be more conveniently written
\begin{align}
\label{eq:OmegaAppendix}
  &\Omega = 
  \underset{\theta}{\mathrm{max}} \bigg\{ 
  \ln\left( \Lambda\,\EXP{-2\mathbf{C}}/4\right)
  +
   (1+\theta)\ln(1+\theta)
  \\\nonumber
  &+ (1-\theta) \left[\ln(1-\theta) - \ln(\Lambda/4)\right]
  + 2 \int_{\theta}^1 \D t\, \ln \psi(t)
  \bigg\}
\end{align}
where $\Lambda=(-\lambda)/(ab)$.
The fugacity is given by solving the transcendental equation \eqref{eq:ExpCase-EqForPsi}. 
%and the optimum occupation $\theta_*$ solves 
%\eqref{eq:ExpCase-SaddleEq}, i.e. 
%\begin{equation}
%   \psi(\theta) = \frac12\sqrt{\Lambda\,\frac{1+\theta}{1-\theta}}
%\:.
% \end{equation}
%  (where $\epsilon=\sqrt{\Lambda}$).

In a first step, we study the fugacity for $\theta\to1^-$, i.e. $\psi\to\infty$, leading to 
\begin{equation}
  \psi \simeq \frac{ \ln(\psi\,\EXP{-\mathbf{C}}) }{\psi} 
  \left[ 1 + \frac{1}{\psi} + \mathcal{O}\left(\frac{1}{\psi\ln\psi}\right) \right]
\end{equation}
leading to the expansion
\begin{align}
  \psi(\theta) \simeq \frac{\ln(\EXP{-\mathbf{C}}/\varepsilon)}{\varepsilon}
  \left[ 
    1 + \frac{\ln \ln(\EXP{-\mathbf{C}}/\varepsilon)}{\ln(\EXP{-\mathbf{C}}/\varepsilon) } + \mathcal{O}\left(\frac{\ln\ln}{\ln^2}\right)
  \right]
\end{align}
where $\varepsilon=1-\theta\to0^+$. 
%the argument of the log is $\EXP{-\mathbf{C}}/\varepsilon$.
A careful integration in \eqref{eq:OmegaAppendix} gives
\begin{align}
\label{eq:ProvisoryOmegaAppendix}
\Omega \simeq 
&\ln\left( \Lambda\,\EXP{-2\mathbf{C}}\right)
+ 
\underset{\varepsilon}{\mathrm{max}} \bigg\{ 
\varepsilon\,
\bigg[
1 + \ln\left( \frac{2}{\Lambda\,\varepsilon}\ln^2(\EXP{-\mathbf{C}}/\varepsilon) \right)
\nonumber\\
&\hspace{1cm}
 + 2 \frac{1+\ln \ln(\EXP{-\mathbf{C}}/\varepsilon)}{\ln(\EXP{-\mathbf{C}}/\varepsilon) } 
  + \mathcal{O}\left(\frac{\ln\ln}{\ln^2}\right)
\bigg]
\bigg\}
\end{align}
The position of the maximum ($\varepsilon=1-\theta_*(\lambda)$) is solution of \eqref{eq:ExpCase-SaddleEq} i.e.
\begin{align}
 \label{eq:D5}
  \varepsilon 
  \simeq
   \frac{2\ln^2\left( \EXP{-\mathbf{C}} / \varepsilon\right)}{\Lambda}\,
  %\ln^2\left( \frac{\EXP{-\mathbf{C}}}{\varepsilon}\right) 
  \left[
     1 +2 \frac{\ln\ln\left( \EXP{-\mathbf{C}} / \varepsilon\right)}{\ln\left( \EXP{-\mathbf{C}} / \varepsilon\right) }
     + \mathcal{O}\left( \frac{(\ln\ln)^2}{\ln^2}\right)
  \right] 
\end{align}
Replacing $\varepsilon$ by its expression in the logartihms of the r.h.s., we get 
\begin{align}
  \varepsilon \simeq \frac{2}{\Lambda}
  \bigg[
    \ln^2(\star) - 2 \ln(\star)  \, \ln\ln (\star) + \mathcal{O}\left((\ln\ln)^2\right)
  \bigg]
\end{align}
where %the argument of the logarithms is now 
$(\star)=(\Lambda\EXP{-\mathbf{C}}/2)$.
Making use of \eqref{eq:D5}, we can simplify \eqref{eq:ProvisoryOmegaAppendix} as 
\begin{equation}
  \label{eq:LastEqForOmega-exp}
  \Omega \simeq 
\ln\left( \Lambda\,\EXP{-2\mathbf{C}}\right)
+ 
 \varepsilon\,\left\{
 1
 + \frac{2}{\ln\left(\EXP{-\mathbf{C}} /  \varepsilon \right) }
     + \mathcal{O}\left( \frac{\ln\ln}{\ln^2}\right)
 \right\}
\end{equation}
where it is now understood that $\varepsilon$ solves \eqref{eq:D5}. Using the above expression of $\varepsilon$, we get  \eqref{eq:OmegaForExpWeights}.

