\title{Computing leaky waves in semi-analytical waveguide models\\ by exponential residual relaxation}

\author[ovgu]{Hauke~Gravenkamp\corref{cor1}}
\ead{hauke.gravenkamp@ovgu.de}

\author[lj]{Bor~Plestenjak}
