\address[ovgu]{Institute of Materials, Technologies and Mechanics, Otto von Guericke University Magdeburg, 39106 Magdeburg, Germany}

\address[lj]{IMFM and Faculty of Mathematics and Physics, University of Ljubljana, Jadranska 19, SI-1000 Ljubljana, Slovenia}

