\subsection{Extension to coupled systems of equations\label{sec:coupled}}\noindent
We observe that the procedure outlined above is adjusted straightforwardly to treat systems that depend on several functions of the parameter $t$. Namely, the minimization of a system of objective functions
\begin{equation}
  \*f(\*y(t), t) \coloneqq 
  \begin{bmatrix}
    f_1(y_1(t),y_2(t),...,y_n(t),t)\\
    f_2(y_1(t),y_2(t),...,y_n(t),t)\\
    \vdots \\
    f_n(y_1(t),y_2(t),...,y_n(t),t)
  \end{bmatrix}
  = \*0
\end{equation}
is posed as the solution of the initial value problem
\begin{subequations}
  \begin{align}\label{eq:ODE_multi}
    \*f'(\*y(t), t) &= -\depa\, \*f(\*y(t), t),\quad t\in\mathcal{I}\\
    \*y(t_0)  &= \*y_0.
  \end{align}
\end{subequations}
Here, we have assumed that the same algorithmic constant $\depa$ is chosen for all entries of $\*f(\*y(t), t)$. Otherwise, $\depa$ is to be replaced by a corresponding  diagonal matrix $\*X = \operatorname{diag}(\depa_1, \depa_2, ..., \depa_n)$.

\subsection{Application to eigenvalues of matrix functions\label{sec:eigencurves}}\noindent
We will now apply the same technique to compute the eigencurves of a matrix function, i.e., to solve an eigenvalue problem that depends on one parameter:
\begin{equation}
  \Mflow(k,\mu)\,\egv=\vt{0}. \label{eq:NLEVP_matrixFlow}
\end{equation}
The specific case of (leaky) guided waves will be addressed in the following section.
For easier comparison with the previous literature, the eigenvalue and eigenvector are denoted as $k = k(\mu)$, $\egv = \egv(\mu)$, and $\mu = \omega^2$ is the free parameter.
As the eigenvectors are only defined up to a multiplicative constant, we need to choose a normalization in order to obtain unique results, e.g.,
\begin{equation}\label{eq:normalization}
  \norma(\egv) \coloneqq \egv^\Her \egv -1 =0.
\end{equation}
Hence, we define the objective function
\begin{equation}
  \*f(\egv,k,\mu) =
  \begin{bmatrix}
    \Mflow(k,\mu)\,\egv \\
    \norma(\egv)
  \end{bmatrix} \label{eq:evp_objective}
\end{equation}
and write the total derivative with respect to the parameter $\mu$ as
\begin{equation}
  \*f'(\egv,k,\mu) =
  \begin{bmatrix}
    \Mflow(k,\mu)\egv'
    +  \Mflow'(k,\mu)\egv \\
    \vg{n}_{\egv}(\egv)\, \egv'
  \end{bmatrix}. \label{eq:leaky_Fdomega}
\end{equation}
\textit{Remark: The normalization defined by Eq.~\eqref{eq:normalization} is not complex differentiable with respect to $\egv$, though it is differentiable with respect to the real and imaginary parts $\mathfrak{R}(\egv)$, $\mathfrak{I}(\egv)$, and the Wirtinger derivatives exist \cite{Amin2011}, permitting a well-defined complex gradient \cite{Brandwood1983, VanDenBos1994}. It is known in the context of optimization problems that we can employ the approximation  $2\egv^\Her$ (analogously to real-valued vectors) to obtain a linearization, e.g., in Newton's method \cite{Lu2022}. Here, we will use the same concept to approximate the derivative with respect to $\egv$ that we require in the following steps. There are other possible normalizations; in particular, a popular choice is to use $n(\egv) = \egv_\mathrm{c}^\Her \egv - 1$, with some constant vector $\egv_\mathrm{c}$ (e.g., the initial value). While this approach generally works and avoids the theoretical issue of a non-differentiable normalization, we found that the one defined by Eq.~\eqref{eq:normalization} resulted in a slightly more robust computation in our examples. Hence, we will stick with this version and the general notation $\vg{n}_{\egv}$, irrespective of the normalization we employ, keeping in mind that, in the case of Eq.~\eqref{eq:normalization}, $\vg{n}_{\egv}(\egv) = 2\egv^\Her$ is not a true complex derivative.
}\\

\noindent
We continue by isolating terms in $\*f'(\egv,k,\mu) $ that are multiplied by $\egv$, $\egv'$, or $k'$. To this end,
the total derivative $\Mflow'(k,\mu)$ is written using the partial derivatives as
\begin{equation}\label{eq:totalDerivative}
  \Mflow'(k,\mu) = \frac{\mathrm{d}}{\mathrm{d}\mu} \Mflow(k,\mu) = 
  \frac{\partial}{\partial\mu} \Mflow(k,\mu) + \frac{\partial}{\partial k} \Mflow(k,\mu)\,\frac{\mathrm{d}}{\mathrm{d}\mu}k,
\end{equation}
which we abbreviate as
\begin{equation}\label{eq:totalDerivative2}
  \Mflow'(k,\mu) \eqqcolon
  \Mflow_\mu(k,\mu) + \Mflow_k(k,\mu)\,k',
\end{equation}
such that
\begin{equation}\label{eq:evp_fdmu}
  \*f'(\egv,k,\mu) =
  \begin{bmatrix}
    \Mflow(k,\mu)\,\egv' + \Mflow_k(k,\mu)\,\egv\,k'  + \Mflow_\mu(k,\mu)\,\egv \\
    \vg{n}_{\egv}(\egv)\, \egv'
  \end{bmatrix}. 
\end{equation}
The precise definition of these terms will be specified later for the cases of interest. 
Substituting Eqs.~\eqref{eq:evp_objective} and \eqref{eq:evp_fdmu} into \eqref{eq:ODE_multi}, we find that the system of ODEs is of the form
\begin{equation}
  \begin{bmatrix}
    \Mflow(k,\mu) & \Mflow_k(k,\mu)\,\egv \\
    \vg{n}_{\egv}(\egv)      & 0
  \end{bmatrix}
  \begin{bmatrix}
    \egv' \\
    k'
  \end{bmatrix}
  =
  - \begin{bmatrix}
    \depa_1\, \Mflow(k,\mu)\,\egv \\
    \depa_2\, \norma(\egv)
  \end{bmatrix}
  -
  \begin{bmatrix}
    \Mflow_\mu(k,\mu)\,\egv \\
    0
  \end{bmatrix}
  , \label{eq:leaky_ODE}
\end{equation}
which we will abbreviate for later use as
\begin{equation}
  \*{A}(\egv,k,\mu) \begin{bmatrix}
    \egv' \\
    k'
  \end{bmatrix}
  = \*{b}(\egv,k,\mu).
\end{equation}
Note that we use two different decay parameters $\depa_1$, $\depa_2$ to account for a potentially different behavior of the matrix equation \eqref{eq:NLEVP_matrixFlow} and the normalization \eqref{eq:normalization}.
The Jacobian is given as
\begin{equation}
  \*J(\egv,k,\mu) =
  \begin{bmatrix}
    \partial_{\egv} \*{b} & \partial_k \*{b}
  \end{bmatrix} =
  -\begin{bmatrix}
    \depa_1\, \Mflow(k,\mu) +  \Mflow_\mu(k,\mu) &
    \depa_1\, \Mflow_k(k,\mu)\,\egv +  \Mflow_{\mu k}(k,\mu)\,\egv \\
    \depa_2\, \vg{n}_{\egv}(\egv)                      &
    0
  \end{bmatrix}
  , \label{eq:leaky_Jac}
\end{equation}
with
\begin{equation}
  \Mflow_{\mu k} = \frac{\partial^2 }{\partial k \partial \mu} \Mflow(k,\mu) \,.
\end{equation}
Both $\egv$ and $k$ are generally complex-valued. It is interesting to note that \eqref{eq:leaky_ODE}  can be split into real and imaginary parts in order to optimize both simultaneously. Defining $\egv = \egv_r + \I\egv_i$ and $k = k_r + \I k_i$, we can rewrite \eqref{eq:leaky_ODE} as
\begin{equation}
  \begin{bmatrix}
    \mathfrak{R}(\Mflow) & -\mathfrak{I}(\Mflow)           & \mathfrak{R}(\Mflow_k\,\egv) & -\mathfrak{I}(\Mflow_k\,\egv)           \\
    \mathfrak{I}(\Mflow) & \phantom{-}\mathfrak{R}(\Mflow) & \mathfrak{I}(\Mflow_k\,\egv) & \phantom{-}\mathfrak{R}(\Mflow_k\,\egv) \\
    \mathfrak{R}(\vg{n}_{\egv})          & -\mathfrak{I}(\vg{n}_{\egv})                     & 0                      & 0                                 \\
    \mathfrak{I}(\vg{n}_{\egv})           & \phantom{-}\mathfrak{R}(\vg{n}_{\egv})         & 0                      & 0                                 \\
  \end{bmatrix}
  \begin{bmatrix}
    \egv_r' \\
    \egv_i' \\
    k_r'    \\
    k_i'    \\
  \end{bmatrix}
  =
  -\begin{bmatrix}
    \depa_1\, \mathfrak{R}(\Mflow\,\egv)    \\
    \depa_1\, \mathfrak{I}(\Mflow\,\egv)    \\
    \depa_2\, \mathfrak{R}(\norma) \\
    \depa_2\, \mathfrak{I}(\norma)
  \end{bmatrix}
  -
  \begin{bmatrix}
    \mathfrak{R}(\Mflow_\mu\,\egv) \\
    \mathfrak{I}(\Mflow_\mu\,\egv) \\
    0                         \\
    0
  \end{bmatrix}
  . \label{eq:leaky_ODE_split}
\end{equation}
While some implementations of solvers for systems of ODEs may recommend or even require this real-valued formulation, we will stick with the complex version in what follows.

\subsection{Incorporating algebraic constraints\label{sec:constraint}}\noindent
It is generally straightforward to formulate the approach for an arbitrary number of coupled equations, as mentioned in Section~\ref{sec:coupled}. Here, we only showcase one specific case that will be of particular importance to our current application, namely the inclusion of additional scalar equations. Assume the eigenvalue problem depends on another parameter $\xi = \xi(\mu)$, such that
\begin{equation}
  \Mflow(k,\xi,\mu)\,\egv=\vt{0}. \label{eq:NLEVP_matrixFlow_xi}
\end{equation}
In our case, the solution to \eqref{eq:NLEVP_matrixFlow_xi} satisfies a scalar equation
\begin{equation}
  g(k,\xi,\mu) = 0.
\end{equation}
Thus, Eq.~\eqref{eq:leaky_ODE} is extended as
\begin{equation}
  \begin{bmatrix}
    \Mflow(k,\xi,\mu) & \Mflow_\xi(k,\xi,\mu)\,\egv & \Mflow_k(k,\xi,\mu)\,\egv \\
    \*0             & g_\xi(k,\xi,\mu)           & g_k(k,\xi,\mu)   \\
    \vg{n}_{\egv}(\egv)      & 0 & 0
  \end{bmatrix}
  \begin{bmatrix}
    \egv' \\
    \xi' \\
    k'
  \end{bmatrix}
  =
  - \begin{bmatrix}
    \depa_1\, \Mflow(k,\xi,\mu)\,\egv \\
    \depa_1\, g(k,\xi,\mu)  \\
    \depa_2\, \norma(\egv)
  \end{bmatrix}
  -
  \begin{bmatrix}
    \Mflow_\mu(k,\xi,\mu)\,\egv \\
    g_\mu(k,\xi,\mu) \\
    0
  \end{bmatrix}
  , \label{eq:leaky_ODE_constraint}
\end{equation}
where the matrix entries are defined via 
\begin{subequations}
  \begin{align}
  \Mflow'(k,\xi,\mu) &\eqqcolon
  \Mflow_\mu(k,\xi,\mu)+ \Mflow_\xi(k,\xi,\mu)\,\xi' + \Mflow_k(k,\xi,\mu)\,k', \\
  g'(k,\xi,\mu) &\eqqcolon g_\mu(k,\xi,\mu) + g_\xi(k,\xi,\mu)\,\xi' + g_k(k,\xi,\mu)\,k',
\end{align}
\end{subequations}
and the Jacobian is extended correspondingly as
\begin{equation}
  \*J(\egv,k,\xi,\mu) =
  \begin{bmatrix}
    \partial_{\egv} \*{b}  & \partial_\xi \*{b} & \partial_k \*{b}
  \end{bmatrix} =
  -\begin{bmatrix}
    \depa_1\, \Mflow +  \Mflow_\mu &
    \depa_1\, \Mflow_\xi\,\egv + \Mflow_{\mu \xi}\,\egv&
    \depa_1\, \Mflow_k\,\egv + \Mflow_{\mu k}\,\egv \\
    \*0 
    & \depa_1\,  g_\xi + g_{\mu \xi}
    & \depa_1\,  g_k + g_{\mu k}\\
    \depa_2\, \vg{n}_{\egv}                     &
    0 & 0
  \end{bmatrix}
  . \label{eq:leaky_Jac_constrained}
\end{equation}
Several constraints of this form can be included analogously.

