\section{End Matter}
\textit{Derivation of the t-SMR.}---The boundary conditions of the spin diffusion equation $\partial_{z}^{2} \mu_{j} = \mu_{j}/\lambda^{2}$ are
\begin{align}
 e\mathcal{J}_{zj}(z=0)&=g_R\epsilon_{jkl}\epsilon_{lab}\hat{m}_k\hat{m}_a\mu_b+g_I\epsilon_{jkl}\hat{m}_k\mu_l, \\
 \mathcal{J}_{zj}(z=t)&=0,
\end{align}
which was consistent with the ordinary SMR. Then by using Eqs.~\eqref{eq:current_potential}, we can solve the spin diffusion equation and obtain
\begin{align}
\label{eq:full_diffusion_sol}
 \mu_{j}(z) &= \mu_{j}^{0} \frac{\sinh [(2z - t)/2\lambda]}{\sinh (t /2\lambda)} - 2\lambda \frac{\cosh [(z-t)/\lambda]}{\sinh( t / \lambda) } \nonumber \\
&\qquad \times \left[\tilde{g}_{R}   \epsilon_{jkl}\epsilon_{lab}\hat{m}_k\hat{m}_a\mu_{b}^{0} + \tilde{g}_{I}      \epsilon_{jkl}\hat{m}_k\mu_{l}^{0})   \right],
\end{align}
where $\mu_{j}^{0} = 2et\eta\chi_{zjk}E_{k}$ with $E_{k}$ being the $k$ component of the applied electric field. Following a similar procedure as the ordinary SMR, we can derive from Eq.~\eqref{eq:full_diffusion_sol} the longitudinal and transverse components of the conductivity as
\begin{subequations}
\label{eq:pre_avg_sigma}
    \begin{align}
        &\frac{\sigma_{xx}}{\sigma} = 1 - \chi'_{xzk} \chi_{zkx} \frac{\cosh [(2z - t)/2\lambda]}{\cosh (t /2 \lambda)} + 2t \eta  \nonumber \\
        & \times \frac{\sinh [(z-t)/\lambda]}{\sinh (t /\lambda)} \left[ \tilde{g}_{R}( \chi_{zjx} \chi'_{xzk} \hat{m}_{j} \hat{m}_{k} -\chi_{zkx}\chi'_{xzk}  )  \right. \nonumber \\
        &\left. \qquad \qquad \qquad \qquad\qquad + \tilde{g}_{I} \epsilon_{kjl}\chi_{zlx}\chi'_{xzk} \hat{m}_{j}   \right] , \label{eq:pre_avg_sigma_xx} \\
        & \frac{\sigma_{xy}}{\sigma} = -\chi_{zkx}\chi'_{yzk}  \frac{\cosh [(2z - t)/2\lambda]}{\cosh (t /2 \lambda)} + 2t \eta \nonumber \\
        & \times \frac{\sinh [(z-t)/\lambda]}{\sinh (t /\lambda)} \left[ \tilde{g}_{R}( \chi_{zjx} \chi'_{yzk} \hat{m}_{j}\hat{m}_{k} -\chi_{zkx}\chi'_{yzk}  ) \right. \nonumber \\
        & \left. \qquad \qquad \qquad \qquad\qquad + \tilde{g}_{I}\epsilon_{kjl}\chi_{zlx}\chi'_{yzk} \hat{m}_{j} \right], \label{eq:pre_avg_sigma_xy}
    \end{align}
\end{subequations}
where $j$, $k$ and $l$ are summed over per Einstein's summation rule. Substituting $\chi_{ijk} = -\chi'_{kij}$ into Eqs.~\eqref{eq:pre_avg_sigma} and averaging the conductivity over the thickness direction, \textit{i.e.}, taking $(1/t)\int_0^t(\cdots)$, we obtain Eqs.~\eqref{eq:conductivities}.

\textit{Derivation of the rectification voltage}---The equilibrium direction of $\hat{\bm{m}}$ is simply $\hat{\bm{h}}$, and we define $\bm{m}_{\perp} = \hat{\bm{m}} - \hat{\bm{h}}$ such that $\bm{m}_{\perp} \cdot \hat{\bm{h}} = 0$ and $|\bm{m}_{\perp}| \ll 1$. Under the Fourier transformation, the LLG Eq.~\eqref{eq:LLG_main} becomes
\begin{align}
   &(1 - g_{I}') i \omega \tilde{\bm{m}}_{\perp} - [ H + (\alpha + g_{R}') i \omega] \hat{\bm{h}} \times \tilde{\bm{m}}_{\perp}  \nonumber \\
   &\qquad = \tilde{\bm{H}}_{\rm{DL}}-(\hat{\bm{h}} \cdot \tilde{\bm{H}}_{\rm{DL}}) \hat{\bm{h}} - \hat{\bm{h}} \times \tilde{\bm{H}}_{\rm{F}},
   \label{eq:LLG_m_perp}
\end{align}
where $\omega$ is the angular frequency of the driving current, $\tilde{\bm{m}}_{\perp}$, $\tilde{\bm{H}}_{\rm{DL}}$ and $\tilde{\bm{H}}_{\rm{F}}$ are the phasors of $\bm{m}_{\perp}$, $\bm{H}_{\rm{DL}}$ and $\bm{H}_{\rm{F}}$. By solving Eq.~\eqref{eq:LLG_m_perp}, we obtain 
\begin{align}
   \tilde{\bm{m}}_{\perp} =& \frac{1}{(1-g_{I}')^{2}\omega^2 - [H + (\alpha + g_{R}')i \omega]^{2}} \hat{\bm{h}} \times \nonumber \\
   & \{ (1 - g_{I}')i\omega  ( \hat{\bm{h}} \times \tilde{\bm{H}}_{\rm{DL}} + \tilde{\bm{H}}_{\rm{F}} ) \nonumber \\
   &\quad + [H + (\alpha + g_{R}')i \omega]
   ( \hat{\bm{h}} \times \tilde{\bm{H}}_{\rm{F}}  - \tilde{\bm{H}}_{\rm{DL}}) \}.
   \label{eq:m_perp}
\end{align}
According to Eq.~\eqref{eq:sigma_xx}, the longitudinal resistivity can be expressed as $\rho_{xx}(\tilde{\bm{m}}_{\perp}) = \rho_{0}(\hat{\bm{h}}\cdot\hat{\bm{s}})\rm{Re}(\tilde{\bm{m}}_{\perp} \cdot \hat{\bm{s}})$, where $\rho_{0}$ is an overall factor absorbing $\sigma$, $\tilde{g}_{R}$, $t$, $\eta$ and $|\bm{s}|$. Substituting Eq.~\eqref{eq:m_perp} into $\rho_{xx}(\tilde{\bm{m}}_{\perp})$ and using the near-resonance approximation $( H^{2} - \omega_{0}^{2})^{2} \approx 4\omega_{0}^{2} (H - \omega_{0})^{2}$, we arrive at Eqs.~\eqref{eq:ST_FMR_V} and \eqref{eq:ST_FMR}.

\textit{Derivation of second harmonic Hall voltage}---In the low-frequency regime, the magnetizaion vector $\hat{\bm{m}}$ remains in quasi-equilibrium, so all time derivatives in Eq.~\eqref{eq:LLG_main} can be set to zero, yielding
\begin{equation}
\label{eq:f}
    \bm{f} = (\bm{H}  + \bm{H}_{\rm{F}}) \times \hat{\bm{m}} + \hat{\bm{m}} \times (\bm{H}_{\rm{DL}} \times \hat{\bm{m}}) = 0.
\end{equation}
In polar coordinates, $\hat{\bm{m}}=\sin \theta \cos \phi\hat{\bm{x}}+ \sin \theta \sin \phi\hat{\bm{y}}+ \cos \theta\hat{\bm{z}}$. To obtain the perturbed angles $\Delta \theta$ and $\Delta \phi$ in the presence of $\bm{H}_{\rm{F}}$, we first calculate $d \bm{f} / d \bm{H}_{\rm{F}}=0$:
\begin{align}
\label{eq:df_dHFL_orig}
    \left[\epsilon (\bm{H} + \bm{H}_{\rm{F}})  + \hat{\bm{m}} \otimes \bm{H}_{\rm{DL}}  +(\hat{\bm{m}} \cdot \bm{H}_{\rm{DL}}) \mathcal{I} \right] \frac{d \hat{\bm{m}}}{d \bm{H}_{\rm{F}}} \nonumber \\
    =- \hat{\bm{m}} \times \mathcal{I},
\end{align}
where $\epsilon$ the Levi-Civita tensor, $\mathcal{I}$ is the $3\times 3$ identity matrix, and $(\hat{\bm{m}} \times \mathcal{I})_{ij} = \epsilon_{iab} \hat{\bm{m}}_{a} \mathcal{I}_{bj}$. When Eq.~\eqref{eq:df_dHFL_orig} is evaluated in equilibrium that $\bm{H}_{\rm{F}} = \bm{H}_{\rm{DL}} = 0$, it can be rewritten as $\mathcal{M} (d \hat{\bm{m}} / d \bm{H}_{\rm{F}}) = \hat{\bm{m}} \times \mathcal{I}$ where the matrix $\mathcal{M}$ has components $\mathcal{M}_{ij} = -\epsilon_{ijk}H_k$. Then defining  the column vector $\bm{\theta} = (\theta, \phi)^{T}$ and using the chain rule $d\hat{\bm{m}}/d\bm{H}_{\rm{F}} = (d\hat{\bm{m}}/d\bm{\theta})( d\bm{\theta}/d\bm{H}_{\rm{F}})$, we have
\begin{align}
\label{eq:dtheta_dHFL}
    \frac{d \bm{\theta}}{d \bm{H}_{\rm{F}}}\!=\!\left[ \left(\mathcal{M}  \frac{d \hat{\bm{m}}}{d \bm{\theta}} \right)^{T}\left(\mathcal{M} \frac{d \hat{\bm{m}}}{d \bm{\theta}} \right) \right]^{-1}\!\!\left(\mathcal{M} \frac{d \hat{\bm{m}}}{d \bm{\theta}} \right)^{T}\!(\hat{\bm{m}} \times \mathcal{I}),
\end{align}
where
\begin{align}
\label{eq:dm_dtheta}
    \frac{d \hat{\bm{m}}}{d \bm{\theta}} =
    \begin{pmatrix}
    \cos \theta \cos \phi & -\sin \theta \sin \phi \\
    \cos \theta \sin \phi & \sin \theta \cos \phi \\
    -\sin \theta & 0
    \end{pmatrix}.
\end{align}
In equilibrium, $\hat{\bm{m}} = \hat{\bm{h}}$, so $\theta = \theta_{H}$ and $\phi = \phi_{H}$. We then obtain from Eqs.~\eqref{eq:dtheta_dHFL} and~\eqref{eq:dm_dtheta} that
\begin{align}
\label{eq:dtheta_dHFL_eq}
    \frac{d \bm{\theta}}{d \bm{H}_{\rm{F}}} = \frac{1}{H}
    \begin{pmatrix}
     \cos \theta_{H} \cos \phi_{H} & \cos \theta_{H} \sin \phi_{H} & -\sin \theta_{H} \\
     -\csc \theta_{H} \sin \phi_{H} & \csc \theta_{H} \cos \phi_{H} & 0 
    \end{pmatrix}.
\end{align}
Following the same procedure, we can also obtain 
\begin{align} \label{eq:dtheta_dHDL_eq}
    \frac{d \bm{\theta}}{d \bm{H}_{\rm{DL}}} = \frac{1}{H}
    \begin{pmatrix}
     \sin \phi_{H} & -\cos \phi_{H} & 0 \\
     \cot \theta_{H} \cos \phi_{H} & \cot \theta_{H} \sin \phi_{H} & -1 
    \end{pmatrix}.
\end{align}
Finally, the perturbed angles can be calculated as
\begin{align}
 \begin{pmatrix}
     \Delta\theta \\ \Delta\phi
 \end{pmatrix}
 = \frac{d\bm{\theta}}{d\bm{H}_{\rm{F}}} \bm{H}_{\rm{F}} + \frac{d\bm{\theta}}{d\bm{H}_{\rm{DL}}} \bm{H}_{\rm{DL}}.
\end{align}

After substitution of $\hat{\bm{s}} = \text{cos}\theta_{s} \hat{\bm{z}} + \text{sin}\theta_{s} \hat{\bm{y}}$ and $\hat{\bm{s}}' = -\hat{\bm{x}}$ into Eq.~\eqref{eq:sigma_xy}, the Hall resistivity $\rho_{xy}$ can be simplified to 
\begin{equation}
    \rho_{xy} =\rho_{0}( \sin \theta_{s}\hat{m}_{x}\hat{m}_{y} + \cos \theta_{s}\hat{m}_{x}\hat{m}_{z}),
    \label{eq:deltadelta}
\end{equation}
where $\hat{m}_{x}\hat{m}_{y}$ and $\hat{m}_{x} \hat{m}_{z}$ are
\begin{subequations}
\label{eq:mxmymz}
\begin{align}
    &\hat{m}_{x}\hat{m}_{y} = \frac{1}{2}\sin^{2}\theta \sin 2\phi \approx \frac{1}{2} (\sin^{2}\theta_{H} \sin 2\phi_{H} \nonumber \\
    &  + 2\sin^{2} \theta_{H} \cos 2\phi_{H} \Delta \phi + \sin 2\theta_{H} \sin 2\phi_{H} \Delta \theta), \label{eq:mxmy} \\
    & \hat{m}_{x} \hat{m}_{z} = \frac{1}{2} \sin 2\theta \cos \phi \approx \frac{1}{2} ( \sin 2\theta_{H} \cos \phi_{H}  \nonumber \\
    & - \sin 2\theta_{H} \sin \phi_{H} \Delta \phi + 2 \cos 2\theta_{H} \cos \phi_{H} \Delta \theta  ). \label{eq:mxmz}
\end{align}
\end{subequations}
Plugging $\Delta \theta$ and $\Delta \phi$ obtained from Eq.~\eqref{eq:deltadelta} into Eqs.~\eqref{eq:mxmymz}, we can justify Eqs.~\eqref{eq:2nd_harmonic}.



