\end{footnotesize}

\subsubsection{\texttt{positivePoint}}

\textbf{Input 1:} List of polynomials $\mathcal{F}_n=\{f_{1},\dots,f_{r}\}$ in variables $x_1,\dots,x_n$. \\
\textbf{Input 2:} A tree of sample points representing an Open CAD (or a subtree reaching down to level $n$).

\textbf{Output:} If every input polynomial is positive at an $n$-dimensional sample point, that sample point is returned. If not, `\textit{no point exists}' is returned.

\begin{Verbatim}[frame=leftline, framerule=4pt]
