\section{Preliminaries}

In this section we recall some results which will be widely used across the article.

\subsection{Outer automorphism group}\label{sec:preliminares}

The aim of this section is to briefly explain the constructions in \cite{MalfaitWim2002Toag} used to compute the outer automorphism group of a group extension. 

Let
\[\begin{tikzcd}
	1\ar{r}{}&K\ar{r}{}&G\ar{r}{p}&Q\ar{r}{}&1
\end{tikzcd}\]
be a short exact sequence of groups. The extension is determined by the morphism $\psi:Q\longrightarrow\Out(K)$ and a 2-cocycle $c\in H^2_\psi(Q,\Zc K)$. Let $\Aut(G,K)=\{f\in\Aut(G):f(K)=K\}$ and $\Out(G,K)=\Aut(G,K)/\Inn G$. Define the group morphism $\Theta:\Aut(G,K)\longrightarrow \Aut(K)\times \Aut(Q)$ such that $f\mapsto(f_{|K},\overline{f})$, where $\overline{f}:Q\longrightarrow Q$ is the map induced by $f$ on $Q$. Finally, recall that if $H$ is a subgroup of $G$, the centralizer $C_G(H)$ is $\{g\in G:c_h(g)=g\text{ for all }h\in H\}$.

\begin{thm}\cite[Theorem 3.3, Theorem 3.6]{MalfaitWim2002Toag}
	With the above notation, we have
	\begin{itemize}
		\item[1.] $\im(\Theta)$ are the elements of $\Aut(K)\times\Aut(Q)$ which fix the 2-cocycle $c$.
		\item[2.] There exists an isomorphism $\xi:\ker(\Theta)\longrightarrow Z^1_\psi(Q,\Zc K)$.
	\end{itemize}
\end{thm}

\begin{defn}\cite[Definition 3.7]{MalfaitWim2002Toag}
	We define
	$$\overline{B}_\psi^1(Q,\Zc K)=\{\xi(c_g):g\in C_G(K),p(g)\in\Zc Q\}. $$
\end{defn} 

\begin{prop}\cite[Proposition 3.8]{MalfaitWim2002Toag}
	We have $$B_\psi^1(Q,\Zc K)\leq\overline{B}_\psi^1(Q,\Zc K)\leq Z^1_\psi(Q,\Zc K).$$ In consequence, there exists a surjective morphism $$H^1_\psi(Q,\Zc K)\longrightarrow \overline{H}_\psi^1(Q,\Zc K)=Z^1_\psi(Q,\Zc K)/\overline{B}_\psi^1(Q,\Zc K).$$ 

	We have an isomorphism $\overline{B}_\psi^1(Q,\Zc K)\cong (p^{-1}(\Zc Q)\cap C_GK)/\Zc G$.
\end{prop}

We can think $\overline{H}_\psi^1(Q,\Zc K)$ as the subgroup of $\Out(G,K)$ whose automorphism classes induce inner automorphisms on $K$ and $Q$. This interpretation is made precise in the next theorem.

\begin{thm}\label{out ses}\cite[Theorem 4.8]{MalfaitWim2002Toag}
	There exist short exact sequences
	\[\begin{tikzcd}
		1\ar{r}{}&\mathcal{K}\ar{r}{}&\Out(G,K)\ar{r}{}&L_1\ar{r}{}&1,
	\end{tikzcd}\]
	and
	\[\begin{tikzcd}
		1\ar{r}{}&\overline{H}_\psi^1(Q,\Zc K)\ar{r}{}&\mathcal{K}\ar{r}{}&L_2\ar{r}{}&1
	\end{tikzcd}\]
	where $$L_1=\{\overline{f}\in\Aut(Q):f\in\Aut(G,K)\}/\Inn(Q)\leq \Out(Q)$$ and $$L_2\cong (\Stab_{\Aut(K)}c/\Inn(K))/\Zc\psi(Q)\leq C_{\Out(K)}\psi(Q)/\psi(\Zc Q).$$
\end{thm} 

There is also a version for the automorphism group, which was also investigated by C. Wells in \cite{wells1971automorphisms}.

\begin{thm}\label{aut ses}\cite[Theorem 4.8]{MalfaitWim2002Toag}
	There exist short exact sequences
	\[\begin{tikzcd}
		1\ar{r}{}&\mathcal{K}'\ar{r}{}&\Aut(G,K)\ar{r}{}&L'_1\ar{r}{}&1,
	\end{tikzcd}\]
	and
	\[\begin{tikzcd}
		1\ar{r}{}&Z_\psi^1(Q,\Zc K)\ar{r}{}&\mathcal{K}'\ar{r}{}&L'_2\ar{r}{}&1
	\end{tikzcd}\]
	where $$L'_1=\{\overline{f}\in\Aut(Q):f\in\Aut(G,K)\}\leq \Aut(Q)$$ and $$L'_2=\Stab_{\Aut(K)}c\leq \Aut(K).$$
\end{thm} 

\begin{rem}
	If $K$ is a characteristic subgroup of $G$ then $\Aut(G,K)=\Aut(G)$ and $\Out(G,K)=\Out(G)$.
\end{rem}

\begin{lem}\label{Minkowski ses}\cite[Lemma 2.4]{daura2024actions}
	Let $\begin{tikzcd}		1\ar{r}{}& K\ar{r}{}&H\ar{r}{p}&Q\ar{r}{}&1
	\end{tikzcd}$ be a short exact sequence of groups. If $K$ and $Q$ are Minkowski, then $H$ is Minkowski. If $K$ is finite and $H$ is Minkowski then $Q$ is Minkowski.
\end{lem}

\begin{lem}\label{outer automorphism and finite index subgroups}\cite[Corollary 2.4]{daura2024actions}
	Let $\Gamma$ and $\Gamma'$ be finitely generated groups with finitely generated center such that $\Gamma'\trianglelefteq\Gamma$ and $\Gamma/\Gamma'=F$ is a finite group. If $\Out(\Gamma')$ is a Minkowski, then $\Out(\Gamma)$ is Minkowski.
\end{lem}

\subsection{Infranilmanifolds and almost crystallographic groups}

Let $N$ be a simply connected nilpotent Lie group and $C$ be a maximal compact subgroup of $\Aut(N)$. A discrete cocompact subgroup $\Gamma$ of $N\rtimes C$ is called an almost-crystallographic group (abbreviated as AC-group). Moreover, $\Gamma$ is said to be almost-Bieberbach if it is torsion-free. If $\Lambda$ be a finitely generated torsion-free nilpotent group, an extension $1\longrightarrow \Lambda\longrightarrow \Gamma\longrightarrow G\longrightarrow 1$ in which $G$ is finite is said to be essential if $\Lambda$ is a maximal nilpotent subgroup of $\Gamma$. 
Note that crystallographic groups are an example of AC-groups. Bieberbach theorems for crystallographic groups have been generalized to almost-crystallographic groups.

\begin{thm}\label{generalized Bieberbach theorems}\cite[Chapter 2]{dekimpe2006almost}
	Let $N$ be a simply connected nilpotent Lie group and $C$ a maximal compact subgroup of $\Aut(N)$. 
	\begin{itemize}
		\item[1.] (Generalized 1st Bieberbach theorem) Let $\Gamma\leq N\rtimes C$ be an AC-group of $N$. The subgroup $N\cap \Gamma=\Lambda$ is a lattice of $N$, $\Lambda$ is the unique normal maximal nilpotent subgroup of $\Gamma$ and $\Gamma/\Lambda$ is a finite group.
		\item[2.] (Generalized 2nd Bieberbach theorem) Let $\Gamma$ and $\Gamma'$ be AC-groups of $N$. Assume that there exists an isomorphism $f:\Gamma\longrightarrow \Gamma'$. Then $f$ can be realized as a conjugation by an element of $\Aff(N)=N\rtimes\Aut(N)$.
		\item[3.] (Generalized 3rd Bieberbach theorem) Let $\Lambda$ be a lattice of $N$. There are only finitely many essential extensions $1\longrightarrow \Lambda\longrightarrow \Gamma\longrightarrow G\longrightarrow 1$.
	\end{itemize}
\end{thm}

If $\Gamma$ is an almost-Bieberbach group of $N$ then $\Gamma$ acts freely on $N$ and the orbit space $N/\Gamma$ is a closed connected aspherical manifold which is finitely covered by the nilmanifold $N/\Lambda$. These manifolds are known as infranilmanifolds, and just like flat manifolds, they also have a geometric characterization, see \cite{gromov1978almost,ruh1982almost}. The algebraic characterization of crystallographic groups (see \cite[Theorem 2.1.4]{dekimpe2016users}) can also be generalized to AC-groups, but we need some further definitions to state it.

\begin{defn}\cite[Definition 2.3.3]{dekimpe2006almost}
	Let $\Gamma$ be a virtually polycyclic group. The Fitting subgroup $\Fitt(\Gamma)$ is the unique maximal normal nilpotent subgroup of $\Gamma$. The Fitting subgroup $\Fitt(\Gamma)$ is unique.
\end{defn}

\begin{thm}\label{AC-groups charactherization}\cite[Theorem 3.4.6]{dekimpe2006almost}
	Let $\Gamma$ be a virtually polycyclic group. The following are equivalent:
	\begin{itemize}
		\item[1.] $\Gamma$ is an AC-group.
		\item[2.] $\Fitt(\Gamma)$ is torsion-free, maximal nilpotent and of finite index in $\Gamma$.
		\item[3.] $\Gamma$ contains a torsion-free nilpotent subgroup $\Lambda$ of finite index such that $C_\Gamma(\Lambda)$ is torsion-free.
		\item[4.] $\Gamma$ contains a nilpotent subgroup of finite index and $\Gamma$ does not contain any non-trivial finite normal subgroup.
	\end{itemize}
\end{thm}
\begin{corollary}
	If $\Gamma$ is a torsion-free virtually polycyclic group then $\Gamma$ is an AC-group if and only if it contains a nilpotent subgroup of finite index.
\end{corollary}

To announce the next propositions we need some facts on the rational Mal'cev completion of a torsion-free finitely generated nilpotent group. We refer to \cite{dekimpe2006almost,dekimpe2016users} for its definition and main properties. Let $\Lambda$ be a torsion-free finitely generated nilpotent group and let $\Lambda_\Q$ denote its rational Mal'cev completion. Given $f\in \Aut(\Gamma)$, we can uniquely extend $f$ to an automorphism $f_\Q:\Lambda_\Q\longrightarrow \Lambda_\Q$ of the rational Mal'cev completion such that $f_{\Q|\Lambda}=f$ (see \cite[Proposition 2.7]{dekimpe2016users}). Thus, we can define an injective group morphism $\Aut(\Lambda)\longrightarrow\Aut(\Lambda_\Q)$ which induces a morphism $\Inn\Lambda\longrightarrow \Inn\Lambda_\Q$. Consequently, we have a group morphism $\Out(\Lambda)\longrightarrow \Out(\Lambda_\Q)$. Given a group morphism $\phi:G\longrightarrow \Out(\Lambda)$, we denote by $\phi_\Q:G\longrightarrow \Out(\Lambda_\Q)$ the composition of $\phi$ and $\Out(\Lambda)\longrightarrow \Out(\Lambda_\Q)$. The proof of \cref{AC-groups charactherization} uses the following proposition, which will be also used in the proof of \cref{main theorem10 intro}.

\begin{prop}\label{infranilmanifolds malcev completion injective}
	Let $\Lambda$ be a finitely generated torsion-free nilpotent group and $1\longrightarrow \Lambda\longrightarrow \Gamma\longrightarrow G\longrightarrow 1$ a group extension where $G$ is finite. Then $\Lambda$ is maximal nilpotent in $\Gamma$ if and only if the induced map $\phi_\Q:G\longrightarrow \Out(\Lambda_\Q)$ is injective.
\end{prop}

This proposition is proved in \cite[Lemma 3.1.1]{dekimpe2006almost} for the real Mal'cev completion, and the same argument can be used to prove \cref{infranilmanifolds malcev completion injective} with the rational Mal'cev completion. It can be also reformulated in the following way:

\begin{prop}\label{infranilmanifolds malcev completion trivial}
	Let $\Lambda$ be a finitely generated torsion-free nilpotent group and $1\longrightarrow \Lambda\longrightarrow \Gamma\longrightarrow G\longrightarrow 1$ a group extension where $G$ is finite and $\Gamma$ is torsion-free. Then $\Gamma$ is nilpotent if and only if the induced map $\phi_\Q:G\longrightarrow \Out(\Lambda_\Q)$ is trivial.
\end{prop}

Recall that $\Lambda_\Q$ has associated a finite dimensional rational Lie algebra $\mathcal{L}(\Lambda)_\Q$ (for the details, see \cite[Theorem 2.11, Theorem 2.12]{dekimpe2016users}).

\begin{lem}\cite[Corollary 2.13]{dekimpe2016users}\label{automorphisms malcev completion}
	Let $\Lambda$ be a finitely generated torsion-free nilpotent group. Then $\Aut(\Gamma_\mathbb{Q})\cong\Aut({\mathcal{L}(\Gamma)}_\mathbb{Q})$.
\end{lem}

\subsection{Groups action on aspherical manifolds}

Let $M$ be a closed connected manifold and let $x_0\in M$. Assume that we have a finite group $G$ acting on $M$. Then for each $g\in G$ we have an isomorphism ${g_*}:\pi_1(M,x_0)\longrightarrow \pi_1(M,gx_0)$. If $x_0$ is fixed by the action of $G$ on $M$, then we can define a group morphism $G\longrightarrow \Aut(\pi_1(M,x_0))$. If $x_0$ is not fixed by the action of $G$ on $M$ then above group morphism is not well defined. However, since $\pi_1(M,x_0)$ and $\pi_1(M,gx_0)$ are isomorphic and the isomorphism is given by a conjugation, we have a well-defined group morphism $\psi:G\longrightarrow \Out(\pi_1(M,x_0))=\Aut(\pi_1(M,x_0))/\Inn(\pi_1(M,x_0))$ given by $\psi(g)=[{g_*}:\pi_1(M,x_0)\longrightarrow \pi_1(M,gx_0)]$. We will say that the action is inner if $\psi:G\longrightarrow \Out(\pi_1(M,x_0))$ is trivial. We will omit the base point whenever it is not necessary for the discussion.

We can always lift the action of $G$ on $M$ to an action of a group $\tilde{G}$ on the universal cover $\tilde{M}$, where the group $\tilde{G}$ fits into the short exact sequence
\[\begin{tikzcd}
	1\ar{r}{}& \pi_1(M)\ar{r}{} & \tilde{G} \ar{r}{}& G\ar{r}{} & 1.
\end{tikzcd}\]
The abstract kernel of the group extension coincides with the group morphism $\psi$.

\begin{lem}\cite[Lemma 3.1.14]{lee2010seifert}\label{aspherical manifolds big diagram}
	Let $G$ be a finite group acting effectively on a closed manifold $M$. Then, there is a commutative diagram with exact rows and columns
	\[\begin{tikzcd}
		& 1\ar{d}{} & 1 \ar{d}{}& 1 \ar{d}{} & \\
		1\ar{r}{}& \Zc\pi_1(M)\ar{r}{}\ar{d}{} & C_{\tilde{G}}(\pi_1(M)) \ar{r}{}\ar{d}{}& \ker\psi\ar{r}{}\ar{d}{} & 1\\
		1\ar{r}{}& \pi_1(M)\ar{r}{}\ar{d}{} & \tilde{G} \ar{r}{}\ar{d}{}& G\ar{r}{}\ar{d}{\psi} & 1\\
		1\ar{r}{}& \Inn(\pi_1(M))\ar{r}{}\ar{d}{} & \Aut(\pi_1(M)) \ar{r}{}& \Out(\pi_1(M))\ar{r}{} & 1\\
		&1 &&&
	\end{tikzcd}\]
	where $C_{\tilde{G}}(\pi_1(M))$ is the centralizer of $\pi_1(M)$ in $\tilde{G}$.
\end{lem}

\Cref{aspherical manifolds big diagram} can be used to prove the following result.

\begin{thm}\cite[Theorem 3.1.16]{lee2010seifert}\label{finite group actions aspherical manifolds}
	Let $G$ be a finite group acting effectively on a closed connected $n$-dimensional aspherical manifold $M$, then:
	\begin{itemize}
		\item[1.] $C_{\tilde{G}}(\pi_1(M))$ is torsion free.
		\item[2.] $\ker \psi$ is abelian. Moreover, if $\Zc\pi_1(M)$ is finitely generate of rank $k$, then $\ker\psi$ is a subgroup of the torus $T^k$.
	\end{itemize}
\end{thm}

