\section{Free iterated actions on closed aspherical manifolds}\label{sec: iterated actions on aspherical manifolds}

The aim of this section is to prove \cref{main theorem9 intro}. To ease notation, we introduce the following definition:

\begin{defn}\label{2-step Minkowski}
	If $\Gamma$ is a finitely generated group satisfying that $\Zc\Gamma$ and $\Zc\Inn\Gamma$ are finitely generated and that $\Out(\Inn\Gamma)$ and $\Aut(\Inn\Gamma)$ are Minkowski then we say that $\Gamma$ has the 2-step Minkowski property.
\end{defn}

\begin{rem}\label{2-step Minkowski 1-cocycles}
	Assume that $\Gamma$ is 2-step Minkowski. Then $\Zc\Gamma$ and $\Inn\Gamma$ are finitely generated and therefore the group of closed 1-cocycles $Z^1(\Inn\Gamma,\Zc\Gamma)$ is a finitely generated abelian group, and hence $Z^1(\Inn\Gamma,\Zc\Gamma)$ is Minkowski.
\end{rem}

\begin{lem}
	Assume that $\Gamma$ is torsion-free and 2-step Minkowski. Then $\Out(\Gamma)$ and $\Aut(\Gamma)$ are Minkowski.
\end{lem}

\begin{proof}
	We consider the central short exact sequence $1\longrightarrow \Zc\Gamma\longrightarrow \Gamma\longrightarrow \Inn\Gamma\longrightarrow 1$. We know that $\Out(\Zc\Gamma)=\Aut(\Zc\Gamma)=\Gl(n,\Z)$ for some $n$, hence $\Out(\Zc\Gamma)$ is Minkowski. Moreover, $H^1(\Inn\Gamma,\Zc\Gamma)$ is Minkowski because $\Inn\Gamma$ and $\Zc\Gamma$ are finitely generated, and $\Out(\Inn\Gamma)$ is Minkowski by hypothesis. By \cref{out ses} and \cref{Minkowski ses}, we can conclude that $\Out(\Gamma)$ is Minkowski.

	The group $Z^1(\Inn\Gamma,\Zc\Gamma)$ is Minkowski by \cref{2-step Minkowski 1-cocycles} and $\Aut(\Inn\Gamma)$ is Minkowski by hypothesis. Therefore $\Aut(\Gamma)$ is Minkowski by \cref{aut ses} and \cref{Minkowski ses}.
\end{proof}

\begin{rem}
	Note that if $\Gamma$ is a centreless finitely generated group, then $\Inn\Gamma\cong \Gamma$. Therefore $\Gamma$ is 2-step Minkowski if and only if $\Out(\Gamma)$ and $\Aut(\Gamma)$ are Minkowski.
\end{rem}

\begin{prop}\label{2-step Minkowski lattice}
	Let $\Gamma$ be lattice of a connected Lie group, then $\Gamma$ has the 2-step Minkowski property.
\end{prop}

\begin{proof}
	Recall that there is a short exact sequence $1\longrightarrow \Gamma_A\longrightarrow \Gamma\longrightarrow \Gamma_{nc}\longrightarrow 1$ where $\Gamma_A$ is virtually polycyclic and $\Gamma_{nc}$ is a centreless lattice in a semisimple Lie group (see \cite[Section 6]{daura2024actions}). In consequence, $\Zc\Gamma\trianglelefteq \Gamma_A\trianglelefteq \Gamma$. Thus, we have a short exact sequence $1\longrightarrow \Gamma_A/\Zc\Gamma\longrightarrow \Inn\Gamma\longrightarrow \Gamma_{nc}\longrightarrow 1$. Moreover $\Gamma_A/\Zc\Gamma$ is virtually polycyclic.

	Since $\Gamma_{nc}$ is centreless, the center $\Zc\Inn\Gamma$ is a subgroup of $\Gamma_A/\Zc\Gamma$. Since $\Gamma_A/\Zc\Gamma$ is virtually polycyclic, $\Zc\Inn\Gamma$ is finitely generated. Moreover, using again that $\Gamma_A/\Zc\Gamma$ is virtually polycyclic and $\Gamma_{nc}$ is a centreless lattice in a semisimple Lie group and that $\Gamma_A/\Zc\Gamma$ is virtually polycyclic we can conclude that $\Out(\Inn\Gamma)$ and $\Aut(\Inn\Gamma)$ are Minkowski (see \cite[Section 6]{daura2024actions} and in particular, \cite[Reamrk 6.7]{daura2024actions}).  

\end{proof}

We are ready to prove \cref{main theorem9 intro}.

\begin{proof}[Proof of \cref{main theorem9 intro}]
	The idea of the proof is to reduce the general case to the case where $M$ is an infranilmanifold finitely covered by a $2$-step nilmanifold. We divide the proof in $4$ parts.

	\textbf{Part 1. Study of the first step of the iterated actions:} Since $\D_2(M)=(f,b)$ there exist a strictly increasing sequence of prime numbers $\{p_i\}_{i\in\mathbb{N}}$ and a sequence of numbers $\{a_i\}_{i\in\mathbb{N}}$ such that $\{(\Z/p_i^{a_i})^f,(\Z/p_i)^b\}\acts M$ freely. Since $\Out(\pi_1(M))$ is Minkowski, there exists $i_0$ such that for all $i\geq i_0$ the induced group morphism $\psi_i:(\Z/p_i^{a_i})^f\longrightarrow \Out(\pi_1(M))$ is trivial. Thus, we can assume without loss of generality that all $\psi_i$ are trivial. Now, we need the following lemma:

	\begin{lem}\label{inner actions aspherical manifolds}\cite[Proposition 3.1.21]{lee2010seifert}
		Let $M$ be a closed aspherical manifold and let $\Zc\pi_1(M)$ be finitely generated. Assume that we have a free action of an abelian group $A$ on $M$ such that $\psi:A\longrightarrow \Out(\pi_1(M))$ is trivial. Then $\Zc\pi_1(M/A)=C_{\pi_1(M/A)}(\pi_1(M))$ and it is an extension of $\Zc\pi_1(M)$ by $A$. In particular, $\rank(\Zc\pi_1(M/A))=\rank(\Zc\pi_1(M))$.
	\end{lem}

	%\begin{lem}
	%Let $G$ be a finite group acting freely on a closed connected aspherical manifold $M$ such that $\psi:G\longrightarrow \Out(\pi_1(M))$ is trivial and let $\tilde{G}=\pi_1(M/G)$. Then $\Zc\tilde{G}=C_{\tilde{G}}(\pi_1(M))$.
	%\end{lem}

	Let $\tilde{G_i}=\pi_1(M/(\Z/p_i^{a_i})^f)$. By \cref{aspherical manifolds big diagram} and \cref{inner actions aspherical manifolds}, we have the following commutative diagram
	\[\begin{tikzcd}
		& 1\ar{d}{}& 1 \ar{d}{}& & \\
		1\ar{r}{}& \Zc\pi_1(M)\ar{d}{}\ar{r}{}& C_{\tilde{G}}(\pi_1(M))=\Zc\tilde{G}_i \ar{d}{}\ar{r}{}& (\Z/p_i^{a_i})^f \ar{d}{id}\ar{r}{}& 1\\
		1\ar{r}{}& \pi_1(M)\ar{d}{}\ar{r}{}& \tilde{G}_i \ar{d}{}\ar{r}{p}&(\Z/p_i^{a_i})^f \ar{r}{}& 1\\
		& \Inn\pi_1(M)\ar{d}{}\ar{r}{\cong}& \Inn \tilde{G}_i \ar{d}{}& & \\	
		& 1& 1 &  & \\
	\end{tikzcd}\]

	where the isomorphism of the last row is induced by the inclusion morphism $\Inn\pi_1(M)\longrightarrow\Aut(\pi_1(M))$. Since $\pi_1(M)$ is 2-step Minkowski and $\Inn\pi_1(M)\cong\Inn \tilde{G}_i$ for all $i$, the groups $\Aut(\Inn \tilde{G}_i)$ and $\Out(\Inn \tilde{G}_i)$ are Minkowski for all $i$. The key observation is that Minkowski constants of $\Aut(\Inn \tilde{G}_i)$ and $\Out(\Inn \tilde{G}_i)$ do not depend on $i$.

	\textbf{Part 2. Study of the second step of the iterated actions:} Note that $M/(\Z/p_i^{a_i})^f$ is a closed aspherical manifold. Therefore the second step of each iterated action induces a group morphism $\psi_i':(\Z/p_i)^b\longrightarrow\Out(\tilde{G}_i)$. We claim that $\psi_i'$ is injective for all $i$. Assume the contrary. Then, each iterated action is equivalent to the iterated action in $3$ steps $\{(\Z/p_i^{a_i})^b,\ker\psi_i',(\Z/p_i)^b/\ker\psi_i'\}\acts M$, where the first 2 steps of the iterated action are inner actions. 

	\begin{lem}\cite[Lemma 5.15]{daura2025IGG1}\label{inner actions simplifiable}
		Let $\{A,A'\}\acts M$ be a free iterated action of abelian groups on a closed connected aspherical manifold such that $\psi:A\longrightarrow \Out(\pi_1(M))$ and $\psi':A'\longrightarrow\Out(\pi_1(M/A))$ are trivial. Then $\{A,A'\}\acts M$ is simplifiable by an abelian group.
	\end{lem}

	%\begin{lem}
	%Let $M$ be a closed connected aspherical manifold and suppose that we have a free iterated action of abelian groups $\{A,A'\}\acts M$ such that $\psi:A\longrightarrow \Out(\pi_1(M))$ and $\psi':A'\longrightarrow \Out(\pi_1(M/A))$ are trivial. Then $\{A,A'\}\acts M$ is simplifiable by a free action of an abelian group $B$ such that $\psi:B\longrightarrow\Out(\pi_1(M))$ is trivial.
	%\end{lem}

	By \cref{inner actions simplifiable}, the iterated action $\{(\Z/p_i^{a_i})^b,\ker\psi_i'\}\acts M$ is simplifiable by an abelian group $A_i$ for all $i$. This implies that $\{(\Z/p_i^{a_i})^b,(\Z/p_i)^b\}\acts M$ and $\{A_i,(\Z/p_i)^b/\ker\psi_i\}\acts M$ are equivalent. Since $\D_2(M)=(f,b)$ we obtain that $\rank A_i=f$. Moreover, we have $\rank((\Z/p_i)^b/\ker\psi_i)<b$. Consequently, $\rank_{ab}(\{(\Z/p_i^{a_i})^b,(\Z/p_i)^b\}\acts M)<f+b$, which contradicts the fact that $\D_2(M)=(f,b)$. Thus, the only possibility is that $\ker\psi'_i$ is trivial for all $i$.

	Like in the first step of the proof, we can use \cref{aspherical manifolds big diagram} and \cref{inner actions aspherical manifolds} to obtain the commutative diagram 

	\[\begin{tikzcd}
		& 1\ar{d}{}& 1 \ar{d}{}& & \\
		& \Zc\tilde{G}_i\ar{d}{}\ar{r}{id}& C_{\tilde{G}_i'}(\tilde{G}_i)\ar{d}{}& & \\
		1\ar{r}{}& \tilde{G}_i\ar{d}{}\ar{r}{}& \tilde{G}_i' \ar{d}{}\ar{r}{p}&(\Z/p_i)^b \ar{r}{}\ar{d}{id}& 1\\
		1\ar{r}{}& \Inn\tilde{G}_i\ar{d}{}\ar{r}{}& G_i \ar{d}{}\ar{r}{}& (\Z/p_i)^b\ar{r}{} &1 \\	
		& 1& 1 &  & \\
	\end{tikzcd}\]

	where $\tilde{G}_i'$ is the fundamental group of $M/\{(\Z/p_i^{a_i})^f,(\Z/p_i)^b\} $ and $G_i\leq \Aut(\tilde{G}_i)$. The key observation in this case is the following lemma:

	\begin{lem}
		The group $\Aut(\tilde{G}_i)$ is Minkowski with a constant that does not depend on $i$.
	\end{lem}

	\begin{proof}
		Consider the short exact sequence $\begin{tikzcd} 1\ar{r}{}& \Zc\tilde{G}_i\ar{r}{}& \tilde{G}_i\ar{r}{}& \Inn\tilde{G}_i\ar{r}{}& 1 \end{tikzcd} $. 
		Since $\Zc\tilde{G}_i$ is a characteristic subgroup there exist short exact sequences
		\[\begin{tikzcd} 1\ar{r}{}& K_i\ar{r}{}& \Aut(\tilde{G}_i)\ar{r}{}& L_i\ar{r}{}& 1 \end{tikzcd} \]
		and 
		\[\begin{tikzcd} 1\ar{r}{}& Z^1(\Inn\tilde{G}_i,\Zc\tilde{G}_i)\ar{r}{}& K_i\ar{r}{}& L'_i\ar{r}{}& 1 \end{tikzcd} \]
		such that $L_i\leq \Aut(\Inn\tilde{G}_i)$ and $L_i'\leq \Aut(\Zc\tilde{G}_i)$. Since $\Inn\tilde{G}_i\cong \Inn\pi_1(M)$ and $\Zc\tilde{G}_i\cong \Zc\pi_1(M)$ we obtain that $\Aut(\tilde{G}_i)$ is Minkowski with a constant not depending on $i$.
	\end{proof}

	\textbf{Part 3. $M$ is an infra-nilmanifold:} Consider the abstract kernel of the extension \[\begin{tikzcd} 1\ar{r}{}& \Inn\tilde{G}_i\ar{r}{}& G_i\ar{r}{}& (\Z/p_i)^b\ar{r}{}& 1 \end{tikzcd}\] which we denote by $\phi_i:(\Z/p_i)^b\longrightarrow\Out(\Inn\tilde{G}_i )$. Since $\Out(\tilde{G}_i)$ is Minkowski with a constant not depending on $i$, $\phi_i$ is trivial for $i$ large enough. Thus, we will assume that $\phi_i$ is trivial. We obtain the following diagram where the first row is a central extension and the columns are inclusions.

	\[\begin{tikzcd} 
		1\ar{r}{}& \Zc\Inn\pi_1(M)\ar{r}{}\ar{d}{}& C_{G_i}(\Inn\pi_1(M))\ar{r}{}\ar{d}{}& (\Z/p_i)^b\ar{r}{}\ar{d}{id}& 1\\
		1\ar{r}{}& \Inn\pi_1(M)\ar{r}{}& G_i\ar{r}{}& (\Z/p_i)^b\ar{r}{}& 1
	\end{tikzcd}\]

	Note that we cannot assume that $C_{G_i}(\Inn\pi_1(M))$ or $\Zc\Inn\pi_1(M)$ are torsion-free. Nevertheless, the group $\Zc\Inn\pi_1(M)$ is finitely generated. Consequently, $\Zc\Inn\pi_1(M)\cong\Z^r\oplus T$, where $T$ is the torsion subgroup of $\Zc\Inn\pi_1(M)$. Moreover,  $C_{G_i}(\Inn\pi_1(M))\leq G_i$, which is Minkowski with a constant which does not depend on $i$. Therefore, for $i$ large enough we can assume that the order of torsion elements of $G_i$ is smaller than $p_i$. In this setting we can use the following lemma:

	\begin{lem} 
		Let \[\begin{tikzcd} 1\ar{r}{}& \Z^r\oplus T\ar{r}{}& G\ar{r}{}& (\Z/p)^b\ar{r}{}& 1 \end{tikzcd}\] be a central group extension such that the order of the torsion elements of $G$ is smaller than the prime $p$. Then $r\geq b$.
	\end{lem}

	\begin{proof}
		We have a central short exact sequence \[\begin{tikzcd} 1\ar{r}{}& \Z^r\ar{r}{}& G/T\ar{r}{}& (\Z/p)^b\ar{r}{}& 1 \end{tikzcd}\] 
		Note that $G/T$ is torsion-free. If not, there would exist an element $g\in G$ such that $g^p\in T$ and therefore its order $o(g)\geq p$, contradicting the fact that the order of the torsion elements of $G$ is smaller than the prime $p$. Since the extension is central and $G/T$ is torsion-free this implies that $r\geq b$.
	\end{proof}

	In consequence $\Z^b\leq \Inn\pi_1(M)$ and we have the following commutative diagram where the rows are central extensions and the columns are inclusions:

	\[\begin{tikzcd} 
		1\ar{r}{}& \Z^f\ar{r}{}\ar{d}{id}& \Gamma\ar{r}{}\ar{d}{}& \Z^b\ar{r}{}\ar{d}{}& 1\\
		1\ar{r}{}& \Z^f\ar{r}{}& \pi_1(M)\ar{r}{}& \Inn\pi_1(M)\ar{r}{}& 1
	\end{tikzcd}\]

	The group $\Gamma$ is a finitely generated torsion-free 2-step nilpotent group and hence it is a lattice in a $2$-step nilpotent Lie group $N$. The nilmanifold $N/\Gamma$ is a the total space of a principal $T^f$-fibration over $T^b$.

	Let $\tilde{M}$ denote the universal covering of $M$. We claim that the covering $\tilde{M}/\Gamma\longrightarrow M$ is a finite covering. Indeed, since $\tilde{M}$ is contractible, we have $H^*(\tilde{M}/\Gamma)\cong H^*(\Gamma,\Z)=H^*(N/\Gamma,\Z)$. Therefore, $H^n(\tilde{M}/\Gamma)\neq 0$, which implies that $\tilde{M}/\Gamma$ is a closed connected manifold. The map $\tilde{M}/\Gamma\longrightarrow M$ is a covering between closed manifolds and hence a finite covering.

	We reach the conclusion that $[\pi_1(M):\Gamma]< \infty$. Since $\pi_1(M)$ is torsion-free, $\pi_1(M)$ is an almost-Bieberbach group (see \cref{AC-groups charactherization}). Since the Borel conjecture holds for almost-Bieberbach groups (see \cite{bartels2012borel}), we obtain that $M$ is an infra-nilmanifold.

	\begin{rem}
		The central short exact sequence \[\begin{tikzcd} 
			1\ar{r}{}& \Z^f\ar{r}{}& \Gamma\ar{r}{}& \Z^b\ar{r}{}& 1
		\end{tikzcd}\]
		can be trivial and therefore $\Gamma\cong \Z^{f+b}=\Z^n$. This implies that $M$ is a flat manifold and $\D_2(M)=(\rank\pi_1(M),0)$ by \cref{iterated discsym flat manifolds}. Thus, $b=0$ and $\rank\Zc\pi_1(M)=f=n$. By \cref{discsym rigidity}.2, we can conclude that $M\cong T^n$, which completes the proof of \cref{main theorem9 intro} in this particular case. Thus, from now on we will assume that the above central exact sequence is not trivial and hence $\Gamma$ will be a 2-step nilpotent torsion-free group. 
	\end{rem}

	\textbf{Part 4. If $M$ is an infra-nilmanifold with $\D_2(M)=(f,b)$ and $f+b=n$ then $M$ is a nilmanifold:} To prove the bolded claim and finish the proof of \cref{main theorem9 intro} we need some preliminary results of free group actions on 2-step nilmanifolds.

	Let $N/\Gamma$ be a 2-step nilmanifold of dimension $n$. Assume that $\rank\Zc\Gamma=f$ and let $b=n-f$. Thus, $N/\Gamma$ is the total space of principal $T^f$-bundle over $T^b$ and $\Gamma$ is a finitely generated torsion-free 2-step nilpotent group fitting in the short exact sequence $1\longrightarrow \Zc\Gamma\cong \Z^f\longrightarrow \Gamma\longrightarrow \Z^b\longrightarrow 1$. Then we have short exact sequences 
	$$1\longrightarrow K\longrightarrow \Out(\Gamma)\longrightarrow \Out(\Z^b)=\Gl(\Z,b)\longrightarrow 1$$
	and 
	$$1\longrightarrow \overline{H}^{1}(\Z^b,\Z^f)\longrightarrow K\longrightarrow K'\longrightarrow 1,$$
	where $K'\leq \Out(\Z^b)=\Gl(b,\Z)$ and $\overline{H}^1(\Z^b,\Z^f)=\{[g]\in\Out(\Gamma):g_{|\Z^f}=id_{\Z^f},\overline{g}:\Z^b\longrightarrow \Z^b=id_{\Z^b}\}$.

	Let $G$ be a finite group acting freely on $N/\Gamma$ and let $\tilde{G}$ be the fundamental group of the manifold $(N/\Gamma)/G$. There exists a group morphism $\phi:G\longrightarrow \Out(\Gamma)$ and therefore we can consider the morphism $\phi_\Q:G\longrightarrow \Out(\Gamma_\Q)$. Our next goal is to study $\ker(\phi_\Q:G\longrightarrow \Out(\Gamma_\Q))$. The first result we need is proved in \cite{daura2024actions}.  

	\begin{prop}\label{discsym coverings}\cite[Proposition 3.14]{daura2024actions}
		Let $M$ be a closed connected aspherical manifold such that $\Zc\pi_1(M)$ is finitely generated. Assume that $G$ is a finite group acting freely on $M$. Then $\rank(\Zc\pi_1(M))$ and $\rank(\Zc\pi_1(M/G))$ are equal if and only if the morphism $\psi':G\longrightarrow \Aut(\Zc\pi_1(M))$, obtained by restricting automorphisms of $\pi_1(M)$ on $\Zc\pi_1(M)$, is trivial.
	\end{prop}	

	In the setting of \cref{main theorem9 intro}, we can rewrite \cref{discsym coverings} as follows:

	\begin{cor}\label{infranilmanifold rank center}
	We have $\rank\Zc\tilde{G}=\rank \Zc\Gamma$ if and only if $\phi':G\longrightarrow \Aut(\Zc\Gamma)$ is trivial. In this situation, $\Zc\tilde{G}=C_{\tilde{G}}(\Gamma)$.
	\end{cor}

	Recall that we can define the isolator of the commutator $[\Gamma,\Gamma]$ as $\sqrt{[\Gamma,\Gamma]}=\{\gamma\in\Gamma:\gamma^r\in[\Gamma,\Gamma]\text{ for some $r$}\}$. It is a characteristic subgroup of $\Gamma$ and $\Gamma/\sqrt{[\Gamma,\Gamma]}$ is torsion-free (see \cite[Lemma 1.1.2]{dekimpe2006almost}). 

	\begin{lem}\cite[Proposition 2.4.1]{dekimpe2006almost}\label{automorphism queotient isolator subgroup}
		Given a positive integer $a$, consider the extension $$1\longrightarrow \Gamma\longrightarrow \tilde{\Gamma}\longrightarrow \Z/a\longrightarrow 1.$$
		The group $\tilde{\Gamma}$ is nilpotent if and only if the induced map $\overline{\phi}:\Z/a\longrightarrow \Aut(\Gamma/\sqrt{[\Gamma,\Gamma]})$ is trivial. 
	\end{lem}

	Since $\Gamma$ is 2-step nilpotent, $\sqrt{[\Gamma,\Gamma]}\subseteq \Zc\Gamma$ and there exists a number $l$ such that $\Zc\Gamma=\sqrt{[\Gamma,\Gamma]}\oplus\Z^l$. Thus, $\Gamma/\sqrt{[\Gamma,\Gamma]}\cong \Gamma/\Zc\Gamma\oplus \Z^l$.

	\begin{lem}\label{infranilmanifold H1}
		We have $\phi(\ker\phi_\Q)\leq \overline{H}^1(\Z^b,\Z^f)$. Conversely, if $g\in G$ such that $\phi(g)\in \overline{H}^1(\Z^b,\Z^f)$, then $g\in \ker\phi_\Q$.
	\end{lem}

	\begin{proof}
		Let $g\in \ker\phi_\Q$. Then there exists $x\in\Gamma_\Q$ such that $\phi(g)(\gamma)=x\gamma x^{-1}$ for all $\gamma\in\Gamma$. Thus, $\phi(g)_{|\Z^f}=id_{\Z^f}$ since $\Z^f$ is in the center of $\Gamma_\Q$ and $\overline{\phi(g)}=id_{\Z^b}$ since $\overline{\phi(g)}$ is a conjugation on an abelian group.

		Conversely, given $g\in G$, we consider the extension $$1\longrightarrow \Gamma\longrightarrow \tilde{\Gamma}\longrightarrow \langle g\rangle\longrightarrow 1.$$ If $\phi(g)\in \overline{H}^1(\Z^b,\Z^f)$, then $\overline{\phi(g)}=id_{\Z^b}$ and $\phi(g)_{\Z^f}=id_{\Z^f}$. In particular, $\phi(g)$ fixes all elements in $\Z^l$. Thus, since $\langle g\rangle$ is a finite group, we have $\overline{\phi}:\langle g\rangle\longrightarrow \Aut(\Gamma/\sqrt{[\Gamma,\Gamma]})=\Aut(\Z^b\oplus\Z^l)$ is trivial. In consequence, $\tilde{\Gamma}$ is a torsion-free nilpotent group and $g\in\ker\phi_\Q$ by \cref{infranilmanifolds malcev completion trivial}.
	\end{proof}

	We are ready to finish the proof of \cref{main theorem9 intro}. Recall that if $\D_2(M)=(f,b)$ with $f+b=n$ then there exists a finite index subgroup $\Gamma\leq \pi_1(M)$ which is the fundamental group of a $2$-step nilmanifold $N/\Gamma$, which is the total space of a principal $T^f$-bundle over $T^b$.

	We consider the Fitting subgroup $\Fitt(\pi_1(M))$, which is torsion-free, nilpotent and of finite index in $\pi_1(M)$ (see \cref{AC-groups charactherization}). Since $\Gamma$ has finite index on $\pi_1(M)$, the groups $\Fitt(\pi_1(M))$ and $\Gamma$ are commensurable, and therefore we have a central short exact sequence \[\begin{tikzcd} 1\ar{r}{}& \Z^f\ar{r}{}& \Fitt\pi_1(M)\ar{r}{}& \Z^b\ar{r}{}& 1. \end{tikzcd}\]   

	In particular, $\D_2(N/\Fitt(\pi_1(M)))=(f,b)$ (see \cite[Theorem 1.16]{daura2025IGG1}).

	We also have a short exact sequence  
	\[\begin{tikzcd} 1\ar{r}{}& \Fitt(\pi_1(M))\ar{r}{}& \pi_1(M)\ar{r}{}& G\ar{r}{}& 1 \end{tikzcd}\]
	where $G$ is a finite group. If $\phi:G\longrightarrow \Out(\Fitt(\pi_1(M)))$ denotes the abstract kernel of the group extension, then the induced map $\phi_\Q:G\longrightarrow \Out(\Fitt(\pi_1(M))_\Q)$ on the rational Mal'cev completion is injective (see \cref{infranilmanifolds malcev completion injective}).

	Since $M$ is an infranilmanifold, we have $\D(M)=\rank\Zc\pi_1(M)$ (see \cite{daura2024actions} and \cite[Theorem 11.7.7]{lee2010seifert}). In consequence, $\rank\Zc\pi_1(M)=\rank\Zc\Fitt(\pi_1(M))=f$ and $\phi'$ is trivial by \cref{infranilmanifold rank center}. The injectivity of $\phi_\Q$ together with \cref{infranilmanifold H1} implies that $\overline{\phi}:G\longrightarrow \Out(\Fitt(\pi_1(M))/\Zc\Fitt(\pi_1(M)))\cong \Gl(b,\Z)$ is injective. We obtain the commutative diagram (see \cref{aspherical manifolds big diagram})

	\[\begin{tikzcd}
		& 1\ar{d}{}& 1 \ar{d}{}& & \\
		& \Zc\Fitt(\pi_1(M))=\Z^f\ar{d}{}\ar{r}{id}& \Zc\pi_1(M)\ar{d}{}& & \\
		1\ar{r}{}&\Fitt(\pi_1(M))\ar{d}{}\ar{r}{}&\pi_1(M) \ar{d}{}\ar{r}{p}&G \ar{r}{}\ar{d}{id}& 1\\
		1\ar{r}{}& \Inn\Fitt(\pi_1(M))=\Z^b\ar{d}{}\ar{r}{}& \Inn\pi_1(M) \ar{d}{}\ar{r}{}& G\ar{r}{} &1 \\	
		& 1& 1 &  & \\
	\end{tikzcd}\]
	where the identity map in the first row is induced by the inclusion morphism $\Zc\Fitt(\pi_1(M))\longrightarrow C_{\pi_1(M)}(\Fitt(\pi_1(M)))=\Zc\pi_1(M)$. The abstract kernel of the third row is $\overline{\phi}$. Since $\overline{\phi}$ is injective, $\Inn\pi_1(M)$ is a crystallographic group. Moreover, $\D_2(M)=(f,b)$ implies that $\Z^b\leq\Zc\Inn\pi_1(M)$ and hence $[\Inn\pi_1(M):\Zc\Inn\pi_1(M)]<\infty$. Therefore, $[\Inn\pi_1(M),\Inn\pi_1(M)]$ is a finite normal subgroup of a crystallographic group, which implies that $[\Inn\pi_1(M),\Inn\pi_1(M)]$ is trivial (see \cref{AC-groups charactherization}). Hence $\Inn\pi_1(M)$ is abelian and $\pi_1(M)$ is a finitely generated torsion-free 2-step nilpotent group. This implies that $M$ is a nilmanifold, as desired.
\end{proof}

The same proof can be used to obtain the following bound on the iterated discrete degree of symmetry.

\begin{cor}\label{discsym2 bound}
	Let $M$ be a closed connected aspherical manifold such that $\pi_1(M)$ is 2-step Minkowski. Then $\D_2(M)\leq (\rank\Zc\pi_1(M),\rank\Zc\Inn\pi_1(M))$ and $\rank\Zc\pi_1(M)+\rank\Zc\Inn\pi_1(M)\leq \dim(M)$.
\end{cor}

Combining \cref{2-step Minkowski lattice} and \cref{discsym2 bound}, we obtain:

\begin{cor}
	Let $G$ be a connected Lie group, $K$ a maximal subgroup of $G$ and $\Gamma$ a torsion-free cocomapct lattice of $G$. The closed aspherical locally homogeneous space $\Gamma\setminus G/K$ satisfies $\D_2(M)\leq (\rank\Zc\Gamma,\rank\Zc(\Inn\Gamma))$.
\end{cor}

\Cref{discsym2 bound} can be used in the following situation:

\begin{cor}
	Let $M$ be a closed connected aspherical manifold. Suppose that the groups $\Out(\pi_1(M))$ and $\Aut(\pi_1(M))$ are Minkowski and that $\Zc\pi_1(M)$ is trivial. Let $E$ be the total space of a principal $T^f$-bundle over $M$. Then $\D_2(E)=(f,0)$. 
\end{cor}

\begin{proof}
	Consider the central short exact sequence
	\[\begin{tikzcd} 1\ar{r}{}& \Zc\pi_1(E)\cong\Z^f\ar{r}{}& \pi_1(E)\ar{r}{}& \pi_1(M)\ar{r}{}& 1. \end{tikzcd}\]
	Consequently, $\Inn\pi_1(E)\cong\pi_1(M)$ and $\pi_1(E)$ is 2-step Minkowski. Hence, by \cref{discsym2 bound}, $\D_2(M)\leq (f,0)$. 

	On the other hand, since $E$ has a free action of $T^f$, $E$ also admits free actions of $(\Z/p^{a})^f$ for any prime $p$ and positive integer $a$. Consequently, $\D_2(E)\geq (f,0)$. Thus, $\D_2(E)=(f,0)$.
\end{proof}


