\section{Free iterated actions on closed aspherical 3-dimensional manifolds}\label{sec: iterated actions on 3-manifolds}

If $M$ is a closed $3$-dimensional aspherical manifold with an effective $S^1$ action, then $M$ can be one of the following four cases (see \cite[\S 14.4]{lee2010seifert}):
\begin{itemize}
	\item[1.] $M\cong T^3$.
	\item[2.] $M$ is homeomorphic to $K\times S^1$ or $SK$, where $K$ denotes the Klein bottle and $SK$ the non-trivial principal $S^1$-bundle over $K$.
	\item[3.] $M\cong H/\Gamma$, where $H$ is the $3$-dimensional Heisenberg group and $\Gamma $ is a lattice of $H$
	\item[4.] $\Zc\pi_1(M)\cong \Z$, and $\Inn \pi_1(M)\cong \pi_1(M)/ \Zc\pi_1(M)$ is centreless.
\end{itemize}

Note that in all cases, we have a central extension $$1\longrightarrow \Z\longrightarrow \pi_1(M)\longrightarrow Q\longrightarrow 1$$ where $Q$ acts effectively, properly and cocompactly on $\R^2$. If $M$ is a closed connected aspherical 3-manifold then $\Out(\pi_1(M))$ is Minkowski by \cite{kojima1984bounding} and $\A(M)=\D(M)=\rank\Zc\pi_1(M)$ by \cite[Corollary 8.3]{gabai1992convergence} and \cite[Theorem 1.1]{casson1994convergence}. Thus, it is straightforward to show that $\D(T^3)=3$, $\D(K\times S^1)=\D(SK)=2$, $\D(H/\Gamma)=1$, and $\D(M)=1$ if $M$ belongs to the case 4. Moreover if $M$ is a closed connected aspherical 3-manifold which does not belong to one of the four cases above, then $\A(M)=\rank\Zc\pi_1(M)=0$ and hence $\D(M)=0$.

We will compute the iterated discrete degree of symmetry and show that it can be used to distinguish the four cases of the above classification. We start by providing a different proof that $\Out(\pi_1(M))$ is Minkowski if $M$ belongs to one of these four cases.

\begin{lem}\label{out minkowski 3-manifolds}
	Let $M$ be a closed $3$-dimensional aspherical manifold with an effective $S^1$-action. Then $\Zc\pi_1(M)$ is finitely generated and $\Out(\pi_1(M))$ is Minkowski.
\end{lem}
\begin{proof}
	In the first three cases the fundamental group is polycyclic and therefore $\Out(\pi_1(M))$ is Minkowski (this is a consequence of Minkowski's lemma and \cite{Wehrfritz1994}). We only need to check the case where we have a short exact sequence $1\longrightarrow \Zc\pi_1(M)\cong\Z\longrightarrow \pi_1(M)\longrightarrow \Inn(\pi_1(M))\longrightarrow 1$ and $ \Inn(\pi_1(M))$ is centreless. Since $\Zc\pi_1(M)$ is a characteristic subgroup of $\pi_1(M)$ then there are short exact sequences $$1\longrightarrow K \longrightarrow \Out (\pi_1(M))\longrightarrow \Out(\Inn\pi_1(M))\longrightarrow 1$$ and $$1\longrightarrow \overline{H}^1(\Inn\pi_1(M),\Z) \longrightarrow K\longrightarrow \Gl(1,\Z)\longrightarrow 1.$$

	Recall that $\overline{H}^1(\Inn\pi_1(M),\Z)\cong Z^1(\Inn\pi_1(M),\Z)/\overline{B}^1(\Inn\pi_1(M),\Z)$ and $$\overline{B}^1(\Inn\pi_1(M),\Z)\cong p^{-1}(\Zc\Inn\pi_1(M)\cap C_{\pi_1(M)}(\Zc\pi_1(M)))/\Zc\pi_1(M)$$ where $p:\pi_1(M)\longrightarrow \Inn\pi_1(M)$ is the quotient map. Since $\Zc\Inn\pi_1(M)$ is trivial, the group $\overline{B}^1(\Inn\pi_1(M),\Z)$ is also trivial and $$\overline{H}^1(\Inn\pi_1(M),\Z)\cong Z^1(\Inn\pi_1(M),\Z)\cong H^1(\Inn\pi_1(M),\Z).$$ 

	The group $\Out(\pi_1(M))$ will be Minkowski if $\Out(\Inn\pi_1(M))$ and $H^1(\Inn\pi_1(M),\Z)$ are Minkowski. Since $\Inn\pi_1(M)$ acts effectively, properly and cocompactly on $\R^2$, $\Inn\pi_1(M)$ is a subgroup of isometries of the Euclidean plane or the hyperbolic plane. In both cases $H^1(\Inn\pi_1(M),\Z)$ is a finitely generated abelian group and therefore Minkowski. 

	If $\Inn\pi_1(M)$ is a subgroup of isometries of the Euclidean plane then it is virtually abelian and therefore $\Out(\Inn\pi_1(M))$ is Minkowski. 
	If $\Inn\pi_1(M)$ is a subgroup of isometries of the hyperbolic plane, then it contains a centreless torsion-free Fuchsian subgroup $Q$ of finite index. Since $\Out(Q)$ is virtually torsion-free, $\Out(\Inn\pi_1(M))$ is also virtually torsion-free (see \cite[Lemma 2.4, Corollary 2.6
	]{metaftsis2006residual}) and therefore Minkowski.
\end{proof}

The proof of \cref{main theorem10 intro} is a combination of \cref{inner actions simplifiable}, \cref{inner actions aspherical manifolds} and the following lemma.

\begin{lem}\label{discsym2 finiteness}
	Let $M$ be a closed aspherical manifold. Assume that $\Zc\pi_1(M)$ is finitely generated, that $\Out(\pi_1(M))$ is Minkowski and that there exists a constant $C$ satisfying that for every free inner action of an abelian group $A$ on $M$, $\Out(\pi_1(M/A))$ is Minkowski with a constant less or equal than $C$. Then $\D_2(M)=(d_1,0)$.
\end{lem}

\begin{proof}
	Assume that $\D_2(M)=(d_1,d_2)$. We have an increasing sequence of primes $\{p_i\}_{i\in \mathbb{N}}$, a sequence of positive integers $\{a_i\}_{i\in \mathbb{N}}$ and a collection of free iterated actions $\{(\Z/p_i^{a_i})^{d_1},(\Z/p_i)^{d_2}\}\acts M$ satisfying that $$\rank_{ab}(\{(\Z/p_i^{a_i})^{d_1},(\Z/p_i)^{d_2}\}\acts M)=(d_1,d_2).$$ We can assume that $p_i>C$ for all $i$. In this case, $\psi_i:(\Z/p_i^{a_i})^{d_1}\longrightarrow \Out(\pi_1(M))$ and $\psi_i':(\Z/p_i)^{d_2}\longrightarrow \Out(\pi_1(M))$ are trivial for all $i$. By \cref{inner actions simplifiable}, this iterated action is simplifiable, which implies that there exists a free group action of $(\Z/p_i)^{d_1+d_2}$ on $M$. But then $d_1+d_2\leq d_1$, which implies that $d_2=0$.
\end{proof}

From \cref{discsym2 finiteness} we can deduce the following corollary, which proves part (2) of \cref{main theorem10 intro}. 

\begin{cor}\label{iterated discsym flat manifolds}
	Let $M$ be a closed flat manifold. Then $\D_2(M)=(\rank\Zc\pi_1(M),0)$.
\end{cor}

\begin{proof}
	Given any abelian group $A$ acting freely on a $n$-dimensional closed flat manifold $M$ such that $\psi:A\longrightarrow \Out(\pi_1(M))$, the quotient space $M/A$ is a closed flat manifold of the same dimension and hence $\pi_1(M/A)$ is a Bieberbach group. Because there is a finite number of isomorphism classes of Bieberbach groups in each dimension and their outer automorphisms group is Minkowski, we can use \cref{discsym2 finiteness} by taking $C$ to be the maximum of all Minkowski constants of the outer automorphism group of Bieberbach groups of flat manifolds of dimension $n$. 
\end{proof}

\begin{proof}[Proof of \cref{main theorem10 intro}]
	By \cref{main theorem9 intro}, we have already proved that $\D_2(M)=(3,0)$ if $M\cong T^3$ and that $\D_2(M)=(1,2)$ if $M\cong H/\Gamma$, as a consequence \cref{main theorem9 intro}. Moreover, $SK$ and $K\times S^1$ are closed flat manifolds, which implies that $\D_2(K\times S^1)=\D_2(SK)=(2,0)$ (see \cref{iterated discsym flat manifolds}). Therefore, we only need to check the last case.

	Let $M$ be a $3$-aspherical manifold of the case 4 and assume that the Minkowski constant of $\Out(\pi_1(M))$ is $C$. Since $\D(M)=\A(M)=\rank\Zc\pi_1(M)=1$, there exist an increasing sequence of primes $\{p_i\}_{i\in\mathbb{N}}$ and a sequence of positive integers $\{a_i\}_{i\in\mathbb{N}}$ such that $\Z/p_i^{a_i}$ acts freely on $M$ and $p_i>C$ for all $i$. Therefore each action induces the trivial group morphism $\psi_i:\Z/p_i^{a_i}\longrightarrow \Out(\pi_1(M))$ and a commutative diagram
	\[
	\begin{tikzcd}
		& 1\ar{d}{}& 1\ar{d}{}& & \\
		1\ar{r}{} & \Zc \pi_1(M)\cong \Z \ar{r}{}\ar{d}{} & C_{G_i}(\pi_1(M))=\Zc G_i\ar{r}{}\ar{d}{}& \Z/p_i^{a_i}\ar{r}{}\ar{d}{Id} &1\\
		1\ar{r}{} & \pi_1(M) \ar{r}{}\ar{d}{} & G_i\ar{r}{}\ar{d}{}& \Z/p_i^{a_i}\ar{r}{} &1\\
		& \Inn \pi_1(M)\ar{d}{}\ar{r}{Id} & \Inn \pi_1(M)\ar{d}{} & &\\
		& 1 &1 & & \\
	\end{tikzcd}
	\]
	where $G_i=\pi_1(M/(\Z/p_i^{a_i}))$. Note that $\Inn\pi_1(M)$ is centreless. 

	We claim that $\Out(G_i)$ is Minkowski with a constant that does not depend on $i$. Since $\Zc G_i$ is a characteristic subgroup of $G_i$ and $\Inn\pi_1(M)$ is centreless there exist two short exact sequence (see \cref{out minkowski 3-manifolds}) $$1\longrightarrow K \longrightarrow \Out (G_i)\longrightarrow \Out(\Inn\pi_1)\longrightarrow 1$$ and $$1\longrightarrow H^1(\Inn\pi_1(M),\Z) \longrightarrow K\longrightarrow \Gl(1,\Z)\longrightarrow 1.$$

	The Minkowski constant of the group $\Out(G_i)$ can be bounded by the Minkowski constants of $\Out(\Inn\pi_1(M))$, $\Gl(1,\Z)$ and $H^1(\Inn\pi_1(M),\Z)$, which do not depend on $p_i$. Thus, we can use \cref{discsym2 finiteness} to conclude that $\D_2(M)=(1,0)$.
\end{proof}

\begin{rem}
	The key observation of the proof of \cref{main theorem10 intro} is that if $\Inn\pi_1(M)$ is centreless then we have $\bar{H}^1(\Inn\pi_1(M),\Z)=H^1(\Inn\pi_1(M),\Z)$, which does not depend on the action of $(\Z/p_i^{a_i})$ on $M$. In general, $\bar{H}^1(\Inn\pi_1(M),\Z)$ does depend on the action of $(\Z/p_i^{a_i})$ on $M$.
\end{rem}
