\section{The length of a free iterated action}\label{sec:lenght iterated actions}

A natural question is whether for a closed manifold $M$, there exists a constant $C$ such that $l(M)\leq C$. For example:

\begin{lem}\label{free iterated action lenght Euler char}
	Let $M$ be a closed manifold with $\chi(M)\neq 0$. Then $l(M)\leq \log_2\chi(M)$.
\end{lem}

\begin{proof}
	Recall that if $G$ is a finite group acting freely on $M$ then $\chi(M)=|G|\chi(M/G)$. If we have an iterated free action $\mathcal{G}\acts M$ then $\chi(M)=\prod_{i=1}^n |G_i| \chi(M/\mathcal{G})$. Since $|G_i|\geq 2$ for all $i$, then $n\leq \log_2\chi(M)$.
\end{proof}

The first main result of this section bounds the iterated length of nilmanifolds. Let $N/\Gamma$ be a $c$-step nilmanifold and let $\{0\}=Z_0\trianglelefteq Z_1\trianglelefteq\cdots\trianglelefteq Z_c=\Gamma$ be the upper central series. The groups $Z_{i+1}/Z_i$ are finitely generated torsion-free and abelian, so we denote by $b_i=\rank(Z_{i+1}/Z_i)$. Then:

\begin{thm}\label{free iterated actions on nilmanifolds}
	There exists a constant $C$ only depending on $\Gamma$ such that any free iterated action $\mathcal{G}\acts N/\Gamma$ is equivalent to a free iterated action $\mathcal{G}'\acts N/\Gamma$ where $\mathcal{G}'=\{A_1,\dots,A_c,G'\}$, $A_i$ are finite abelian groups such that $\rank(A_i)\leq b_i$ and $|G'|\leq C$.
\end{thm}

\begin{cor}\label{free iterated actions on nilmanifolds lenght}
	If $N/\Gamma$ is a $c$-step nilmanifold then $l(N/\Gamma)\leq c+1$.
\end{cor}

We need some preliminary lemmas before proving \cref{free iterated actions on nilmanifolds}. Firstly, we study the case where $(N/\Gamma)/\mathcal{G}$ is a nilmanifold.

\begin{lem}\label{free iterated actions nilmanifolds quotient nilmanifold}
	Let $N$ be a $c$-step nilpotent Lie group and let $\Gamma$ and $\Lambda$ be lattices of $N$ such that $\Gamma\leq \Lambda$. There exist subgroups $\Lambda_0,\Lambda_1,\dots,\Lambda_c$ such that $\Lambda_0=\Gamma$, $\Lambda_c=\Lambda$ and $\Lambda_i\trianglelefteq \Lambda_{i+1}$ for all $i$. Moreover, $A_i=\Lambda_{i+1}/\Lambda_{i}$ is abelian and $\rank(A_i)\leq b_i$ for all $i$.
\end{lem}

\begin{proof}
	We prove the claim by induction on $c$. If $c=1$ then $N$ is abelian and therefore $\Gamma=\Lambda_0\trianglelefteq\Lambda_1=\Lambda$.

	Assume that $N$ is $c$-step nilpotent and let $\pi:N\longrightarrow N/\Zc N$ be the quotient map to the $(c-1)$-step nilpotent Lie group $N/\Zc N$. Then $\pi(\Lambda)$ and $\pi(\Gamma)$ are lattices of $N/\Zc N$. Since $\Zc\Lambda=\Lambda\cap\Zc N$ and $\Zc\Gamma=\Gamma\cap\Zc N$, there are short exact sequences
	\[
	\begin{tikzcd}
		1 \ar{r}{}& \Zc\Lambda \ar{r}{}&\Lambda \ar{r}{\pi_{|\Lambda}}& \pi(\Lambda) \ar{r}{}&1
	\end{tikzcd}
	\]

	and 

	\[
	\begin{tikzcd}
		1 \ar{r}{}& \Zc\Gamma \ar{r}{}&\Gamma \ar{r}{\pi_{|\Gamma}}& \pi(\Gamma) \ar{r}{}&1.
	\end{tikzcd}
	\]

	By induction hypothesis, there exists $\Lambda'_0=\pi(\Gamma)\trianglelefteq \Lambda'_1\trianglelefteq \dots\trianglelefteq \Lambda'_{c-1}=\pi(\Lambda)$. Then we define $\Lambda_{i+1}=\pi_{|\Lambda}^{-1}(\Lambda'_i)$ for $0\leq i\leq c-1$, which satisfy that $\Lambda_{i}\trianglelefteq \Lambda_{i+1}$ for all $0\leq i\leq c-1$.

	Lastly, we take $\Lambda_0=\Gamma$. We have the commutative diagram where the rows are central extensions

	\[
	\begin{tikzcd}
		1 \ar{r}{}& \Zc\Lambda \ar{r}{}&\Lambda_1 \ar{r}{\pi_{|\Lambda}}& \pi(\Gamma) \ar{r}{}&1\\
		1 \ar{r}{}& \Zc\Gamma \ar{r}{}\ar[hook]{u}{}&\Gamma \ar{r}{\pi_{|\Gamma}}\ar[hook]{u}{}& \pi(\Gamma) \ar{r}{}\ar{u}{id}&1.
	\end{tikzcd}
	\]
	Consequently, $\Gamma\trianglelefteq \Lambda_1$.
\end{proof}

\begin{cor}
	A free iterated action $\mathcal{G}\acts N/\Gamma$ such that $(N/\Gamma)/\mathcal{G}$ is a nilmanifold is equivalent to a free iterated action $\mathcal{G}'\acts N/\Gamma$ where $\mathcal{G}'=\{A_1,\dots,A_c\}$ and $A_i$ are finite abelian groups such that $\rank(A_i)\leq b_i$.
\end{cor}

For the general case we need \cref{AC-groups charactherization}, \cref{infranilmanifolds malcev completion trivial} to prove the following two lemmas.
