\begin{lem}\label{itertaed actions on nilmanifolds and Fitt}
	Let $\mathcal{G}\acts N/\Gamma$ be a free iterated action. Then $\pi_1((N/\Gamma)/\mathcal{G})=E$ is an AC-group and $\Gamma\leq \Fitt(E)$. 
\end{lem}

\begin{proof}
	Since $(N/\Gamma)/\mathcal{G}$ is a closed aspherical manifold, then $E$ is torsion-free and contains $\Gamma$ as a finite index subgroup. Using \cref{AC-groups charactherization}, $E$ is an AC-group. It only remains to prove that $\Gamma\leq \Fitt(E)$.

	Consider the exact sequence
	\[
	\begin{tikzcd}
		1\ar{r}{} & \Fitt(E)\ar{r}{} & E\ar{r}{p} & F\ar{r}{} & 1
	\end{tikzcd}
	\]
	If $G=p(\Gamma)$ and $\Lambda=p^{-1}(G)$ we obtain the commutative diagram
	\[
	\begin{tikzcd}
		1\ar{r}{} & \Fitt(E)\cap\Gamma\ar{r}{}\ar{d}{} & \Gamma\ar{r}{p}\ar{d}{i} & G\ar{r}{}\ar{d}{} & 1\\
		1\ar{r}{} & \Fitt(E)\ar{r}{} & \Lambda\ar{r}{p} & G\ar{r}{} & 1
	\end{tikzcd}
	\]
	where the vertical arrows are inclusions. Let $\sigma:G\longrightarrow \Gamma$ be a set-theoretic section of $p$ and $\psi:G\longrightarrow \Out(\Fitt(E)\cap \Gamma)$ the induced group morphism such that $\psi(g)=[c_{\sigma(g)|\Fitt(E)\cap \Gamma}]$. The map $\overline{\sigma}=i\circ \sigma$ is a section for the second short exact sequence and it induces a group morphism $\bar\psi:G\longrightarrow \Out(\Fitt(E))$ such that $\tilde\psi(g)=[c_{\sigma(g)|\Fitt(E)}]$.

	Since $\Gamma$ and $\Fitt(E)$ have finite index inside $E$, then $\Fitt(E)\cap \Gamma$ has finite index inside $\Fitt(E)$ and $\Gamma$ and therefore $\Gamma_\Q=\Fitt(E)_\Q=(\Fitt(E)\cap \Gamma)_\Q$. This implies that the maps $\psi':G\longrightarrow \Out(\Gamma_\Q)$ and $\bar\psi':G\longrightarrow \Out(\Gamma_\Q)$ are the same. By \cref{infranilmanifolds malcev completion trivial} the morphism $\psi'$ is trivial since $\Gamma$ is nilpotent. On the other hand $\overline{\psi}'$ is injective by \cref{infranilmanifolds malcev completion trivial} and part 2. of \cref{AC-groups charactherization}. Therefore, the only option is that $G$ is trivial and $\Gamma\leq\Fitt(E)$.
\end{proof}

\begin{lem}\label{out rational malcev completion}
	There exists a constant $C$ such that if $G$ is a finite subgroup of $\Out(\Gamma_\Q)$ then $|G|\leq C$.
\end{lem}

\begin{proof}
	Let $\psi:G\longrightarrow \Out(\Gamma_\Q)$ denote the inclusion of the finite group. We have $H^2_\psi(G,\Q^n)=0$, since $G$ is finite and $\Q^n$ is divisible and therefore there is an injective lift $\tilde{\psi}:G\longrightarrow \Aut(\Gamma_\Q)$ of $\psi$. By \cref{automorphisms malcev completion}, $\Aut(\Gamma_\Q)=\Aut(\mathcal{L}(\Gamma_\Q))$, which is a subgroup of $\Gl(m,\Q)$ for some $m$. In consequence, $G$ is conjugated to a finite subgroup of $\Gl(m,\Z)$ and therefore the bound is a consequence of Minkowski's lemma. 
\end{proof}

\begin{proof}[Proof of \cref{free iterated actions on nilmanifolds}]
	Assume that we have a free iterated action of $\mathcal{G}$ on a nilmanifold $N/\Gamma$. Then $(N/\Gamma)/\mathcal{G}=M$ is a closed almost-flat manifold and $\pi_1(M)$ is an almost-Bieberbach group. In consequence, $\pi_1(M)$ contains a maximal normal nilpotent group $\Lambda$, which has $\Gamma$ as a subgroup by maximality by \cref{itertaed actions on nilmanifolds and Fitt}. Since $[\pi_1(M):\Gamma]<\infty$, $[\Lambda:\Gamma]<\infty$ and therefore $\Lambda$ is a lattice of $N$. By \cref{free iterated actions nilmanifolds quotient nilmanifold}, there exists a subnormal series $\Gamma=\Lambda_0\trianglelefteq\Lambda_1\trianglelefteq\cdots\trianglelefteq\Lambda_c=\Lambda\trianglelefteq \pi_1(M)$. We have a free iterated action of $\{\Lambda_i/\Lambda_{i-1},\pi_1(M)/\Lambda\}_{i=1,\dots,c}$ on $N/\Gamma$ equivalent to $\mathcal{G}\acts N/\Gamma$. By \cref{free iterated actions nilmanifolds quotient nilmanifold}, $\rank(\Lambda_i/\Lambda_{i-1})\leq b_i$. Moreover, $\pi_1(M)/\Lambda\leq \Out(\Lambda_\Q)$ and $\Lambda_\Q\cong \Gamma_\Q$. Therefore, by \cref{infranilmanifolds malcev completion trivial} $|\pi_1(M)/\Lambda|\leq C$, where $C$ is a constant depending on $\Gamma_\Q$.
\end{proof}  

\begin{rem}\label{lenght remark}
	The bound of \cref{free iterated actions on nilmanifolds lenght} is sharp. For example, the free iterated action on $T^3$ from \cite{daura2025IGG1} shows that $2\geq l(T^3)$ and therefore $l(T^3)=2$. Consequently, $l(T^n)=2$ for all $n\geq 3$. On the other hand, in \cite{daura2025IGG1} we show that all free iterated actions on $S^1$ and $T^2$ are simplifiable, which implies that $l(T^n)=1$ for $n=1,2$. Thus, \cref{free iterated actions on nilmanifolds lenght} is not an equality in general. 
\end{rem}

On the other hand, a bound for $l(M)$ when $M$ is a solvmanifold does not always exist.

\begin{thm}\label{solvmanifold inifite lenght}
	There exists a $3$-dimensional solvmanifold $M$ such that $l(M)=\infty$.
\end{thm}

\begin{proof}
	Consider the 3-dimensional solvable Lie group $R=\operatorname{Sol}^3$. Explicitly, $R\cong \R^2\rtimes_\psi\R$, where 
	\[ \psi(t)= \left(\begin{matrix}
		e^{-t} & 0\\
		0 & e^t
	\end{matrix}\right).\] 

	Any lattice of $R$ is isomorphic to a semi-direct $\Z^2\rtimes_\phi \Z$, where $\phi:\Z\longrightarrow \Sl(2,\Z)$ satisfies $\operatorname{tr}(\phi(1))>2$ (see \cite[\S 2]{lee2015infra}). Two of these lattices $\Gamma$ and $\Gamma'$ are isomorphic if and only if $\phi'(1)$ is conjugate to $\phi(1)$ or $\phi(1)^t$.

	We take the matrix 
	\[ A= \left(\begin{matrix}
		5 & 2\\
		2 & 1
	\end{matrix}\right)\]
	and the lattice $\Gamma=\Z^2\rtimes_\phi \Z$ of $R$ where $\phi(1)=A$. We are going to see that the solvmanifold $M=R/\Gamma$ satisfies $l(M)=\infty$. We start by studying the lattice $\Gamma$ and some of its sublattices.

	For an integer $k\geq 0$ we define the group $\Gamma_k=2^k(\Z)^2\rtimes_\phi\Z$. We have a series $\Gamma=\Gamma_0\geq \Gamma_1\geq \Gamma_2 \geq \dots$. Firstly, we note that the group morphism $f_k:\Gamma\longrightarrow \Gamma_k$ such that $f_k(v,t)=(2^kv,t)$ is an isomorphism for all $k\geq 0$, which implies that $R/\Gamma$ and $R/\Gamma_k$ are diffeomorphic for all $k\geq 0$.

	We claim now that the normalizer $N_\Gamma(\Gamma_k)=\Gamma_{k-1}$. Firstly, a computation shows that:
	\begin{itemize}
		\item[1.] If $(v,t)\in\Gamma$ then $(v,t)^{-1}=(-A^{-t}v,-t)$.
		\item[2.] If $(v,t),(w,s)\in\Gamma$ then $(v,t)(w,s)(v,t)^{-1}=((Id-A^s)v+A^tw,s)$.
	\end{itemize}

	Therefore, the normalizer takes the form 
	$$N_\Gamma(\Gamma_k)=\{(v,t)\in\Gamma:(Id-A^s)v\in 2^{k}\Z^2 \text{ for all $s$}\}.$$

	The matrix $A$ is of the form $A=Id+B$ with 
	\[ B= \left(\begin{matrix}
		4 & 2\\
		2 & 0
	\end{matrix}\right)\in M_{2\times 2}(2\Z)\]
	which implies that $Id-A^s=-\sum_{i=1}^{s}\binom{s}{i}B^s\in M_{2\times 2}(2\Z)$ for all $s\geq1$ (and we have a similar form for $A^{-s}$). Let $(v,t)\in N_\Gamma(\Gamma_k)$ with $v=(v_1,v_2)\in \Z^2$. Since $(Id-A^s)v\in 2^{k}\Z^2$ for all $s$, in particular $-Bv=(Id-A)v\in 2^{k}\Z^2$. We obtain that $2v_1,2v_2\in 2^k\Z$ and therefore $v_1,v_2\in 2^{k-1}\Z$. Moreover, if $v\in 2^{k-1}\Z^2$ then $(Id-A^s)v\in 2^{k}\Z^2$ for all $s$. Thus, we have seen that  
	$$N_\Gamma(\Gamma_k)=\{(v,t)\in\Gamma:v\in 2^{k-1}\Z^2\}= \Gamma_{k-1}.$$

	In consequence, $\Gamma_k\trianglelefteq\Gamma_{k-1}$ and $\Gamma_k\ntrianglelefteq\Gamma_{k-i}$ for $i>1$. In addition, $ \Gamma_{k-1}/\Gamma_{k}\cong \Z/2\oplus\Z/2$. If $\pi_k:\Gamma_{k-1}\longrightarrow \Z/2\oplus\Z/2$ denotes the quotient map, then we can define new lattices
	$$\Gamma_k^{(1,0)}=\pi_k^{-1}(\langle(1,0)\rangle)=(2^k\Z\times 2^{k-1}\Z)\rtimes_\phi\Z, $$
	$$\Gamma_k^{(0,1)}=\pi_k^{-1}(\langle(0,1)\rangle)=(2^{k-1}\Z\times 2^{k}\Z)\rtimes_\phi\Z, $$
	$$\Gamma_k^{(1,1)}=\pi_k^{-1}(\langle(1,1)\rangle)= \{((v_1,v_2),t)\in\Gamma_{k-1}:v_1+v_2\in 2^{k}\Z\}.$$

	Analogous computations show that $N_\Gamma(\Gamma_k^{(i,j)})=\Gamma_{k-1}^{(i,j)}$ and $\Gamma_k^{(i,j)}/\Gamma_{k-1}^{(i,j)}\cong \Z/2\oplus\Z/2$ for all $(i,j)\in \Z/2\oplus\Z/2$, where we set $\Gamma_k^{(0,0)}=\Gamma_{k-1}$.

	We consider the regular $\Z/2\oplus \Z/2$ self-covering $p:R/\Gamma_1\cong M\longrightarrow R/\Gamma\cong M$. We can obtain a tower of regular self-coverings $p^k: R/\Gamma_k\cong M\longrightarrow R/\Gamma\cong M$, which has associated a free iterated action of $\mathcal{G}_k=\{\Z/2\oplus\Z/2,\dots,\Z/2\oplus\Z/2\}$ with $l(\mathcal{G}_k)=k$ on $M$. 

	Let $\mathcal{G}'=\{G_1',\dots,G_m'\}\acts M$ be a free iterated action equivalent to $\mathcal{G}_k\acts M$. Then we have a subnormal series $\Gamma_k=\Lambda_0\trianglelefteq\Lambda_1\trianglelefteq\cdots\trianglelefteq \Lambda_{m}=\Gamma$ such that $\Lambda_{i}/\Lambda_{i-1}\cong G_i'$. We have $\Lambda_1\leq N_\Gamma(\Gamma_k)$ and therefore $\Lambda_1= \Gamma_k^{(i,j)}$ for some $(i,j)\in\Z/2\oplus\Z/2$. In consequence, $|G_1'|\leq 4$. We can repeat the same process with $\Lambda_1= \Gamma_k^{(i,j)}$, since $N_\Gamma(\Gamma_k^{(i,j)})=\Gamma_{k-1}^{(i,j)}$. Repeating this process we find that all the subgroups of the subnormal series are of the form  $\Gamma_a^{(i,j)}$. This implies that $|G_i'|\leq 4$ for all $1\leq i\leq m$. 

	Finally, if $\mathcal{G}'\acts M$ satisfies that $m=l(\mathcal{G}_k\acts M)$ then $[\Gamma:\Gamma_k]=4^k=\prod_{i=1}^m |G_i|\leq 4^{m}$, which implies that $l(\mathcal{G}_k\acts M)=k$. Since $k$ can be chosen to be arbitrarily large, we obtain that $l(M)=\infty$. 
\end{proof}

\begin{rem}
	The solvmanifold $M$ of \cref{solvmanifold inifite lenght} satisfies $\D(M)=0$. Indeed, since $M$ is aspherical and $\Gamma$ is polycyclic, we have $\D(M)\leq\rank\Zc\Gamma$. Since $\Gamma$ is isomorphic to the semi-direct product $\Z^2\rtimes_\phi\Z$, we can use \cite{daura2025IGG1} to conclude that $\Zc\Gamma$ is trivial. Consequently,  $\D(M)\leq\rank\Zc\Gamma=0$ and therefore $\D(M)=0$. 
\end{rem}

We study now the iterated length of locally symmetric spaces.

\begin{lem}\label{lenght locally symmetric spaces}
	Let $K\setminus G/\Gamma$ be a locally symmetric space where $G$ is a connected semisimple Lie group without compact factors, $K$ is a maximal compact subgroup and $\Gamma$ is a lattice. Then $l(K\setminus G/\Gamma)$ is bounded by a constant $C$ depending on $\Gamma$. 
\end{lem}

\begin{proof}
	Recall that if $\mu$ is the Haar measure of $G$ then $\vol(G/\Gamma)=\mu(F)$, where $F$ is a fundamental domain of $\Gamma$ in $G$. By \cite[11.9 Corollary]{raghunathan2012discrete}, there exists a constant $A$ such that $\vol(G/\Gamma)>A$ for all lattices of $G$. Moreover, if $\Gamma'$ is another lattice containing $\Gamma$ as a finite index subgroup then $\vol(G/\Gamma)=[\Gamma':\Gamma]\vol(G/\Gamma')$.

	Let $\mathcal{G}\acts K\setminus G/\Gamma$ be a free iterated action with $l(\mathcal{G})=l(\mathcal{G}\acts K\setminus G/\Gamma)=l$. Then $(K\setminus G/\Gamma)/\mathcal{G}\cong K\setminus G/\Gamma'$ where $\Gamma'$ is a lattice of $G$. Then $$\vol(G/\Gamma)=[\Gamma':\Gamma]\vol(G/\Gamma')=\prod_{i=1}^l|G_i|\vol(G/\Gamma')\geq 2^n A.$$

	In consequence $l\leq \log_2(\tfrac{\vol(G/\Gamma)}{A})$. The proof is finished by taking $C=\log_2(\tfrac{\vol(G/\Gamma)}{A})$.
\end{proof}

The dependence on the lattice cannot be removed. In order to give an example we need the following result:

\begin{prop}\cite[Proposition 2.3]{baker2001towers}\label{tower hyperbolic coverings}
	Let $N_0\longrightarrow N_1\longrightarrow \cdots \longrightarrow N_s$ be a tower of coverings of closed 3-manifolds. There exists a tower of coverings $M_0\longrightarrow M_1\longrightarrow \cdots \longrightarrow M_s$ of closed hyperbolic 3-manifolds and maps $f_i:M_i\longrightarrow N_i$  such that $\deg(f_i)=1$ and the covering $M_{i-1}\longrightarrow M_i$ is the pullback of $N_{i-1}\longrightarrow N_i$ by $f_i$ for all $i$.
\end{prop}

\begin{cor}\label{iterated action lenght degree 1 maps}
	Assume that we are in the setting of \cref{tower hyperbolic coverings}, $\pi_1(M_i)\trianglelefteq\pi_1(M_j)$ if and only if $\pi_1(N_i)\trianglelefteq\pi_1(N_j)$ for all $i<j$.
\end{cor}

Now, we take $N_i=M$ the solvmanifold from \cref{solvmanifold inifite lenght} for all $i$ and the covering $N_{i-1}\longrightarrow N_i$ the self-covering of \cref{solvmanifold inifite lenght}. By \cref{tower hyperbolic coverings}, for each action $\mathcal{G}_k=\{\Z/2\oplus\Z/2,\cdots \Z/2\oplus \Z/2\}\acts M$, there exists a closed hyperbolic $3$-manifold $M_{0,k}$ (which depends on $k$) such that we have a free iterated action $\mathcal{G}_k\acts M_{0,k}$. By \cref{iterated action lenght degree 1 maps}, we have $l(\mathcal{G}_k\acts M_{0,k})=k$. Since $M_{0,k}$ are hyperbolic manifolds for all $k$, the bound of \cref{lenght locally symmetric spaces} needs to depend on the lattice and not only the Lie group (in this example $\SO^+(3,1)$).

\begin{ques}
	Let $ K\setminus G/\Gamma$ be a locally symmetric space where $G$ is connected semisimple without compact factors and $\rank_\R G\geq 2$, $K$ is a maximal compact subgroup and $\Gamma$ is an irreducible lattice. Does there exist a constant $C$ only depending on $G$ such that $l(K\setminus G/\Gamma)\leq C$?
\end{ques}

The solvmanifold of \cref{solvmanifold inifite lenght} can be used to construct other closed aspherical locally homogeneous space $ K\setminus G/\Gamma$ such that $l( K\setminus G/\Gamma)=\infty$. 

\begin{prop}\label{lenght infty locally homogeneous space}
	There exists a closed aspherical locally homogeneous space $ K\setminus G/\Gamma$ such that the solvable radical of $G$ is abelian and $l( K\setminus G/\Gamma)=\infty$.
\end{prop} 

\begin{proof}
	Let $\Lambda$ be the fundamental group of a closed hyperbolic manifold of dimension $n\geq 3$ such that there exists an epimorphism $f:\Lambda\longrightarrow \Z$ and let $\phi:\Z\longrightarrow \Gl(2,\Z)$ be as in the proof of \cref{solvmanifold inifite lenght}. Then we can define $\Gamma_k=2^k(\Z^2)\rtimes_{\phi\circ f} \Lambda$. Using the Seifert construction (see \cite[Theorem 11.7.29]{lee2010seifert}) we can construct a closed aspherical locally homogeneous space with fundamental group $\Gamma_k$ for all $k$, which we denote by $M_k$. 

	The same arguments as in \cref{solvmanifold inifite lenght} show that all $\Gamma_k$ are isomorphic and since the Borel conjecture is true for lattices in connected Lie groups (see \cite{bartels2012borel,kammeyer2016farrell}) we can conclude that $M_k\cong M$ for all $k$. The inclusion $\Gamma_k\longrightarrow \Gamma_{k-1}$ induces a regular self-covering $M_{k}\longrightarrow M_{k-1}$. Finally, the tower of self-coverings $M_{k}\longrightarrow M_{k-1}\longrightarrow\cdots\longrightarrow M_0$ induces a free iterated group action $\mathcal{G}_k=\{\Z/2\oplus\Z/2,\cdots, \Z/2\oplus \Z/2\}\acts M$ such that $l(\mathcal{G}_k\acts M)=k$. Thus $l(M)=\infty$.
\end{proof}

\begin{ques}
	Let $K\setminus G/\Gamma$ be a closed aspherical locally homogeneous space where the solvable radical $R$ of $G$ is nilpotent and $G/R$ is semisimple without compact factors and $\rank_\R G/R\geq 2$. Does there exist a constant $C$ such that $l(K\setminus G/\Gamma)\leq C$?
\end{ques}



