\section{Methodology} \label{sec:methods}


\subsection{Lagged dependence matrix of filtered signals}
Consider a non-stationary MTS $\bs{Z}_{BT\times(p+q)} = (\bs{X}_{BT\times p}, \bs{Y}_{BT\times q})$. Suppose that this process is `locally stationary' so that for a block $b, (b = 1, \dots , B)$ of length $T$, the time series are approximately stationary. Let $\bs{Z}^{(b)}_{\Omega}(t) \in \mathbb{R}^{p+q}$ denote the $\bs{Z}_t$ corresponding to the $b$-th block filtered to the $\Omega$ frequency band.
We define $\bs{P}^{(b)}(\Omega, \ell)$ as the $b$-th block lagged dependence among filtered signals on $\Omega$ at lag $\ell = 0, \pm 1, \dots, \pm L$, i.e., ${P}^{(b)}_{jk}(\Omega, \ell)$ = $f(Z_{\Omega,j}(t), Z_{\Omega,k}(t+\ell))$ = $f(Z_{\Omega,j}(t-\ell), Z_{\Omega,k}(t))$, for $j,k = 1, \dots, p+q$ \citep[see][for details]{talento2024kencoh}. The function $f: \mathbb{R}^{2} \rightarrow (-1,1)$ is defined for $t \neq s = 1, \dots, T-\ell$ as
\begin{gather}
    {\tau}^{(b)}(\Omega, \ell) = \mathbb{E}[\text{sign}\{(Z^{(b)}_{\Omega}(t) - Z^{(b)}_{\Omega}(s)) (Z^{(b)}_{\Omega}(t-\ell) - Z^{(b)}_{\Omega}(s-\ell))\}], \label{ktau} \notag \\
     f(Z_{\Omega,j}(t-\ell), Z_{\Omega,k}(t)) = \sin\left(\frac{\pi}{2}{\tau}^{(b)}(\Omega, \ell)\right). \label{tsksm}
\end{gather}
We can subset the lagged dependence matrix into four sub-parts as
\begin{equation}
    \bs{P}^{(b)}(\Omega, \ell) = \begin{pmatrix}
    \bs{P}^{(b)}_{X,X}(\Omega, \ell) & \bs{P}^{(b)}_{X,Y}(\Omega, \ell) \\
    \bs{P}^{(b)}_{Y,X}(\Omega, \ell) & \bs{P}^{(b)}_{Y,Y}(\Omega, \ell)
\end{pmatrix}. \label{Pmat}
\end{equation}

These four submatrices of $\bs{P}^{(b)}(\Omega, \ell)$ are the ingredients in identifying fuzzy series. We now define spectral canonical coherence at block $b$, denoted as $R_1(b,\Omega)$. The overall measure of spectral association between $\bs{X}(t)$ and $\bs{Y}(t)$ is defined as

\begin{gather}\label{R1ab}
    R_1(b,\Omega) = \max_{\bs{u}_{b,\Omega},\bs{v}_{b,\Omega}, l} \left\{\bs{u}^\top_{b,\Omega}\bs{P}^{(b)}_{X,Y}(\Omega,\ell)\bs{v}_{b,\Omega}\right\}^2, \; \; \;\text{such that,} \\
    \bs{u}^\top_{b,\Omega}\bs{P}^{(b)}_{X,X}(\Omega,0)\bs{u}_{b,\Omega} = \bs{v}^\top_{b,\Omega}\bs{P}^{(b)}_{Y,Y}(\Omega,0)\bs{v}_{b,\Omega} = 1. \notag
\end{gather}

These $\bs{u}_{b,\Omega}$ and $\bs{v}_{b,\Omega}$ are the block-wise canonical variates \citep[see][for details]{talento2024kencoh}. These vectors show the relative contribution of the variables to the maximum association, $R_1(b,\Omega)$. This paper exploited the structure of connectivity through $\bs{u}_{b,\Omega}$ and $\bs{v}_{b,\Omega}$ to determine the clusters of multiple time series for a specific oscillation band. 

\subsection{FuzzCoh: The robust fuzzy clustering algorithm based on KenCoh}
\subsubsection{The clustering procedures}
We use the standardized canonical directions, $\bs{u}_{b,\Omega}$ and $\bs{v}_{b,\Omega}$, which are computed from the filtered signals $\bs{X}^{(b)}_{\Omega} \in \mathbb{R}^{T \times p}$ and $\bs{Y}^{(b)}_{\Omega} \in \mathbb{R}^{T \times q}$, and capture the maximum cross-dependence at a given spectral band $\Omega$, as spectral features to conduct the fuzzy clustering. 

Consider a filtered MTS dataset consisting of $B$ realizations, denoted by $\bs{Z}_{\Omega} = \{ \bs{Z}^{(1)}_{\Omega}, \dots, \bs{Z}^{(B)}_{\Omega} \}$. Also,
let $\bs{Z}^{(b)}_{\Omega}$ be the concatenation of realizations $\bs{X}^{(b)}_{\Omega} \in \mathbb{R}^{T \times p}$ and $\bs{Y}^{(b)}_{\Omega} \in \mathbb{R}^{T \times q}$, that is, 
\[
\bs{Z}^{(b)}_{\Omega} = \left( \bs{X}^{(b)}_{\Omega}, \bs{Y}^{(b)}_{\Omega} \right),
\]
for $b=1, \dots, B$.
%We assume that each block $\bs{Z}^{(b)}_{\Omega}$ is locally stationary.
Moreover, denote $\bs{d}_b^{\Omega} = ( \lvert\bs{u}_{b,\Omega}^\top\rvert, \lvert\bs{v}_{b,\Omega}^\top \rvert)^\top \in \mathbb{R}^{p+q},$ 
where \(\lvert\cdot\rvert\) is the absolute-value operator, applied element-wise to a vector. It concatenates the element-wise absolute values of the standardized canonical directions obtained at frequency band $\Omega$ and $b$-th series. We compute this for each MTS object to obtain a collection of $\{\bs{d}_b^{\Omega}\}_{b = 1}^B$, denoted as $\bs{d}^{\Omega} = \{\bs{d}_1^{\Omega},\cdots,\bs{d}_B^{\Omega}\}$.
Then we perform a fuzzy $C$-means clustering model using $\bs{d}^\Omega$, aiming to find a set of cluster centers 
$\overline{\bs{d}}^{\Omega}= \left\{\overline{\bs{d}}_{1}^{\Omega}, \dots, \overline{\bs{d}}_{C}^{\Omega}\right\}$,
and the $B\times C$ fuzzy coefficient matrix, $\bs{E}=(e_{bc}^{\Omega})$, for ${b=\{1,\cdots,B\}}$ and $c=\{1,\cdots,C\}$, by solving the minimization problem
\begin{equation}\label{fuzzy_opt}
    \left\{
\begin{aligned}
&\min_{\overline{\bs{d}}^{\Omega}, \bs{E}} \sum_{b=1}^B \sum_{c=1}^C (e_{bc}^{\Omega})^m \left\| \bs{d}_b^{\Omega} - \overline{\bs{d}}_{c}^{\Omega} \right\|^2, \\
&\text{subject to} \quad \sum_{c=1}^C e_{bc}^{\Omega} = 1, \quad e_{bc}^{\Omega} \ge 0, \quad \forall b=1,\dots,B.
\end{aligned}
\right.
\end{equation}
Here, $e_{bc}^{\Omega} \in [0,1]$ represents the membership degree of the $b$-th series to the $c$-th cluster, and $m>1$ is the fuzziness parameter controlling the degree of fuzziness of the partition.

The optimization problem in Equation \ref{fuzzy_opt} is solved via an iterative procedure. The update formula for the membership takes the form
\begin{equation}
    e_{bc}^{\Omega} = \left( \sum_{c'=1}^C \left( \frac{ \left\| \bs{d}_b^{\Omega} - \overline{\bs{d}}_{(c)}^{\Omega} \right\|^2 }{ \left\| \bs{d}_b^{\Omega} - \overline{\bs{d}}_{(c')}^{\Omega} \right\|^2 } \right)^{\frac{1}{m-1}} \right)^{-1},
\end{equation}
and for the centers, we have
\begin{equation}
   \overline{\bs{d}}_{c}^\Omega = \frac{ \sum_{b=1}^B (e_{bc}^{\Omega})^m \bs{d}_b^\Omega }{ \sum_{b=1}^B (e_{bc}^{\Omega})^m }.
\end{equation}


\subsubsection{The cluster validity index for the automatic selection of $C$ and $m$}
As stated by \cite{rhee1996validity}, if fuzzy cluster analysis is to make a significant contribution to engineering applications, greater attention must be given to the fundamental decision of determining the number of clusters in the data. In this paper, we present a cluster validity index (CVI) to help determine the optimal selection of $C$. We adopt the Fuzzy Silhouette index (FSI) \citep{rawashdeh2012crisp}, which generalizes the classical silhouette index \citep{rousseeuw1987silhouettes} to the fuzzy setting. For each MTS
object \( d_b^\Omega \), the silhouette value with respect to cluster \( c \) is computed as

\begin{equation}
s_{bc}^\Omega = \frac{n^\Omega_{bc} - a^\Omega_{bc}}{\max(a^\Omega_{bc}, n^\Omega_{bc})},
\end{equation}

where \( a_{bc} \) is the average dissimilarity between \( d_b^\Omega \) and all other objects in cluster \( c \), weighted by their membership degrees, defined as,
  \begin{equation}
  a^\Omega_{bc} = \frac{\sum_{j \neq b} (e_{jc}^\Omega)^m \cdot \lVert d_b^\Omega - d_j^\Omega \rVert}{\sum_{j \neq b} (e_{jc}^\Omega)^m},
  \end{equation}
and \( n_{bc} \) is the minimum average dissimilarity between \( d_b^\Omega \) and all objects in another cluster \( c' \ne c \), defined as,
  \begin{equation}
  n^\Omega_{bc} = \min_{c' \ne c} \left( \frac{\sum_{b=1}^B (e_{bc'}^\Omega)^m \cdot \lVert d_b^\Omega - d_j^\Omega \rVert}{\sum_{b=1}^B (e_{bc'}^\Omega)^m} \right).
  \end{equation}

The overall FSI, for a specific frequency band $\Omega$, is then given by,

\begin{equation}
\mathrm{FSI}_\Omega = \frac{1}{B} \sum_{b=1}^{B} \sum_{c=1}^{C} (e_{bc}^{\Omega})^m \cdot s^\Omega_{bc}.
\end{equation}


A higher FSI$_\Omega$ value indicates that the fuzzy memberships align well with the underlying cluster structure, reflecting compact and well-separated clusters with minimal ambiguity in membership assignments. Therefore, when no prior knowledge is available for a given dataset, we recommend performing a grid search. For example, $C\in \{2,3,\cdots,6\}$, as suggested in \cite{fclust}, and $m\in [1.2, 2.5]$  (a common range for the fuzziness parameter), and selecting the configuration that yields the highest FSI. However, as in our simulation and real data application, we focus on detecting two different brain states, i.e., drowsy and alert. Thus, we fix $C=2$ in our paper.

