\begin{document}

\title{On Fine-Grained Distinct Element Estimation}
%\date{}
\author{Ilias Diakonikolas\thanks{University of Wisconsin-Madison. E-mail:\email{ilias@cs.wisc.edu}.}
\and
Daniel M. Kane\thanks{University of California, San Diego. E-mail: \email{dakane@cs.ucsd.edu}.}
\and
Jasper C.H. Lee\thanks{University of California, Davis. E-mail: \email{jasperlee@ucdavis.edu}.}
\and
Thanasis Pittas\thanks{University of Wisconsin-Madison. E-mail: \email{pittas@wisc.edu}.}
\and
David P. Woodruff\thanks{Carnegie Mellon University. E-mail: \email{dwoodruf@andrew.cmu.edu}.}
\and
Samson Zhou\thanks{Texas A\&M University. E-mail: \email{samsonzhou@gmail.com}.}
}

\begin{titlepage}
\maketitle

\begin{abstract}
We study the problem of distributed distinct element estimation, where $\alpha$ servers each receive a subset of a universe $[n]$ and aim to compute a $(1+\varepsilon)$-approximation to the number of distinct elements using minimal communication. While prior work establishes a worst-case bound of $\Theta\left(\alpha\log n+\frac{\alpha}{\varepsilon^2}\right)$ bits, these results rely on assumptions that may not hold in practice. We introduce a new parameterization based on the number $C = \frac{\beta}{\varepsilon^2}$ of pairwise collisions, i.e., instances where the same element appears on multiple servers, and design a protocol that uses only $\mathcal{O}\left(\alpha\log n+\frac{\sqrt{\beta}}{\varepsilon^2} \log n\right)$ bits, breaking previous lower bounds when $C$ is small. We further improve our algorithm under assumptions on the number of distinct elements or collisions and provide matching lower bounds in all regimes, establishing $C$ as a tight complexity measure for the problem. Finally, we consider streaming algorithms for distinct element estimation parameterized by the number of items with frequency larger than $1$. Overall, our results offer insight into why statistical problems with known hardness results can be efficiently solved in practice. 
\end{abstract}
\end{titlepage}

\section{Introduction}
Estimating the number of distinct elements in a large dataset is a fundamental question that was first introduced by Flajolet and Martin~\cite{FlajoletM85} and has subsequently received significant attention, e.g.,~\cite{Cohen97,AlonMS99,Bar-YossefJKST02,DurandF03,RaskhodnikovaRSS09,KaneNW10,CormodeMY11,WoodruffZ12,WoodruffZ14,BravermanGLWZ18,Blasiok20,WoodruffZ21,AjtaiBJSSWZ22,BlockiGMZ23,JainKRSS23,GribelyukLWYZ24} due to both the simplicity of the question as well as its wide range of applications. 
We study the problem of distinct element estimation in a distributed setting, so that there are $\alpha$ servers that each receive a subset of the universe $[n]:=\{1,\ldots,n\}$. 
The goal is for the servers to execute a protocol that can approximate the total number of distinct elements, which is the number of coordinates $j\in[n]$ that appears in at least some server. 
The protocol should use as small of an amount of total communication as possible, where the total communication is the sum of the sizes of all messages exchanged in the protocol in the worst-case. 
To capture approximation, for a prescribed accuracy parameter $\eps\ge 0$, the goal is to output a $(1+\eps)$-approximation to the number of distinct elements. 
The problem of distinct element estimation across a distributed dataset has a large number of applications, including database design~\cite{FinkelsteinST88}, data warehousing~\cite{AcharyaGPR99,Gibbons01}, network traffic monitoring~\cite{akella2003detecting,estan2003bitmap,LiuZRBR20}, internet mapping~\cite{palmer2001connectivity}, and online analytic processing (OLAP)~\cite{ShuklaDNR96,PadmanabhanBMCH03}. 

In the context of machine learning, distributed distinct element estimation plays a crucial role in many applications where data is distributed across multiple nodes or servers. 
For instance, in collaborative filtering~\cite{ResnickISBR94}, such as recommendation systems~\cite{Aggarwal16,KorenBV09}, estimating the distinct preferences or behaviors of users across various platforms requires efficient distributed algorithms. 
Similarly, in anomaly detection~\cite{ChandolaBK09}, identifying rare or novel events across different data sources—such as network traffic or sensor data—requires tracking unique occurrences without centralized data aggregation. 
Distributed distinct element estimation is also relevant in federated learning~\cite{McMahanMRHA17}, where machine learning models are trained across decentralized devices while keeping data local. 
Estimating the number of distinct features or labels across distributed devices is essential for improving training efficiency. 
In large-scale graph analysis~\cite{MalewiczABDHLC10,GonzalezXDCFS14}, where nodes or edges are distributed across servers, this problem helps in tasks like counting distinct subgraphs or community structures. 
Additionally, in streaming data applications~\cite{MankuM02}, such as real-time monitoring or natural language processing, estimating the diversity of items in large data streams is essential for efficient data summarization and decision-making. 

\cite{KaneNW10,Blasiok20} gave a one-pass streaming algorithm for achieving a $(1+\eps)$-approximation to the number of distinct elements on a dataset from a universe of size $[n]$, using $\O{\frac{1}{\eps^2}+\log n}$ bits of space. 
This can be transformed into a distributed protocol across $\alpha$ servers that uses $\O{\frac{\alpha}{\eps^2}+\alpha\log n}$ bits of communication, since each server can locally simulate the streaming algorithm on their dataset and then pass the state of the algorithm to the next server. 
On the lower bound side, \cite{CormodeMY11} showed that distributed distinct element estimation requires $\Omega(\alpha)$ communication, while \cite{ArackaparambilBC09,ChakrabartiR12} showed a lower bound of $\Omega\left(\frac{1}{\eps^2}\right)$. 
These lower bounds were then subsequently strengthened by \cite{WoodruffZ12} and finally \cite{WoodruffZ14} for all parameter regimes to $\Omega\left(\frac{\alpha}{\eps^2}+\alpha\log n\right)$, seemingly resolving the problem by showing that the protocol of \cite{KaneNW10,Blasiok20} is optimal. 

However, the lower bound instance of \cite{WoodruffZ14} requires a constant fraction of coordinates to appear across a constant fraction of servers, which may be unrealistic in many applications. 
For example, in traffic network monitoring, suppose each server oversees a flow of communication, corresponding to messages from individuals, so that the coordinates of the universe would correspond to IP addresses of the senders of the messages. 
Then the lower bound instance of \cite{WoodruffZ14} would require that a constant fraction of IP addresses send messages to a constant fraction of the servers, i.e., it requires a constant fraction of all senders to be high volume. 
In reality, previous studies have shown that internet traffic patterns~\cite{adamic2002zipf} often follow a Zipfian distribution, i.e., a polynomial decay law, c.f., \defref{def:zipf}. 

More generally, it has long been observed that many large datasets across other domains follow a Zipfian distribution. 
For example, the distribution of words in a natural language~\cite{zipf2013psycho}, e.g., user passwords~\cite{WangW16,WangCWHJ17,BlockiHZ18,HouW23}, the distribution of degrees in the internet graph~\cite{KleinbergKRRT99}, and the distribution of population sizes~\cite{gabaix1999zipf,rhodes23talk} have all been commonly observed to follow a Zipfian distribution. 
Indeed, \cite{Mitzenmacher03} claims that ``power law distributions are now pervasive in computer science''.
Thus it seems natural to ask
\begin{quote}
\emph{Does the distributed distinct element estimation problem still require $\Omega\left(\frac{\alpha}{\eps^2}+\alpha\log n\right)$ communication across more ``realistic'' distributions?}
\end{quote}

\subsection{Our Contributions}
In this paper, we give a resounding negative answer to the above question, translating to positive algorithmic results that break previous impossibility barriers. 
We introduce a novel parameterization of the distributed distinct element estimation problem, showing that although previous upper and lower bounds show optimality for the worst-case input, these hardness of approximation results do not necessarily apply across various regimes of our parameterization. 
Namely, we show that the complexity of the problem can be characterized by the number of \emph{pairwise collisions} in the dataset. 
Formally, for vectors $v^{(1)},\ldots,v^{(\alpha)}\in\{0,1\}^n$, we define the number of pairwise collisions to be the number of ordered triplets $(a,b,i)$ such that $1\le a<b\le\alpha$, $i\in[n]$, and $v^{(a)}_i=v^{(b)}_i=1$. 
We remark that the assumption that the vectors $v^{(i)}$ are binary is without loss of generality, as it turns out the resulting protocols and reductions will behave the same regardless of whether a server has a single instance or multiple instances of a coordinate. 
Nevertheless for the sake of completeness, for vectors $v^{(1)},\ldots,v^{(\alpha)}\in\{0,1,\ldots,m\}^n$, we define the number of pairwise collisions to be the number of ordered triplets $(a,b,i)$ such that $1\le a<b\le\alpha$, $i\in[n]$, and $v^{(a)}_i\ge 1$ and $v^{(b)}_i\ge 1$. 

We first show a general protocol for the distributed distinct element estimation problem across general ranges of $F_0(S)$, the number of distinct elements in the dataset $S$ that is the union of all items given to all servers. 
\begin{restatable}{theorem}{thmhighcollsub}
\thmlab{thm:high:colls:ub}
Given a dataset $S$ on a universe of size $n$ with $C=\beta\cdot\O{\min\left(F_0(S), \frac{1}{\eps^2}\right)}$ pairwise collisions for a parameter $\beta\ge 1$, distributed across $\alpha$ players, there exists a protocol that computes a $(1+\eps)$-approximation to $F_0(S)$ with probability at least $\frac{2}{3}$ that uses 
\[\O{\alpha\log n}+\O{\min\left(F_0(S), \frac{1}{\eps^2}\right)}\cdot\sqrt{\beta}\log n\]
bits of communication. 
\end{restatable}
\thmref{thm:high:colls:ub} shows that the $\Omega\left(\frac{\alpha}{\eps^2}\right)$ lower bound of \cite{WoodruffZ14} need not apply when the number of pairwise collisions is in the range of $o(\alpha^2\cdot F_0(S))$. 
That is, the lower bound of \cite{WoodruffZ14} only applies when there is a constant fraction of coordinates that appear across a constant fraction of servers.

In the case where the number of pairwise collisions is less than the number of distinct elements, e.g., $C<F_0(S)$, we can further improve the guarantees of our protocol as follows:
\begin{restatable}{theorem}{thmlowcollsub}
\thmlab{thm:low:colls:ub}
Given a dataset $S$ on a universe of size $n$ with the promise that there are at most $C\le F_0(S)$ pairwise collisions, distributed across $\alpha$ players, there exists a protocol that uses total communication 
\[\tO{\alpha\log n+\max\left(\frac{1}{F_0(S)},\eps^2\right)\cdot\frac{C}{\eps^2}\log n}\]
bits, and with probability at least $\frac{2}{3}$, outputs a $(1+\eps)$-approximation to $F_0(S)$. 
\end{restatable}

While ascertaining the number of pairwise collisions itself may be a difficult challenge and possibly lead to a chicken-and-egg problem, we remark that computing a loose upper bound $C$ on the number of collisions can be performed much easier, particularly given distributional or other a priori side information about the number of collisions. 
For example, additional knowledge about the number of collisions can be collected using previous datasets from a similar source, in a similar vein to the auxiliary input that is often utilized by learning-augmented algorithms~\cite{Mitzenmacher18,Balcan20,MitzenmacherV20}. 
We also remark that the number of pairwise collisions is an important statistic in other problems, such as uniformity testing~\cite{DiakonikolasKS18,FischerMO18,AcharyaCT19,MeirMO19} and closeness testing~\cite{DiakonikolasGPP19}. 

We remark that for the case when the number of servers for each item follows a Zipfian distribution across the $\alpha$ servers, then the total number of pairwise collisions is $C=\O{\alpha}\cdot F_0(S)$, provided that the Zipfian exponent is a constant larger than $1$. 
On the other hand, the number of distinct elements can be substantially larger than $\frac{1}{\eps^2}$, where $\eps$ is the desired accuracy for the output estimate for the number of distinct elements. 
Our results indicate that in this regime, only $\tO{\alpha\log n}$ bits of communication suffice, which bypasses the known $\Omega\left(\frac{\alpha}{\eps^2} +\alpha\log n\right)$ lower bounds. 
In particular, if the number of distinct elements is $\O{n}$ and $\eps$ is around $\frac{1}{\sqrt{n}}$, then the lower bounds indicate $\Omega(n)$ communication is necessary, which is substantially worse than our protocol that achieves $\tO{\alpha\log n}$ communication. 

We complement \thmref{thm:high:colls:ub} and \thmref{thm:low:colls:ub} with a pair of lower bounds matching in $\beta$ and $\frac{1}{\eps}$:

\begin{restatable}{theorem}{thmlbmanycolls}
\thmlab{thm:lb:many:colls}
Let $\beta\in[1,\alpha^2]$. 
Given a dataset $S$ with $C=\Omega(\beta\cdot F_0(S))$ pairwise collisions, distributed across $\alpha$ players, any protocol that computes a $(1+\eps)$-approximation to $F_0(S)$ with probability at least $\frac{2}{3}$ uses $\sqrt{\beta}\cdot\Omega\left(\min\left(F_0(S),\frac{1}{\eps^2}\right)\right)$ communication.
\end{restatable}
\begin{restatable}{theorem}{thmlowcollslb}
\thmlab{thm:low:colls:lb}
Given a dataset $S$ with the promise that there are at most $C\in[\eps\cdot F_0(S),F_0(S)]$ pairwise collisions distributed across $\alpha$ players, any protocol that computes a $(1+\eps)$-approximation to $F_0(S)$ with probability at least $\frac{2}{3}$ uses $\Omega\left(\frac{C}{\eps^2\cdot F_0(S)}\right)$ communication.  
\end{restatable}
We remark that \thmref{thm:lb:many:colls} follows immediately as a parameterization of a lower bound from~\cite{WoodruffZ14}, while \thmref{thm:low:colls:lb} is perhaps our most technically involved contribution. 
We recall that well-known results, e.g.,~\cite{CormodeMY11} additionally show that regardless of the number of pairwise collisions and regardless of $F_0(S)$, any protocol that estimates $F_0(S)$ to a constant factor requires $\Omega(\alpha)$ communication. 
Thus, \thmref{thm:lb:many:colls} and \thmref{thm:low:colls:lb} together imply the lower bound results in \tableref{table:summary}. 

Moreover, we remark that for the regime where $C<\eps\cdot F_0(S)$, then $F_1(S)=\sum_{i\in[\alpha]}\|v^{(i)}\|_1$ becomes an additive $\eps\cdot F_0(S)$ approximation to $F_0(S)$, and so the players can use $\O{\alpha\log n}$ bits of communication to deterministically compute a $(1+\eps)$-multiplicative approximation to $F_0(S)$. 

Our results can be viewed as a first step toward analyzing standard statistical problems with known lower bounds, e.g.,~\cite{WoodruffZ12,WoodruffZ14} through the lens of parameterized complexity. 
Thus our work makes important progress toward a better understanding of natural parameters that explain why these problems are not challenging in practice. 
We summarize our results for the distributed distinct elements estimation problem in \tableref{table:summary}. 

\begin{table*}[!htb]
\centering
\begin{tabular}{|c|c|c|}\hline
\multirow{2}{*}{} & \multicolumn{2}{|c|}{$C=\beta\cdot F_0(S)$, $\beta\ge1$} \\\cline{2-3}
& $F_0(S)<\frac{1}{\eps^2}$ & $F_0(S)\ge\frac{1}{\eps^2}$ \\\hline
\thmref{thm:high:colls:ub} & $\O{\alpha\log n+\sqrt{\beta}\cdot F_0(S)\cdot \log n}$ & $\O{\alpha\log n+\frac{\sqrt{\beta}}{\eps^2}\log n}$ \\\hline
\thmref{thm:lb:many:colls} & $\Omega(\alpha+\sqrt{\beta}\cdot F_0(S))$ & $\Omega\left(\alpha+\frac{\sqrt{\beta}}{\eps^2}\right)$ \\\hline
& \multicolumn{2}{|c|}{$C=\beta\cdot F_0(S)$, $\beta<1$, $C>\eps\cdot F_0(S)$}\\\cline{2-3}
& $F_0(S)<\frac{1}{\eps^2}$ & $F_0(S)\ge\frac{1}{\eps^2}$ \\\hline
\thmref{thm:low:colls:ub} & $\O{\alpha\log n+\frac{\beta}{\eps^2}\log n}$ & $\O{\alpha\log n+\beta\cdot F_0(S)\cdot\log n}$ \\\hline
\thmref{thm:low:colls:lb} & $\Omega\left(\alpha+\frac{\beta}{\eps^2}\right)$ & $\Omega(\alpha+\beta\cdot F_0(S))$ \\\hline
\end{tabular}
\caption{A summary of our results for the distributed distinct elements estimation problem on a universe of size $n$ across $\alpha$ servers, parameterized by the number $C$ of collisions across the $\alpha$ servers, and the accuracy parameter $\eps\in(0,1)$.}
\tablelab{table:summary}
\end{table*}

In proving \thmref{thm:low:colls:lb}, we first show the hardness of approximation for the closely related distributed duplication detection problem, in which the goal is for the $\alpha$ servers to approximate the total number of duplicates, where a duplicate is defined to be a coordinate $j\in[n]$ that appears on at least two distinct servers. 
For discussion on the applications of the distributed duplication detection problem, see \appref{sec:duplicates}. 
\begin{theorem}
\thmlab{thm:main}
Let $C$ be an input parameter for the number of duplicates and $\eps\in(0,1)$ be an accuracy parameter.  
Suppose there are $\alpha$ players, each receiving a set of at most $s$ items from a universe of size $N=\Omega(s)$. 
Then any protocol $\Pi$ that with probability at least $\frac{2}{3}$, identifies whether there are fewer than $(1-\eps)\cdot C$ duplicates or more than $(1+\eps)\cdot C$ duplicates requires $\Omega(\alpha s)$ communication for $C<\frac{4}{\eps^2}$ and $\Omega\left(\frac{\alpha s}{C\eps^2}\right)$ communication for $C\ge\frac{4}{\eps^2}$. 
\end{theorem}

We remark that for $\eps=0$, the lower bound of $\Omega(\alpha s)$ follows via a simple reduction from previous work on non-promise set disjointness in the coordinator model~\cite{BravermanEOPV13}. 
Thus, the main contribution in \thmref{thm:main} is to show that even the problem of approximating the number of duplicates requires a substantial amount of total communication. 
We also give a simple protocol that uses $\O{\frac{\alpha s\log\alpha}{C\eps^2}}$ bits of communication, showing that \thmref{thm:main} is near-optimal. 

Further, we remark that given \thmref{thm:low:colls:ub}, a natural question would be to ask whether the promise of the upper bound on $C$ must be known in advance in order to achieve improved communication bounds, perhaps through a preliminary subroutine to estimate $C$. 
However, \thmref{thm:main} shows that in general, one cannot estimate $C$ using ``small'' total communication when $C$ is small. 

Finally, we complement our theoretical results with a number of empirical evaluations in \secref{sec:exp}. 
We show that the standard CAIDA dataset, often used to analyze statistics on virtual traffic networks, is surprisingly skewed, allowing our algorithm to outperform the previous worst-case theoretical bounds by several orders of magnitude. 
While this may be an extreme case, it demonstrates that our algorithm can achieve significantly better performance in practice, aligning with our theoretical guarantees and serving as a proof-of-concept that illustrates the accuracy-vs-communication tradeoffs in real-world scenarios.

%\textbf{Paper organization.}
\paragraph{Paper organization.}
The remainder of this paper is structured as follows. 
In \secref{sec:ddee:lb}, we present a parameterized lower bounds for the distributed distinct element estimation problem, assuming the communication complexity of the so-called $\GapSet$ problem. 
We then show a corresponding upper bound in \secref{sec:ddee:ub}. 
We defer the proof of the $\GapSet$ problem to \appref{sec:new:game:lb} and \appref{sec:duplicates}. 
We provide our experimental results in \secref{sec:exp}. 
Finally, we show in \appref{app} that both distinct element estimation and norm estimation can similarly be parameterized in the streaming model. 

\subsection{Preliminaries}
\seclab{sec:prelims}
For a positive integer $n>0$, we use the notation $[n]$ to represent the set $\{1,2,\ldots,n\}$. 
We use $\polylog(n)$ to denote a fixed polynomial in $\log n$. 

For a vector $v\in\mathbb{R}^n$, we define $F_0(v)=|\{i\in[n]\,\mid\,v_i\neq 0\}|$ and $F_1(v)=|v_1|+\ldots+|v_n|$. 
For a random variable $X$, we use $\Ex{X}$ to denote its expectation and $\Var{X}$ to denote its variance. 

\begin{definition}[Zipfian distribution dataset]
\deflab{def:zipf}
We say a sequence $X=\{x_1,\ldots,x_n\}$ follows a Zipfian distribution with exponent $s$ if there exist parameters $C_1,C_2>0$ such that for any index $i$, we have $\frac{C_1}{i^s} \le x_i \le \frac{C_2}{i^s}$. 
\end{definition}

Recall the following definition of the squared Hellinger distance. 
\begin{definition}[Squared Hellinger distance]
For two distributions $P$ and $Q$ with probability density functions $f$ and $g$, respectively, defined on a space $X$, their squared Hellinger distance is defined by
\[h^2(P,Q)=\frac{1}{2}\int_X\left(\sqrt{f(x)}-\sqrt{g(x)}\right)^2\,dx\]
\end{definition}
It can be shown, c.f., \lemref{lem:inf:hellinger} in \secref{sec:new:game:lb}, that the squared Hellinger distance between a function on two random variables is a lower bound on informally the mutual information between one of the random variables and the corresponding value of the function on that random variable. 

\paragraph{Communication complexity.}
We now recall some preliminaries from communication and information complexity. 

\begin{definition}[Entropy, conditional entropy, mutual information]
Given a pair of random variables $X$ and $Y$ with joint distribution $p(x,y)$ and marginal distributions $p(x)$ and $p(y)$, the \emph{entropy} of $X$ is defined as $H(X):=-\sum_x p(x)\log p(x)$. 
The \emph{conditional entropy} is $H(X|Y):=-\sum_{x,y} p(x,y)\log\frac{p(y)}{p(x,y)}$. 
The \emph{mutual information} is 
\[I(X;Y):=H(X)-H(X|Y)=\sum_{x,y}p(x,y)\log\frac{p(x,y)}{p(x)p(y)}.\] 
\end{definition}

\begin{definition}[Information cost]
Let $\Pi$ be a randomized protocol that produces a (possibly random) transcript $\Pi(X_1,\ldots,X_T)$ on inputs $X_1,\ldots,X_T$ drawn from a distribution $\mu$. 
The \emph{information cost} of $\Pi$ with respect to $\mu$ is $I(P_1,\ldots,P_T;\Pi(P_1,\ldots,P_T))$.  
\end{definition}

\begin{fact}[Information cost to communication complexity]
\factlab{fact:ic:cc}
For any distribution $\mu$ and failure probability $\delta\in(0,1)$, the communication cost of any randomized protocol for $\mu$ on a problem $f$ that fails with probability $\delta$ is at least the information cost of $f$ under distribution $\mu$ and failure probability $\delta$. 
\end{fact}

\begin{definition}[Conditional information cost]
Let $\Pi$ be a protocol on $((\bx,\by),R)\sim\eta$ for $\bx\sim X$ and $\by\sim Y$, where $\eta$ is a mixture of product distributions on $X^n\times Y^n\times\calR$ and $R\sim\calR$ is a source of randomness. 
Then we define the conditional information cost of $\Pi$ with respect to $\eta$ by $I(\bx,\by;\Pi(\bx,\by)|R)$. 
\end{definition}

\begin{definition}[Conditional information complexity]
Given a failure probability $\delta\in(0,1)$ and a mixture $\eta$ of product distributions, we define the conditional information complexity of $f$ with respect to $\eta$ as the minimum conditional information cost of a protocol for $f$ with failure probability at most $\delta$, with respect to $\eta$, i.e.,
\[\CIC_{\eta,\delta}(f)=\min_{\Pi}I(\bx,\by;\Pi(\bx,\by)|R),\]
where the minimum is taken over all protocols $\Pi$ with failure probability at most $\delta$ on the distribution $\eta$. 
\end{definition}

\begin{lemma}[Proposition 4.6 in~\cite{Bar-YossefJKS04}]
\lemlab{lem:cic:ic}
Let $\mu$ be a distribution on $X^n\times Y^n\times$. 
If $\eta$ is a mixture of product distributions on $X^n\times Y^n\times\calR$ such that the marginal distribution on $X^n\times Y^n$ is $\mu$, then the information cost of a function $f$ with success probability $1-\delta$ on $\mu$ is at least $\CIC_{\eta,\delta}(f)$. 
\end{lemma}

\begin{fact}[Chain rule]
\label{fact:chain}
Given discrete random variables $X,Y,Z$, then
\[I(X,Y;Z) = I(X;Z) + I(X;Y|Z).\]
\end{fact}

\begin{fact}[Maximum likelihood estimation principle]
\label{fact:err}
Let $X\in\mathcal{X}$ and $Y\in\mathcal{Y}$ be randomly selected from some underlying distribution $\mu$. 
Then there exists a deterministic function $g:Y\to X$ with error $\delta\le 1-\frac{1}{2^{H(X|Y)}}$.
\end{fact}

\begin{definition}
For a vector $\by\in X^n$, let $j\in[n]$ and $x\in X$. 
We define $\embed(\by,j,x)$ to be the $n$-dimensional vector $\by$ with its $j$-th coordinate replaced by $x$, i.e., for $\bz=\embed(\by,j,x)$, we have $z_i=y_i$ for $i\neq j$ and $z_j=x$. 
\end{definition}

\begin{definition}[Decomposable function]
Let $f:X^n\to\{0,1\}$ be a function. 
Then we say $f$ is $g$-decomposable with primitive $h$ if there exist functions $g:\{0,1\}^n\to\{0,1\}$ and $h:X\to\{0,1\}$ such that $f(\bx,\by)=g(h(x_1,y_1),\ldots,h(x_n,y_n))$. 
\end{definition}

\begin{definition}[Collapsing distribution]
Let $f:X^n\to\{0,1\}$ be $g$-decomposable with primitive $h$. 
We say that $(\bw,\bz)\in X^n$ is a collapsing input for $f$ if for every $j\in[n]$ and $x,y\in X$, we have $f(\embed(\bw,j,x),\embed(\bz,j,y))=h(x,y)$. 
We call a distribution $\mu$ on $X^n$ a collapsing distribution for $f$ if every $(\bw,\bz)$ in the support of $\mu$ is a collapsing input. 
\end{definition}

\begin{theorem}[Direct sum, Theorem 5.6 in~\cite{Bar-YossefJKS04}]
\thmlab{thm:direct:sum}
Let $f:X^n\to\{0,1\}$ be a decomposable function with primitive $h$ and let $\zeta$ be a mixture of product distributions on $X\times\calD$. 
Let $\eta=\zeta^n$ and $((\bx,\by),\bD)\sim\eta$. 
Then if the distribution of $(\bx,\by)$ is a collapsing distribution for $f$, we have $\CIC_{n,\delta}(f)\ge n\cdot\CIC_{\zeta,\delta}(h)$. 
\end{theorem}

