We show that any protocol for $\GapSet_{n,k}$ with constant $k$ requires $\Omega(n)$ communication. 
To that end, we first recall the following structural properties from \cite{Bar-YossefJKS04}:

\begin{lemma}[Lemma 6.2 in~\cite{Bar-YossefJKS04}]
\lemlab{lem:inf:hellinger}
Let $f(X)$ and $f(Y)$ be two random variables and let $Z$ be a random variable with uniform distribution in $\{X,Y\}$. 
If $Z$ is independent of both $f(X)$ and $f(Y)$, then $I(Z;f(Z))\ge h^2(f_X,f_Y)$, where $f_X$ denotes the distribution of $f$ on $X$. 
\end{lemma}

\begin{lemma}[Cut-and-Paste, e.g., Lemma 6.3 in~\cite{Bar-YossefJKS04}]
\lemlab{lem:hellnger:cut:paste}
Let $\Pi$ be a randomized protocol, $x,x'\in X$, and $y,y'\in Y$ for some domains $X,Y$. 
Then $h(\Pi_{xy},\Pi_{x'y'})=h(\Pi_{xy'},\Pi_{x'y})$.
\end{lemma}

\begin{lemma}[Pythagorean Lemma, e.g., Lemma 6.4 in~\cite{Bar-YossefJKS04}]
\lemlab{lem:hellinger:pyth}
Let $\Pi$ be a randomized protocol, $x,x'\in X$, and $y,y'\in Y$ for some domains $X,Y$. 
Then $h^2(\Pi_{xy},\Pi_{x'y})+h^2(\Pi_{xy'},\Pi_{x'y'})\le2h^2(\Pi_{xy},\Pi_{x'y'})$.
\end{lemma}

\begin{lemma}[Lemma 6.5 in~\cite{Bar-YossefJKS04}]
\lemlab{lem:hellinger:proto:lb}
Let $\Pi$ be a randomized protocol with failure probability $\delta\in(0,1)$ for a function $f$. 
Then for any two input pairs $(x,y)$ and $(x',y')$ with $f(x,y)\neq f(x',y')$, we have $h^2(\Pi_{xy},\Pi_{x'y'})\ge1-2\sqrt{\delta}$.
\end{lemma}

\begin{lemma}
\lemlab{lem:hellinger:zero:one}
Let $\alpha\ge 2$ be an integer and let $k\in[\alpha]$. 
Let $\Pi$ be a randomized $\alpha$-party communication protocol with inputs from $\{0,1\}^\alpha$ for determining whether exactly $\ell$ coordinates are one and let $\pi:[\alpha]\to[\alpha]$ be any permutation. 
Then,
\[\sum_{i=1}^\alpha h^2(\Pi_{0^\alpha},\Pi_{\mathbf{e}_{i}})\ge\frac{1}{2k}\sum_{j=1}^{\flr{\alpha/k}} h^2(\Pi_{0^\alpha},\Pi_{I_j}),\]
where $I_j=\left[\frac{\alpha(j-1)}{2k}+1,\frac{\alpha j}{2k}\right]$. 
\end{lemma}
\begin{proof}
Similar to the proof of Lemma 7.2 in \cite{Bar-YossefJKS04}, we prove the claim by using an induction argument on a tree. 
Let $\alpha'$ be the smallest power of two such that $\alpha\le\alpha'$ and let $\phi$ be any mapping that extends a permutation $\pi:[\alpha]\to[\alpha]$ in the natural way to $\alpha'$ coordinates, i.e., $\phi(i)=\pi(i)$ for $i\in[\alpha]$ and $\phi(i)=i$ for $i\in(\alpha,\alpha']$. 
Let $T$ be a complete binary tree of height $\log(\alpha')$ with leaves labeled from $\phi(1)$ to $\phi(\alpha')$ and internal nodes labeled with the leaves in their corresponding rooted subtrees. 

For $a,b\in[\alpha]$ with $b-a+1=k$, let $c=\left\lfloor\frac{a+b}{2}\right\rfloor$. 
Let $u=\mathbf{e}_{\pi([a,b])}$, $v=\mathbf{e}_{\pi([a,c])}$, and $w=\mathbf{e}_{\pi([c+1,b])}$. 
By an analogue of \lemref{lem:hellnger:cut:paste} for $\alpha'$-player communication games, we have that
\[h(\Pi_{0^{\alpha'}},\Pi_{u})=h(\Pi_{v},\Pi_{w}).\]
On the other hand, since the last $\alpha'-\alpha$ input coordinates are known by all players, we have
\[h(\Pi_{0^\alpha},\Pi_{u})=h(\Pi_{v},\Pi_{w}).\]
By the triangle inequality,
\[h(\Pi_{0^\alpha},\Pi_{v})+h(\Pi_{0^\alpha},\Pi_{w})\ge h(\Pi_{v},\Pi_{w}).\]
Thus by the Cauchy-Schwarz inequality,
\[h^2(\Pi_{v},\Pi_{w})\le 2(h^2(\Pi_{0^\alpha},\Pi_{v})+h^2(\Pi_{0^\alpha},\Pi_{w})).\]
Then by induction,
\[2(b-a+1)\sum_{i=a}^b h^2(\Pi_{0^\alpha},\Pi_{\mathbf{e}_{i}})\ge h^2(\Pi_{0^\alpha},\Pi_{\mathbf{e}_{[a,b]}}).\]
For $k=b-a+1$, we can split the interval $[0,\alpha]$ into at least $\flr{\frac{\alpha}{k}}$ disjoint intervals of length $k$. 
Therefore,
\[\sum_{i=1}^\alpha h^2(\Pi_{0^\alpha},\Pi_{\mathbf{e}_{i}})\ge\frac{1}{2k}\sum_{j=1}^{\flr{\alpha/k}} h^2(\Pi_{0^\alpha},\Pi_{I_j}),\]
where $I_j=\left[\frac{\alpha(j-1)}{2k}+1,\frac{\alpha j}{2k}\right]$. 
\end{proof}

We now show that any protocol for $\GapSet_{n,k}$ requires $\Omega(n)$ communication for constant $k>0$. 
\begin{restatable}{lemma}{lemicostsetdisj}
\lemlab{lem:icost:setdisj}
The conditional information cost of any algorithm for $\SetDisj_{n,k}$ that succeeds with probability $\frac{1}{2}+\Omega(1)$ is $\Omega(n)$. 
\end{restatable}
\begin{proof}
We first use the direct sum paradigm by defining the NO distribution $\zeta$ for the single coordinate $\SetWt_{n,k}$ problem, which implicitly forms the NO distribution $\mu_0$ for $\SetDisj_{n,k}$. 
We use a random variable $Q\in[\alpha]$ chosen uniformly at random, so that conditioned on the value of $Q=i\in[\alpha]$, we have that $\mathbf{u}$ is chosen from $\{0^\alpha, \mathbf{e}_i\}$ uniformly at random, implicitly defining the distribution $\zeta$.  
Then $\zeta^n$ is the collapsing distribution that matches the distribution of $\mu_0$ and so by \thmref{thm:direct:sum}, it suffices to show that the conditional information cost of $\Pi$ with respect to $\zeta$ is $\Omega(1)$. 

To that end, we have
\[I(\Pi(\mathbf{u}); \mathbf{u}|Q)=\frac{1}{\alpha}\sum_{i=1}^\alpha I(\Pi(\mathbf{u}); \mathbf{u}|Q=i).\]
By \lemref{lem:inf:hellinger} and \lemref{lem:hellinger:zero:one}
\begin{align*}
I(\Pi(\mathbf{u}); \mathbf{u}|Q)&\ge\frac{1}{\alpha}\sum_{i=1}^\alpha h^2(\Pi_{0^\alpha},\Pi_{\mathbf{e}_i})\\
&\ge\frac{1}{2\alpha} \sum_{j=1}^{{\flr{\alpha/k}}} h^2(\Pi_{0^\alpha},\Pi_{\mathbf{e}_{2j-1}+\mathbf{e}_{2j}}),
\end{align*}
By the correctness of the protocol on $\mu$ and \lemref{lem:hellinger:proto:lb}, we have that $I(\Pi(\mathbf{u}); \mathbf{u}|Q)=\Omega(1)$. 
Hence, the conditional information cost of any algorithm for $\SetDisj_{n,k}$ that succeeds with probability $\frac{1}{2}+\Omega(1)$ under the mixture distribution $\mu=\frac{1}{2}\mu_0+\frac{1}{2}\mu_1$ is $\Omega(n)$. 
\end{proof}

We now define the composition communication problem $\GapSet$. 
\begin{definition}[$\GapSet$]
In $\GapSet_{t,\alpha,n,k}$, the distribution $\phi$ for the GapSet problem over $t$ blocks each with $n$ coordinates and $k$ collisions for $\alpha$ players is defined as follows. 
The $\alpha$ players receive input vectors $\bu^{(1)},\ldots,\bu^{(\alpha)}\in\{0,1\}^{nt}$ such that the $i$-th player receives vector $\bu^{(i)}$, for all $i\in[\alpha]$. 
Let $\beta=\flr{\frac{\alpha}{2}}$ and $\ell=\flr{\frac{k}{2}}$. 
The input is generated by first drawing $\bx,\by\in\{0,1\}^t$ from $\GapAnd_t$ and creating input vectors $\{\bu^{(i,j)}\}_{i\in[\alpha], j\in[t]}$. 
\begin{itemize}
\item
For each $j\in[t]$, a special coordinate $Z_j\in[n]$ is selected uniformly at random. 
\begin{itemize}
\item
If $x_j=1$, then the coordinate $Z_j$ is given to $\ell$ random players, i.e., the protocol selects $\ell$ indices that are at most $\beta$, i.e., $i_{j_1},\ldots,i_{j_\ell}\le\beta$, and sets $u^{(i_{j_1},j)}_{Z_j}=\ldots=u^{(i_{j_\ell},j)}_{Z_j}=1$. 
\item
If $y_j=1$, then the coordinate $Z_j$ is given to $k-\ell$ random players, i.e., the protocol selects $k-\ell$ indices that are at least $\beta+1$, i.e., $i_{j_{\ell+1}},\ldots,i_{j_k}\ge\beta+1$, and sets $u^{(i_{j_{\ell+1}},j)}_{Z_j}=\ldots=u^{(i_{j_k},j)}_{Z_j}=1$. 
\end{itemize}
\item
For all coordinates $w\in[n]$ with $w\neq Z_j$, with probability $\frac{1}{2}$, the protocol assigns $w$ to a random player $w_j\in[\alpha]$, i.e., it sets $u^{(w_j,j)}_w=1$. 
\end{itemize}
Each vector $\bu^{(j)}=\bu^{(1,j)}\circ\bu^{(2,j)}\circ\ldots\circ\bu^{(\alpha,j)}$ and the $\alpha$ players' goal to determine whether the input falls into the cases:
\begin{itemize}
\item
In the YES case, the input is generated from vectors $\bx,\by\in\{0,1\}^t$ that are in the YES case for $\GapAnd_t$. 
\item
In the NO case, the input is generated from vectors $\bx,\by\in\{0,1\}^t$ that are in the NO case for $\GapAnd_t$. 
\item
Otherwise if the input is generated from vectors $\bx,\by\in\{0,1\}^t$ that are neither in the YES or NO cases for $\GapAnd_t$, then the $\alpha$ players' output may be arbitrary. 
\end{itemize}
\end{definition}
See \figref{fig:gap:set} for examples of possible inputs to $\GapSet$.

