    \caption{Variation of the scaling function $\mathcal{F}(u,N)$ as in \eref{Fu_exact.1} with respect to $u$ for different choices of $N$. The markers represents the results from numerical simulation which match perfectly with the theoretical curves indicated by the solid lines.}
    \label{tvsu}
\end{figure}


\section{Derivation of the closed form for the scaling function $\mathcal{F}(u,N)$ for $N=2$ as in Eq. (9)}
Here we derive the scaling function (or the scaled MFPT) for $N=2$ ballistic searchers i.e. $\mathcal{F}(u,2)$. It is convenient to make the change of variable $t=1/x$ and re-write the scaling function (Eq.  (8) of the main text or \eref{Fu_exact.1}) as
\begin{equation}
{\cal F}(u,N)=\frac{2}{N\, u^2}\, \frac{I_N(u)}{J_N(u)}\, ,
\label{Fu_exact.2}
\end{equation}
where $I_N(u)$ and $J_N(u)$ are given by
\begin{eqnarray}
I_N(u)&= & \int_0^{\infty} \frac{dx}{x^2}\, 
\left[1- \frac{1}{2}\, e^{-u\, x}-\frac{1}{2}\, e^{-(1-u)x}\right]^{N} \label{Inu.1} \\
J_N(u) &=& 
\int_0^{\infty} dx\, e^{-u\, x}\, \left[1- \frac{1}{2}\, 
e^{-u\, x}-\frac{1}{2}\, e^{-(1-u)x}\right]^{N-1}\, .
\label{Jnu.1}
\end{eqnarray}
For general $N\ge 2$, it is not easy to compute the two integrals $I_N(u)$ and $J_N(u)$, and
hence ${\cal F}(u,N)$ in Eq. (\ref{Fu_exact.2}). However for $N=2$, as we show below,
one can compute ${\cal F}(u,2)$ exactly for all $u\in [0,1]$. 
This will serve also as a benchmark to compare
to the asymptotic behaviors of ${\cal F}(u,N)$ for general $N$ in the
two asymptotic limits $u\to 0$ and $u\to 1$.

For $N=2$, let us start with the integral $J_2(u)$ in Eq. (\ref{Jnu.1}) which is relatively
simpler to evaluate. Setting $N=2$ in Eq. (\ref{Jnu.1}) we get
\begin{equation}
J_2(u)=\int_0^{\infty} dx\, e^{-ux}\, \left[1- \frac{1}{2}\, 
e^{-u\, x}-\frac{1}{2}\, e^{-(1-u)x}\right]= \frac{3}{4u}-\frac{1}{2}\, .
\label{J2u.1}
\end{equation}
The computation of $I_2(u)$ in Eq. (\ref{Inu.1}) turns out to be tricky as we show in below. Following
Eq. (\ref{Inu.1}), we write
\begin{equation}
I_2(u)= \int_0^{\infty} \frac{dx}{x^2} \left[ 1- \frac{1}{2}\, e^{-u\, x}- \frac{1}{2}\,
e^{-(1-u)\, x}\right]^2\, .
\label{I2u.1}
\end{equation}
To get rid of the singularity $x^{-2}$ in the integrand, it is convenient to first take
a derivative with respect to $u$. This gives
\begin{equation}
I_2'(u)= \frac{dI_2(u)}{du}=\int_0^{\infty} \frac{dx}{x} 
\left[ 1- \frac{1}{2}\, e^{-u\, x}- \frac{1}{2}\, e^{-(1-u)\, x}\right]\, 
\left[ e^{-u\, x}- e^{-(1-u)\, x}\right]\, .
\label{I2u.2}
\end{equation}
We note one important fact from this equation that will be useful later, namely
\begin{equation}
I_2'\left(u=\frac{1}{2}\right)=0\, .
\label{bc.1}
\end{equation}
The integrand in Eq. (\ref{I2u.2}) still has an  singularity $1/x$. To get rid of this 
term, let us take one more derivative with respect to $u$. Further simplification leads to the following integral that can be trivially computed to yield
\begin{equation}
I_2''(u)= \frac{d^2I_2(u)}{du^2}= \int_0^{\infty} dx\, 
\left[e^{-2 u x}- e^{-2(1-u)x} - e^{-u x}- e^{-(1-u) x}\right]= -\frac{1}{2u}- \frac{1}{2(1-u)}\, .
\label{I2u.3}
\end{equation}
Now, integrating it back with respect to $u$ gives
\begin{equation}
I_2'(u)= -\frac{1}{2} \ln u + \frac{1}{2} \ln (1-u) +C_1\, ,
\label{I2u.4}
\end{equation}
where the unknown constant $C_1=0$ is fixed from the condition in Eq. (\ref{bc.1}). Thus we get
\begin{equation}
I_2'(u)= -\frac{1}{2} \ln u + \frac{1}{2} \ln (1-u)\, .
\label{I2u.5}
\end{equation}
\begin{figure}
    \centering
    \includegraphics[width=8cm]{Neq2.pdf}
    \caption{Comparison of the scaling function for $N=2$ as in \eref{F2u_exact} with that obtained via numerical integration of \eref{Fu_exact.1} .}
    \label{N2}
\end{figure}
Integrating once more we get
\begin{equation}
I_2(u)= -\frac{1}{2} \left[u \ln u-u\right] + \frac{1}{2} \left[1-u - (1-u)\ln (1-u)\right]+C_0\, ,
\label{I2u.6}
\end{equation}
where the constant $C_0$ is fixed from the value $I_2(0)$ in
Eq. (\ref{I2u.1}). Thus we finally get
\begin{equation}
I_2(u)= I_2(0) - \frac{1}{2}\, u\, \ln u- \frac{1}{2}\, (1-u)\, \ln(1-u)\, ,
\label{I2u.7}
\end{equation}
where, using Eq. (\ref{I2u.1}),
\begin{equation}
I_2(0)= \frac{1}{4} \, a_2 \, \quad {\rm with}\quad a_2= \int_0^{\infty} \frac{dx}{x^2} \left[1- e^{-u x}\right]^2\, .
\label{I20.1}
\end{equation}
To evaluate the integral $a_2$, we do one integration by part that gives
\begin{equation}
a_2= 2 \int_0^{\infty} \frac{dx}{x}\, e^{-x} \left(1- e^{-x}\right)\, .
\label{a2.1}
\end{equation}
To do the remaining integral in Eq. (\ref{a2.1}),
let us introduce an auxiliary parameter $b$ and define
\begin{equation}
a_2(b)= 2\, \int_0^{\infty} \frac{dx}{x}\, e^{-x} \left(1- e^{-b\, x}\right)\, ,
\label{a2b.1}
\end{equation}
such that $a_2(b=1)= a_2$. Differentiating Eq. (\ref{a2b.1}) with respect to $b$ we get
\begin{equation}
a_2'(b)= \frac{da_2(b)}{db}= 2\, \int_0^{\infty} dx\, e^{-(b+1)\, x}= 
\frac{2}{b+1}\, .
\label{a2b.2}
\end{equation}
Integrating it back with respect to $b$ and using $a_2(b=0)=0$, we get
\begin{equation}
a_2(b)= 2\, \ln (b+1)\, .
\label{a2b.3}
\end{equation}
Consequently,
\begin{equation}
a_2= a_2(b=1)= 2\, \ln 2\, .
\label{a2_final}
\end{equation}
Using this result in Eq. (\ref{I20.1}) gives
\begin{equation}
I_2(0)= \frac{a_2}{4}= \frac{1}{2}\, \ln 2 \, .
\label{I20.2}
\end{equation}
Following Eq. (\ref{I2u.7}), we get the complete expression for $I_2(u)$ as 
\begin{equation}
I_2(u) = \frac{1}{2}\,\left[\ln 2  - u\, \ln u- 
(1-u)\, \ln(1-u)\right]\, . 
\label{I2u.8} 
\end{equation}
Substituting $J_2(u)$ from Eq. (\ref{J2u.1}) and $I_2(u)$ from Eq.  (\ref{I2u.8})
into Eq. (\ref{Fu_exact.2}) with $N=2$ gives the exact scaling function ${\cal F}(u,2)$ as 
\begin{equation}
{\cal F}(u,2)= \frac{2}{u\,(3-2u)}\, \left[\ln 2 - u\,\ln u
-(1-u)\, \ln (1-u)\right]\, , 
\label{F2u_exact}
\end{equation}
as mentioned in Eq. (9) of the main text.  In Fig. (\ref{N2}) we show that the exact result as in \eref{F2u_exact} matches exactly with the numerical integration of \eref{Fu_exact.1} for $N=2$. The limiting behaviors of ${\cal F}(u,2)$ are given by
\begin{eqnarray}
\label{F2u_asymp}
{\cal F}(u,2) \approx \begin{cases}
\frac{2\ln 2}{3\, u} \, \quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad 
{\rm as}\quad u\to 0 \\
\\
2\, \ln 2 - 2\ (1-u)\, \ln(1-u) \,\,\, \quad {\rm as}\quad u\to 1\, .
\end{cases}
\end{eqnarray} 
% as indicated by Eq. (10) in the main text for general $N$.
Derivation of the scaling function for general $N$ is subject matter of the next section. 




\section{Asymptotic behaviors of ${\cal F}(u,N)$  
for general $N\ge 2$ as in Eq. (10)}

We now consider the scaling function ${\cal F}(u,N)$ in Eq. (\ref{Fu_exact.2})
for general $N\ge 2$. 
Unlike the $N=2$ case, it turns out to be much harder to compute the scaling
function explicitly for general $N>2$. However, as mentioned earlier, 
one can extract
the asymptotic behaviors of ${\cal F}(u,N)$, for arbitrary $N\ge 2$,
in the two limits
$u\to 0$ and $u\to 1$ as shown below.

\subsection{The limit $u\to 0$}

We will show that for general $N\ge 2$, the scaling function ${\cal F}(u,N)$
diverges as $u\to 0$, and this leading divergence originates 
from the denominator $J_N(u)$ in Eq. (\ref{Fu_exact.2}) as $u\to 0$. Hence,
for the numerator $I_N(u)$ in Eq. (\ref{Fu_exact.2}), it is enough only the
leading $u=0$ behavior where it turns out to be finite for all $N\ge 1$. %{\color{magenta}$N\ge 1$}. 
This becomes evident by setting $u=0$ in Eq. (\ref{Inu.1}), and it gives
\begin{equation}
I_N(0)= \frac{a_N}{2^N}\, \quad {\rm where}\quad a_N= \int_0^{\infty} \frac{dx}{x^2}\left(1- e^{-x}\right)^{N}\, .
\label{In0.1}
\end{equation}
We then need to evaluate $J_N(u)$ in Eq. (\ref{Jnu.1}) in the limit $u\to 0$.
By naively putting $u=0$ in Eq. (\ref{Jnu.1}) one finds that the resulting
integral diverges. To extract the leading divergence of $J_N(u)$ as $u\to 0$,
we first make a change of variable $u\, x=y$ in the integral in Eq. (\ref{Jnu.1}).
This gives
\begin{equation}
J_N(u)= \frac{1}{u}\, \int_0^{\infty} dy\, 
e^{-y}\, \left[1- \frac{1}{2}\, e^{-y}- 
\frac{1}{2}\, e^{-\frac{(1-u)}{u}\, y}\right]^{N-1}\, .
\label{Jnu.2}
\end{equation}
Now, in the limit $u\to 0$, we can safely neglect the third term inside the
parenthesis $[\ldots]$ since the resulting integral is convergent. This gives the
leading order behavior as $u\to 0$
\begin{equation}
J_N(u) \approx \frac{1}{u}\, 
\int_0^{\infty} dy\, e^{-y}\, \left[1-\frac{1}{2}\, e^{-y}\right]^{N-1}\, .
\label{Jnu.3}
\end{equation}
Making the change of variable $z=1- \frac{1}{2}\, e^{-y}$, the integral
can be done exactly leading to
\begin{equation}
J_N(u)\approx \left[\frac{2}{N}\left(1- 2^{-N}\right)\right]\, \frac{1}{u}\, 
\quad {\rm as}\quad u\to 0\, .
\label{Jnu.4}
\end{equation}
Substituting Eq. (\ref{Jnu.4}) and Eq. (\ref{In0.1}) into the exact expression
for ${\cal F}(u,N)$ in Eq. (\ref{Fu_exact.2}) then gives the leading
small $u$ behavior
\begin{equation}
{\cal F}(u,N) \approx \frac{a_N}{2^N-1}\, \frac{1}{u} \quad 
{\rm as}\quad u\to 0\, ,
\label{Fu0.1}
\end{equation}
where $a_N$ is defined in Eq. (\ref{In0.1}). Note that this result is
valid for any $N\ge 2$. For $N=2$, using $a_2= 2\, \ln 2$ from
Eq. (\ref{a2_final}), we see that the general result in Eq. (\ref{Fu0.1})
for $N=2$ matches perfectly with the leading asymptotic behavior as $u\to 0$
derived in Eq. (\ref{F2u_asymp}) from the exact scaling function for $N=2$.


% {\color{magenta} In Fig. , we compare this leading $u\to 0$ behavior
% in Eq. (\ref{Fu0.1}) with the numerically evaluated ${\cal F}(u,N)$
% in Eq. (\ref{Fu_exact.2}) for few values of $N$, finding excellent agreement.}



% \begin{figure}
% \includegraphics[width=0.6\textwidth]{Left_tail_asymptotics.pdf}
% \caption{The leading $u\to 0$ asymptotics
% in Eq. (\ref{Fu0.1}) compared 
% with the numerically evaluated ${\cal F}(u,N)$
% in Eq. (\ref{Fu_exact.2}) for few values of $N$.}
