\section{SYZ-type mirror symmetries} \label{section SYZ}



%suppose $T$ is a proper $\Oo_F$ subscheme $T_{\Oo_F} \longrightarrow  M_{\SLn}^{L}$, such that it generically lifts to $T_F \longrightarrow \Mm_{\widetilde{\SLn}}^{L, \rig}$ which is a $F$-torsor under an abelian variety $A_F$.

%Since $F$ is a $p$-adic field, it is not separable or algebraically closed, so we will continue to use the relative scheme machinery.



Set $S = \Spec k$ where $k$ is a field with $ \charac k \nmid n $, with $\mu_{n, k}$ and $\Gamma = \Pp ic^0_{\Cc/S} [n]$ constant group schemes. 

Let $a \in \Aa^{\textnormal{sm}}(k)$, corresponding to a spectral curve $\Tilde{\Cc} \xlongrightarrow{\pi} \Cc$. 


\subsection{First \texorpdfstring{$SYZ$}{SYZ}-type symmetry}

The following proposition generalises \cite[Proposition 3.6]{HT} to any field $k$ satisfying our assumptions. 

\begin{proposition}[First $SYZ$-type symmetry]
\label{firstSYZ}
Let $d \in \ZZ$ and $L \in \Pp ic^d_{\Cc/S}(S)$. Let $\alpha$ denote the gerbe $\Mm^L_{\SLn} \rightarrow \Mm^{L, \rig}_{\SLn}$ (\ref{slngerbe eq}). Set $L' = L \otimes \Dd$ (Notation \ref{notation d'}). For any $e \in \ZZ$, there is an isomorphism of $\Pp rym^0/\Gamma$-torsors over $S$ :
    $$ \Triv^0 (\alpha^{e} \ | \ \Pp rym^{L'}) \simeq \Pp rym^{e}_{\PGLn}. $$
\end{proposition}

\begin{proof}
    We can follow closely the proof by Hausel and Thaddeus. First, the statement for $e=1$ suffices, since the map $Triv^0$ in \ref{sub torsor of trivial} is a group morphism, and we can iterate the group law for $\Pp rym^0/\Gamma$-torsors over $S$ on both sides. 

  A trivialisation of the $\mu_n$-gerbe $\Mm_{\SLn}^{L} \longrightarrow \Mm_{\SLn}^{L, \rig}$ over $ \Pp rym^{L'} \longrightarrow \Mm_{\SLn}^{L, \rig}$ is a section $$ \Pp rym^{L'} \longrightarrow \Pp rym^{L'} \times_{\Mm_{\SLn}^{L, \rig}} \Mm_{\SLn}^{L}.$$ 
    Using the spectral correspondence, it is a universal line bundle  $\Ll$ over $\Pp rym^{L'} \times \tilde{\Cc}$ such that $\det \pi_* \Ll \simeq pr_2^*L$. 

    Let $\Tt = \Triv^0 (\alpha \ | \ \Pp rym^{L'})$. It is the set of universal line bundles over $\Pp rym^{L'} \times \tilde{\Cc}$ such that any pullback over $\Pp rym^{L'}$ is of degree $0$. The universal property implies that two such bundles differ by an element of $\Pp ic^0 (\Pp rym^{L'} ) \simeq \Pp rym^0/\Gamma$. 

    This  $\Pp rym^0/\Gamma$-torsor $\Tt$ is a quotient by $\Pp ic^0_{\Cc/S}$ of the $\Pp ic^0_{\Tilde{\Cc}/S}$-torsor 
    $$\Tt' = \big\{ \Ll \longrightarrow \Pp ic^{d'}_{\Tilde{\Cc}/S} \times \Tilde{\Cc} \text{ universal } \mid \ y^* \Ll \in \Pp ic^0(\Pp ic^{d'}_{\Tilde{\Cc}/S}) \ \forall \ y \in |\tilde{\Cc}| \big\}. $$ 
    In fact, 
    \begin{itemize}[-]
        \item Since $\Pp ic^0_{\Cc/S} \cong \Pp ic^0_{\Pp ic^{d'}_{\Cc/S}/S}$, the action of $\Pp ic^0_{\Cc/S}$ is by pullback of line bundles over $\Pp ic^{d'}_{\Cc/S}$ along
   $$ \begin{tikzcd}
       \Pp ic^{d'}_{\Tilde{\Cc}/S} \times \Tilde{\Cc}  \arrow[r, "pr_1"] & \Pp ic^{d'}_{\Tilde{\Cc}/S} \arrow[r, "\Nm" ]& \Pp ic^{d'}_{\Cc/S}.
    \end{tikzcd}$$
    \item There is a natural map $\Tt' \longrightarrow \Tt$ given by restriction, since $\Prym^L \hookrightarrow \Pp ic^{d'}_{\tilde{\Cc}/S}$. It is compatible with the $\Pp ic^0_{\tilde{\Cc}/S}$-action, and since $\Tt$ is a  $\Pp ic^0_{\tilde{\Cc}/S}/\Pp ic^0_{\Cc/S}$-torsor, it is $\Pp ic^0_{\Cc/S}$-invariant. Hence, it induces a map $$\Tt'/\Pp ic^0_{\Cc/S} \longrightarrow \Tt$$ of $\Pp rym^0/\Gamma$-torsors, which must be an isomorphism. 
    \end{itemize}

Moreover, $\Pp rym^{1}_{\PGLn}$ is also a quotient by $\Pp ic^0_{\Cc/S}$ of a $\Pp ic^0_{\Tilde{\Cc}/S}$-torsor, namely $\Pp ic^1_{\Tilde{\Cc}/S}$. Hence, it suffices to show an isomorphism of $\Pp ic^0_{\Tilde{\Cc}/S}$-torsors $ \Tt' \xlongrightarrow{\sim} \Pp ic^1_{\Tilde{\Cc}/S} $.

Let $T$ be a $S$-scheme. For $L_1 \ : \ T \longrightarrow  \Pp ic^1_{\Tilde{\Cc}/S}$, the pullback of the Poincaré line bundle $\Pp_{\Tilde{\Cc}}$ along 

$$\begin{tikzcd}
   \Tilde{\Cc} \times \Pp ic^{d'}_{\Tilde{\Cc}/S} 
 \arrow[r, "h_{L_1}"] & \Pp ic^0_{\Tilde{\Cc}/S} \times \Pp ic^0(\Pp ic^0_{\Tilde{\Cc}/S} ) \\ 
  (y, L_{d'})  \arrow[r] & \big( \Oo_{\Tilde{\Cc}}(y) \otimes L_1^{-1}, \Oo_{\Pp ic^0_{\Tilde{\Cc}/S} }( [L_{d'} \otimes L_1^{-d'}] - [0]) \big)
\end{tikzcd}$$

is a universal line bundle over $(\Tilde{\Cc} \times \Pp ic^{d'}_{\Tilde{\Cc}/S}) \times_S T $, whose pullback over $\Pp ic^{d'}_{\Tilde{\Cc}/S}$ is of degree $0$. It shows that $\Pp ic^1_{\Tilde{\Cc}/S}$ maps to $\Tt'$ via
$$L_1 \longmapsto  h_{L_1}^* \Pp_{\Tilde{\Cc}}.$$  
As both are $\Pp ic^0_{\Tilde{\Cc}/S}$-torsor, they are isomorphic. 
\end{proof}

\begin{remark}[]
For the case $L = \Dd^{-1}$, the $\GG_m$-gerbe $\Mm_{\widetilde{SLn}}^{\Dd^{-1}} \longrightarrow \Mm_{\SLn}^{\Dd^{-1}, \rig} $ restricted to a Hitchin fibre can be written as an extension of commutative group stacks : 
    $$ 0 \longrightarrow B\GG_m \longrightarrow \PP rym^0 \longrightarrow \Pp rym^0  \longrightarrow 0 $$
where $\PP rym^{0}$ is the substack of the Picard stack $\PP ic^0_{\Tilde{\Cc}/S}$ of line bundles $L$ such that $\Nm(L) = \Oo_\Cc$. 
Applying the dualising functor $\Hh om(-, B\GG_m)$, we get an exact sequence (see \cite[§7]{Brochard}) : 
     $$ 0 \longrightarrow Prym^0/\Gamma \longrightarrow Pic(\Tilde{\Cc})/Pic(\Cc)  \xrightarrow{\deg} \ZZ \longrightarrow 0 $$
which corresponds to a $Prym^0/\Gamma$-torsor, splitting when $\Pp ic^1(\Tilde{\Cc})/\Pp ic(\Cc) = \Pp rym^{1}_{\PGLn} $ has a section.

\end{remark}



\subsection{Second \texorpdfstring{$SYZ$}{SYZ}-type symmetry} 

Fix $N \in \Pp ic^1_{\Cc/S}(S)$. The following extends \cite[Proposition 3.6]{HT}, where $N$ is taken to be $\Oo_{\Cc}(c)$ for a basepoint $c \in \Cc$, to more general fields. 

Let $e \in \ZZ$ and $L_e \in \Pp ic^{e}_{\Cc/S}(S)$. Recall that we constructed a $\Gamma$-equivariant gerbe $\alpha_N \colon \Mm_{\widetilde{\SLn}}^{L_e} \longrightarrow \Mm_{\SLn}^{L_e, \rig}$ in \autoref{pglngerbe}. 

\begin{proposition}[Second $SYZ$-type symmetry] \label{secondSYZ} For any $d \in \ZZ$, there is an isomorphism of $\Pp rym^0$-torsors: 
    $$\Triv^0(\alpha_N^d \ | \ \Pp rym_{\PGLn}^{e'}) \simeq \Pp rym^{N^d}$$
where $e' =  e - \deg D \cdot \frac{n(n-1)}{2}$. 
\end{proposition}

\begin{proof}
We follow the arguments of Hausel and Thaddeus again. As for Proposition \ref{firstSYZ}, we first reduce to the case where $d=1$. 

Let $L_e' = L_e \otimes \Dd$, it is of degree $e'$. Using Lemma \ref{equiv lemma}, $\Triv^0(\alpha_N \ | \ \Pp rym_{\PGLn}^{e'})$ parametrises $\Gamma_N$-equivariant universal line bundles on $\Pp rym^{L_e'} \times \Tilde{\Cc}$, with the condition that any pullback to $\Pp rym^{L_e'}$ is  of degree $0$. Two such objects differ by a $\Gamma$-equivariant line bundle of degree $0$ on $\Pp rym^{L_e'}$, and $\Pp ic^0_{\Gamma}(\Pp rym^{L_e'}) = \Pp ic^0(\Pp rym^{L_e'}/\Gamma) \cong \Pp rym^0 $. Hence, $\Triv^0(\alpha_N \ | \ \Pp rym_{\PGLn}^{e'})$ is a $\Pp rym^0$-torsor. 

We construct a map $ \Pp rym^{N} \longrightarrow \Triv^0(\alpha_N \ | \ \Pp rym_{\PGLn}^{e'})$. Let $T \longrightarrow S$ and $L_1 \in \Pp rym^{N}(T)$. We can consider 
    $$\begin{tikzcd}
   \Pp ic^1_{\Tilde{\Cc}/S} \times \Pp ic^{e'}_{\Tilde{\Cc}/S} 
 \arrow[r, "g_{L_1}"] & \Pp ic^0_{\Tilde{\Cc}/S} \times \Pp ic^0(\Pp ic^0_{\Tilde{\Cc}/S} ) \\ 
  (M, \Ll)  \arrow[r] & \big( M \otimes L_1^{-1}, \Oo_{\Pp ic^0_{\Tilde{\Cc}/S} }( [\Ll \otimes L_1^{-e'}] - [0]) \big).
\end{tikzcd}$$

% Note that $h_{L_1}$ in the previous proof is just $h_{L_1} = g_{L_1} \circ (AJ \times \id)$.

%since $$ \Cc \xrightarrow{AJ} \Pp ic^1_{\Cc/S} \xrightarrow{\cdot{L_1}^{-1}} \Pp ic^0_{\Cc/S} $$
%$$ c \longmapsto \Oo_{\Cc}(c) \otimes L_{1}^{-1}$$

Let $\LL_{L_1} = g_{L_1}^*\Pp_{\Tilde{\Cc}}$. Since $L_e' \in \Pp ic^{e'}_{\Cc/S}(S)$, there is an isomorphism of étale group sheaves over $S$,
\begin{align*}
       \frac{\Pp rym^{L_e'} \times \Pp ic^0_{\Cc/S} }{\Gamma}  
        &\longrightarrow \Pp ic^{e'}_{\Tilde{\Cc}/S} \\
        [(A, B)]  &\longmapsto A \otimes \pi^*B^{-1}.
\end{align*}

Thus we can lift $ \LL_{L_1}$ to a $\Gamma$-equivariant line bundle $ \widetilde{\LL}_{L_1}$ over $\Pp rym^{L_e'} \times \Pp ic^0_{\Cc/S} \times \Pp ic^1_{\Tilde{\Cc}/S} $. Then, the universality of $\LL_{L_1}$ implies that \begin{itemize}[-]
    \item The restriction of $\widetilde{\LL}_{L_1}$ to $\Pp rym^{L_e'} \times \{ \Oo_\Cc \} \times \Pp ic^1_{\Tilde{\Cc}/S} $ is a universal line bundle, using $L_1$ again to embed $\Pp rym^{L_e'} \hookrightarrow \Pp ic^0(\Pp ic^1_{\Tilde{\Cc}/S} ) \simeq \Pp ic^0_{\Tilde{\Cc}/S}$. Note that by construction any of its pullback to $\Pp rym^{L_e'}$ is of degree $0$.
    \item The restriction to $\{A\} \times \Pp ic^0_{\Cc/S} \times \Pp ic^1_{\Tilde{\Cc}/S} $ is a universal line bundle twisted by $A$ in the sense that for all $B \in \Pp ic^0_{\Cc/S}$, the restriction to $\{A\} \times \{ B \} \times \Pp ic^1_{\Tilde{\Cc}/S} $ is isomorphic to $A \otimes (\Nm^{*} B)^{-1}$ over $\Pp ic^1_{\Tilde{\Cc}/S}$ (using that $\pi^*$ and $\Nm$ are dual). 
\end{itemize}


Hence, there exists $N' \in \Pp ic^1_{\Cc/S}(S)$ such that 
$$ \widetilde{\LL}_{L_1}  = p_{13}^* {\Ll}_{L_1}' \otimes p_{23}^* ((\id \times  g_{N'} \circ \Nm)^* \Pp_{\Cc})^{-1} $$

where 
\begin{itemize}[.]
    \item ${\Ll}_{L_1}'$ is a universal line bundle on $\Pp rym^{L_e'} \times \Pp ic^1_{\Tilde{\Cc}/S} $,
    \item $\Pp_{\Cc} \longrightarrow \Pp ic^0_{\Cc/S} \times \Pp ic^0_{\Cc/S}$ is the Poincaré sheaf for $\Pp ic^0_{\Cc/S}$,
    \item $g_{N'} \circ \Nm \ : \ \Pp ic^1_{\Tilde{\Cc}/S} \xrightarrow{\Nm} \Pp ic^1_{\Cc/S} \xrightarrow{\cdot N'^{-1}} \Pp ic^0_{\Cc/S}$. 
\end{itemize}

By construction $((\id \times  g_{N'} \circ \Nm)^* \Pp_{\Cc})^{-1}$ is normalised at $Nm^{-1}(N')$. As ${\LL}_{L_1} $ is normalised at $L_1$, in fact $$ N' = Nm(L_1) = N.$$
Recall the relative group scheme 
$$g_{N}^* \coprod_{\gamma  \in \Gamma} \LL_\gamma^* \longrightarrow \Pp ic^1_{\Cc/S}$$
with a canonical identification of the fibre of $N$ with $\GG_m \times \Gamma$. It acts on $(\id \times g_N)^*\Pp_{\Cc}$, hence on $((\id \times  g_{N} \circ \Nm)^* \Pp_{\Cc})^{-1} $, and $\GG_m$ acts with weight $-1$ (due to the inverse). As $\GG_m$ acts trivially on $\widetilde{\LL}_{L_1}$ (it is simply $\Gamma$-equivariant), ${\Ll}_{L_1}'$ is a $ g_{N}^* \underset{\gamma  \in \Gamma}{\coprod}  \LL_\gamma^*$-equivariant universal line bundle on ${\Pp rym^{L_e'} \times \Pp ic^1_{\Tilde{\Cc}/S}} $, where $\GG_m$ acts with weight $1$.

Pulling back ${\Ll}_{L_1}'$ over the curve via $\Tilde{\Cc} \xrightarrow{AJ} \Pp ic^1_{\Tilde{\Cc}/S}$, we obtain a $\Gamma_{N}$-equivariant universal line bundle on $\Pp rym^{L_e'} \times \Tilde{\Cc}$, and thus a $\Gamma$-equivariant trivialisation of $\alpha_{N}$ on $\Pp rym^{L_e'}$ by Lemma \ref{equiv lemma}. Hence, $\Pp rym^{N}$ maps to $\Triv^0(\alpha_N \ | \ \Pp rym_{\PGLn}^{e'})$. Both are $\Pp rym^0$-torsors so they are isomorphic. \end{proof}







\section{A non-archimedean topological mirror symmetry} \label{sectionnaTMS}

Let $S = \Spec \Oo_F$, where $\Oo_F$ is the ring of integers of a local field $F$ and $k$ is the residue field. We assume that $k$ is finite with characteristic $p$ which does not divide $n$. We use the relative construction of the moduli spaces of Higgs bundles over $S$ in \autoref{prelim}. 

\subsection{The set-up for integration} \label{measure}

We refer to \cite[Section 4]{GWZ} for an introduction to $p$-adic integration. In \cite{COW}, the authors constructed a $p$-adic measure in the following situation. Let $\Mm$ be a stack over $S$. Assume : 
    \begin{itemize}[-]
      \item  $ \Mm \longrightarrow S $ is normal of dimension $n$, with smooth atlas $s \ : \ V \longrightarrow \Mm $. 
        \item There is an open stabilizer-free substack $U' \subset \Mm$ whose complements has codimension at least $2$. 
         \item There is an open substack $U \subseteq U'$ and a morphism $\pi \ : \ \Mm \longrightarrow M$  where $M$ is a quasi-projective variety and $\pi_{|U}$ is an isomorphism. Its image is denoted $U$ as well.  
        \item For $x \in M(\Oo_F)^\sharp := M(\Oo_F) \cap U(F) $, there exists a finite extension $L/F$ such that there is a lift of $x$ as an $\Oo_L$-point $x_L \ : \ \Spec \ \Oo_L \longrightarrow \Mm $. 
    \end{itemize}

In this situation, there is a measure $\mu_{\can}$ on $M(\Oo_F)^\sharp$ constructed out of local trivialising top forms. Moreover, the measure does not depend on their choices \cite[Proposition 3.1.2]{COW}.


\begin{lemma} \label{lemma measure}
   The $\Oo_F$-variety $M_{\SLn}^L(\Oo_F)^\sharp$ (resp. $M_{\PGLn}^e(\Oo_F)^\sharp$) satisfies the conditions in \cite{COW} to be equipped with a $p$-adic measure $\mu_{\can, \SLn}$ (resp. $\mu_{\can, \PGLn}$), with respect to morphisms $\Mm_{\SLn}^{L,\rig} \longrightarrow M_{\SLn}^L$ (resp. $\Mm_{\PGLn}^{e} \longrightarrow M_{\PGLn}^e$). 
\end{lemma}

\begin{proof}
 In \cite[Theorem 2.3.1.]{COW}, the authors checked these conditions for $\Mm_{\GLn}^d \longrightarrow M_{\GLn}^d$, and their arguments work for $\SLn$ and $\PGLn$. We summarize it here.

\textit{Normality.} 
 As explained in \autoref{section symplectic}, the stack $\Mm_{\SLn}^d \longrightarrow S$ is smooth for $\deg D > 2g - 2$ and normal for $D=K_\Cc$. Rigidification by a finite group preserves smoothness and normality, thus it holds also for $\Mm_{\SLn}^{L,rig} \longrightarrow
 S$. 

Taking quotient by a finite abelian group does not affect the cotangent complex nor the atlas of a stack, hence $\Mm_{\PGLn}^e = \Mm_{\SLn}^{L_e,\rig}/\Gamma$  for any $L_e \in \Pp ic^e_{\Cc/S}(S)$ is also smooth (resp. normal) over $S$ for $\deg D > 2g - 2$ (resp. $D=K_\Cc$). 

\textit{Stabilizer free open set of codimension $2$.} We can consider $U' = h_{\SLn}^{-1}(A_{\SLn}^{\textnormal{red}})$, where $A^{\textnormal{red}}$ is the locus of reduced spectral curve. Replacing the dimension of the Hitchin base for $\GLn$ by $$ \dim \ \Aa = \deg \ D \big( \frac{n(n+1)}{2} - 1 \big) + (n-1)(1-g) $$ in the calculation of \cite{COW} leads to the condition 
$$codim \  S_{k, n_1, n_2} \geq 3 \deg D - (2g -2) $$
where $S_{k, n_1, n_2}$ are strata of $\Aa^{\textnormal{red}}$. 
For $D = K$, $g > 1$ or $\deg D > 2g - 2$, $g \geq 1$, the codimension of all strata are greater than $2$, and so is $U'$ by equidimensionality of the Hitchin fibration. 

For $\PGLn$, let $U^{\circ}$ be the open set where $\Gamma$ acts freely. It suffices to consider $ U' \cap U^{\circ}/\Gamma$, who has the same codimension as $U'$.

\textit{Generic isomorphism.}
The open substack $U$ can be chosen to be the open substack of Higgs bundles which are stable over the algebraic closure $\overline{F}$.

\textit{Existence of lifts.}
The last condition follows from \cite[Lemma 21.22]{BLM} or \cite[Theorem A8]{AHLH} (using the GIT construction of $M_{\SLn}^{L}$ ). 
\end{proof}

\subsection{Gerbe functions and \texorpdfstring{$SYZ$}{SYZ}-type duality}  \label{recapsection}
In this section, we convert each $SYZ$-type symmetry in an equality of integrable functions. Let $a \in \Aa(\Oo_F) \cap \Aa^{\textnormal{sm}}(F)$ and $S = \Spec F$. The quotient map $\Phi \ : \ \Pp rym^{0} \longrightarrow \Pp rym^{0}/\Gamma$ is a self-dual isogeny \cite[Proposition 7.10]{GWZ} with kernel $\Gamma$. Hence there is an associated long exact sequence of abelian group : 
$$0 \longrightarrow \Gamma \longrightarrow \Pp rym^{0}(F) \xlongrightarrow{\Phi} \Pp rym^{0}/\Gamma(F) \xlongrightarrow{\beta} H^1(F,\Gamma) \xlongrightarrow{\iota} H^1(F, \Pp rym^{0}) \longrightarrow \dots $$

Recall from \ref{gerbefunction} that for a $n$-torsion $\GG_m$-gerbe $\alpha$ over an abelian variety $A$, the gerbe function $f_{\alpha} \colon A(F) \longrightarrow \CC$ can be expressed in terms of the following Tate pairing,
$$ \langle -,- \rangle_A \ : \  A(F) \times H^1(F, \hat{A}) \longrightarrow \QQ/\ZZ$$
with $f_{\alpha}(x) = \langle -, Triv^0(\alpha \ | \ A ) \rangle_A $

From the first $SYZ$-type symmetry, Proposition \ref{firstSYZ}, since $h^{-1}_{\PGLn}(a) \simeq \Pp rym^{e'}_{\PGLn}$, we have $$ \langle -, Triv^0 (\alpha^{e'} \ | \ \Pp rym^{L \otimes \Dd}) \rangle_{\Pp rym^0} = \langle -, h^{-1}_{\PGLn}(a) \rangle_{\Pp rym^0}  $$ 
on $\Pp rym^0(F)$. 

The second $SYZ$-type symmetry, Proposition \ref{secondSYZ} can also be converted in similar terms. Writing $L \otimes  \Dd = N^{d'} \otimes L_0 $ with $L_0 \in \Pp ic^0(\Cc)$, 
%s for any $L_e \in \Pp ic^e(\Cc)$, we have $\Mm_{\PGLn}^e = \Mm_{\SLn}^{L_e}/ \Gamma $, we can work $\Gamma$-equivariantly on $\Mm_{\SLn}^{L_e}$. 
\begin{align} \label{iso pour prymL}
    h^{-1}_{\SLn}(a) &\simeq \Pp rym^{L\otimes \Dd}   \\
    &\simeq (\Pp rym^{N})^{d'} \times^{\Pp rym^0} \Pp rym^{L_0} \nonumber \\
    &\simeq \Triv^0(\alpha_N^{d'} \ | \ \Pp rym_{\PGLn}^{e'})  \times^{\Pp rym^0} \Pp rym^{L_0} \nonumber
\end{align} 

as $\Pp rym^0$-torsors, where we denote by $\times^{\Pp rym^0}$ the product of $\Pp rym^0$-torsor. We used the isomorphism $\Triv^0(\alpha_N^{d'} \ | \ \Pp rym_{\PGLn}^{e'}) \simeq (\Pp rym^{N})^{d'}$ given by the second SYZ symmetry statement (Proposition \ref{secondSYZ}). 



Combining three standard long exact sequences, we obtain the following commutative diagram of abelian groups :

\begin{equation} \label{bigdiagram}
    \begin{tikzcd}  
& 1 \arrow[d] & 1 \arrow[d] & 1 \arrow[d] & \dots \arrow[d, "\beta"] \\
  1 \arrow[r]&  \Gamma(F) \arrow[d, "\pi^*"]\arrow[r]& \Pp ic^0_{\Cc/S}(F)\arrow[d, "\pi^*"] \arrow[r, "\cdot n"]&  \Pp ic^0_{\Cc/S}(F)\arrow[d, "\id"]\arrow[r, "\delta"] & H^1(F, \Gamma)  \arrow[d, "\iota"] \\
   1 \arrow[r]& \Pp rym^{0}(F) \arrow[d, "\Phi"]\arrow[r] & \Pp ic^0_{\tilde{\Cc}/S}(F) \arrow[d]\arrow[r, "\Nm"]& \Pp ic^0_{\Cc/S}(F) \arrow[d] \arrow[r, "\Delta"]& H^1(F, \Pp rym^{0} ) \arrow[d] \\
   1 \arrow[r]&  \Pp rym^{0}/\Gamma(F) \arrow[d, "\beta"]\arrow[r, "\id"]& \Pp rym^{0}/\Gamma(F) \arrow[d]\arrow[r]& 1 \arrow[r]& H^1(F, \Pp rym^{0}/\Gamma) \\
   & \dots & \dots & 
\end{tikzcd}
\end{equation}

Since $\Gamma$ is Cartier self-dual, $H^1(F, \Gamma)$ is equipped with a Tate pairing \cite[Corollary I.2.3]{milnearithmdual} : 
$$ \langle - , - \rangle_\Gamma \ : \ H^1(F, \Gamma) \times H^1(F, \Gamma) \longrightarrow \QQ/\ZZ. $$

Moreover, there is an identity for $t \in H^1(F, \Gamma)$ and $y \in \Pp rym^{0}/\Gamma(F)$ \cite[eq. (34)]{GWZ} : 
$$ \langle y, \iota(t) \rangle_{\Pp rym^{0}/\Gamma} = \langle  \beta(y), t \rangle_\Gamma. $$
% where the first pairing is the Tate pairing for $A = \Pp rym^{0}/\Gamma$ and the second pairing is the Weil pairing $$ \langle \ , \ \rangle_\Gamma \ : \ H^1(F, \Gamma) \times H^1(F, \Gamma) \longrightarrow \QQ/\ZZ $$


Since $\Pp rym^{L_0}$ represents $\Delta(L_0)$ and $ \Delta(L_0) = \iota(\delta(L_0))$, 
\begin{equation} \label{equation pairings}
    \langle y, \Pp rym^{L_0} \rangle_{\Pp rym^{0}/\Gamma} = \langle \beta(y), \delta(L_0) \rangle_\Gamma.
\end{equation}

% Moreover $H^1(F, \Gamma) \simeq H^1_{\textnormal{ur}}(F, \Gamma) \oplus \Gamma^\vee \simeq \Gamma \oplus \Gamma$ \cite[Proposition 3.6]{GWZ}. Since $L$ is extends to $\Oo_F$, $\delta(L_0) \in H^1_{\textnormal{ur}}(F, \Gamma)$. It follows from \cite[Lemma 3.7]{GWZ} that $ \langle \delta(L_0), \beta(y) \rangle_\Gamma$ depends only on the second summand of $\beta(y)$. 
Then, using (\ref{iso pour prymL}), 
\begin{align*}
   \langle y, Triv^0 (\alpha_N^{d'} \ | \ \Pp rym_{\PGLn}^{e'}) \rangle_{\Pp rym^0/\Gamma} + \langle \delta(L_0), \beta(y) \rangle_\Gamma 
   &=  \langle y, \Pp rym^{N^{d'}} \rangle_{\Pp rym^0/\Gamma}  + \langle y, \Pp rym^{L_0} \rangle_{\Pp rym^0/\Gamma} \\
    &=\langle y, \Pp rym^{N^{d'}} \times^{\Pp rym^0} \Pp rym^{L_0} \rangle_{\Pp rym^0/\Gamma} \\
    &= \langle y, h^{-1}_{\SLn}(a) \rangle_{\Pp rym^0/\Gamma}. 
\end{align*} 

We just proved the following lemma.

\begin{lemma} \label{recaplemma}
Let $S = \Spec F$. Let $d, e \in \ZZ$ and $L \in \Pp ic^d_{\Cc/S}(S)$. Consider the Hitchin maps $h_{\SLn} \colon M_{\SLn}^L \longrightarrow \Aa$ and $h_{\PGLn} \colon M_{\PGLn}^e \longrightarrow \Aa$. Let $a \in \Aa^{\textnormal{sm}}(F) \cap \Aa(\Oo_F)$. 
\begin{enumerate}
    \item Let $\alpha$ denote the gerbe ${\Mm^{L}_{\widetilde{\SLn}} \longrightarrow \Mm^{L,\rig}_{\SLn}}$. For $x \in \Pp rym^0(S)$, 
$$\langle x, h^{-1}_{\PGLn}(a) \rangle_{\Pp rym^0} = \langle x, Triv^0 (\alpha^{e'} \ | \ h^{-1}_{\SLn}(a))\rangle_{\Pp rym^0}.  $$ 

    \item Let $N \in \Pp ic^1_{\Cc/S}(S)$ and $L_e \in \Pp ic^e_{\Cc/S}(S)$. Let $\alpha_N$ denote the $\Gamma$-equivariant gerbe ${\Mm^{L_e}_{\widetilde{\SLn}} \longrightarrow \Mm^{e}_{\PGLn}}$ from (\ref{pgln gerbe eq}). Set ${L_0 = L \otimes \Dd \otimes N^{-d'} \in \Pp ic^0_{\Cc/S}(S)} $. For $y \in \Pp rym^0/\Gamma(S)$, 
$$ \langle y, h^{-1}_{\SLn}(a) \rangle_{\Pp rym^0/\Gamma} = \langle y, Triv^0 (\alpha_N^{d'} \ | \ h^{-1}_{\PGLn}(a)) \rangle_{\Pp rym^0/\Gamma} + \langle \beta(y), \delta(L_0)  \rangle_\Gamma .$$     
\end{enumerate}
\end{lemma}

As explained in \ref{gerbefunction}, gerbe functions are intrinsic analogues to $\langle - , Triv^0 \rangle $, meaning that gerbe functions are defined without respect to a choice of trivialisation $h_{\SLn}^{-1}(a) \xrightarrow{\sim} \Pp rym^0$ and $h_{\PGLn}^{-1}(a) \xrightarrow{\sim} \Pp rym^0/\Gamma$. 

Since the function $\beta \colon \Pp rym^0/\Gamma(F) \longrightarrow H^1(F, \Gamma)$ is defined on the abelian variety $\Pp rym^0/\Gamma(F)$, and not directly on the Hitchin fibre, we need an intrinsic analogue to $\langle \beta(-), \delta(L_0)  \rangle_\Gamma $. 

Let $e \in \ZZ$ and $L_e \in \Pp ic^e_{\Cc/S}(S)$. There is a $\Gamma$-quotient map 
$$ M^{L_e}_{\SLn} \longrightarrow M^{e}_{\PGLn}$$
which is a free quotient above the chosen open set $U \subset M^{e}_{\PGLn}(F)$ in Lemma \ref{lemma measure} defining $M_{\PGLn}^e(\Oo_F)^\sharp$. Hence, for $y \colon \Spec \Oo_F \longrightarrow M_{\PGLn}^e$ in $M_{\PGLn}^e(\Oo_F)^\sharp$, there is an induced $\Gamma$-torsor $T_y = \Spec F \times_{M^{e}_{\PGLn}} M^{L_e}_{\SLn} $  over $\Spec F$. 

\begin{definition}[The function $\beta_{L_e}$] \label{def beta Le}
    Let $e \in \ZZ$ and $L_e \in \Pp ic^e(\Cc)$. We define 
    $$ \beta_{L_e} \colon M_{\PGLn}^e(\Oo_F)^\sharp \longrightarrow H^1(F, \Gamma),  $$
    sending $y \colon \Spec \Oo_F \longrightarrow M_{\PGLn}^e$ to $[T_y]$. 
\end{definition}

For a different choice of line bundle $L_e' \in \Pp ic^e_{\Cc/S}(S)$, 
the function $\beta_{L_e'}$ differs from $\beta_{L_e}$ by multiplication by $\delta(L_e^{-1} L_e') \in H^1(F, \Gamma)$. 

A trivialisation of the $\PGLn$-Hitchin fibre is given by $x \in \Pp rym^{e'}_{\PGLn}(F)$ and denoted $h_x$. Such $x$ lifts to $\tilde{x} \in \Pp rym^{L_x}_{\SLn}$ for a certain line bundle $L_x$ of degree $e$. Then, $\beta \circ h_x$ agrees with $\beta_{L_x}$, both sending $x$ to $[0] \in H^1(F, \Gamma)$.

In turn, for $x \in \Pp rym^{e'}_{\PGLn}(F)$,
   \begin{align} \label{eqbeta}
       \exp (2i\pi \cdot \langle \beta_{L_e}(x), \delta(L_0) \rangle_{\Gamma}) 
       &=  c \cdot \exp (2i\pi \cdot \langle \beta(h(x)), \delta(L_0) \rangle_{\Gamma}) \\
       &=c \cdot \exp (2i\pi \cdot\langle h(x), \Pp rym^{L_0} \rangle_{\Pp rym^0}) \nonumber
   \end{align}
where $c$ is a constant depending on the choice of trivialisation as in \cite[Lemma 6.7]{GWZ}. The last equality is given by (\ref{equation pairings}). 
Note that both sides of (\ref{eqbeta}) are constantly $1$ when $L_0$ has a $\mathit{n}$th root, since $\delta(L_0) = [0]$. 


