\subsection{The non-archimedean topological mirror symmetry}
Before stating the main theorem, we recall the main objects that come into play. We fix a rank $n \in \NN$. We work over a base scheme $S = \Spec \Oo_F$, where $\Oo_F$ is the ring of integers of a local field $F$ of finite residue field $k_F$, chosen so that $\charac k_F \nmid n$ and $\mu_{n, S}$ is constant. We fix a relative curve $\Cc \longrightarrow S$ of genus $g$ and a relative divisor $D$ such that $\deg D > 2g - 2$ or $D=K_\Cc$. We denote $\Gamma = \Pp ic^0_{\Cc/S}[n]$, which we assume to be constant.

For the $\SLn$ side, we fix a degree $d \in \ZZ $ and a line bundle $L \in \Pp ic^d_{\Cc/S}(S)$. We consider the moduli space $M_{\SLn}^L$ of semi-stable Higgs bundles of determinant $L$ and traceless Higgs field, relative over $S$. We explained in \autoref{slngerbe} that it is the good moduli space of a stack $\Mm^{L,\rig}_{\SLn}$ endowed with a $n$-torsion $\GG_m$-gerbe $\alpha \colon \Mm^{L}_{\widetilde{\SLn}} \longrightarrow \Mm^{L,\rig}_{\SLn}$. 


For the $\PGLn$ side, we fix a degree $e \in \ZZ$ and line bundles $L_e \in \Pp ic^e_{\Cc/S}(S)$ and $N \in \Pp ic^1_{\Cc/S}(S)$. The space $M^e_{\PGLn}$ is the good moduli space of a stack $\Mm^e_{\PGLn}$ which admits a $n$-torsion $\GG_m$-gerbe $\alpha_N \colon \Mm^{L_e}_{\widetilde{\SLn}} \longrightarrow \Mm^{L_e,\rig}_{\SLn}/\Gamma \simeq \Mm^e_{\PGLn}$. It depends on $N$, see \autoref{pglngerbe}. We have introduced complex valued functions associated to gerbes in \ref{gerbefunction}. 

We denote $\Dd = \overset{n-1}{\underset{i=0}{\bigotimes}} \Oo_\Cc(-iD)$, $d' = d + \deg \Dd$, $e' = e + \deg \Dd$ and ${L_0 = L \otimes \Dd \otimes N^{-d'} \in \Pp ic^0_{\Cc/S}(S)}$. Then $\delta(L_0) \in H^1(F, \Gamma)$ measure its class in $\Pp ic^0_{\Cc/S}(\Oo_F)/(\Pp ic^0_{\Cc/S}(\Oo_F))^{\times n}$ (see  \autoref{recapsection}). We also introduced a function $\beta_{L_e} \colon M_{\PGLn}^e(\Oo_F)^\sharp \longrightarrow H^1(F, \Gamma)$ in Definition \ref{def beta Le}. 

Finally, for a good moduli space map $\Mm \longrightarrow M$ which is an isomorphism when restricted to an open set $U$, we write
$$ M(\Oo_F)^\sharp := M(\Oo_F) \cap U(F), $$
and by Lemma \ref{lemma measure} there are canonical $p$-adic measures $\mu_{\can, \SLn}$ and $\mu_{\can, \PGLn}$ on $M_{\SLn}^L(\Oo_F)^\sharp$ and $M_{\PGLn}^e(\Oo_F)^\sharp$.

\begin{theorem}[Non-archimedean topological mirror symmetry] \label{mainthm}
With the above notations, the following equality holds : 
     $$ \int_{M_{\SLn}^L(\Oo_F)^\sharp} f_{\alpha}^{e'} \ \mu_{\can, \SLn} = \int_{M_{\PGLn}^e(\Oo_F)^\sharp} f_{\alpha_{N}}^{d'} \cdot exp(2i\pi \cdot \langle \beta_{L_e}(-), \delta(L_0)\rangle_\Gamma )  \ \mu_{\can, \PGLn}. $$
\end{theorem}

\begin{remark}
Degrees $e$ and $e'$ on the $\PGLn$ side are only well-defined modulo $n$ but the gerbe function $f_\alpha$ is $n$-torsion (see \autoref{slngerbe}) so that $f_{\alpha}^{e'}$ is well-defined.   
\end{remark}

\begin{proof}
    We use the same proof strategy as in \cite[Theorem 6.12]{GWZ} and \cite[Thm 5.0.2]{COW}. 

Let $\Aa^{\textnormal{red}}_S$ denote the locus of reduced spectral curves. Let $\Pp rym^0_{\SLn} \longrightarrow \Aa^{\textnormal{red}}_S $ and $\Pp rym^0_{\PGLn} \longrightarrow \Aa_S^{\textnormal{red}}$ be the relative group schemes acting faithfully and transitively on $ \Mm_{\SLn}' = M_{\SLn}^L \times_\Aa \Aa^{\textnormal{red}}$ and $\Mm_{\PGLn}' = M_{\PGLn}^e \times_\Aa \Aa^{\textnormal{red}}$ \cite[Proposition 4.3.3]{ngo}. 

    There exists a global, translation-invariant trivialising volume form $\omega_{\Pp, \PGLn}$ for $ \Omega^{top}_{\Pp rym^0_{\PGLn}/\Aa^{\textnormal{red}}}$. Using the isogeny 
    $$ \Phi \colon \Pp rym^0_{\SLn} \longrightarrow \Pp rym^0_{\PGLn} $$
    the pullback $\omega_{\Pp, \SLn} = \Phi^* \omega_{\Pp, \PGLn}$ gives a global, translation-invariant, trivialising relative volume form for $\Pp rym^0_{\SLn} \longrightarrow \Aa_S^{\textnormal{red}}$. 


    Using \cite[Lemma 6.13]{GWZ}, those relative forms induce trivialising relative forms for the torsors $\Mm_{\SLn}'$ and $\Mm_{\PGLn}'$, denoted $\omega_{h, \SLn}$ and $\omega_{h, \PGLn}$. 

    There are isomorphisms of line bundles :
    $$ \Omega^{top}_{\Mm_{\SLn}'/S} \simeq \Omega^{top}_{\Mm_{\SLn}'/\Aa^{\textnormal{red}}} \otimes \Omega^{top}_{\Aa^{\textnormal{red}}/S} $$
    and 
    $$ \Omega^{top}_{\Mm_{\PGLn}'/S} \simeq \Omega^{top}_{\Mm_{\PGLn}'/\Aa^{\textnormal{red}}} \otimes \Omega^{top}_{\Aa^{\textnormal{red}}/S} .$$

    Moreover, $\Aa$ being an affine space, there exists a global volume form $\omega_{\Aa}$ on $\Aa$. We obtain global volume forms on $\Mm_{\SLn}'$ and $\Mm_{\PGLn}'$, 
    $$ \omega_{\SLn}' = h_{\SLn}^* \omega_\Aa \wedge \omega_{h, \SLn} $$
    $$ \omega_{\PGLn}' = h_{\PGLn}^* \omega_\Aa \wedge \omega_{h, \PGLn}. $$

    Since $\Mm_{\SLn}^L \setminus \Mm_{\SLn}'$ is of codimension at least $2$, by Hartog's extension theorem $\omega_{\SLn}'$ extends to a global trivialising form $\omega_{\SLn}$ on $\Mm_{\SLn}^L(\Oo_F)^{\sharp}$. The same apply to construct $\omega_{\PGLn}$. Moreover, $\Mm_{\PGLn}' \subset U' \cap U^{\circ}/\Gamma$ from Lemma \ref{measure} since $\Mm_{\PGLn}'$ is represented. Hence, $\mu_{\can, \SLn}$ (resp. $\mu_{\can, \PGLn}$) is given by integrating global volume forms $\omega_{\SLn}$ (resp. $\omega_{\PGLn}$) on $M_{\SLn}^L(\Oo_F)^\sharp$ (resp. $M_{\PGLn}^e(\Oo_F)^\sharp$).


    Then, the volume of $ M_{\SLn}^L \times_\Aa (\Aa \setminus \Aa^{\textnormal{sm}})$ (resp. $M_{\PGLn}^e \times_\Aa ((\Aa \setminus \Aa^{\textnormal{sm}})$) is zero, since it is a closed subscheme of positive codimension \cite[Proposition 4.4]{GWZ}. Since the Hitchin map is proper over $\Aa$ and using the Fubini theorem \cite[Proposition 4.1]{GWZ}, we reduce to the fibrewise equality 
    $$ \int_{h_{\SLn}^{-1}(a)(F)} f_{\alpha}^{e'} \ |\omega_{\SLn, a} | = \int_{h_{\PGLn}^{-1}(a)(F)} f_{\alpha_{N}}^{d'} \cdot exp(2i\pi \cdot \langle \beta_{L_e}(-), \delta(L_0)\rangle_\Gamma )  \ |\omega_{\PGLn, a} |$$
    for all $a \in \Aa(\Oo_F) \cap \Aa^{\textnormal{sm}}(F)$, where $\omega_{\SLn, a}$ (resp. $\omega_{\PGLn, a}$) is the restriction of $\omega_{\SLn}$ (resp.  $\omega_{\PGLn}$) to the fibre over $a$. 
    % where 
    % $$ h_{\SLn} \ : M_{\SLn}^L \longrightarrow \Aa  $$
    % $$ h_{\PGLn} \ : M_{\PGLn}^e \longrightarrow \Aa  $$
    % are the associated Hitchin maps. 

    Pick $a \in \Aa(\Oo_F) \cap \Aa^{\textnormal{sm}}(F)$. There is an associated smooth spectral curve $\Tilde{\Cc}$, for which we use the notation $\Pp rym^0$, $\Pp rym^0/\Gamma$ as introduced in \autoref{pryms}. 
    %Since the fibres $h_{\PGLn}^{-1}(a)(F)$ and  $h_{\SLn}^{-1}(a)(F)$ are torsors for abelian varieties, we can use identical arguments as in \cite[Section 6.3]{GWZ}

    % The measures are given by integrating top degree forms of. 

    Then, there are four possible cases. 

    \begin{itemize}[-]
        \item If both fibres are empty, both sides are zero. 
        \item If both fibres have a rational point, then they are trivial $\Pp rym^0$-torsor and  $\Pp rym^0/\Gamma$-torsor, so we can pick two trivialisations. By Lemma \ref{recaplemma} and passing to the exponential, the integrands can be expressed in terms of Tate pairing against the dual fibre, $\exp^{2 i \pi \cdot \langle -, h^{-1}_{\SLn}(a)(F) \rangle} $ (resp. $\exp^{2 i \pi \cdot \langle -, h^{-1}_{\SLn}(a)(F) \rangle} $), so they are identically $\id$. 


        It suffices to prove that the $p$-adic volume of $\Pp rym^0$ and $\Pp rym^0/\Gamma$ is the same. It is the content of \cite[Lemma 6.15]{GWZ}. The proof relies on the Fubini theorem \cite[Proposition 4.4]{GWZ}, the construction of the translation-invariant form $\omega_{\SLn}$ by pullback along $\Phi$ and the fact that the quotient map $\Phi \ : \ \Pp rym^0 \longrightarrow \Pp rym^0/\Gamma$ is a self-dual isogeny, so that \cite[Proposition 3.16]{GWZ} holds : 
        $$\bigg|  \frac{\Pp rym^0/\Gamma(F)}{\Phi(\Pp rym^0)(F)} \bigg| = \mid \ker \Phi (F) \mid.   $$

        \item If $h_{\SLn}^{-1}(a)(F) = \emptyset$, and $h_{\PGLn}^{-1}(a)(F) \neq \emptyset$, we pick a trivialisation $h \ : \ h_{\PGLn}^{-1}(a) \xrightarrow{\sim} \Pp rym^0/\Gamma$. Using Lemma \ref{recaplemma}, the integrand on the right is $\exp^{2 i \pi \cdot \langle -, h_{\SLn}^{-1}(a) \rangle}$ up to a constant due to the choice of trivialisation. Since $h_{\SLn}^{-1}(a)(F)$ is empty, it is a non-trivial $\Pp rym^0$-torsor. The integrand is then a non-trivial character of $ \Pp rym^0/\Gamma$, so the integral is $0$.  

        \item If $h_{\SLn}^{-1}(a)(F) \neq \emptyset$, and $h_{\PGLn}^{-1}(a)(F) = \emptyset$, we use a symmetric argument.     
    \end{itemize}
\end{proof}




