As explained in \cite[Proposition 3.6]{GWZ}, for a choice of primitive $\mathit{n}$th root of unity, there is a decomposition corresponding to ramified and unramified part $$H^1(F, \Gamma) \simeq H^1_{\textnormal{ur}}(F, \Gamma) \oplus \Gamma \simeq \Gamma \oplus \Gamma$$
where $H^1_{\textnormal{ur}}(F, \Gamma) = H^1_{\textnormal{ét}}(k_F, \Gamma)$ is the group of torsors which lifts to $\Spec \Oo_F$. 

The lift of $y_{\Oo_F}$ to $\Mm^e_{\PGLn}$ has a unique closed point. Let $\gamma$ be the generator of its automorphism group. Then, $\gamma$ is the projection of $[T_y]$ to the ramified part. The construction is detailed in \cite[Construction 4.15]{GWZ} and \cite[Construction 3.1.2]{LW}. Composing $\beta_{L_e}$ with this second projection $H^1(F, \Gamma) \longrightarrow \Gamma$, we obtain a specialisation map :
$$ M_{\PGLn}^e(\Oo_F)^\sharp \xlongrightarrow{s} \Gamma. $$

It does not depend on $L_e$, since a different choice gives a multiplication by $\delta(L_e^{-1} L_e') \in H^1_{\textnormal{ur}}(F, \Gamma)$, which does not affect the ramified part.



\begin{remark}[Weil pairing] \label{rmk weil pairing}
  The group $\Gamma$ is a self-dual abelian variety as kernel of the self-dual isogeny $[n]$. Thus, there is a Weil pairing $(- , - )_\Gamma \colon \Gamma \times \Gamma \longrightarrow \mu_n(\CC)$. It provides a canonical identification $\omega \ : \ \Gamma \longrightarrow \hat{\Gamma}$. For $\gamma \in \Gamma$, we denote $\kappa = \omega(\gamma)$ the corresponding character.
\end{remark}


 We fix an identification $H^1_{\textnormal{ur}}(F, \Gamma) \simeq  \Gamma$, which is given by a choice of uniformiser of $F$ \cite[Construction 3.5]{GWZ}. Recall that $\delta$ denotes the connecting morphism $\delta \colon \Pp ic^0(\Oo_F) \longrightarrow H^1_{\textnormal{ur}}(F, \Gamma)$ in (\ref{bigdiagram}). 

\begin{theorem}[Refinement]\label{fourier}
  Let $d, e \in \ZZ$. Let $L = N^{\otimes d}$ and for $\nu \in \Gamma$, let $L_{\nu} \in \Pp ic^0(\Cc)(\Oo_F)$ such that $\delta(L_\nu) = \nu$. Then, for $\kappa \in \hat{\Gamma}$ and $\omega (\gamma) = \kappa$, 
  $$ \frac{1}{ |\Gamma|} \sum_{\nu \in \Gamma} \Big( \int_{M_{\SLn}^{N^d \otimes L_\nu} (\Oo_F)^\sharp} f_{\alpha}^{e'} \ \mu_{\can} \Big) \kappa(\nu) = \int_{M_{\PGLn}^e(\Oo_F)^\sharp \cap s^{-1}(\gamma)}  f_{\alpha_{N}}^{d'}  \ \mu_{\can}.  $$
\end{theorem}


\begin{proof}
 The pairing $ \langle \beta_{L_e}(-), \delta(L_0)\rangle_\Gamma$ is the Tate pairing
$$ \langle - , - \rangle_\Gamma \ : \ H^1(F, \Gamma) \times H^1(F, \Gamma) \longrightarrow \QQ/\ZZ. $$

Its behaviour with respect to the decomposition $H^1(F, \Gamma) \simeq H^1_{\textnormal{ur}}(F, \Gamma) \oplus \Gamma$ is described in \cite[Lemma 3.7]{GWZ}. The first factors jointly pairs to zero, as well as the second factors. Then, its restriction to $ H^1_{\textnormal{ur}}(F, \Gamma) \times \Gamma $ and $ \Gamma \times H^1_{\textnormal{ur}}(F, \Gamma) $ is given by the Weil pairing $(-,-)_\Gamma$ (see the proof of \cite[Lemma 7.25]{GWZ}). 

Since $L_{\nu} \in \Pp ic^0(\Cc)(\Oo_F)$, $\delta(L_\nu)$ lies in the unramified part $H^1_{\textnormal{ur}}(F, \Gamma)$. It pairs non-trivially only with torsors in the ramified part. Hence, for $y \in M_{\PGLn}^e(\Oo_F)^\sharp$, 
\begin{align*}
    \langle \beta_{L_e}(y), \delta(L_\nu)\rangle_\Gamma &= \langle \ (0, s(y)), (\nu, 0) \ \rangle_\Gamma \\
    &= (s(y), \nu)_\Gamma .
\end{align*} 


% , it that the restriction to $s^{-1}(\gamma')$ of $exp(2i\pi \cdot \langle \beta_{L_e}(-), L_{\nu} \rangle_\Gamma)$ coincides with  $(\gamma', \nu)_\Gamma \in \mu_n(\CC)$. 

For $\gamma' \in \Gamma$, we denote $\kappa' := \omega(\gamma')$ (Remark \ref{rmk weil pairing}). Then,


\begin{align*}
    \sum_{\nu \in \Gamma} \Big( \int_{M_{\SLn}^{N^d \otimes L_\nu} (\Oo_F)^\sharp} f_{\alpha}^{e'} \ \mu_{\can} \Big) \kappa(\nu) 
    &= \sum_{\nu \in \Gamma} \Big( \int_{M_{\PGLn}^e(\Oo_F)^\sharp} f_{\alpha_{N}}^{d'} \cdot  exp(2i\pi \cdot \langle \beta_{L_e}(-), \delta(L_\nu)\rangle_\Gamma ) \ \mu_{\can} \Big) \kappa(\nu) \\
    &= \sum_{\nu \in \Gamma} \sum_{\gamma' \in \Gamma} \Big(  \int_{M_{\PGLn}^e(\Oo_F)^\sharp \cap s^{-1}(\gamma')}  f_{\alpha_{N}}^{d'} \cdot ( \gamma', \nu )_\Gamma \ \mu_{\can} \Big) \kappa(\nu)  \\
   &= \sum_{\gamma' \in \Gamma}  \Big( \int_{M_{\PGLn}^e(\Oo_F)^\sharp \cap s^{-1}(\gamma')}  f_{\alpha_{N}}^{d'}  \ \mu_{\can} \Big) \sum_{\nu \in \Gamma} \kappa \kappa'^{-1}(\nu)  \\
    &= |\Gamma| \int_{M_{\PGLn}^e(\Oo_F)^\sharp \cap s^{-1}(\gamma)}  f_{\alpha_{N}}^{d'}  \ \mu_{\can} 
\end{align*}

where we used \autoref{mainthm} for the first equality. Note that $\underset{\nu \in \Gamma}{\sum} \kappa \kappa'^{-1}(\nu) = |\Gamma|$ if $\kappa = \kappa'$ and $0$ otherwise.   
\end{proof}






\section{Interpretation of \texorpdfstring{$p$}{p}-adic integrals}

\label{section corollaries}

% An equality of $p$-adic integrals as \ref{mainthm} can be used to understand relations between cohomological invariants of the moduli spaces over $S = \Spec \CC$. Following \cite{GWZ}, we can give a proof of topological mirror symmetry in the coprime case, which extend to the case of $D$ of odd degree. Then, we explain two cases where we can relate the $p$-adic integrals to cohomology groups, using the function-sheaf dictionary and the relation between $p$-adic integrals and finite fields countings. 

% We fix a curve $\Cc$, a line bundle $L$ and a divisor $D$ as before, with $S = \Spec \ \CC$. 

In this section, we are interested in interpreting the $p$-adic integrals of \autoref{mainthm} in terms of cohomological invariants. 
%It goes in two steps : first, we use a connection between $p$-adic integrals and finite fields countings. Second, expressing these countings in terms of traces of Frobenius on $\ell$-adic cohomology, we can relate them to invariants of the moduli space over $\CC$, such as Betti numbers and $E$- polynomials.  

\begin{remark}[How to apply \autoref{mainthm} ?] \label{spread out rmk}
   We follow the reasoning in \cite[Remark 3.2.2]{COW}. Given a pair $M_{\SLn}^L, M_{\PGLn}^e$ over $\Spec \CC$, we find a spreading out, i.e. a finitely generated $\ZZ$-algebra $R$ such that the curve $\Cc$ and line bundles $D, L, N$ are defined over $B = \Spec R$, such that $\mu_{n, B}$ and $ \Gamma_B$ are constant. Then, $M_{\SLn}^L \longrightarrow B$ and $M_{\PGLn}^e \longrightarrow B$ are geometrically normal so there is an open $B' \subset B$ whose fibres are normal. It gives infinitely many prime characteristic $p$ for which we can consider a ring of $p$-adic numbers $\Oo_F$ satisfying the assumptions of \autoref{sectionnaTMS}. 
\end{remark}

% In order to relate $p$-adic integrals to cohomological invariants, 



\begin{notation} \label{notation frob}
    Fixing a prime number $\ell$, for a finite field $k$ of characteristic $p \neq \ell$ we consider the Frobenius element $\Fr$ of $Gal(\overline{k}/k)$ acting on $\ell$-adic complexes over  ${M_{\SLn, k}^L}$ and ${M_{\PGLn, k}^e}$. For a bounded complex $H^\bullet \colon \ldots \longrightarrow H^{i-1} \longrightarrow H^i \longrightarrow H^{i+1} \longrightarrow \dots $ of vector spaces on which the Frobenius acts, the expression 
    $$ \tr(\Fr \ | \ H)$$
    denote the alternated sum $\underset{i \in \ZZ}{\sum} (-1)^i \tr(\Fr \ | \ H^i ) $. 
\end{notation}


\subsection{Completing the coprime case}

The topological mirror symmetry theorem \cite[Theorem 7.21]{GWZ} holds for $\deg D$ even. This restriction avoids the case where $d \not\equiv d' \mod n$. Our main theorem extends this result to the odd degree $D$ case.  

Let $S = \Spec \CC$. Fix a smooth projective curve $\Cc$ of genus $g$ over $\CC$ and line bundles $D, N$ on $\Cc/\CC$ of degree $\deg D$ and $1$ respectively. As before, assume $\deg D > 2g- 2$ or $D \sim K_\Cc$.

\begin{corollary}[Topological mirror symmetry - coprime case] \label{corTMScoprime}
Let $(d,n)=(e,n)=1$. Let $d \in \Pp ic^d(\Cc)$ and $d' = d - \deg D \cdot \frac{n(n-1)}{2}$. We have the following equality of stringy twisted $E$-polynomials (Definition \ref{defi stringy}):
$$ E(M_{\SLn}^{L}) = E_{\textnormal{st}, \alpha_N^{d'}}(M_{\PGLn}^{e}). $$
Let $q$ be the multiplicative inverse of $d$ modulo $n$. For any $\gamma \in \Gamma$ and $L_e \in \Pp ic^e_{\Cc/\CC}(\CC)$, there is a refinement:
$$ E(M_{\SLn}^{L})_{\kappa} = E(M_{\SLn}^{L_e, \gamma})_{\kappa^{-qd'}} $$
where $\kappa = \omega(\gamma)$ as in Remark \ref{rmk weil pairing}.
\end{corollary}

\begin{proof}
In the coprime case, $\Mm_{\SLn,\rig}^{L}$ is a smooth scheme and $\Mm_{\PGLn}^e$ is a smooth Deligne-Mumford stack equipped with the gerbe $\alpha_N^{d'} \colon \Mm^{L_e}_{\SLn} \rightarrow \Mm_{\PGLn}^e$. Since $\CC$ is algebraically closed, $L \otimes \Dd \otimes N^{- d'}$ has a $\mathit{n}$th root $L_0^{\frac{1}{n}}$. 

As explained in Remark \ref{spread out rmk}, is possible to spread out $\Cc, D, L, N, L_0^{\frac{1}{n}}, L_e$ over a finitely generated $\ZZ$-algebra $R$. 
% Then, we can consider a $p$-adic field $F$ as before such that there is a ring homomorphism $R \longrightarrow \Oo_F$. 
Then, $\Mm_{\SLn, R}^{L,\rig}$ and $\Mm_{\PGLn, R}^e$ form an abstract dual Hitchin system in the sense of \cite[Definition 6.9]{GWZ}.

 Since the gerbe $\alpha \ : \ \Mm^{L}_{\SLn} \longrightarrow \Mm^{L,\rig}_{\SLn} \simeq M_{\SLn}^L$ is over the good moduli space, we have $f_{\alpha} \equiv 1$, as explained in the proof of \cite[Lemma 7.19]{GWZ}. Indeed, for $x \in M_{\SLn}^L(\Oo_F)^\sharp$, $f_{\alpha_{L}}(x) = \exp(2 \pi i \cdot inv(\tilde{x}^* \alpha))$ (Construction \ref{gerbe function construction}). As $\Mm^{L,\rig}_{\SLn} \simeq M_{\SLn}^L$, the lift $\tilde{x}$ extends to the $\Oo_F$-point $x$, and the vanishing of Brauer groups over local fields implies $inv(x^* \alpha) = 0$. 

  Thus, \autoref{mainthm} reads : 
 $$ \int_{M_{\SLn}^L(\Oo_F)^\sharp} 1 \ \mu_{\can, \SLn} = \int_{M_{\PGLn}^e(\Oo_F)^\sharp} f_{\alpha_{N}}^{d'}  \ \mu_{\can, \PGLn} .$$




    By \cite[Theorem 6.11]{GWZ}, $M_{\SLn, R}^{L}$ and $\Mm_{\PGLn, R}^e$ have the same stringy twisted $E$-polynomial (with respect to $\alpha_N^{d'}$ for the $\PGLn$-side). Since  $M_{\SLn}^{L}$ is smooth, its stringy invariants corresponds to the classical ones.

    The reasoning uses an orbifold formula \cite[Theorem 4.16, Theorem 6.12]{GWZ} relating $p$-adic integrals to finite fields counts. By Grothendieck-Lefschetz theorem, those counts are traces of Frobenius in $\ell$-adic cohomology, which recover $E$-polynomials by means of $p$-adic Hodge theory.



    For the refinement, the proof of \cite[Theorem 7.24]{GWZ} applies. In the coprime case, the gerbe corresponds to a twist by a $\Gamma$-equivariant trivial local system, whose equivariant structure corresponds to the character $\kappa^{-q}$ as explained in \cite[Appendix A]{LW} based on \cite[Proposition 8.1]{HT}. 
\end{proof}



\begin{remark} \label{inaccuracy}
The corollary above allows us to detect an inaccuracy in \cite[Theorem 3.2]{MSendoscopicHTcoprime} for the choice of the character, since the $\kappa$-part and $\kappa^{-qd'}$-isotypical part can be strictly different when $d \not\equiv d' \mod n$. It happens only when $\deg D$ is odd. According to the authors, it is due to a certain $G$-equivariant local system appearing in the vanishing cycles argument, where $G$ is a Galois group of a Galois cover of $\Cc$ related to $\gamma$-fixed locus, as in Proposition \ref{prop link IH}. 

The parity assumption for $D$ was also missing in the non-coprime case in \cite[Theorem 0.2]{MSnoncoprime}. The authors recently uploaded a corrected version on arXiv of both articles \cite{MSarxivcoprime, MSarxivnoncoprime}. 
\end{remark}

\begin{remark}
As computational evidence, the computation in prime ranks in \cite[Proposition 10.1 and 8.2]{HT} can be adapted to the meromorphic case $ D> K_\Cc$, and $d'$ appears in equations (10.2) and (10.3) for the $\kappa$-part on the $\SLn$ side, while the computation for the $\kappa$-part on the $\PGLn$ side is insensitive to $\deg D$. Taking the $d'$th power on the $\PGLn$ side therefore rebalances both sides.
\end{remark}


