\subsection{Link to intersection cohomology when \texorpdfstring{$D > K$}{D>K}}

In \cite{MSnoncoprime}, the authors proved the existence of the following isomorphism when $\deg D> 2g - 2$ is even, $S = \Spec \ \CC$ and $L \in \Pp ic_{\Cc/S}(S)$, for $\kappa = \omega(\gamma)$:
\begin{equation} \label{MSeq}
    (R{h_{\SLn, *}} IC _{M_{\SLn}^{L}})_{\kappa} \xlongrightarrow{\sim} i_{\gamma, *} (R{h_\gamma, *} IC_{M_{\SLn}^{L, \gamma}})_{\kappa} [-F_\gamma]
\end{equation}
in the bounded derived category of $\Aa^\gamma = h_{\SLn}(M_{\SLn}^{L, \gamma})$, where $i_\gamma \colon \Aa^\gamma \hookrightarrow \Aa $ denotes the inclusion and $h_\gamma$ the restriction of the Hitchin map to $M_{\SLn}^{L, \gamma}$. This isomorphism allows us to prove the following proposition. 

%should I also prove it for L_nu using the refinement ? 



\begin{proposition} \label{prop link IH}
    Let $n$ be prime. Let $\Cc$, $D$, $L$, $N$ be defined over $\CC$, such that $\deg D> 2g-2$ even and $L= N^{\otimes d}$. There exists a spreading out over $B = \Spec R$ (as in Remark \ref{spread out rmk}) and a dense open $\tilde{B} \longrightarrow B$ such that for any $\Spec k_F \longrightarrow \tilde{B}$, residue field of a ring $\Oo_F$,
    $$ \int_{M_{\SLn}^L(\Oo_F)^\sharp} f_{\alpha} \ \mu_{\can} = q^{- \dim M_{\SLn}^L} \tr ( \Fr \ | \ IH_c(M_{\SLn, k_F}^L, \underline{\QQ}_\ell))$$
    using Notation \ref{notation frob} for the right hand side, with $q = |k_F|$. 
\end{proposition}

\begin{proof}
   We can assume that $L = \Oo_\Cc$. Indeed, we assume $L = N^{\otimes d}$ and since $n$ is prime, the degree $0$ case is the only non-coprime case, and the equality is already known for the coprime case (where intersection cohomology is the same as singular cohomology). We use $M^0_{\SLn}$ to denote $M^{\Oo_\Cc}_{\SLn}$. 

    There are three steps for this proof, summarised in the square below. Step $1$ uses our main \autoref{mainthm}. Step $2$ combines the explicit description of $\gamma$-fixed loci in terms of Prym varieties and the $\chi$-independence results for $\GLn$ by Maulik and Shen \cite{MS23}. Step $3$ uses the topological mirror symmetry equality (\ref{MSeq}) from \cite{MSnoncoprime}. 

$$    \begin{tikzcd}[column sep=huge] 
         \int_{M_{\SLn}^0(\Oo_F)^\sharp} f_{\alpha} \ \mu_{\can} \arrow[r, equal, "\text{Step 1 : \autoref{mainthm}}"] &  \int_{M_{\PGLn}^1(\Oo_F)^\sharp} 1 \ \mu_{\can} \arrow[d, equal, "\text{Step 2 : \cite{GWZ}, \cite{MS23}}"] \\
         q^{- \dim M_{\SLn}^0} \tr ( \Fr \ | \ IH_c(M_{\SLn, k_F}^0, \underline{\QQ}_\ell)) \arrow[r, equal, "\text{Step 3 : \cite{MSnoncoprime}}"] &  q^{- \dim M_{\PGLn}^0} \underset{\gamma \in \Gamma}{\sum}  \tr (\Fr \ | \ IH_c^{* -F_\gamma}(M_{\SLn,k_F}^{0,\gamma}, \underline{\QQ}_\ell)_\kappa)
    \end{tikzcd}$$

    As in Remark \ref{spread out rmk}, we can find a spreading out of $M_{\SLn}^0$ over $B = \Spec R$. 

    \textit{Step 1.} We apply \autoref{mainthm} for triples $(F, \Oo_F, k_F)$ equipped with a map $R \rightarrow \Oo_F$. Since $d' \equiv d \equiv 0 \mod n$ ($\deg D$ is even),
    $$\int_{M_{\SLn}^{0}(\Oo_F)^\sharp} f_{\alpha} \ \mu_{\can} =   \int_{M_{\PGLn}^1(\Oo_F)^\sharp} 1 \ \mu_{\can}. $$

    \textit{Step 2.} Using \cite[Theorem 4.16]{GWZ}, we get 
    \begin{align} \label{degree 1 pgln coho}
        \int_{M_{\PGLn}^1(\Oo_F)^\sharp} 1 \ \mu_{\can} &=  q^{- \dim M_{\PGLn}^1} \cdot \tr (\Fr \ | \ H_c^{orb} (M_{\PGLn, k_F}^1, \underline{\QQ}_\ell)) \nonumber \\
        &= q^{- \dim M_{\PGLn}^1} \cdot \bigg( \tr (\Fr \ | \ H_c(M_{\PGLn, k_F}^1, \underline{\QQ}_\ell)) + \sum_{\gamma \neq 1} \tr (\Fr \ | \ H_c^{* - F_\gamma} (M_{\SLn, k_F}^{L_1,\gamma}, \underline{\QQ}_\ell)^\Gamma ) ) \bigg)
    \end{align}  
    for any line bundle $L_1 \in \Pp ic^1_{\Cc/k_F}(k_F)$. 

\begin{claim}[First term in (\ref{degree 1 pgln coho})] \label{claim first term}
There exists a dense open set $B' \hookrightarrow
B$ for which at any closed point $\Spec k \rightarrow B'$,
     $$\tr (\Fr \ | \ H_c(M_{\PGLn, k}^1, \underline{\QQ}_\ell)) = \tr (\Fr \ | \ H_c(M_{\PGLn, k}^0, \underline{\QQ}_\ell)).$$
\end{claim}

\begin{proof}[Proof of Claim \ref{claim first term}]
      Arguing as in \cite[Proposition 6.4]{GWZ24}, we use the $\chi$-independence result for $\GLn$-Higgs bundles by Maulik and Shen \cite[Theorem 0.1]{MS23}. 

    There, it is deduced from \cite[Theorem 0.4]{MS23}, which can be rephrased as an isomorphism in $D^b_{c}(\Aa_{\CC}, \QQ_\ell)$, for $d\in \ZZ$, 
         $$ \bigoplus_{i=0}^{2g'} IC(\wedge^i R^1 \pi_* \QQ_\ell) \xlongrightarrow{\sim} {Rh_{\GLn}}_* {IC_{M_{\GLn}^d, \CC}}  $$
    where $\pi \colon \tilde{\Cc} \longrightarrow \Aa^{\textnormal{sm}}$ is the smooth universal spectral curve of genus $g'$.

    Now, consider the relative Hitchin basis $\Aa \longrightarrow \Spec R$. The work of Hansen and Scholze \cite{Scholze} provides a relative perverse $t$-structure in $D^b_c(\Aa, \QQ_\ell)$ and a well-behaved category of perverse sheaves $Perv^{\text{ULA}}(\Aa/R)$.
    It follows from \cite[Proposition 2.2]{MS23} and \cite[Theorem 1.10]{Scholze} that a morphism 
   \begin{align} \label{morph}
     \bigoplus_{i=0}^{2g'} IC(\wedge^i R^1 \pi_* \QQ_\ell) \longrightarrow {Rh_{\GLn}}_* {IC_{M_{\GLn, R}^d}}  
   \end{align} 
    exists in $Perv^{\text{ULA}}(\Aa/R)$. Moreover, its base change to $\CC$ is an isomorphism \cite[Theorem 0.4]{MS23}. Hence, using the equivalence of categories in \cite[Lemme 6.1.9]{BBD}, there exists a dense open set $B' \longrightarrow B = \Spec R$ such that the restriction of (\ref{morph}) to $B'$ is an isomorphism. 
    Using the compatibilities between perverse $t$-structures in \cite[Theorem 1.1]{Scholze}, for any finite field $k$ with $\Spec k \rightarrow B'$, we obtain an isomorphism over $k$ and a corresponding equality of traces of Frobenius. Repeating for $d=0$ and $d=1$, we get for any $\Spec k \rightarrow B'$. 
    $$\tr (\Fr \ | \ IH_c (M_{\GLn, k}^0, \underline{\QQ}_\ell)) = \tr (\Fr \ | \ IH_c(M_{\GLn, k}^1, \underline{\QQ}_\ell)). $$

    Now, the albanese map gives a splitting \cite[(10)]{felisettiMauri} :
    \begin{align} \label{splitting}
     IH_c(M_{\GLn, k}^d )&\simeq IH_c(M_{\PGLn, k}^d) \otimes H_c (M_{GL_1, k}^d).   
    \end{align} 
    Since $M_{GL_1, k}^0 \simeq M_{GL_1, k}^1$, we get the claim. 
\end{proof}

    We now turn to the rest of the right-hand side in (\ref{degree 1 pgln coho}). Let $\gamma \neq 1 \in  \Gamma$. The $\gamma$-fixed loci have been well studied in the literature and we refer to \cite{NR, HT, MSendoscopicHTcoprime} for an introduction.

\begin{claim}[Remaining terms in (\ref{degree 1 pgln coho})]
    Let $\gamma \neq 1$. Then, for any line bundle $L_1 \in \Pp ic^1_{\Cc/k_F}(k_F)$,  
    \begin{align*}
    \tr (\Fr \ | \ H_c (M_{\SLn, k}^{L_1,\gamma}, \underline{\QQ}_\ell)^\Gamma ) 
    &= \tr (\Fr \ | \ H_c (M_{\SLn, k}^{0,\gamma}, \underline{\QQ}_\ell)_\kappa )
\end{align*}
where $\kappa = \omega(\gamma)$ (Remark \ref{rmk weil pairing}). \end{claim}

\begin{proof}
    Since $n$ is prime, $\gamma$ has order $n$. Let $\Cc_\gamma \xrightarrow{\pi} \Cc$ be the degree $n$ Galois cover corresponding to $\gamma$ and $G$ denote its Galois group. The $\GLn$-Higgs bundles on $\Cc$ fixed by $\gamma$ correspond to push-forwards of line bundles on $\Cc_\gamma$ with a section of $\pi^*D$. The fixed determinant Higgs bundles correspond to a fibre of the Norm map. Since these fibres are all torsors under $Nm^{-1}_{\Cc_\gamma / \Cc}(\Oo_\Cc)$, we get : 
     \begin{align*}
M_{\SLn}^{L_1,\gamma} \big/\Gamma &\simeq \Biggl( \frac{ \Nm^{-1}_{\Cc_\gamma / \Cc}(L_1') \times H^0(\Cc_\gamma, \pi^* D) }{G}  \Biggr) \bigg/ \Gamma \\
   &\simeq \Biggl( \frac{ \Nm^{-1}_{\Cc_\gamma / \Cc}(L_0') \times H^0(\Cc_\gamma, \pi^* D) }{G}  \Biggr) \bigg/ \Gamma \\
   &\simeq  M_{\SLn}^{0,\gamma} \big/\Gamma 
      \end{align*}  
where\footnote{The line bundle $\det(\pi_* \Oo_{\Cc_\gamma})$ is $2$-torsion, it is $L_\gamma^{\frac{n}{2}}$ if $n$ is even and $\Oo_\Cc$ otherwise \cite{HT}.} $L_0' = \det\pi_* \Oo_{\Cc_\gamma}$  and $L_1' = L_1 \otimes \det \pi_* \Oo_{\Cc_\gamma}$. 

However, the isomorphism $Nm^{-1}_{\Cc_\gamma / \Cc}(L_1') \simeq Nm^{-1}_{\Cc_\gamma / \Cc}(L_0')$  is not $G$-equivariant, since $G$ acts cyclically on the components of $Nm^{-1}_{\Cc_\gamma / \Cc}(L_1') $ but fixes the components of $Nm^{-1}_{\Cc_\gamma / \Cc}(L_0')$ \cite[Proposition 3.5]{NR}. Since in the latter case $\Gamma$ acts cyclically on components, the $\Gamma$-representation $H^* (M_{\SLn}^{0,\gamma})$ is regular. Hence, 
\begin{align*}
    \tr (\Fr \ | \ H_c (M_{\SLn, k}^{L_1,\gamma}, \underline{\QQ}_\ell)^\Gamma ) &= \tr (\Fr \ | \ H_c (M_{\SLn, k}^{0,\gamma}, \underline{\QQ}_\ell)^\Gamma ) \\
    &= \tr (\Fr \ | \ H_c (M_{\SLn, k}^{0,\gamma}, \underline{\QQ}_\ell)_\kappa ).
\end{align*}
\end{proof}

 \textit{Step 3.} We use \cite{MSnoncoprime}'s isomorphism (\ref{MSeq}). The morphism $$c_\kappa \colon (Rh_{\SLn,*} IC_{M_{\SLn}^{0}})_{\kappa} \longrightarrow {i_\gamma}_* (R{h_\gamma}_* IC _{M_{\SLn}^{0, \gamma}})_{\kappa} [-F_\gamma] $$ is of geometric nature, being constructed as a combination of algebraic correspondences \cite[§0.3]{MS23}. 
Hence, the morphism exists over $B = \Spec R$, and its base change to $\CC$ is an isomorphism. By spreading out, there exists an open $B'' \subset B$, such that for all $\Spec k \longrightarrow B''$, 
$$c_{\kappa, k} \colon (Rh_{\SLn,*} IC _{M_{\SLn, k}^{0}})_{\kappa} \xlongrightarrow{\sim} {i_\gamma}_* (R{h_\gamma}_* IC _{M_{\SLn, k}^{0, \gamma}})_{\kappa} [-F_\gamma] $$
is an isomorphism. 

Finally, we can consider an open set $\tilde{B}$ contained in $B'$ and $B''$. Then, for $\Spec k_F \longrightarrow \tilde{B}$: 

\begin{align*}
    \int_{M_{\SLn}^{0}(\Oo_F)^\sharp} f_{\alpha} \ \mu_{\can}  &= q^{- \dim M_{\PGLn}^0} \cdot \bigg( \tr (\Fr \ | \ IH_c(M_{\PGLn,k_F}^0, \underline{\QQ}_\ell)) + \sum_{\gamma \neq 1}  \tr (\Fr \ | \ H_c^{* -F_\gamma}(M_{\SLn,k_F}^{0,\gamma}, \underline{\QQ}_\ell)_\kappa) \bigg) \\
    % &=  q^{- \dim M_{\SLn}^0} \sum_{\gamma \in \Gamma} \tr (\Fr \ | \ IH_c^{* -F_\gamma}(M_{\SLn, k_F}^{0,\gamma}, \underline{\QQ}_\ell)_\kappa) \\
    &= q^{- \dim M_{\SLn}^0} \sum_{\gamma \in \Gamma} \tr (\Fr \ | \ IH_c(M_{\SLn, k_F}^{0}, \underline{\QQ}_\ell)_\kappa) \\
    &= q^{- \dim M_{\SLn}^0} \tr (\Fr \ | \ IH_c(M_{\SLn, k_F}^{0}, \underline{\QQ}_\ell)).
\end{align*}
\end{proof}

\begin{remark}
    We could weaken our assumptions by assuming that $n$ is an odd prime and $D$ arbitrary, since for odd $n$, $d' \equiv d \mod n$. Also, instead of $L = N^{d}$ we could assume that $L\otimes N^{- d}$ has a $\mathit{n}$th root. Finally, we expect that the proof extends to the case where $n$ is not prime, but it requires to control $G$-equivariance in the $\chi$-independence isomorphisms.
\end{remark}

\begin{remark}
    The same argument using our refinement (\autoref{fourier}) shows that under the same hypothesis, for $\kappa \in \hat{\Gamma}$,
    $$  \frac{1}{ |\Gamma|} \sum_{\nu \in \Gamma} \Big( \int_{M_{\SLn}^{L_\nu} (\Oo_F)^\sharp} f_{\alpha}^{e'} \ \mu_{\can} \Big) \kappa(\nu)  = q^{- \dim M_{\SLn}^0} \tr (\Fr \ | \ IH_c(M_{\SLn, k_F}^0, \underline{\QQ}_\ell)_{\kappa}).$$
\end{remark}


\subsection{Link to BPS cohomology when \texorpdfstring{$D = K$}{D=K}.} In this subsection we discuss a possible link between \autoref{mainthm} and the recent Hausel--Thaddeus type conjecture formulated in terms of BPS cohomology \cite{Davison}. It is speculative because the $BPS$ sheaf has not yet be constructed as $\ell$-adic sheaf. 


Focusing on the case where $D=K_{\Cc}$, \autoref{mainthm} reads, for all $ d, e \in \ZZ/n\ZZ$,
 \begin{align} \label{p-adic D=K}
     \int_{M_{\SLn}^{L}(\Oo_F)^\sharp} f_\alpha^e  \ \mu_{\can} &= 
    \int_{M^e_{\PGLn}(\Oo_F)^\sharp} f_{\alpha_N}^d   \ \mu_{\can}
 \end{align}
 where $L \in \Pp ic^d(\Cc)$, assuming that $L\otimes N^{-d}$ has a $\mathit{n}$th root. 

In \cite{Davison}, authors construct a perverse sheaf $\phi_{BPS}$ on the good moduli space of the loop stacks $\Ll \Mm_{\SLn}^{L}$ and $\Ll \Mm_{\PGLn}^e$. The Euler characteristic specialises to invariants related to counting of $BPS$ (for Bogomol'nyi--Prasad--Sommerfield) states in physics, as explained in \cite[\textsection 1.2.14]{Davison}

They propose a Hausel--Thaddeus-type conjecture \cite[Conjecture 10.3.25]{Davison} which reads :  
\begin{equation} \label{BPSconj}
    H^*_{BPS} (\Ll M_{\SLn}^{L})_e \simeq H^*_{BPS} (\Ll M_{\PGLn}^{e})_d
\end{equation} 
where $\Ll M_{\SLn}^{L}$ denote the good moduli space of the loop stack $\Ll \Mm_{\SLn}^{L}$ and similarly for $\PGLn$. 

The $BPS$ cohomology of $\Ll M_{\SLn}^{L}$ inherits a $Z(\SLn) = \mu_n$ action. Interpreting $e$ as a character of $\mu_n$, $H^*_{BPS} (\Ll M_{\SLn}^{L})$ decomposes into a sum of isotypical components denoted $H^*_{BPS} (\Ll M_{\SLn}^{L})_e$. A similar decomposition is constructed on the $\PGLn$ side in \cite[Subsection 10.3.24]{Davison}. 

