% \subsection{Comparison of gerbes in \cite{HT} and \cite{GWZ}} 

Let $S = \Spec k$ for a field $k$. As before, pick a curve $\Cc$ over $S$, line bundles $L, D$ over $\Cc$ and consider the coarse moduli space of determinant $L$, traceless semi-stable Higgs bundles $M^L_{\SLn}$. There are two ways to describe $M^L_{\SLn}$ as a good moduli space of a stack endowed with a $\mu_n$-gerbe. As before, we consider gerbes with respect to the étale topology. 

\begin{Construction}
    This construction was used in \cite{GWZ} and the present work. Recall the stack $\Mm_{\SLn}^L$ whose objects are :
    \begin{align*}
    \Ob(\Mm_{\SLn}^L(T)) = \Bigg\{ (E, \phi) \ &| \ E \in \Vv ec_n(\Cc)(T), \  \phi \in H^0(\Cc, \mathfrak{sl}_n(E)\otimes D), \\
                                    & \ \text{semi-stable}, \ \det(E) \simeq q^*L \in \Pp ic_{C \times_S T/S}^d  (S) \Bigg\} 
\end{align*} 
where $q \colon T \times_S \Cc \longrightarrow \Cc$. The gerbe $\alpha_n$ is given by the $\mu_n$-rigidification defined in \cite{ACV}, 
$$\Mm_{\SLn}^L \xrightarrow{\alpha_n} \Mm_{\SLn}^{L,\rig},$$
which is obtained by removing the scalar action from the automorphisms.
\end{Construction}



\begin{Construction}
This construction appears in \cite{HT}. Note that in the coprime case, $\Mm_{\SLn}^{L, \rig} \simeq M^L_{\SLn}$. Fix a basepoint $\varepsilon \in \Cc(S)$. There is a universal projective bundle $\PP\EE$ over $\Cc \times \Mm_{\SLn}^{L, \rig}$. Take  $U \longrightarrow \Mm_{\SLn}^{L,\rig}$. Then, let $\alpha_{HT}$ be the stack defined by :
$$ \Ob ( \alpha_{HT}(U)) = \big\{  \EE^{\varepsilon}_{U} \in \Bb un_{\SLn}(U) \ | \ \PP(\EE^{\varepsilon}_{U}) \simeq \varepsilon^*\PP\EE_{|U} \big\}.$$ 
We call $\EE^{\varepsilon}_{U}$ a lift over $U$. Isomorphisms between lifts over $U$ are given by $\mu_n$-torsors over $U$. The étale-local existence of lifts means that $\alpha_{HT}$ is an étale $\mu_n$-gerbe. 
\end{Construction}

\begin{remark}
    Using the seesaw principle, it is equivalent to rephrase the condition $\det(E) \simeq q^*L$ in $\Ob(\Mm_{\SLn}^L(T))$ as $\forall \ t \in |T|, \  \det(t^*E) \simeq L \in \Pp ic^d  (\Cc) \text{ and } \det(\varepsilon^*E) \simeq \Oo_T $. The latter is used in \cite{HT}. 
\end{remark}

\begin{lemma}
Both gerbes are isomorphic, i.e. there is a commuting diagram :
$$\begin{tikzcd}
    \Mm_{\SLn}^L \arrow[dr, "\alpha_n"] \arrow[rr, "\sim"] & & \alpha_{HT} \arrow[dl] \\
    &\Mm_{\SLn}^{L,\rig} &
\end{tikzcd}$$
\end{lemma}

\begin{proof}
A section of $\alpha_n$ over $U \longrightarrow \Mm_{\SLn}^{L,\rig}$ gives a universal (Higgs) bundle $\EE_U$ of determinant $q^*L \in \Pp ic(\Cc \times U )$. Then, $\det(\varepsilon^* \EE_U) \simeq \Oo_U$, and the universality implies that the projectivisation of $\EE_U$ is $\PP\EE_{|U}$. Hence, $\varepsilon^* \EE_U$ provides a section of $\alpha_{HT}$ over $U$. We just constructed a map of $\mu_n$-gerbes $\alpha_n \longrightarrow \alpha_{HT}$. As for torsors, a map between $\mu_n$-gerbes is necessarily an isomorphism. 
\end{proof}

