Here, we provide some additional results pertaining to the pair propagator asymptotic error analysis that were omitted from the main text for the sake of brevity. 

\subsection{Green's Function Differential Equation} \label{supp_sect_a}
In the main text, we use the following differential equation for the quotient ($F(\vecphi, \vecphi', \tau)$) given by dividing the density matrix elements corresponding to the full Hamiltonian ($\rho(\vecphi, \vecphi', \tau)$) by the free propagator matrix elements (($\rho_0(\vecphi, \vecphi', \tau)$),
\begin{equation}
    \left(\frac{\partial}{\partial \tau} - \Delta_{\vecphi} - 2 \frac{\nabla_{\vecphi} \rho_0}{\rho_0} \cdot \nabla_{\vecphi} + V\right) F = 0, \ \ F = \rho/\rho_0 \label{green_diff_eq_supp}
\end{equation}
This can be derived using the Bloch equation for the free and the full propagators,  
\begin{gather}
    \left(\frac{\partial}{\partial \tau} + H\right) \rho(\vecphi, \vecphi', \tau) = 0, \ \ \lim_{\tau \rightarrow 0} \rho(\vecphi, \vecphi', \tau) = \delta(\vecphi - \vecphi') \label{full_H_bloch_supp}\\ \left(\frac{\partial}{\partial \tau} + K\right) \rho_0(\vecphi, \vecphi', \tau) = 0 
    , \ \ \lim_{\tau \rightarrow 0} \rho_0(\vecphi, \vecphi', \tau) = \delta(\vecphi - \vecphi') \label{free_H_bloch_supp}
\end{gather}
To see this, note that $H = K + V$ and $K = -\Delta_{\vecphi}$. Moreover, using our ansatz, we have that $\rho = F \rho_0$. Using this with Eq. \eqref{full_H_bloch_supp}, we get, 
\begin{equation}
    F \left(\frac{\partial \rho_0}{\partial \tau} - \Delta_\vecphi (\rho_0)\right) + \frac{\partial F}{\partial \tau} \rho_0 - \rho_0 \Delta_\vecphi (F) - 2 \nabla_{\vecphi} (\rho_0) \cdot \nabla_{\vecphi} (F) + V F \rho_0 = 0 \label{intermediate_1_supp}
\end{equation}
Eq. \eqref{free_H_bloch_supp} implies that the first term in the above equation is $0$. Dividing the resulting equation by $\rho_0$ yields Eq. \eqref{green_diff_eq_supp}. 

\subsection{Rotational Free Propagator Asymptotics} \label{supp_sect_b}
The many-body free propagator is a product of single particle free propagators which yields, 
\begin{gather}
    \rho_0 (\vecphi, \vecphi', \tau) = \prod_{i=1}^{N} \rho_0^{(1)}(\phi^i, \phi'^i, \tau) \nonumber
    \Rightarrow \left(\frac{\nabla_{\vecphi} \rho_0}{\rho_0}\right)_{j} = \frac{1}{\rho_0^{(1)} (\phi^j, \phi'^j, \tau)}\frac{\partial \rho_{0}^{(1)} }{\partial \phi_j} (\phi^j, \phi'^j, \tau)
\end{gather}
where $\rho_{0}^{(1)}$ is the single rotor free propagator. Using properties of Jacobi-Theta functions, it can be shown that, \cite{Whittaker_Watson_1996}  
\begin{equation}
     \left(\frac{\nabla_{\vecphi} \rho_0}{\rho_0}\right)_{j} = \sum_{n=1}^\infty (-1)^n \csch(\tau n) \sin(n (\phi^j-\phi'^j))
\end{equation}
Since we want an asymptotic expansion in $\tau$, we can use the series expansion of $\csch(n\tau)$ and retain the first non-trivial term to get:
\begin{equation}
    \left(\frac{\nabla_{\vecphi} \rho_0}{\rho_0}\right)_{j} \approx \frac{1}{\tau}\sum_{n=1}^{\infty} (-1)^n\frac{\sin(n (\phi^j-\phi'^j))}{n} 
\end{equation}
The above equation is just the Fourier series of the saw-tooth function divided by $\tau$ which, when restricted to $[-\pi, \pi)$ becomes: 
\begin{equation}
    \left(\frac{\nabla_{\vecphi} \rho_0}{\rho_0}\right)_{j} \approx -\frac{1}{2\tau} (\phi^j - \phi'^j) 
\end{equation}

\subsection{Second Term  Of The Wigner-Kirkwood Expansion} \label{supp_sect_c}
As discussed in the main text, Eq. \eqref{green_diff_eq_supp}, can be solved recursively using the Perelomov relation, 
\begin{gather} \label{Perelomov_recursion_supp}
    P_n(\vecphi, \vecphi') = n \int_0^1 dt \ t^{n-1} V(\vectheta(t)) P_{n-1}(\vectheta(t), \vecphi') - n \int_0^1 dt \ t^{n-1} \Delta_\vectheta P_{n-1}(\vectheta(t), \vecphi') 
\end{gather}
where $P_n$ is the $n$th term in the series expansion of $F$ in powers of $\tau$ ($F = \sum_{n} \frac{(-\tau)^n}{n!} P_n(\vecphi, \vecphi')$). Using Perelomov's recursion relation for $n=1$ and $n=2$ gives,  
\begin{gather}
    P_1(\vecphi, \vecphi') = \sum_{i=1}^{N-1}\int_{0}^{1} V_{i,i+1}(\vectheta(t)) \ dt = \sum_{i=1}^{N-1} W_{i, i+1} (\vecphi, \vecphi') \\
    P_2(\vecphi, \vecphi') = 2 \sum_{i, j=1}^{N-1}\int_0^1 dt \ t \ V_{i, i+1} W_{j, j+1}
    - 2\sum_{i=1}^{N-1} \int_0^1 dt \ t \left(\frac{\partial^2 W_{i, i+1}}{\partial \theta_i^2} + \frac{\partial^2 W_{i, i+1}}{\partial \theta_{i+1}^2}\right) \label{P_2_eqn_1_supp}
\end{gather}
where, $V_{i,i+1}=V_{i, i+1}(\vectheta(t))$, $W_{j,j+1}=W_{j,j+1}(\vectheta(t), \vecphi')$ in the above equation. We can simplify the above expression for $P_2$. To see this, define $I_{ij}$ to be a single term in the first summation of Eq. \eqref{P_2_eqn_1_supp}, 
\begin{equation}
    I_{ij} = \int_0^1 dt \ t \ V_{i, i+1}(\vectheta(t)) W_{j, j+1}(\vectheta(t), \vecphi') \label{I_i_j_eqn_supp}
\end{equation}
Using the definition of $W_{j,j+1}(\vectheta(t), \vecphi')$ where $\vectheta(t)$ represents a point on the line between $\vecphi$ and $\vecphi'$, we get, 
\begin{equation}
    W_{j,j+1}(\vectheta(t), \vecphi') = \frac{1}{t} \int_0^t V_{j,j+1}(\vectheta(t')) dt' \label{W_eqn_intermediate_supp}
\end{equation}
Using Eq. \eqref{W_eqn_intermediate_supp} and integrating Eq. \eqref{I_i_j_eqn_supp} by parts yields: 
\begin{gather}
    I_{ij} + I_{ji} = W_{i,i+1}W_{j,j+1}, \ \ I_{jj} = \frac{W_{j,j+1}^2}{2} \\ \Rightarrow 2\sum_{i,j=1}^{N-1} I_{ij} = 2\sum_{i<j}^{N-1} (I_{ij} + I_{ji}) + 2\sum_{j=1}^{N-1} I_{jj} = \sum_{j=1}^{N-1} W_{j,j+1}^2 + 2\sum_{i<j}^{N-1} W_{i,i+1}W_{j,j+1} \label{P_2_eqn_2_supp}
\end{gather} 
This gives the equation for $P_2$ provided in the main text, 
\begin{equation}
    P_2(\vecphi, \vecphi') = \sum_{j=1}^{N-1} W_{j,j+1}^2 + 2\sum_{i<j}^{N-1} W_{i,i+1}W_{j,j+1} 
    - 2\sum_{i=1}^{N-1} \int_0^1 dt \ t \left(\frac{\partial^2 W_{i, i+1}}{\partial \theta_i^2} + \frac{\partial^2 W_{i, i+1}}{\partial \theta_{i+1}^2}\right)
\end{equation}

\subsection{Pair Density Error} \label{supp_sect_d}

The diagonal terms ($\vecphi = \vecphi'$) of the Wigner-Kirkwood expansion are \cite{WK_expansion2}: 
\begin{gather}
    P_1 = V\\
    P_2 = V - \frac{1}{3}\Delta V\\
    P_3 = V^3 - V \Delta_{\vecphi} V - \frac{1}{2} (\nabla_\vecphi V)^2 + \frac{1}{10} \Delta_{\vecphi}^2 V \label{P_3_diag_eqn_supp}
\end{gather}
We can express $V^3$ from $P_3$ as follows: 
\begin{gather}
    V^3 = \sum_{n}V_{n,n+1}^3 + 6\sum_{n<m<l} V_{n,n+1}V_{m,m+1}V_{l,l+1} + 3 \sum_{n<m}(V_{n,n+1}^2V_{m,m+1} + V_{m_m+1}^2V_{n,n+1})
\end{gather}
$V\Delta_\vecphi V$ can be expressed as: 
\begin{gather}
    V \Delta_\vecphi V = \sum_{n} V_{n,n+1} (\Delta V)_{n,n+1} + \sum_{n<m} (V_{n,n+1} (\Delta V)_{m,m+1} + V_{m,m+1} (\Delta V)_{n,n+1}) \label{V_delta_V_supp}
\end{gather}
where we have used the notation: 
\begin{equation}
    (\Delta V)_{m,m+1} = \frac{\partial^2 V_{m,m+1}}{\partial \phi_m^2} + \frac{\partial ^2 V_{m,m+1}}{\partial \phi_{m+1}^2}
\end{equation}
Moreover, the bi-laplacian term $\Delta_{\vecphi}^2V$ is given by: 
\begin{gather}
    \Delta_{\vecphi}^2V = \sum_{m} (\Delta^2V)_{m,m+1} \\(\Delta^2V)_{m,m+1} = \frac{\partial^2 (\Delta V)_{m,m+1}}{\partial \phi_m^2} + \frac{\partial ^2 (\Delta V)_{m,m+1}}{\partial \phi_{m+1}^2}
\end{gather}
To compare $P_3(\vecphi, \vecphi)$ and $Q_3(\vecphi, \vecphi)$, first note that:
\begin{gather}
    Q_3 = \sum_{n=1}^{N-1} P_{3,n}^{(2)} + 6\sum_{n<m<l}P_{1,n}^{(2)}P_{1,m}^{(2)}P_{1,l}^{(2)} + \ 3\sum_{n<m}^{N-1} (P_{2,n}^{(2)}P_{1,m}^{(2)} + P_{1,n}^{(2)}P_{2,m}^{(2)}) \label{Q_3_eqn_supp}
\end{gather}
The first term in Eq. \eqref{Q_3_eqn_supp} can be expressed as, 
\begin{gather}
    \sum_{n}P_{3,n}^{(2)} = \sum_{n} (V_{n,n+1}^3 - V_{n,n+1} (\Delta V)_{n,n+1}) + \frac{1}{10}\sum_{n} (\Delta^2V)_{n,n+1} \nonumber \\ - \frac{1}{2}\sum_{n} \left( (\nabla V_{n,n+1})_{n}^2 +  (\nabla V_{n,n+1})_{n+1}^2\right)
\end{gather}
where $(\nabla V_{n,n+1})_{n}^2= (\partial_n V_{n,n+1})^2$ ($\partial_n$ here represents the derivative with respect to $\phi_n$). The second term in Eq. \eqref{Q_3_eqn_supp} can be written as, 
\begin{gather}
6\sum_{n<m<l}P_{1,n}^{(2)}P_{1,m}^{(2)}P_{1,l}^{(2)} = 6\sum_{n<m<l} V_{n,n+1}V_{m,m+1}V_{l,l+1} 
\end{gather}
The final term in Eq. \eqref{Q_3_eqn_supp} can be written as, 
\begin{gather}
3\sum_{n<m}^{N-1} (P_{2,n}^{(2)}P_{1,m}^{(2)} + P_{1,n}^{(2)}P_{2,m}^{(2)}) = 3 \sum_{n<m}(V_{n,n+1}^2V_{m,m+1} + V_{m_m+1}^2V_{n,n+1}) \nonumber \\ - \sum_{n<m} (V_{n,n+1} (\Delta V)_{m,m+1} + V_{m,m+1} (\Delta V)_{n,n+1})
\end{gather}
Using these, we find that $P_3$ and $Q_3$ agree for all terms in equation $\eqref{P_3_diag_eqn_supp}$ except for $-(\nabla_{\vecphi} V)^2/2$. The exact difference between $P_3$ and $Q_3$ is:
\begin{equation}
    P_3 - Q_3 = -\sum_{n=2}^{N-1} (\nabla V_{n-1,n})_{n} (\nabla V_{n,n+1})_{n} \neq 0 \label{P_3_error_term_supp}
\end{equation}
where we have used: 
\begin{gather}
    (\nabla_{\vecphi} V)^2 = \sum_{n=1}^{N-1} \left( (\nabla V_{n,n+1})_{n}^2 + (\nabla V_{n,n+1})_{n+1}^2\right) + 2 \sum_{n=2}^{N-1} (\nabla V_{n-1,n})_{n} (\nabla V_{n,n+1})_{n}
\end{gather}
Eq. \eqref{P_3_error_term_supp} is the error term provided in the main text. 



