        Then let 
        \[\Psi(i,j)=\left\{\begin{array}{cc}
             \Phi_f(i,j)&i>n \text{ and for some }f\in A\text{, }  f(i)\geq j\\
             0&\text{otherwise} 
        \end{array}\right.\]
        $\Psi$ trivializes $\Phi$ since for each $f\in\omega^\omega$, we may find $g\in A$ and $m<\omega$ such that $f<^mg$ so that
        whenever $i\geq m$, $j\geq m$, and $\Phi_f(i,j)=\Phi_g(i,j)$, $\Psi(i,j)=\Phi_f(i,j)$.

    \end{proof}
    Now, for each $i$ with $s^\frown i\in q$, fix an $f_i$ such that for all $n<\omega$, $q^{[s^\frown i]}\not\Vdash\dot\Psi=^n\Phi_f$. 
    Let $f_s$ be a $<^*$ upper bound for $\{f_i\mid s^\frown i\in q\}$. 
    Then whenever $s^\frown i\in q$ and $n<\omega$, $q^{[s^\frown i]}\not\Vdash \dot\Psi=^n\Phi_{f_s}$. 
    Now, recursively define $q_i\leq q^{[s^\frown i]}$ and $n_i$ as in the claim, first forcing that $\dot\Psi\neq^{\max_{j<i}n_j}\Phi_f$ and then using that $\dot\Psi$ is forced to be a trivialization of $\Phi$ to decide some $n_i$ with $\dot\Psi=^{n_i}\Phi_f$. 
    Then $\bigcup_{i\in\operatorname{succ}_q(s)}q_i$ is a condition extending $q$ which still has $s$ as a splitting node and $f_s$ and $\langle n_i\rangle$ satisfy the Claim \ref{miller_pres_clm}. 
    \end{enumerate}
\end{proof}
