\section{Preliminaries: Katz-Stapledon decomposition formulas} \label{ks_decomp_rec_sec}

In this section we recall (lower) Eulerian posets that abstract face posets of polytopes and their $h$- and $g$-polynomials. We recall $h^*$- and local $h^*$-polynomials of polytopes coming from the Ehrhart theory. We also recall the local $h$-polynomials of strong formal subdivisions and Katz-Stapledon decomposition formulas from \cite{KS16}.

For an introduction to posets (partially ordered sets) see \cite{Stan}. For surveys on the local $h$-polynomial of triangulations of simplices see \cite{Cha} and \cite{Ath}. For a survey on the local $h$-polynomials of polyhedral subdivisions and Katz-Stapledon decomposition formulas see \cite[\S 2]{BKN24}. For an introduction to the Ehrhart theory including $h^*$-polynomial see \cite{BR07}. For a survey on local $h^*$-polynomials see \cite[\S 2]{BKN24}.

\subsection{Eulerian posets, $h$- and $g$-polynomial}

\begin{definition}
    The dual of a finite poset $\mathcal{P}$ is denoted $\mathcal{P}^\ast$. A finite poset $\mathcal{P}$ is \textbf{locally graded} if every inclusion-maximal chain in every interval $[x,y]$ has the same length $r(x,y)$. The \textbf{rank} $\rk(\mathcal{P})$ is the length of the longest chain in $\mathcal{P}$. If in addition there exists a rank function $\rho: \mathcal{P} \rightarrow \Z$, i.e., $r(x,y) = \rho(y) - \rho(x)$ for every interval $[x,y]$, then $\mathcal{P}$ is called \textbf{ranked}. If $\mathcal{P}$ is ranked and every interval $[x,y]$ with $x \neq y$ has the same number of even rank and odd rank elements, then $\mathcal{P}$ is \textbf{locally Eulerian}. If $\mathcal{P}$ is locally Eulerian and contains a minimal element $\hat{0}$, then it is called \textbf{lower Eulerian}. If it also contains a maximum $\hat{1}$, then $\mathcal{P}$ is called \textbf{Eulerian}. In presence of a minimum $\hat{0}$ in a ranked poset $\mathcal{P}$, we will always assume that the rank function satisfies $\rho(\hat{0}) = 0$.
\end{definition}



\begin{remark}
    We use the notations of $g$- and $h$-polynomials from \cite{KS16}. Unfortunately, these notations are a bit different in different literature. For more details, see \cite[Remark 2.6.]{BKN24}.
\end{remark}

\begin{definition}\label{d:g}
Let $B$ be an Eulerian poset of rank $n$. If $n = 0$, 
then $g(B;t) = 1$. If $n > 0$, then $g(B;t)\in\Z[t]$ is the unique polynomial in $t$ 
of degree strictly less the $n/2$ satisfying
\[
t^{n}g(B;t^{-1}) = \sum_{x \in B} g([\hat{0}_B,x];t) (t - 1)^{n - \rho(\hat{0}_B,x)}. 
\]
\end{definition}

\begin{remark}
    (see e.g. \cite[Example 3.8.]{KS16}). The constant term of $g(B;t)$ is $g(B;0) = 1$. The linear coefficient of $g(B;t)$ is $\#\{x \in B | \rho(\hat 0_B,x) = 1\} - n$.
\end{remark}

\begin{remark} (see e.g. \cite[Example 3.9.]{KS16}) \label{g=1_rem}
    One can verify that $g(B;t) = 1$ if and only if $B$ is a Boolean algebra.
\end{remark} 


\begin{definition}\label{d:hpoly}\cite[Example~7.2]{Stan92}
Let $B$ be a lower Eulerian poset of rank $n$. Then the \textbf{$h$-polynomial} of $B$ is defined by
\[
t^n h(B;t^{-1}) = \sum_{x \in B}  g([\hat{0}_B,x];t) (t - 1)^{n - \rho(\hat{0}_B,x)}.
\]
\end{definition}

\begin{remark}(see e.g. \cite[Example 3.13]{KS16})
Let $B$ be a lower Eulerian poset of rank $n$. Then the constant term of $h(B;t)$ is $h(B;0) = 1$, and the linear coefficient of $h(B;t)$ is $\#\{x \in B | \rho(\hat 0_B,x) = 1\} - n$.
\end{remark}

\begin{claim}\label{h_out_top_ut}
If $B$ is an Eulerian poset of rank $n$, then comparison of the recursive formulas in Definition~\ref{d:g} and Definition~\ref{d:hpoly} implies that $h(B;t) = g(B;t)$. 
 If, furthermore, $n > 0$, then $B \setminus \{ \hat{1} \}$ is a %pure, 
 lower Eulerian poset of rank $n - 1$, and 
\[
(1 - t) h(B \setminus \{ \hat{1} \};t) =  g(B;t) - t^ng(B;t^{-1}).
\]
In particular, $h(B \setminus \{ \hat{1} \};t)$ is a polynomial of degree $n - 1$ with symmetric coefficients.
\end{claim}


\begin{ex}\label{face_pos_ex}
The poset of faces of a polytope $P$ (including the empty face) is an Eulerian poset under inclusion, called the \textbf{face poset} $\Pd$ of $P$, with $\rho (Q) = \dim Q + 1$ for every face $Q$ of $P$. The poset of faces of a cone $C$ (excluding the empty face) is an Eulerian poset under inclusion, called the \textbf{face poset} $\Cp$ of $C$, with $\rho (F) = \dim F$ for every face $F$ of $C$. If the cone $C$ is sharp then its face poset coincides with the face poset of the polytope in its hyperplane section.
\end{ex}

The $h$-polynomial of the face poset of rational polytopes computes the intersection cohomology groups of the corresponding toric varieties, see \cite[Theorem 3.1]{Stan87}. Together with the results concerning the non-rational case from \cite{Kar04} (recall that there are non-rational polytopes which are not combinatorially equivalent to any rational polytopes, see e.g. \cite{Zie08}) this implies the following theorem.

\begin{theorem}(see e.g. \cite[Theorem 2.8]{BKN24})
    Let $P$ be a polytope of dimension $n$. Then 
    $$h (\Pd;t) = \sum_{i=0}^n h_i t^i$$
    is a palindromic polynomial with positive integer coefficients that form a unimodal sequence, i.e., $1 =h_0 \le h_1 \le \dots \le h_{\lfloor d /2\rfloor}$. Equivalently, $g(\Pd;t)$ has non-negative coefficients.
\end{theorem}

\subsection{Local $h$-polynomials of strong formal subdivisions} \label{loc_h_strong_formal_subsec}

Strong formal subdivisions abstract polyhedral subdivisions. In this subsection we recall the Katz-Stapledon decomposition formulas for the local $h$-polynomial of strong formal subdivisions from \cite{KS16}.

A function $f: \Gamma \rightarrow B$ between finite posets is \define{order-preserving} if $y \le y' \in \Gamma$ implies $f(y) \le f(y') \in B$.
If $(\Gamma,r_\Gamma)$ and $(B,r_B)$ are ranked posets, then a function  $f: \Gamma \rightarrow B$ is \define{rank-increasing} if $r_\Gamma(y) \le r_B(f(y))$ for all $y \in \Gamma$. 
Throughout, we let $\sigma: \Gamma \rightarrow B$ be an order-preserving, rank-increasing function  between locally Eulerian posets with rank functions $\rho_\Gamma$ and $\rho_B$ respectively. 
\begin{definition}
Consider an order-preserving  function $\sigma: \Gamma \rightarrow B$ between locally Eulerian posets. Then for all $y \in \Gamma$ and $x \in B$ such that $\sigma(y) \le x$, we may 
consider the lower Eulerian posets $\Gamma_{\ge y} := \{ y' \in \Gamma \mid y \le y' \}$ and $(\Gamma_{\ge y})_x := \{ y' \in \Gamma \mid y \le y', \sigma(y') \le x \}$, and the locally Eulerian poset 
$\IInt((\Gamma_{\ge y})_x):=\sigma^{-1}(x) \cap (\Gamma_{\ge y})_x$.   If $\Gamma$ is lower Eulerian, then we write $\Gamma_x  := (\Gamma_{\ge \hat{0}_\Gamma})_x$ and 
 $\IInt(\Gamma_x)  := \IInt((\Gamma_{\ge \hat{0}_\Gamma})_x)$.
%$\IInt(\Gamma_x)=\sigma^{-1}(x)$.   
%For a lower Eulerian poset, we will use $\Gamma_x$ to denote $(\Gamma_{\geq \hat{0}})_x$.
\end{definition}

\begin{definition}
Let $\sigma: \Gamma \rightarrow B$ be an order-preserving, rank-increasing function  between locally Eulerian posets with rank functions $\rho_\Gamma$ and $\rho_B$ respectively. 
Then $\sigma$ is \define{strongly surjective} if it is surjective and for all $y \in \Gamma$ and $x \in B$ such that $\sigma(y) \le x$, there exists $y \le y' \in \Gamma$ such that $\rho_\Gamma(y') = \rho_B(x)$ and $\sigma(y') = x$. 
\end{definition}

The following definition abstracts polyhedral subdivisions. The property of subdivisions that is abstracted is that the subdivision of the relative interior of a polytope has Euler characteristic equal to $1$.

\begin{definition}\label{strong_formal_def}
    Let $\sigma: \Gamma \rightarrow B$ be an order-preserving, rank-increasing function  between locally Eulerian posets with rank functions $\rho_\Gamma$ and $\rho_B$ respectively. 
Then $\sigma$ is a \textbf{strong formal subdivision} if it is strongly surjective and  for all $y \in \Gamma$ and $x \in B$ such that $\sigma(y) \le x$,
$$
\sum_{ \substack{y \le y'\\ \sigma(y') = x}} (-1)^{\rho_B(x) - \rho_\Gamma(y')} = 1.
$$
If $\Gamma$ and $B$ are lower Eulerian, then it follows that $\sigma(\hat{0}_\Gamma) = \hat{0}_B$, and the \textbf{rank} $\rk(\sigma) \in \Z_{\ge 0}$ of $\sigma$ is defined to be $\rk(\sigma) := \rho_B(\hat{0}_B) - \rho_\Gamma(\hat{0}_\Gamma)$. Alternatively, it follows from the fact that $\sigma$ is rank-increasing and strongly surjective that $\rk(\sigma) = \rk(\Gamma)-\rk(B)$.
\end{definition}



\begin{definition} \cite[Definition 4.1]{KS16}\label{d:localpoly} 
Let $\sigma: \Gamma \rightarrow B$ be a strong formal subdivision  between a lower  Eulerian poset $\Gamma$ and an Eulerian poset $B$. % with rank functions $\rho_\Gamma$ and $\rho_B$ respectively.
Then the  \textbf{local $\mathbf {h}$-polynomial} $l_B(\Gamma;t) \in \Z[t]$ is defined by
\[
l_B(\Gamma;t) = \sum_{ x \in B } h(\Gamma_{x};t) (-1)^{\rho_B(x,\hat{1}_B)} g([x,\hat{1}_B]^*;t).
\]
We also introduce the following useful notation. 
Let $\sigma: \Gamma \rightarrow B$ be a strong formal subdivision  between locally Eulerian posets with rank functions $\rho_\Gamma$ and $\rho_B$ respectively, and 
fix $y \in \Gamma$ and  $x \in B$. %We define the associated  local $h$-polynomial $l_B(\Gamma,x,y;t) \in \Z[t]$ as follows:
If $\sigma(y) \le x$, then we may the restricted strong formal subdivision 
$\sigma: (\Gamma_{\ge y})_x \rightarrow [ \sigma(y),x]$. In this case we set %define %In this case, we define 
\[
l_B(\Gamma,x,y;t) := l_{[ \sigma(y),x]}((\Gamma_{\ge y})_x;t) = \sum_{\sigma(y) \le x' \le x} h((\Gamma_{\ge y})_{x'};t) (-1)^{\rho_B(x',x)} g([x',x]^*;t). 
\]
We set $l_B(\Gamma,x,y;t) = 0$ if $\sigma(y) \nleq x$. 
\end{definition}

\begin{sign}
We say that polynomial $f(t)$ has symmetric coefficients centered at $d \in \Z /2$ if $$f(t) = t^{2k}f(t^{-1})$$
\end{sign}

\begin{cor}\cite[Corollary 4.5.]{KS16}\label{loc_h_sym_cor}
     Let $\sigma: \Gamma \to B$ be a strong formal subdivision between a lower Eulerian poset $\Gamma$ of rank $r$ and an Eulerian poset $B$. Then the local $h$-polynomial $\ell_B(\Gamma;t)$ has symmetric coefficients centered at $r/2$.
\end{cor}



\begin{remark}\label{r:reverseh}
Let $\sigma: \Gamma \rightarrow B$ be a strong formal subdivision  between a lower  Eulerian poset $\Gamma$ and an Eulerian poset $B$. % with rank functions $\rho_\Gamma$ and $\rho_B$ respectively.
We recover the $h$-polynomial of $\Gamma$ via:
\[
h(\Gamma;t)= \sum_{ x \in B }  \ell_B (\Gamma, x,\hat 0_\Gamma;t) g([x,\hat{1}_B];t).
\]
\end{remark}

\begin{cor}(Katz-Stapledon decomposition of local $h$-polynomial)\cite[Corollary 4.7.]{KS16} \label{c:hrefine}
Let  $\tau: \Omega  \rightarrow  \Gamma$ and let $\sigma: \Gamma \rightarrow B$ be strong formal subdivisions lower Eulerian posets $\Omega,\Gamma$ and Eulerian poset $B$. Then for $z\in\Omega$, $x\in\Gamma$,
\[
\ell_B(\Omega;t) =  \sum_{ y \in \Gamma } \ell_B(\Gamma, \hat 1_B, y;t)  \ell_\Gamma(\Omega, y, \hat 0_\Omega;t)
\]
\end{cor}


\begin{ex}\label{e:lconstant} \cite[Example 4.10]{KS16}
Let $\sigma: \Gamma \rightarrow B$ be a strong formal subdivision  between a lower  Eulerian poset $\Gamma$ of rank $r$ and an Eulerian poset $B$ of rank $n$. Then we have:

\begin{itemize}

\item The constant term of $\ell_B(\Gamma;t)$ is equal to the coefficient of $t^{r}$ in $\ell_B(\Gamma;t)$, which is equal to 
\[
\left\{\begin{array}{cl}  1 & \text{if } n = 0,  \\ 
0 & \text{if } n > 0.  \end{array}\right. 
\]

\item The linear coefficient of $\ell_B(\Gamma;t)$ is equal to the coefficient of $t^{r - 1}$ in $\ell_B(\Gamma;t)$, which is equal to 
\[
 \left\{\begin{array}{cl}   \beta- r  & \text{if } n=0,  \\ 
\beta  - 1  & \text{if } n=1, \\
\beta & \text{if }  n > 1.
  \end{array}\right. ,
\]
where 
\[
\beta = \# \{ y \in \Gamma \mid \sigma(y) = \hat{1}_B, \rho_\Gamma(\hat{0}_\Gamma,y) =  1 \}.
\]
\end{itemize}

\end{ex}


The \textbf{Boolean} algebra on $r$ elements consists of all subsets of a set of cardinality $r$ and forms an Eulerian poset under inclusion of rank $r$. It is the face poset of an $(r-1)$-dimensional simplex. A poset $B$ with minimal element $\hat 0$ is \textbf{simplicial} if for every $x$ in $B$, the interval $[\hat 0,x]$ is a Boolean algebra.

\begin{lemma}\cite[Lemma 4.12]{KS16}\label{l:simplicialsub}
Let $\sigma: \Gamma \rightarrow B$ be a strong formal subdivision between 
a simplicial poset $\Gamma$  of rank $r$ and a Boolean algebra $B$ of rank $n$ with rank functions $\rho_\Gamma$ and $\rho_B$ respectively. Then 
\[
\ell_B(\Gamma;t)  = \sum_{x \in B} h(\Gamma_x;t) (-1)^{\rho_B(x,\hat{1}_B)}   = \sum_{ y \in \Gamma } (-1)^{r - \rho_\Gamma(\hat{0}_\Gamma,y)} t^{r- e(y)}(t - 1)^{e(y)},
\]
where $e(y) = \rho_B(\sigma(y)) - \rho_\Gamma(y)$  is the \textbf{excess} of $y$. 
\end{lemma}

\begin{remark}
The local $h$-polynomial of strong formal subdivision is not necessarily non-negative (see \cite[Example 5.6.]{KS16} and Corollary \ref{non_pos_cor}).
\end{remark}

In case of polyhedral subdivision $\Ss$ of a polytope $P$ we denote $\ell_P(\Ss;t)$ assuming the strong formal subdivision between the corresponding face posets. Recall that $\sigma(F), F \in \Ss$ is defined as the minimal face of $P$ containing $F$.
For any face $Q$ of $P$ containing $\sigma(F)$, we may consider the corresponding  local $h$-polynomial:
\[
l_P(\Ss,Q,F;t) := l_{[\emptyset, P]}(\Ss,Q,F;t) =  l_{[\sigma(F),Q]}(\st_{\Ss|_{Q}}(F);t).
\]


\begin{theorem}\cite[Theorem 6.1.]{KS16}\label{l_poly_non-neg_uni}
     Let $\Ss$ be a polyhedral subdivision of a polytope P. Then for every cell $F$ of $\Ss$ and face $Q$ of $P$ containing $F$, the local $h$-polynomial $\ell_P(\Ss,Q,F;t)$ has non-negative symmetric coefficients. Moreover, if $\Ss$ is a regular subdivision, then the coefficients of $\ell_P(\Ss,Q,F;t)$ are unimodal.
\end{theorem}

\begin{remark}
    In \cite[Theorem 6.1.]{KS16} the condition ``symmetric'' is written only for regular subdivisions. But due to \cite[Corollary 4.5]{KS16} the local $h$-polynomial has symmetric coefficients for arbitrary strong formal subdivision, therefore we include the condition ``symmetric'' for arbitrary polyhedral subdivision. We also removed the word ``rational'' because the results from \cite{Kar19} allows this (see e.g. \cite[Theorem 2.11]{BKN24}). The latter remark is non-trivial since there are non-rational convex polytopes which are not combinatorially equivalent to any rational polytopes, see e.g. \cite{Zie08}.
\end{remark}

The local $h$-polynomials are non-negative in the polyhedral case because they appear when applying the Beilinson-Bernstein-Deligne decomposition theorem from \cite{BBD81} to the toric morphisms (see \cite[Lemma 6.4]{KS16} and \cite{CMM18}; see also \cite[Notes and References, Part 2, Chapter 11; p. 514]{GKZ94}).


\subsection{$h^*$- and local $h^*$-polynomials of lattice polytopes}\label{h_loc_h_rec_sebsec}

In this subsection we recall Ehrhart theory, the (local) $h^*$-polynomials and Katz-Stapledon decomposition formulas. We recommend \cite{BR07} as an introduction to Ehrhart theory.


 Let $P$ be a non-empty lattice polytope in a lattice $\Z^d$. 
 Consider the function $f_P(m)=\#(mP\cap \Z^d)$, for $m\in \Z_{> 0}$.  By Ehrhart's theorem  \cite[Section~3.3]{BR07}, $f_P(m)$ is a polynomial of degree $\dim P$, called
 the \define{Ehrhart polynomial} of $P$, and $f_P(0) = 1$. It follows that we can write
\begin{equation*}\label{e:Ehrhartpoly}
f_P(m)=f_0(P)+f_1(P)m+\dots+f_{\dim P}(P)m^{\dim P}, 
\end{equation*}
where $f_i(P)\in \Z$, and
\[
\Ehr_P(t)\equiv 1 + \sum_{m > 0} f_P(m) t^m = \frac{h^*(P;t)}{(1 - t)^{\dim P + 1}}, 
\]
where  $h^*(P;t)$ is a polynomial of degree at most $\dim P$ called the \define{$\mathbf{h^*}$-polynomial} of $P$ (see, for example, \cite[Section~3.3]{BR07}). A non-trivial theorem of Stanley \cite{Stan80} states that the coefficients of the 
$h^*$-polynomial are non-negative integers. Throughout, we will use the notation\[
h^*(P; t) =  \sum_{i = 0}^{\dim P} h^*_i t^i. 
\]

\begin{remark} (see e.g. \cite[Example 7.1]{KS16}) \label{h=vol_rem}
The $h^*$-polynomial of lattice polytope $P\subset \Z^n$ satisfy the following properties:
\begin{enumerate}
    \item $h^*_0 = 1$
    \item $h^*_1 = \# \{P\cap\Z^n\} - \dim P - 1$
    \item $h^*_{\dim P} = \# \{\text{int} (P)\cap\Z^n\}$
    \item $h^* (P;1) = \Vol_\Z(P)$, where $\Vol_\Z$ is the lattice volume (see Notation \ref{lattice_vol_sign}).
\end{enumerate}

\end{remark}


The following definition was introduced by Stanley in \cite[Example 7.13]{Stan92}, generalizing the definition of Betke and McMullen in the case of a simplex \cite{BeM85}. It was independently introduced by Borisov and Mavlyutov in \cite{BoM03} as $\tl S(t)$.

\begin{definition}\cite[Example 7.13]{Stan92}\label{d:localstar}
The \textbf{local $\mathbf{h^*}$-polynomial} $\ell^*(P;t)$ of $P$ is 
\begin{equation*}%\label{e:localdef}
\ell^*(P; t) =  \sum_{Q \subseteq P} (-1)^{\dim P - \dim Q}h^*(Q;t)g([Q,P]^*;t). 
\end{equation*}
\end{definition}

\begin{lemma}\cite[Lemma 7.3(2)]{KS16}\label{l:localprop}
Let $P$ be a non-empty lattice polytope. Then the $h^*$-polynomial of a polytope can be recovered from the local $h^*$-polynomials of its faces via %the formula
\[
h^*(P;t) =  \sum_{Q \subseteq P} \ell^*(Q; t)g([Q,P];t).
\]
\end{lemma}

\begin{sign}\label{star_sign}
    Consider a lattice polyhedral subdivision $\Ss$ of a polytope $F$. The \textbf{star} $\st_\Ss(F)$ of $F$ in $\Ss$ is the subcomplex consisting of all cells $F^\prime$ of $\Ss$ that contain $F$ under inclusion.
\end{sign}

\begin{remark}
    In \cite{KS16} and some other papers it is called the ``\textit{link}'' but the ``\textit{star}'' is a more common way to name it.
\end{remark}

\begin{lemma}(Katz-Stapledon decomposition of local $h^*$-polynomials)\cite[Lemma 7.12 (2-4)]{KS16}\label{l:pushstar} Let $\sigma:\Ss\rightarrow [\emptyset,P]$ be the strong formal subdivision induced by a lattice polyhedral subdivision $\Ss$ of a lattice polytope $P$.  Then
the following holds:
\begin{enumerate}
\item\label{i:push2}\[ h^*(P;t) = \sum_{\substack {F \in \Ss\\ \sigma(F) = P}} h^*(F;t) (t-1)^{\dim P - \dim F}
\]
\item\label{i:push3}  \[ h^*(P;t) = \sum_{F \in \Ss} \ell^*(F; t)  h(\st_\Ss(F);t),\]
\item\label{i:push4}  \[ \ell^*(P; t) = \sum_{F \in \Ss} \ell^*(F;t) \ell_P(\Ss, P,F;t).\]
\end{enumerate}
\end{lemma}



\begin{theorem}\cite[Theorem 7.17]{KS16} \label{loc_h*_non_neg_th}
    The coefficients of $h^*(P;t)$ and $\ell^*(P;t)$ are non-negative.
\end{theorem}

\begin{lemma}\cite[Lemma 7.3 (1)]{KS16}\label{loc_h*_sym_lem}
    The local $h^*$-polynomial $\ell^*(P)$ has symmetric coefficients centered at $(\dim (P)+1)/2$ 
\end{lemma}

\begin{theorem}\cite[Theorem 7.20]{KS16}
    Let $P \subset \R^n$ be a non-empty lattice polytope. Then the local $h^*$-polynomial $\ell^*(P;t) = \ell^*_1 t^1 + \dots + \ell^*_{\dim P}t^ {\dim P}$ satisfies $\ell^*_1 = \#(Int(P) \cap \Z^n) \le \ell^*_i \ \text{for}\  1 \le i \le \dim P$.
\end{theorem}

\begin{remark}
The local $h^*$-polynomial does not have unimodular coefficients in general (see e.g. \cite[Example 7.22.]{KS16}). However it has unimodular coefficients for IDP polytopes \cite[Theorem 2.5.]{APPS22} and $s$-lecture hall polytopes \cite[Corollary 5.5.]{GS20}. 
\end{remark}

\section{Strong formal subdivision with boundary}\label{boundary_sec}


In this section we define strong formal subdivisions with boundary, which are strong formal subdivision with marked elements, called boundary elements. The restriction to these boundary elements must also be a strong formal subdivision.

We define the agglutination of the strong formal subdivisions with the same boundaries along their boundary. Lemma \ref{agglut_lemma} provides a simple formula for the local $h$-polynomial of the agglutination in terms of the local $h$-polynomials of the initial strong formal subdivisions and their boundary. The most important examples (Example \ref{boundary_pol_ex}) of strong formal subdivision with boundary are obtained from polyhedral subdivisions of convenient polytopes inside a cone. We prove that the local $h$-polynomial of such agglutinations inherit the properties of the local $h$-polynomial of usual polyhedral subdivisions, including nonnegativity and symmetricity.

\subsection{Poset with boundary and twins-poset}

In this subsection we define two types of posets and prove their basic properties. We need them to define strong formal subdivisions with boundaries. Recall that a lower set of a poset is a subposet which, together with each element, contains all smaller elements from the original poset.

\begin{definition}\label{poset_w_boundary_def}
A pair $(\Gamma, \Gamma_B)$ of embedded posets is called \textbf{poset with boundary} if $\Gamma_B$ is a lower set of $\Gamma$ and $\rk (\Gamma_B) = \rk (\Gamma) - 1$. 
\end{definition}


\begin{definition}\label{agglutination_posets_def}
    Consider two posets $(\Gamma^1, \Gamma_B)$ and $(\Gamma^2, \Gamma_B)$ with common boundary $\Gamma_B = \Gamma^1 \cap \Gamma^2$. The \textbf{agglutination} $\Gamma^1 \sharp_{\Gamma_B} \Gamma^2$ is the poset $\Gamma^1\cup\Gamma^2$ with incomparable $\Gamma^1\setminus \Gamma_B$ and $\Gamma^2\setminus \Gamma_B$, and the induced poset structure on both $\Gamma^1$ and $\Gamma^2$.
\end{definition}

Note that the agglutination of any pair of lower Eulerian posets is lower Eulerian.

\begin{lemma}\label{agglutination_posets_lem}
    The $h$-polynomial of the agglutinations of a pair of lower Eulerian posets $\Gamma^1, \Gamma^2$ with the same boundary $\Gamma_B$ equals the following sum:
    $$h(\Gamma^1\sharp_{\Gamma_B} \Gamma^2; t) = h(\Gamma^1;t) + h(\Gamma^2;t) + (t-1) h(\Gamma_B;t)$$
\end{lemma}

\begin{proof}

    Applying the definition of the $h$-polynomial

    $$h(\Pd;t) = t^{\rk \Pd} \sum\limits_{x \in \Pd} (t^{-1}-1)^{\rk \Pd-\rho_\Pd (x) } g([\hat 0, x]; t^{-1}),$$
    we obtain:
    \begin{align*} h(\Gamma^1 \sharp_{\Gamma_B} \Gamma^2; t)& = (h(\Gamma^1;t) - t(t^{-1} - 1) h(\Gamma_B;t)) + (h(\Gamma^2;t) - t(t^{-1} - 1) h(\Gamma_B;t)) +\\ 
    &+t(t^{-1} - 1) h(\Gamma_B;t) = h(\Gamma^1;t) + h(\Gamma^2;t) + (t-1)  h(\Gamma_B;t)
\end{align*}

\end{proof}

\begin{definition}\label{twins_pos_def}
    Consider a poset $R$. Denote by $R^-$ its copy and the corresponding bijection by $\phi_R^+: R^- \to R$ and by $\phi_R^-: R\to R^-$ the inverse bijection. Denote by $R^\pm$ the poset consisting of elements $R \sqcup R^-$ with relations generated by:
    \begin{enumerate}
        \item Relations in $R$ and $R^-$,
        \item Additional relations $\forall r \in R : \phi_R^-(r) < r$.
    \end{enumerate}  We call $R^\pm$ the \textbf{twins-poset born from} $R$.
\end{definition}

Note that $R^\pm$ is (lower) Eulerian if and only if $R$ is (lower) Eulerian.

\begin{lemma}\label{twins_lem}
    For any lower Eulerian poset $R$, we have $h(R;t) = h(R^\pm;t)$.
\end{lemma}


\begin{proof}
First, we prove the lemma for Eulerian posets. In this case, we replace the $h$-polynomial by the $g$-polynomial. We proceed by induction on the rank $n$ of poset $R$. By the definition of the $g$-polynomial, we have: 

\begin{align*}
    t^{n+1}&g(R^\pm;t^{-1}) = \sum_{x \in R^\pm} g([\hat{0}_{R^\pm},x];t) (t - 1)^{n+1 - \rho(\hat{0}_{R^\pm},x)} = \\
    &= \sum_{x \in R^-} g([\hat{0}_{R^\pm},x];t) (t - 1)^{n+1 - \rho(\hat{0}_{R^\pm},x)} + \sum\limits_{x \in R\setminus \hat 1_R} g([\hat{0}_{R^\pm},x];t) (t - 1)^{n + 1 - \rho(\hat{0}_{R^\pm},x)} + g(R^\pm;t)
\end{align*}

By the induction hypothesis and the definitions of $g$-polynomial and $h$-polynomials, we have:

$$t^{n+1}g(R^\pm;t^{-1}) = (t-1) t^n g(R;t^{-1}) + (t-1) t^{n-1} h(R\setminus \hat 1_R;t^{-1}) + g(R^\pm,t)$$

By Claim \ref{h_out_top_ut}, we have: $$t^{n-1} h(R\setminus \hat 1_R;t^{-1}) = h(R\setminus \hat 1_R;t) = \frac{g (R;t) - t^n g(R;t)}{1-t},$$
therefore, we can rewrite the formula for the $g$-polynomial:

$$t^{n+1}g(R^\pm;t^{-1}) - t^{n+1} g(R;t^{-1}) =  g(R^\pm,t) - g(R;t)$$

Note that:
\begin{itemize}
\item All monomials on the left-hand side have degree greater than $(n+1)/2$
\item All monomials on the right-hand side have degree less than $(n+1)/2$
\end{itemize}

This implies that both sides vanish, and thus $g(R^\pm,t) =g(R;t)$.

Now we can verify the lemma for any lower Eulerian posets. Indeed, by the definition of the $h$-polynomial we have:

\begin{align*}
    t^{n+1} h (R^\pm;t^{-1}) &= \sum\limits_{x\in R^\pm} g([\hat 0_{R^\pm},x];t) (t-1)^{n+1 - \rho(\hat 0_{R^\pm},x)} = \\
    &= ((t-1)+1) (\sum\limits_{x\in R^-} g([\hat 0_{R^-},x];t) (t-1)^{n- \rho(\hat 0_{R^-},x)})  = t \cdot t^nh(R^-;t^{-1})
\end{align*}

\end{proof}


\subsection{Strong formal subdivisions with boundaries}

\begin{definition} \label{Strong_formal_subdiv_w_bo_def}
A map $\sigma: (\Gamma, \Gamma_B) \to R^\pm$ with  $ \sigma (\Gamma\setminus \Gamma_B) = R$ and $\sigma(\Gamma_B) = R^-$ from a lower Eulerian poset with boundary to an Eulerian twins-poset is called \textbf{strong formal subdivision with boundary} if both $\sigma$ and its restriction $\sigma_B$ on $\Gamma_B$ are strong formal subdivisions. 
\end{definition}

Note that the restriction of $\sigma$ on $\Gamma \setminus \Gamma_B$ is generally not a strong formal subdivision since $\Gamma \setminus \Gamma_B$ may not be lower Eulerian (may have several minimal elements).

%\begin{definition} \label{Strong_formal_subdiv_w_bo_def}
%Let $\Gamma$ be a poset with rank function $\rho_\Gamma$. Suppose that $\Gamma = \Gamma_I \sqcup \Gamma_B$ is the disjoint union of the inner part $\Gamma_I$ and the boundary part $\Gamma_B$ with restricted rank functions $\rho_I$ and $\rho_B$ respectively. Suppose that $\Gamma_B$ is a lower set, or equivalently, $\Gamma_I$ is an upper set. 

