%Consider function $\sigma: \Gamma \to R^{\pm}$. Suppose that its restrictions of on $\Gamma_I$ and $\Gamma_B$ are of the form $\sigma_I: \Gamma_I \to R$ and $\sigma_B: \Gamma_B \to R^-$. Suppose that the function $\sigma: (\Gamma = \Gamma_I \sqcup \Gamma_B) \to (R^{\pm} = R \sqcup R^-)$ is a strong formal subdivision. Then we call it a \textbf{strong formal subdivision with boundary}.
%\end{definition}

%Note that if $\sigma: \Gamma \to R^{\pm}$ is a strong formal subdivision with boundary, then its \textcolor{red} {restrictions $\sigma_I: \Gamma_I\to R$} and $\sigma_B : \Gamma_B \to R^-$ are also strong formal subdivisions. The most important property of strong formal subdivisions with boundary is that pair of them can be agglutinated into one strong formal subdivision. 


\begin{definition} \label{agglutination_def}
    Consider two strong formal subdivisions \mbox{$\sigma_1: (\Gamma^1, \Gamma_B) \to R^\pm$} and \mbox{$\sigma_2: (\Gamma^2,\Gamma_B) \to R^\pm$}  sharing the same boundary $\sigma_B: \Gamma_B \to R^-$. The \textbf{agglutination} $\sigma_1 \sharp_{\sigma_B}\sharp \sigma_2 : \Gamma^1 \sharp_{\Gamma_B}\sharp \Gamma^2  \to R$ of these strong formal subdivisions is defined as:
\begin{itemize}
\item $\phi^+_R \circ \sigma_B$ on $\Gamma_B$, 
\item $\sigma_1$ on $\Gamma^1\setminus \Gamma_B$, 
\item $\sigma_2$ on $\Gamma^2\setminus \Gamma_B$.
\end{itemize}

\end{definition}

A simple verification shows that $\sigma_1 \sharp_{\sigma_B}\sharp \sigma_2$ is indeed a strong formal subdivision.


\begin{lemma} \label{agglut_lemma}
    The local $h$-polynomial of the agglutination satisfies:
    $$\ell_R(\Gamma^1 \sharp_{\Gamma_B}\sharp \Gamma^2;t) = \ell_{R^\pm} (\Gamma^1;t)+ \ell_{R^\pm} (\Gamma^2;t) + (t+1)\ell_{R^-} (\Gamma_B;t)$$
\end{lemma}

\begin{proof}
    Recall the definition of the local $h$-polynomial of strong formal subdivisions:

%    $$t^{\rk \Pd} h(\Pd;t^{-1}) = \sum\limits_{x \in \Pd} (t-1)^{\rk \Pd-\rho_\Pd (x) } g([\hat 0, x]; t)$$

%     $$h(\Pd;t) = t^{\rk \Pd} \sum\limits_{x \in \Pd} (t^{-1}-1)^{\rk \Pd-\rho_\Pd (x) } g([\hat 0, x]; t^{-1})$$

    \begin{align*}
    \ell_R(\Gamma^1 \sharp_{\Gamma_B}\sharp \Gamma^2;t) &= \sum \limits_{x\in R} h((\Gamma^1 \sharp_{\Gamma_B}\sharp \Gamma^2)_x;t) (-1)^{\rho_{R}(x,\hat 1_{R})} g([x,\hat 1_{R}]^*;t)\\
    \ell_{R^\pm}(\Gamma^i;t) &= \sum \limits_{x\in R^\pm} h(\Gamma^i_x;t) (-1)^{\rho_{R^{\pm}}(x,\hat 1_{R^\pm})} g([x,\hat 1_{R^\pm}]^*;t)\\
    \ell_{R^-} (\Gamma_B;t) &= \sum \limits_{x\in R^-} h((\Gamma_B)_x;t) (-1)^{\rho_{R^-} (x,\hat 1_{R^-})}  g([x,\hat 1_{R^-}]^*;t)
    \end{align*}

%    Note that posets $R^{\pm}$ and $R^-$ are also boolean. This implies that $g$-polynomials in the above formula are equal to $1$.

 %   $$\ell_R(\Gamma_{ag};t) = \sum \limits_{x\in R} h((\Gamma_{ag})_x;t) (-1)^{\rho_{R}(x,\hat 1_{R})}$$

  %  $$\ell_{R^\pm}(\Gamma^i;t) = \sum \limits_{x\in R^\pm} h(\Gamma^i_x;t) (-1)^{\rho_{R^{\pm}}(x,\hat 1_{R^\pm})}$$

  %  $$\ell_{R^-} (\Gamma_B;t) = \sum \limits_{x\in R^-} h((\Gamma_B)_x;t) (-1)^{\rho_{R^-} (x,\hat 1_{R^-})}$$

%    The following inequality provides the lemma. For each $x \in R$ we have:

%    $$ h(\Gamma^i_{\phi^-(\hat 1_R)};t ) = h(\Gamma_B;t)$$

Applying Lemma \ref{twins_lem}, we obtain that Lemma \ref{agglut_lemma} is implied by the following equation. To prove the lemma, it suffices to show that for every $x \in R$ we have the equality:
$$h((\Gamma^1 \sharp_{\Gamma_B}\sharp \Gamma^2)_x;t) =  h(\Gamma^1_x;t) + h(\Gamma^2_x;t) - h(\Gamma^1_{\phi^-(x)};t) - h(\Gamma^2_{\phi^-(x)};t) + (t+1) h((\Gamma_B)_{\phi^-(x)};t)$$
Without loss of generality, we may assume that $x = \hat 1_R$. Thus, the latter equation is equivalent to:
$$h(\Gamma^1 \sharp_{\Gamma_B}\sharp \Gamma^2;t) =  h(\Gamma^1;t) + h(\Gamma^2;t) - h(\Gamma_B;t) - h(\Gamma_B;t) + (t+1) h(\Gamma_B;t).$$
This equality follows directly from Lemma \ref{agglutination_posets_lem}.

\end{proof}


\subsection{Subdivisions of convenient polytopes in cones}

For a cone $C$, denote its face poset by $\mathcal C$ as in Example \ref{face_pos_ex}. Note that it is an Eulerian poset.

\begin{ex}\label{boundary_pol_ex}
    Let $P \subset C$ be a convenient polytope and $\Ss$ be a polyhedral subdivision of $P$. Denote by $\Ss_B$ the lower set of $\Ss$ consisting of polytopes contained in the boundary $\partial_C P$ (see Definition \ref{conv_boun_def}). Denote by $\sigma_0: \Ss \to \mathcal C$ mapping $Q \in \Ss$ to the minimal face of $C$ containing $Q$. Then the map $\sigma: \Ss \to \mathcal C^\pm$ defined as $\sigma_0$ on $\Ss\setminus \Ss_B$ and as $\phi_{\mathcal C}^-\circ\sigma_0$ on $\Ss_B$ is a strong formal subdivision with boundary.
\end{ex}

Note that the polytope's convenience implies that the map $\sigma$ is strongly surjective. The remaining conditions defining strong formal subdivisions can be confirmed the same way as for polyhedral subdivisions of polytopes \cite[Lemma 3.25.]{KS16}.

Consider the face poset $\Pd$ of polytope $P$.

\begin{remark}\label{boundary_reg_rem}
    Note that $\Pd_B$ can be obtained from regular polyhedral subdivision:

\begin{enumerate}
\item Let $C_{\min}$ the minimal non-empty face of $C$ (i.e., its maximal affine subspace).
\item Take $X$ in relative interior of $(P \cap C_{\min})$.
\item Define the height function: $0$ on the vertices of $P$, and $1$ at $X$.
\item Denote $\mathcal{X}$ be the resulting regular subdivision of $P$.
\end{enumerate}

Then for any $F \in \Pd_B$ we have: $\st_{\Pd_B} (F) = \st_{\mathcal X} (\conv (F,X))$. Thus, for any face $Q \in \mathcal C: F \subset Q$ we have $\ell_{\mathcal C^-} (\Pd_B,Q,F;t) = \ell_\Pd(\mathcal X, Q, F;t)$.
\end{remark}

Consider a face $U\in \Pd_B$ of $P$ and face $Q \in \mathcal C: U \subset Q$. Denote $\dim (U) = u$ and $\dim (Q) = q$.


\begin{lemma}\label{loc_estim_lem}
    The following formula holds:
    $$\ell_{\mathcal C ^\pm} (\Pd,Q,U;t) =- \ell_{\mathcal C^-} (\Pd_B,Q,U;t) + R_{<(q-u)/2},$$
    where $\deg (R_{<(q-u)/2}) < (q-u)/2$ is completely determined by $\ell_{\mathcal C^-} (\Pd_B,Q,U;t)$. 
\end{lemma}

\begin{cor}\label{non_pos_cor}
    The polynomial $\ell_{\mathcal C ^\pm} (\Pd,Q,U;t)$ has symmetric coefficients centered at $(q-u)/2$ and polynomial $\ell_{\mathcal C^-}(\Pd_B,Q,U;t)$ has symmetric coefficients centered at $(q-u-1)/2$. So Lemma \ref{loc_estim_lem} fully recovers $\ell_{\mathcal C ^\pm} (\Pd,Q,U;t)$ from $\ell_{\mathcal C^-} (\Pd_B,Q,U;t)$.
    For instance, $\ell_{\mathcal C ^\pm} (\Pd,Q,U;t)$ has non-positive coefficients.
\end{cor}

\begin{proof}
    By definition of the local $h$-polynomial we have:
    $$\ell_{\mathcal C ^\pm}(\Pd,Q,U;t) = \sum\limits_{\sigma(U) \le x \le Q} h(\st_\Pd(U)|_x;t) (-1)^{\rho_{\mathcal C^{\pm}}(x,Q)} g([x,Q]^*;t)$$

    Let us separate the sum over $x\in \mathcal C$ and $x \in \mathcal C^-$. Applying Lemma \ref{twins_lem} and the fact that every face of polytope forms an Eulerian poset (and hence its $h$-polynomial equals its $g$-polynomial), we obtain:

    \begin{align*}
    \ell_{\mathcal C ^\pm}(\Pd,Q,U;t) = &\sum\limits_{\phi_{\mathcal C}^+(\sigma(U)) \le x \le Q} g(\st_\Pd(U)|_x;t) (-1)^{\rho_{\mathcal C}(x,Q)} g([x,Q]^*;t) -\\
    &-\sum\limits_{\sigma(U) \le x \le \phi_{\mathcal C}^-(Q)} h(\st_\Pd(U)|_x;t) (-1)^{\rho_{\mathcal C^{-}}(x,\phi_{\mathcal C}^-(Q))} g([x,\phi_{\mathcal C}^-(Q)]^*;t)
    \end{align*}

    Note that:
    \begin{enumerate}
        \item The first summand is the the sum of products of pairs of $g$-polynomials of posets with rank sum $q-u+1$.
        \item For a poset of rank $r$, $\deg(g) \leq (r-1)/2$.
    \end{enumerate} 

    Thus, the first summand has degree less than $(q-u)/2$ and can be rewritten as $R_{<(q-u)/2}$.

    The second summand is equal to $- \ell_{\mathcal C^-} (\Pd_B,Q,U;t)$ and this completes the proof.

\end{proof}


\begin{lemma}\label{l_agl_lem}
        We have the following formula:
        $$\ell_{\mathcal C} (\Pd\sharp_{\Pd_B} \sharp \Pd,Q,U;t) = (t-1)\ell_{\mathcal C^-} (\Pd_B,Q,U;t) + R_{<(q-u)/2},$$
where $\deg (R_{<(q-u)/2}) < (q-u)/2$ is determined by $\ell_{\mathcal C^-} (\Pd_B,Q,U;t)$.

\end{lemma}


\begin{proof}
By Lemma \ref{agglut_lemma} we have:
$$\ell_{\mathcal C} (\Pd\sharp_{\Pd_B} \sharp \Pd,Q,U;t) = 2 \ell_{\mathcal C^\pm} (\Pd,Q,U;t) + (t+1)\ell_{\mathcal C^-} (\Pd_B,Q,U;t)$$

Lemma \ref{loc_estim_lem} yields:
$$\ell_{\mathcal C} (\Pd\sharp_{\Pd_B} \sharp \Pd,Q,U;t) = (t-1)\ell_{\mathcal C^-} (\Pd_B,Q,U;t) + R_{<(q-u)/2}, $$
where $\deg (R_{<(q-u)/2}) < (q-u)/2$.

Recall that by Corollary \ref{loc_h_sym_cor} the local $h$-polynomial of $\ell_{\mathcal C} (\Pd\sharp_{\Pd_B} \sharp \Pd,Q,U;t)$ has symmetric coefficients centered at $(q-u)/2$, so they are indeed determined by $\ell_{\mathcal C^-} (\Pd_B,Q,U;t)$.


\end{proof}

By Theorem \ref{l_poly_non-neg_uni} and Remark \ref{boundary_reg_rem} the polynomial $\ell_{\mathcal C^-}(\Pd_B,Q,U;t)$ has symmetric unimodal coefficients centered at $(q-u-1)/2$. Hence, we obtained the following corollary.


\begin{cor}\label{non_neg_l_cor}
    The local $h$-polynomial $\ell_{\mathcal C}(\Pd\sharp_{\Pd_B}\sharp\Pd,Q,U;t)$:
    \begin{enumerate}
        \item Has non-negative coefficients.
        \item Vanishes if and only if $\ell_{\mathcal C^-}(\Pd_B,Q,U;t)$ vanishes.
        \item Its evaluation $\ell_{\mathcal C}(\Pd\sharp_{\Pd_B}\sharp\Pd,Q,U;1)$ equals the coefficient of $\ell_{\mathcal C^-}(\Pd_B,Q,U;t)$ at $t^{\lfloor(q-u-1)/2\rfloor}$.
    \end{enumerate}
\end{cor}




%consider the agglutinated poset $\Pd \sharp_{\Pd_B}\sharp\Pd$, where $\Pd_B$ consists of all faces of $\Pd$ which are contained in the boundary $\partial_C P$. Define the \textbf{agglutinated polytope $P\sharp_{\partial_C P}\sharp P$} as a formal polyhedral complex formed by the polytopes in the poset $\Pd \sharp_{\Pd_B}\sharp\Pd$. Let $\Ss$ be a polyhedral subdivision of $P\sharp_{\partial_C P}\sharp P$, i.e. the agglutination of two polyhedral subdivisions of $P$ (coinciding on the boundary) along the boundary. We denote by $\Ss_B$ the corresponding boundary poset.

Note that Katz-Stapledon decomposition formulas \ref{c:hrefine}, non-negativity of the local $h$-polynomial Theorem \ref{l_poly_non-neg_uni} and Corollary \ref{non_neg_l_cor} imply the following theorem.

\begin{theorem} \label{non_neg_l_th}
Let $P$ be a convenient polytope in a cone $C$. Consider two polyhedral subdivisions $\Ss_1$ and $\Ss_2$ of $P$ that coincide on the boundary $\partial_C P$. Let $\sigma_1$ and $\sigma_2$ be the corresponding strong formal subdivisions with boundaries. Denote by $\sigma:\Ss_1\sharp_{\Ss_B}\sharp\Ss_2\to \Cp$ their agglutination. Then the local $h$-polynomial $\ell_{\mathcal C} (\Ss_1\sharp_{\Ss_B}\sharp \Ss_2,Q, U;t)$ has symmetric non-negative coefficients centered at $(\dim Q- \dim U)/2$.     
\end{theorem}


\section{Generalization of $h^*$- and $\ell^*$-polynomial}\label{gen_of_polyn_sec}

\subsection{$h^*$- and $\ell^*$-polynomial of polyhedral strong formal subdivision}

We call an \textbf{abstract lattice polyhedral complex} $\Ss$ a poset of ``abstract'' convex lattice polytopes, such that every face of any polytope is also contained in the poset and any two polytopes intersect along a common face. Formally, abstract lattice polyhedral complex is a map $\theta$ from a poset $\Gamma$ to lattice polytopes in different lattices such that for every $x \in \Gamma$ the lower set $\Gamma_{\le x}$ is the face poset of the polytope $\theta (x)$ and for every $y\le x$ there is a lattice isomorphism between the polytope $\theta (y)$ and the corresponding face of the polytope $\theta (x)$. We do not assume that there is a geometric realization in a common lattice. 

A \textbf{polyhedral strong formal subdivision} is a strong formal subdivision between an abstract lattice polyhedral complex and an Eulerian poset.
Inspired by Katz-Stapledon decomposition formulas (Lemma \ref{l:pushstar}) we define $h^*$- and local $h^*$-polynomials of polyhedral strong formal subdivisions. Note that since strong formal subdivisions are strongly surjective, any abstract lattice polyhedral complex $\Ss$ is pure, i.e. every its maximal polytope has the same dimension $\dim \Ss$.


\begin{definition}\label{h*_ag_def}
The $h^*$-polynomial of a polyhedral strong formal subdivision $\sigma: \mathcal{S} \to R$ is:
    $$h_R^*(\Ss;t) =  \sum\limits_{\substack{F \in \Ss \\ \sigma(F) = \hat 1_R}}  h^*(F;t) (t-1)^{\dim  \Ss - \dim F}$$
\end{definition}



\begin{definition}\label{loc_h*_def}
    The local $h^*$-polynomial of a polyhedral strong formal subdivision $\sigma: \Ss \to R$ is:
    $$\ell_R^*(\Ss;t) =  \sum\limits_{x \in R} (-1)^{\rk \hat 1_R - \rk x}  h_{[\hat 0_R, x]}^*(\Ss_x;t) g([x,\hat 1_R]^*;t)$$
\end{definition}


It follows e.g. from \cite[Theorem 3.11]{KS16} that we recover the $h^*$-polynomial via the local $h^*$-polynomial

$$h_R^*(\Ss;t) = \sum\limits_{x \in R}  \ell_{[\hat 0_R, x]}^*(\Ss_x;t) g([x,\hat 1_R];t)$$



If $\Ss$ is a polyhedral subdivision of a polytope $P$ and $\sigma$ is the strong formal subdivision corresponding to this polyhedral subdivision, the definitions yield the standard $h^*(P;t)$ and $\ell^*(P;t)$. In the following subsection we give other examples of polyhedral strong formal subdivisions using agglutinations technique. 

Note that Katz-Stapledon decomposition formulas remain valid in this more general setting.

\begin{lemma}\label{ks_decomp_h*_ag} Let $\sigma:\Ss\rightarrow R$ be a polyhedral strong formal subdivision. Then the following holds:
\begin{enumerate}
\item\label{i:push2new}\[ h_R^*(\Ss;t) = \sum_{\substack {F \in \Ss\\ \sigma(F) = \hat 1 _R}} h^*(F;t) (t-1)^{\dim \Ss - \dim F}
\]
\item\label{i:push3new}  \[ h_R^*(\Ss;t) = \sum_{F \in \Ss} \ell^*(F; t)  h(\st_\Ss(F);t),\]
\item\label{i:push4new}  \[ \ell_R^*(\Ss; t) = \sum_{F \in \Ss} \ell^*(F;t) \ell_R(\Ss, C,F;t).\]
\end{enumerate}
\end{lemma}

\begin{proof}
    The first formula is implied by Definition \ref{h*_ag_def} and the corresponding Katz-Stapledon decomposition formula from Lemma \ref{l:pushstar}.
    The equivalence of these formulas is proved the same way as in \cite[Lemma 7.12.]{KS16}.
\end{proof}


