\begin{theorem}\label{loc_h*_ag_th}
    For a convenient polytope $P \subset C$ with $\dim C = n$ we have:
    \begin{enumerate}
        \item The polynomial $\ell_\Cp^*(\Pd\sharp_{\Pd_B} \Pd;t)$ has nonnegative symmetric coefficients centered at $(n+1)/2$.
        \item The $\ell$-Newton number is a non-negative integer, moreover, satisfies $\nu^\ell_C(P)\ge \ell^*(P;1)$.
        \item If the face poset $\mathcal C$ is boolean, then $\nu^\ell_C(P) = \nu_C(P)$.
    \end{enumerate}

    \begin{proof}
    \begin{enumerate}
        \item The first item follows from Theorems \ref{non_neg_l_th}, \ref{loc_h*_non_neg_th} and Lemma \ref{loc_h*_sym_lem}; 
        \item The second item follows from Theorems \ref{non_neg_l_th}, \ref{loc_h*_non_neg_th} and Lemma \ref{agglut_lemma}.
        \item The third item follows from Remark \ref{g=1_rem}, Definition \ref{loc_h*_def}, and Remark \ref{h=vol_rem}
    \end{enumerate}

        \end{proof}

\end{theorem}

\begin{cor}
    The $h^*$-polynomial $h^*_\Cp (\Pd\sharp_{\Pd_B}\sharp \Pd;t)$ has non-negative coefficients.
\end{cor}


\begin{ex}[Compatibility with Stapledon's formulas for monodromy]\label{Stap_mon_ex}
    Consider a convenient polytope $P$ in $C = \R^n_{\ge 0}$ with face poset $\Pd$ and boundary poset $\Pd_B$ consisting of its faces in $\partial_C P$. Suppose that $T$ is the polyhedral subdivision of $P$ consisting of faces in $\Pd_B$ and their convex hulls with the origin. For $F \in \Pd_B$ denote by $F^0$ its convex hull with the origin. The global version of Stapledon's formulas for monodromy from \cite[Corollary 6.14.]{Stap17} implies that:
    $$\nu_C(P) = \sum\limits_{F \in \Pd_B} \ell_{\Cp^-} (\Pd_B, \hat 1_{\Cp^-}, F;1) (\ell^*(F;1) + \ell^*(F^0;1))$$

    Let us show that this formula agrees with Lemma \ref{ks_decomp_h*_ag} (\ref{i:push4}) via:

    $$\ell_\Cp^*(T\sharp_{\Pd_B}\sharp T;t) = \sum\limits_{F \in \Pd_B} \ell_{\Cp} (T\sharp_{\Pd_B}\sharp T, \hat 1_{\Cp}, F;t) \ell^*(F;t) + 2 \sum\limits_{F \in \Pd_B} \ell_{\Cp} (T, \hat 1_{\Cp}, F^0;t) \ell^*(F^0;t)$$

    By the construction of $T$, we have $\ell_{\Cp} (T, \hat 1_{\Cp}, F^0;t) = \ell_{\Cp^-} (T, \hat 1_{\Cp^-}, F;t)$ (since the corresponding strong formal subdivisions coincide). By Lemma \ref{agglut_lemma} we have:

    $$\ell_{\Cp} (T\sharp_{\Pd_B}\sharp T, \hat 1_{\Cp}, F;t) = 2 \ell_{\Cp^\pm} (T, \hat 1_{\Cp^\pm}, F;t) + (t+1) \ell_{\Cp^-} (\Pd_B,  \hat 1_{\Cp^-}, F;t) $$

    Lemma \ref{twins_lem} implies that for any $F \in \Pd_B$, we have $\ell_{\Cp^\pm} (T, \hat 1_{\Cp^\pm}, F;t) = 0$. Thus, we obtain:

    $$\ell_\Cp^*(T\sharp_{\Pd_B}\sharp T;t) = \sum\limits_{F \in \Pd_B} (\Pd_B,  \hat 1_{\Cp^-}, F;t) ((t+1) \ell^*(F;1) +  2 \ell^*(F^0;t)) $$

    Recall that our cone $C$ has boolean face poset, so $\nu_C(P) = \frac{1}{2} \ell_\Cp^*(T\sharp_{\Pd_B}\sharp T;1)$ and this is consistent with Stapledon's formulas for monodromy. 
\end{ex}

\begin{remark}
The agglutination technique can be extended to coconvex polytopes and remains compatible with Stapledon's formulas for local monodromy \cite[Corollary 6.22]{Stap17}.
\end{remark}

