%        The Minkowski sum $\D_1 + \D_2$ of two polytopes is the set of all vector sums $p_1+p_2, \ p_1 \in \D_1, \ p_2 \in \D_2$.
%\end{definition}

Let us recall the mixed volume and Bernstein-Kouchnirenko-Khovansky theory. For an introduction to the convex polyhedral geometry see \cite{Ew}, for a survey on this connection between polyhedral geometry and algebraic geometry see \cite{EKK}.


\begin{sign}\label{lattice_vol_sign}
        Suppose that $\R^k$ is an affine space with lattice $L\subset \R^k$ of full rank. We use the \textbf{lattice} volume $\Vol_\Z$, which differs from the usual one by a factor, so that the lattice volume of the initial simplex in the lattice $L$ is equal to $1$. Note that the lattice volume of any lattice polytope is integer. In the standard $\R^n$ we consider the standard lattice $\Z^n$. When we consider any operations with affine spaces we assume that we apply the same operations to the corresponding lattices.
\end{sign}

\begin{definition}\label{mv}
\textbf{Mixed volume $MV$} is the function that maps collections of $n$ convex lattice polytopes in $\R^n$ to real numbers and satisfies the following conditions:
		\begin{enumerate}
			\item It is symmetric in its arguments.
			\item $MV(P, \dots, P) = \Vol_\Z(P)$ for any polytope $P$.\\
			\item For any polytopes $P_1,P_2,\dots , P_n$ and $P_1^\prime$ and non-negative numbers $\lambda, \lambda^\prime$ the following equation holds 
			$$MV(\lambda P_1 + \lambda^\prime P_1
            ^\prime, P_2, \dots, P_n) = \lambda \cdot MV(P_1,P_2, \dots, P_n) + \lambda^\prime \cdot  MV(P_1^\prime, P_2, \dots, P_n),$$
			where the sum in the left hand side is the \textbf{Minkowski sum} and multiplication is the homothety with the corresponding coefficient.
		\end{enumerate}
	\end{definition}


\begin{theorem}[Bernstein-Kouchnirenko] \cite{Ber75} \label{bk_th}
    Consider Laurent polynomials $f_1,\dots, f_n \in \C[z_1^{\pm 1},\dots, z_n^{\pm 1} ]$ with Newton polytopes $P_1,\dots,P_n$ and generic coefficients. Then the number of solutions $f_1=\dots = f_n = 0$ in the torus $(\C \setminus0)^n$ is equal to the mixed volume $MV(P_1,\dots P_n)$.
\end{theorem}

The Bernstein-Kouchnirenko-theorem admits the following interpretation in terms of the line bundles on toric varieties (for an introduction to toric varieties see e.g. \cite{Ful}). We formulate it in the unmixed case, but of course, there exists a mixed analogue. Let $P\subset \R^n$ be an $n$-dimensional lattice polyhedron, let $\Sigma$ be its dual fan. Denote by $\mathbb T^\Sigma$ the corresponding (projective) toric variety. Consider holomorphic sections $f_1,\dots,f_n$ of the line bundle $I_P$ on $\mathbb T^\Sigma$ defined by $P$. For the definition of the intersection number see e.g. \cite[Section 1.3]{Es10}.

\begin{remark}\label{bk_th_toric_rem}
    The intersection number equals the lattice volume:
    $$mult(f_1\cdot{\dots} \cdot f_n\cdot \mathbb T^\Sigma) = \Vol_\Z (P)$$
    For finite zero sets (the case of complete intersection), the intersection number equals the sum of positive local multiplicities.
\end{remark}

Note that (for instance, by the Bernstein-Kouchnirenko theorem) the mixed volume of any collection of convex lattice polytopes is non-negative and integer. The following criteria hold for the mixed volume to be equal to zero or one.

\begin{proposition}(\cite{Kh78}; see \cite[Lemma 1.2]{Es10} for a proof.) \label{mv=0_prop}
The mixed volume of convex polytopes is zero if and only if some $k$ of these polytopes sum up to a polytope of dimension strictly smaller than $k$.
\end{proposition}


\begin{proposition} \cite{EG15}\label{mv=1_prop}
    A collection of $n$ lattice polytopes in $\R^n$ has the mixed volume equal to one if and only if:
    \begin{enumerate}
        \item the mixed volume is not zero, and
        \item there exists $k > 0$ such that (after translation):
        \begin{enumerate}
            \item $k$ of the polytopes are faces of the same $k$-dimensional volume $1$ lattice simplex in a $k$-dimensional rational subspace $\R^k\subset \R^n$.
            \item The images of the other $n-k$ polytopes under the projection $\R^n\to \R^n/\R^k$ have the unit mixed volume.
        \end{enumerate}
    \end{enumerate}
\end{proposition}


\begin{theorem}[Bernstein-Kouchnirenko-Khovanskii] \cite[Section 3]{Kh78}\label{BKK_th}
Consider Laurent polynomials $f_1,\dots, f_k \in \C[z_1^{\pm 1},\dots, z_n^{\pm 1} ]$ with Newton polytopes $P_1,\dots,P_k$ and generic coefficients. Then the Euler characteristic of the complete intersection equals the following:
$$\chi (\{f_1= \dots = f_k = 0\}) =  (-1)^{n-k}  \sum\limits_{\substack{a_0 > 0, \dots , a_k > 0 \\ a_0+\dots + a_k = n}} MV(\underbrace{P_0,\dots,P_0}_{a_0}, \dots, \underbrace{P_k,\dots,P_k}_{a_k}) $$
\end{theorem}


\begin{definition} \label{Cayley_sum_def}
    Let $k \le n$ be non-negative integers. Let $e_1, \dots ,e_k$ be the standard basis of $\Z^k$. For finite sets $\Ps_0, \Ps_1,\dots, \Ps_k \subset \Z^{n-k}$, the \textbf{Cayley sum} is defined to be 
    $$\Ps_0 \ast \Ps_1 \ast \cdots \ast  \Ps_k = (\Ps_0 \times \{0\}) \cup (\Ps_1 \times \{e_1\}) \cup \dots \cup (\Ps_k \times  \{e_k\})$$
    The Cayley sum of convex polytopes is defined as the convex hull of the corresponding shifts of the polytopes.
\end{definition}


The volume of the Cayley sum of convex polytopes can be calculated via the mixed volume. The original proofs of these formulas use algebraic geometry (more precisely, they consider the Euler characteristic of certain hypersurfaces in complex tori). These results also admit purely combinatorial proofs using the Cayley trick.

\begin{remark}\cite[Below Remark 6.6]{DK86} \label{cayley_vol_rem}
    Consider lattice polytopes $P_0,\dots P_k \subset \R^{n-k}$. Then the volume of their Cayley sum can be calculated in terms of their mixed volumes:
    $$Vol_\Z(P_0 \ast P_1 \ast \cdots \ast  P_k) = \sum\limits_{\substack{a_0 \ge 0, \dots , a_k \ge 0 \\ a_0+\dots + a_k = n-k}} MV(\underbrace{P_0,\dots,P_0}_{a_0}, \dots, \underbrace{P_k,\dots,P_k}_{a_k})$$
\end{remark}


\begin{lemma}\cite[Lemma 1.7.]{Es10} \label{cayley_signed_vol_lem}
    Consider lattice polytopes $P_0,\dots, P_k \subset \R^{n-k}$. Then we have the following formula
    $$\sum\limits_{\substack{I \subset \{1,\dots,k\}\\ I =\{i_1,\dots, i_{|I|}\} }} (-1)^{k-|I|} Vol_\Z(P_{i_1} \ast \cdots \ast  P_{i_{|I|}}) = \sum\limits_{\substack{a_0 > 0, \dots , a_k > 0 \\ a_0+\dots + a_k = n-k}} MV(\underbrace{P_0,\dots,P_0}_{a_0}, \dots, \underbrace{P_k,\dots,P_k}_{a_k})$$

    In other words, we can rewrite the BKK-theorem as certain Newton number. Denote by $C$ the cone $\R^{k}_{\ge 0} \oplus \R^{n}$ and consider any point $Q\in \Z^{n}$, then under assumptions of Theorem \ref{BKK_th} we have:

    $$\chi (\{f_1= \dots = f_k = 0\}) =  (-1)^{n-k} \nu_{C} (Q\ast P_1\ast\dots\ast P_k)$$

\end{lemma}

For a more general formula for the mixed volume of Cayley sums see \cite[Theorem 24]{Es12}.

\subsection{Preliminaries: Zero-dimensional critical complete intersections}\label{0-cci_subsec}

\subsubsection{Euler obstructions of sets}

Let us recall the formula for the number of points of zero-dimensional critical complete intersections from \cite[Lemma 2.50]{Es17}. First, we recall the Euler obstructions of toric varieties from \cite{MT11} (for an introduction to the toric varieties see e.g. \cite{Ful}). Euler obstructions were introduced in \cite{Mcp74} in order to construct characteristic classes of singular complex algebraic varieties. We use the notations from \cite[Section 1.5]{Es10}.

\begin{definition}
A subset $\As'\subset \As\subset\Z^k$ is called a \textbf{face}
of $\As$, if it can be represented as the intersection of $\As$ with
a face of the convex hull of $\As$. The \textbf{dimension} $\dim \As$ of $\As$ is the dimension of its convex hull.
\end{definition} 

For a face $\As'$ of a finite set $\As\subset\R^k$, let $M'$ and $M\subset\R^k$ be the vector spaces, parallel to the affine spans of $\As'$ and $\As$
respectively. We denote the projection $\R^k\to\R^k/M'$ by $\pi_{\As'}$. Then the lattice volume of the difference of the convex hulls of $\pi_{\As'}(\As)$ and $\pi_{\As'}(\As\setminus
\As')$ is denoted by $c^{\As'}_\As\in\Z$. Set $c^{\As}_\As$ to $1$ and
$c^{\As'}_{\As}$ to $0$ if $\As'$ is not a face of $\As$.


Consider the square matrix $C$ with entries $c^{\As''}_{\As'}$, where
$\As''$ and $\As'$ run over the set of all faces of $\As$, and define
$e^{\As''}_{\As'}$ as the $(\As'',\, \As')$-entry of the inverse of $C$.
Note that $C$ is upper triangular with $1$'s on the diagonal, if
we order faces of $\As$ by their dimension; in particular, the
determinant of $C$ equals $1$, and its inverse is integer.

\begin{definition}
The number $e^{\As'}_ {\As}$ is called the \textbf{Euler
obstruction} of the set $\As$ at its face $\As'$.
\end{definition}

See e.g. \cite[Example 1.24 and Example 1.26]{Es10} for an illustration of the combinatorial definitions. Euler obstructions of sets have the following geometric meaning.

\begin{proposition}\cite{MT11}
    The Euler obstruction of the set $\As \subset \Z^k$ at its face $\As'$ equals $(-1)^{\dim \As-\dim \As'}$ times the Euler obstruction of the toric variety, corresponding to $\As$, at a point of its orbit, corresponding to $\As'$.
\end{proposition}

\begin{definition}\label{smooth_set_def}
    A set $\As$ is called \textbf{smooth} at its face $\As'$ if $\pi_{\As'} (Conv(\As)) \setminus \pi_{\As'}(Conv(\As \setminus \As'))$ is a unimodular  simplex.
\end{definition}

\begin{remark}\label{eu=1_rem}
    By the definition of the Euler obstruction, its value is $1$ on the smooth stratum. The projective toric variety corresponding to the set $\As$ is smooth at the orbit corresponding to its face $\As'$ if and only if the set $\As$ is smooth at $\As'$ and $\As' \cap \Z^n = \text{aff}(\As') \cap \Z^n$ (see e.g. \cite[Chapter 5, Theorem 3.16.]{GKZ94}). However, it is straightforward to verify (e.g., combinatorially) that $e^{\As'}_{\As} = (-1)^{\dim \As - \dim \As'}$ for any smooth face $\As'$ of $\As$.
\end{remark}


\subsubsection{Zero-dimensional critical complete intersections}

Denote the $(n+1)$-dimensional space of affine linear functions on $\Z^n$ by $(\Z^n)^\star$, to be distinguished from the dual space $(\Z^n)^*$. For every subspace $L\subset\Z^n$, let $L^\perp\subset (\Z^n)^\star$ be the set of affine functions on $\Z^n$ that vanish on $L$. For a Laurent polynomial $f(z)=\sum_{b\in\Z^n} c_bz^b$ on $\CC^n$ with the standard coordinates $z=(z_1,\ldots,z_n)$ and an element $\alpha\in(\Z^n)^\star$, denote the polynomial $\sum_{b\in\Z^n} \alpha(b)c_bz^b$ by $\partial_\alpha f$.

\begin{ex} If $\alpha$ is the $i$-th coordinate function, then $\partial_\alpha f=z_i\frac{\partial f}{\partial z_i}$.
\end{ex}

\begin{definition}The set  $\{\partial_D f=0\}\subset\CC^n$, given by the equations $\partial_\alpha f=0,\, \alpha\in D$, is called a {\bf critical complete intersection}.
\end{definition}

Assume that $D\subset(\Z^n)^\star$ is a hyperplane. It is uniquely determined by the common zero $D^\star\in\mathbb Q \mathbb P^n$ of all affine linear functions $\alpha\in D$. We also denote by $Q^\star, Q \in \mathbb Q \mathbb P^n$ the hyperplane in $(\Z^n)^\star$ consisting of all affine functions vanishing at $Q$. Let $\mathfrak{A}_\As (D^\star)$ be the set $\{\Gamma\,|\,\Gamma$ is a face of the convex hull of $\As$, and the affine span of $\Gamma$ contains $Q\}$.


\begin{proposition}\label{deg_cci_prop}\cite[Section 2.7.]{Es17}
Consider a generic polynomial $f$ with support $\As$. Critical complete intersection defined by $f$ is indeed a complete intersection. The system $\partial_D (f)$ is degenerate at a face $\Gamma \subset \conv (\As)$ (in the Bernstein-Kouchnirenko-Khovanskii sense) only if $\Gamma \in \mathfrak A_\As(D^\star)$.
\end{proposition}

\begin{definition}\label{e_nn_def}
    Define the \textbf{$\mathbf e$-Newton number} $\nu_Q^e(\As)$ to be the sum $\sum_{\Gamma\in\mathfrak{A}_\As(Q)} e^\Gamma_\As \Vol_\Z \Gamma$, where $e^\Gamma_\As$ is the Euler obstruction of $\As$ at $\Gamma$.
\end{definition}


\begin{remark}
    One can think of $\nu_Q^e(\As)$ as the $e$-Newton number with respect to the convex cone $C_Q(\Ps)$ with vertex $Q$ and spanned by $\As$. It is important for the following subsection, where we compare different Newton numbers.
\end{remark}

\begin{lemma} \label{dim0crit_lem} (the statement appears in \cite[Lemma 2.50.]{Es17}, see \cite[Theorem 1.8]{Es24b} for a more detailed proof) Consider a finite set $\As \subset \Z^n$ and a hyperplane $D$ in $(\Z^n)^\star$, then, for a generic Laurent polynomial $f(x)=\sum_{z\in A} c_az^a$, the zero-dimensional critical complete intersection $\{\partial_D f=0\}$ consists of $\nu_{D^\star}^e(\As)$ points (counted with multiplicity).
\end{lemma}

\begin{remark}
    The above lemma is proved in \cite[Theorem 1.8]{Es24b} for $D^\star = 0$. This immediately implies the lemma for arbitrary $D^\star\in\Z^n$ since it corresponds to the shift of $\As$ by $-D^\star$. The proof for arbitrary $D^\star \in \mathbb Q\mathbb P^n$ is the same; it can be also proved by constructing an appropriate set $\As^{+1} \subset \Z^{n+1}$, so that $\nu^e_{D^\star}(\As) = \nu^e_O(\As^{+1})$ (as in Remark \ref{-1dim_rem}).
\end{remark}

\begin{remark}\label{inv_nu_e_rem}
    In \cite[Lemma 2.50.]{Es17} it is said that the formula from Lemma \ref{dim0crit_lem} ``is the Bernstein formula \cite{Ber75} with some roots hidden at infinity (more precisely, at the orbits of the $\As$-toric variety, corresponding to the faces from $\As$)''. It is easier to see that if we invert the formula:
    $$\Vol_\Z (\conv (\As)) = \sum\limits_{\Gamma \in \mathfrak A_\As(Q)} c_\As^\Gamma \cdot  \nu^e_Q(\Gamma \cap \As)$$
    Namely, by the version of the Bernstein-Kouchnirenko theorem from Remark \ref{bk_th_toric_rem}, the total number of solutions on the $\As$-toric variety of the system $\{\partial_D f = 0\}$ (considered as the sections of $I_P$) is equal to $\Vol_\Z (\conv (\As))$. But the system is not Newton non-degenerate and some solutions are on tori corresponding to proper faces of $\As$. For each face $\Gamma \in \mathfrak A_\As(Q)$, we can consider the subsystem $\{\partial_{\Gamma^\star} f = 0\}$ defined by linear functionals vanishing on $\Gamma$. One can check that the non-degeneracy conditions from  \cite[Lemma 1.28]{Es10} are satisfied, so \cite[Lemma 1.28]{Es10} implies that the system $\{\partial_{\Gamma^\star} f = 0\}$ contains the toric orbit corresponding to $\Gamma$ with multiplicity $c_\As^\Gamma$. The total multiplicity of solutions of the ``factor-system'' $\{\partial_{Q^\star / \Gamma^\star} f = 0\}$ restricted to the corresponding orbit is equal to $\nu_Q^e(\Gamma \cap \As)$ by the definition of the $e$-Newton number.

    Thus, on the orbit corresponding to $\Gamma \in \mathfrak A_\As(Q)$, there is a discrete set of solutions with total multiplicity $c_\As^\Gamma \cdot  \nu^e_Q(\Gamma \cap \As)$.
\end{remark}


\begin{ex}\label{crit_ex}
    The number of critical points $\# \{\frac{\partial f}{x_1} = \dots = \frac{\partial f}{x_n} = 0\}$ of a generic polynomial $f$ with support $\As$ in the torus equals $\nu^e_O (\As)$, where $O$ is the origin.
\end{ex} 

In the case of a critical complete intersection, the Bernstein-Kouchnirenko-Khovanskii non-degeneracy conditions are violated (otherwise the number of solutions would have been $\Vol_\Z (Conv(\As))$). However, the degeneracy of such systems can be controlled and analogues of the Bernstein-Kouchnirenko-Khovanskii formulas can be obtained. The geometry of such (and more general) complete intersections was recently studied in \cite{Es24a}, \cite{Es24b} and \cite{Es25}.

\subsection{Comparison of Newton numbers: $\nu$, $\nu^\ell$ and $\nu^e$}\label{Comparison_sec}

In this subsection we compare different types of Newton numbers: the usual Newton number (Definition \ref{newton_def}), the $\ell$-Newton number (Definition \ref{l_nn_def}) and the $e$-Newton number (Definition \ref{e_nn_def}).


\begin{remark}
    Both $\nu^\ell$ and $\nu^e$ are non-negative (by Theorem \ref{loc_h*_ag_th} and Lemma \ref{dim0crit_lem}), while the usual $\nu$ is generally not (see \cite[Example 2.5, p.353]{GKZ94}).
\end{remark}

\begin{remark}\label{ell=nu_rem}
    Suppose that $P$ is a convenient polytope in a cone $C$ and the face poset $\Cp$ of $C$ is boolean (i.e., the projection of $C$ along the maximal vector subspace in it is a simplicial cone). Then by Theorem \ref{loc_h*_ag_th} we have $\nu_C(P) = \nu^\ell_C(P)$.
\end{remark}


\begin{lemma}\label{nu>nu_e_lem}
    Consider a set $\Ps$ such that $P = \conv(\Ps)$ is a convenient polytope in the cone $C = \R^m_{\ge 0} \oplus \R^{n-m}$ and a point $X \in \Z^{n-m}$. Then we have:
    $$\nu_C(P) = \nu^\ell_C(P) \ge \nu^e_X (\Ps)$$
\end{lemma}

\begin{proof}
    Without loss of generality we may assume that $X= O$ is the origin (the corresponding shift does not change the usual Newton number).

    Consider the dual fan $\Sigma$ of $P$ with support $(\R^n)^{*}$ and the corresponding toric variety $\mathbb T^\Sigma$. Suppose that $e_1,\dots,e_m, e_{m+1}, \dots, e_n$ is the standard basis of $\Z^m\oplus \Z^{n-m}$. Suppose that $f$ is a generic polynomial with support $\Ps$. Consider $\partial_{e_i} f = z_i \frac{\partial f}{\partial z_i}$ as sections of the line bundle $I_P$ corresponding to the polytope $P$ on $\mathbb T^\Sigma$.


    Consider rays $\xi_1,\dots ,\xi_m \subset (\Z^n)^*$ corresponding to $e_1,\dots ,e_m \subset \Z^n $ in the dual basis. Note that the section $\partial_{e_i} f = z_i \frac{\partial f}{\partial z_i}, i \le m$ of $I_P$ vanishes at the orbit corresponding to $\xi_i$. Thus, the divisor of $I_P$ is the sum of two effective divisors $D_{\xi_i} + D_{f,i}$, where $D_{\xi_i}$ is the reduced closure of the orbit, corresponding to $\xi_i$.

    Recall that the sections $\partial_{e_1} f = \dots = \partial_{e_n} f$ of $I_P$ have only isolated intersections on $\mathbb T^\Sigma$ (see Remark \ref{inv_nu_e_rem}). Thus the global intersection number is the sum of positive local intersection multiplicities. By Remark \ref{bk_th_toric_rem} the sum of multiplicities of $\{\partial_{e_1} f = \dots = \partial_{e_n} f = 0\}$ on $\mathbb T^\Sigma$ is equal to $\Vol_\Z (P)$. The inclusion-exclusion principle (similar to \cite[Section 4]{Oka79}) implies that:

    $$\nu_C(P) = mult(D_{f,1} \cdot {\dots }\cdot D_{f,n} \cdot \mathbb T^\Sigma)$$

    Recall that the number of points of $\{\partial_{e_1} f = \dots = \partial_{e_n} f = 0\}$ in the open torus equals $\nu^e_O (\Ps)$. Thus it is less than or equal to the total multiplicity in $\mathbb T^\Sigma$. 
\end{proof}

It is also easy to prove Lemma \ref{nu>nu_e_lem} for an arbitrary cone in dimension $2$. We conjecture that the same inequality holds for every cone.


\begin{con}\label{nu_ell>nu_e_con}
    Consider a cone $C$ and a finite set $\Ps \subset C \subset \R^n$, such that $\conv (\Ps) = P$ is convenient in $C$. Suppose that $C_\text{min}$ is the minimal face of $C$. Then for every $X \in C_{\text {min}} \cap \Z^n$ we have the following inequalities between the $\ell$- and the $e$-Newton numbers:
    $$\nu_C^\ell(P) \ge \nu^e_X(\Ps)$$
\end{con}

The following remark is implied by the proof of Lemma \ref{nu>nu_e_lem} in case of convenient polytopes, and it is also implied by \cite[Theorem 5.10 (2)]{Sel24}.

\begin{remark}\label{mon_nu_rem}
    The Newton number in the cone $C = \R^m_{\ge 0} \oplus \R^{n-m}$ is monotonous, i.e., if $P_1\subset P_2\subset C$ are convenient, then $\nu_C(P_1) \le \nu_C(P_2)$.
\end{remark}

\begin{lemma}\label{nu_e=mv_lemma}
    Consider a cone $C$ with boolean face poset $\Cp$, i.e., its projection along the maximal affine subspace of $C$ is a simplicial cone. Denote its facets by $E_1,\dots,E_m$. Consider a lattice set $\Ps \subset C$, the polytope $P = \conv (\Ps)$ and a point $Q\in E_1\cap\dots\cap E_m$. Suppose that the affine span of any face in $\mathfrak A_\Ps (Q)$ is a face of $C$. Then we have the following formula:
$$\nu_Q^e(\Ps) = MV(\conv(\Ps \setminus E_1), \dots, \conv(\Ps \setminus E_m), P, \dots, P)$$
\end{lemma}

\begin{remark}
    The conditions of the above lemma are applied, for instance, if $P$ is a convenient and $Q\in E_1\cap\dots\cap E_m$ is a generic point.
\end{remark}

\begin{proof}
Consider the covectors $\xi_1,\dots, \xi_m$ orthogonal to the facets of $C$. Consider $n-m$ affine functions $\psi_{m+1}, \dots,\psi_n$ vanishing on $Q$ so that $\xi_1,\dots, \xi_m, \psi_{m+1}, \dots,\psi_n$ form a basis in $Q^\star$. The critical complete intersection is defined by the system $\partial_{\xi_1} f =\dots = \partial_{\xi_m} f = \partial_{\psi_m+1} f = \dots \partial_{\psi_n} f$. Note that the Newton polytopes of the corresponding polynomials are contained in $Conv(\Ps\setminus E_1) , \dots, Conv(\Ps\setminus E_m), P,\dots,P$ respectively. Proposition \ref{deg_cci_prop} implies that the corresponding system is non-degenerate in the sense of the Bernstein-Kouchnirenko theorem \ref{bk_th}. This implies that the number of solutions equals the mixed volume.
\end{proof}

%\begin{definition}
%    Convex polytope $P$ in cone $C$ is called \textbf{almost strongly convenient} if the poset $\Cp_P = \{ Y \in \Cp:\dim(P\cap Y) = \dim (Y)\}$ form an upper poset of $\Cp$, i.e. together with each face contains all the faces containing it.
%\end{definition}


The following lemma is implied by Remark \ref{eu=1_rem}.


\begin{lemma}\label{nu_e=nu_lem}
Consider a finite lattice set $\Ps$, its convex hull $P = \conv (\Ps)$, and a point $Q\in \mathbb Q^n$. Suppose that for any face $F \in \mathfrak A_\As(Q)$, the set $\Ps$ is smooth at $\Ps \cap F$. Then we have $\nu_Q^e(\As) = \nu_{\mathsmaller {C_Q(\Ps)}}(P)$.
\end{lemma}

\begin{remark}
Denote by $\Ds_m$ the set of vertices of the unit m-simplex in $\R^m_{\ge 0}$. Consider a convenient polytope $P = \conv (\Ps), \Ps \subset \Z^n$ in the cone $C = \R^m_{\ge 0} \oplus \R^{n-m}$. Suppose that $\Ds_m \subset \pi_{\R^{n-m}}(\Ps)$ and $X \in \mathbb Q^{n-m} \subset \R^{n-m}$ is a generic point (for instance, in the relative interior of $P \cap \R^{n-m}$). Then the conditions of the above lemma are satisfied and we have $\nu^e_X(\As) = \nu_C(P)$.
\end{remark}




\subsection{Algebraic degrees} \label{algebraic_subsec}


In this subsection, following \cite[Example 1.7(6)]{Es24b}, we recall that different algebraic degrees are equal to the number of points in zero-dimensional critical complete intersections. Hence, they are equal to the corresponding $e$-Newton numbers in the Newton non-degenerate case.

We show that the formulas for the maximum likelihood degree from \cite[Theorem 15]{CHKS06} and \cite{LNRW23}, the Euclidean distance degree (introduced in \cite{DHOST16}) from \cite{BSW22} and \cite{TT24}, and the polar degree from \cite[Corollary 4.6.]{Huh13} are all implied by properties of the $e$-Newton number given in \S \ref{Comparison_sec}. Our formulas generalize those for maximum likelihood and Euclidean distance degrees, while for polar degree we provide new formulas (including expressions via the mixed volume).

We also discuss geometrically interesting cases, where the maximum likelihood degree is equal to $0$ or $1$ (see \cite{Huh14} and \cite[Theorem 1.11]{Es24c}), and the polar degree is equal to $0$ or $1$ (see \cite[Example 4.8. and below]{Huh13} and \cite{CRS08}).

%In this subsection we recall the different types of algebraic degrees, recall \cite[Example 1.7(6)]{Es24b} that these degrees are equal to the number of points of certain $0$-dimensional complete intersections. We provide formulas for all these degrees in terms of the (usual) Newton number. We show that this technique provides the formulas for the Eucledean distance degree from \cite{DHOST16}, \cite{BSW22} and \cite{TT24}, the formulas for the maximum likelihood degree (or signed Euler characteristic) from \cite[Section 3]{Kh78}, \cite[Theorem 15]{CHKS06} and \cite{LNRW23}. We provide analogues formula for the polar degree (or the degree of the gradient map) using the mixed volume and show that it is consistent with the formula \cite[Corollary 4.6.]{Huh13}. 

The following theorem is \cite[Example 1.7(6)]{Es24b} with several minor additions and corrections. We consider all the algebraic degrees in separate subsubsections below. In the following theorem we use the usual Lagrangian multiples, and the ones that we call ``outer'' Lagrangian multiples and ``dehomogenizing'' Lagrangian multiples. We call them this way since ``outer'' Lagrangian multiples let us count the critical points outside the corresponding variety and ``dehomogenizing'' Lagrangian multiples let us count the degree of the gradient map by extracting a single point out of a projective line (for more detailed see the corresponding subsubsections below).

There are two types of maximum likelihood degrees, we need to distinguish them in the theorem.

\begin{enumerate}
    \item For mappings (see \cite{CHKS06}), we call it the \textbf{MML-degree}.
    \item For subvarieties (see \cite{Huh13} and \cite{HS}), we calle it the \textbf{ML-degree}.
\end{enumerate}

\begin{theorem}(cf. \cite[Example 1.7(6)]{Es24b})\label{alg_deg_th}
Algebraic degrees are equal to certain $e$-Newton numbers in the Newton non-degenerate case. Below we list all of them. Recall that \textbf{very affine variety} is a closed subvariety of the complex torus $(\Cc)^n$.

\begin{enumerate}
    \item \textbf{Mapping maximum likelihood degree (MML-degree)} from \cite{CHKS06}

    Consider a mapping  $\mathbf \Theta = (\Theta_1,\dots,\Theta_{m}): (\Cc)^{n-m} \to (\Cc)^{m}$. The critical points of the function $\mathbf \Theta ^ u = \Theta_1^{u_1} \dots \Theta_{m}^{u_{m}}$ on $(\Cc)^{n-m} \setminus\bigcup_i \{\Theta_i = 0\}$ are defined via ``outer'' Lagrangian multipliers:

    $$\partial_{Q_u^\star} (\mathbf \Theta_{\text{MML}}(z,\lambda)) = 0\text{\quad , where}$$

    $$\mathbf \Theta_{\text{MML}}(z,\lambda) = c + \sum\limits_{i=1}^{m} \Theta_i\lambda_i \quad \quad c \in \Cc  \quad \quad Q_u  =  (u_1:{\dots}:u_{m}:\underbrace{0:{\dots}:0}_{{n-m+1}}) \in \mathbb Q \mathbb P^n$$

    In the Newton non-degenerate case with supports $\Ps_1,\dots ,\Ps_m$, the MML-degree equals:

    $$\text{MMLdeg} (\mathbf \Theta,u) = \nu^e_{Q_u} (O\ast \Ps_1 \ast \dots \ast \Ps_m)$$

    \item \textbf{Maximum likelihood degree (ML-degree)} from \cite{Huh14}

    The critical points of $z^u$ on the smooth very affine variety $V_{\mathbf f} = \{f_1 = \dots = f_m = 0\}\subset (\Cc)^{n-m}$ are defined via Lagrangian multipliers:

    \begin{align*}
    &\partial_{O^\star} (F_{\text{ML}}(z,\lambda)) = 0 \quad \text{, where}\\
    &F_{\text{ML}}(z,\lambda) = z^u + \sum \limits_{i=1}^m\lambda_i f_i
    \end{align*}

    In the Newton non-degenerate case with supports $\Ps_1,\dots ,\Ps_m$, the ML-degree equals:

    $$\text{MLdeg} (V_{\mathbf f},u) =  \nu^e_O(u\ast \Ps_1\ast\dots\ast \Ps_m)$$

    \item \textbf{Eucledean distance degree (ED-degree)} from \cite{DHOST16}

    The critical points of the distance function $\rho_u$ on the very affine variety $V_{\mathbf f} = \{f_1 = \dots = f_m = 0\}\subset (\Cc)^{n-m}$ are defined via Lagrangian multipliers:

    \begin{align*}
    &\partial_{O^\star} (F_{\text{ED}}(z,\lambda)) = 0 \quad \text{, where}\\
    &F_{\text{ED}}(z,\lambda) = \rho_u + \sum \limits_{i=1}^m\lambda_i f_i
    \end{align*}

    Denote by $\mathbf \D_\rho$ the support of the quadratic distance function. In the Newton non-degenerate case with supports $\Ps_1,\dots ,\Ps_m$, the ED-degree is equal to:

    $$\text{EDdeg} (V_{\mathbf f}) =  \nu^e_O(\Ds_\rho\ast \Ps_1\ast\dots\ast \Ps_m)$$

    \item \textbf{Polar degree (P-degree)}

    Consider a degree $d$ homogeneous polynomial $f \subset \C[z_0,\dots,z_n],\ d\ge 2$, and a generic linear function $L_\mathbf{c} (z) = c + c_0z_0 + \dots + c_nz_n$. Then the preimages of the point $\mathbf c = (c_0:{\dots}:c_n) \in \C \mathbb P^n$ under the gradient map:
    $$\grad (f): \C \mathbb P ^n  \dashrightarrow \C \mathbb P^n, \quad \grad(f) = (\frac{\partial f}{\partial z_0}: \dots:  \frac{\partial f}{\partial z_n})$$
    are defined via ``dehomogenizing'' Lagrangian multipliers:

    \begin{align*}
    &\partial _{O^\star} (F_{\text{P}}(z,\lambda)) = 0 \quad \text{, where}\\
    &F_{\text{P}}(z,\lambda) = \lambda L_{\mathbf c} (z) + f(z)
    \end{align*}

    Denote by $\Ds_{n+1}$ the set of vertices of the unit simplex in $\Z^{n+1}$. In the Newton non-degenerate case with support $\Ps$ the P-degree (i.e. the number of the preimages of a generic point $\mathbf c \in \C \mathbb P^n$) is equal to:

    $$\text{Pdeg} (f) =  \nu^e_O(\Ps \ast \Ds_{n+1}) = \nu_{\mathsmaller{ \R^{n+2}_{\ge 0}}} (\Ps \ast \Ds_{n+1})$$

    Note that the dimension can be reduced by $1$ (see Remark \ref{-1dim_rem}).
\end{enumerate}

\end{theorem}

