    \begin{tabular}{|c|c|c|c|c|c|c|c|c|}
        $A_1$ & $B_1$ & $A_2$ & $B_2$ & $A$ & $B$ & $C$ & $D$ & $E$ \\
         $e_1$ & $e_1 + e_3$ & $e_2$ & $e_2+e_3$ & $0$ & $3e_3$ & $3e_4$ & $3e_5$ & $e_3+e_4+e_5$
    \end{tabular}
    \label{12}
\end{table}

\begin{figure}[H]
		\begin{center}
	\includegraphics[scale=7]{Thin_example.png}
		\end{center}
		\caption{
		\label{Thin_example} Example of a thin polytope which is neither trivially thin nor a join}
