\subsection{Proof of the $B_k$-Theorem}


In this section we prove the $B_k$-Theorem \ref{neg_class_th}.

We split the proof into two parts. First, we check that $B_k$-polytopes are indeed negligible and this is the easy part. Second, using the Furukawa-Ito classification of dual defective sets, we prove that if a polytope $P$ is negligible, then it is a $B_k$-polytope.

\subsubsection{$B_k$-polytopes are negligible}


\begin{lemma}(Simple part of the $B_k$-theorem)\label{B_k-neg_lem}
    Consider the cone $C = \R^m_{\ge 0} \oplus \R^{n-m}$. Then any $B_k$-polytope $P\subset \R^m_{\ge 0} \oplus \R^{n-m}$ based on a coordinate subspace $\R^k_{\ge 0} \subset \R^m_{\ge 0}$ is negligible.
\end{lemma}


\begin{proof}

First let us prove the lemma for $B_k$-polytopes in $C = \R^k_{\ge 0} \oplus \R^{n-k}$. Applying Lemma \ref{cayley_signed_vol_lem} to $P_0 \ast P_1 \ast \cdots \ast  P_k$ and $P_1 \ast \cdots \ast  P_k$ we obtain:

$$\nu_{Q} (P_0 \ast P_1 \ast \cdots \ast  P_k) = \sum\limits_{\substack{a_0 \ge 0, a_1> 0, \dots , a_k > 0 \\ a_0+\dots + a_k = n-k}} MV(\underbrace{P_0,\dots,P_0}_{a_0}, \dots, \underbrace{P_k,\dots,P_k}_{a_k})$$

Recall that by the definition of $B_k$-polytopes, we have $\dim(P_1 + \dots + P_k) < k$, so by Proposition \ref{mv=0_prop} each summand of the above sum is equal to $0$. Thus, we obtained that the Newton number vanishes:
$$\nu_Q(P_0 \ast P_1 \ast \cdots \ast  P_k) = 0$$

Now we pass to the arbitrary case $C = \R^m_{\ge 0} \oplus \R^{n-m}, m \ge k$. Let us decompose the cone $C$ in the following way $C = \R^k_{\ge 0} \oplus \R^{m-k}_{\ge 0} \oplus \R^{n-m}$. To avoid confusion, denote the first summand by $L_k = \R^k_{\ge 0}$ and the last by $L_{n-m} = \R^{n-m}$. For $J \subset \{k+1,\dots,m\}$, denote by $E_J\subset \R^n$ the vector space generated by the corresponding coordinate vectors. Denote by $C_J \subset \R^n, \dim C_J = n + k - m + |J|$ the cone $L_k +E_J + L_{n-m}$. Then we have:

$$\nu_C(P_0 \ast P_1 \ast \cdots \ast  P_k) = \sum\limits_{J \subset \{k+1,\dots,m\}} (-1)^{m-k-|J|} \nu_{\mathsmaller {C_J}} ((P_0 \ast P_1 \ast \cdots \ast  P_k )\cap C_J)$$

Note that each summand is a $B_k$-polytope in a cone $\R^k_{\ge 0}\oplus \R^{n-m+|J|}$ based on $\R^k_{\ge 0}$. Hence all these summands are equal to $0$ as we checked in the beginning of the proof of the lemma.

\end{proof}


\subsubsection{Negligible polytopes are $B_k$-polytopes}

Consider a negligible polytope $P \subset C = \R^m_{\ge 0}\oplus \R^{n-m}$. Denote by $\Ps \subset \Z^m_{\ge 0} \oplus \Z^{n-m}$ a lattice set such that $\conv(\Ps) = P$ (e.g. the set of the vertices of $P$ or $P \cap \Z^n$).

The idea of the proof is to consider the Newton number in $C$ as the $e$-Newton number and apply the Furukawa-Ito classification theorem of dual defective sets. The Furukawa-Ito theorem provides that our set is a Cayley sum with certain properties, but we need the Cayley sum to be a ``coordinate'' Cayley sum, and verifying it is the non-trivial part of the proof.



%\begin{lemma}(Complicated part of the $B_k$-theorem in spanning case)\label{b_k_span_lem}
%Consider cone $C = \R^m_{\ge 0} \oplus \R^{n-m}$ and a spanning lattice set $\Ps \subset \Z^m_{\ge 0} \oplus \Z^{n-m}$. Suppose that $P = \conv(\Ps)$ is a negligible polytope $C$. Then $P$ is a $B_k$-polytope based on a face of $C$.
%\end{lemma}

First, we need the following proposition.


\begin{proposition}\label{no_cay_prop}
    Consider a full-dimensional lattice set in $\Ps \subset \Z^r$. Then for a generic point $X \in \Z^r$ the set $\Ps \cup X$ has width greater than $1$ (i.e. is not a non-trivial Cayley sum).
\end{proposition}

\begin{proof}
    Consider a subset $\Ds \subset \Ps$ consisting of vertices of an $r$-dimensional simplex. For a pair of opposite faces $F_1 \sqcup F_2 = \Ds$, consider the stripe parallel to $\text{aff} (F_1-F_2)$ such that $F_1$ and $F_2$ are on its boundary. Then for any point $X$ onside such $2^r$ stripes the union $\Ps \cup X$ has width greater than one.
\end{proof}

\begin{remark}
    A similar Proposition \ref{no_cay_prop} can be proved for arbitrary large width.
\end{remark}

Consider a generic lattice point $X \in \Z^{n-m}$. By Lemma \ref{nu>nu_e_lem} we have the inequality $\nu^e_X(\Ps) \ge \nu_C(P)$, so $\nu^e_X(\Ps) = 0$. Note that $\nu^e_X(\Ps) = \nu^e_X(\Ps \cup X)$ (it is implied e.g. by Remark \ref{dim0crit_lem}). Denote by $\As \supset O$ the set $(\Ps \cup X)-X$, i.e. the set $\Ps \cup X$ shifted by the vector $-X$. By Lemma \ref{dual=no_crit_points_lem} it is dual defective. 



%Consider negligible polytope $P \subset \R^n_{\ge 0}$. Recall that $\nu(P)$ is the number of critical points of generic polynomial with Newton polyhedron in $\C^n$. The polytope $P$ is negligible, hence generic polynomial with Newton polytope $P$ has no critical points in $\C^n$ and hence no critical points in the torus $(\C \setminus 0)^n$. Thus, by Lemma \ref{dual=no_crit_points_lem} the set $\Ps = P \cap \Z^n$ is dual defective. Note that $\Ps$ is spanning, since it contains the vertices of the unit simplex (and similar argument does not work for the cones $\R^m_{\ge 0}\oplus\R^{n-m}, n>m$). 

Denote by $\Z_\As^n$ the minimal sublattice of $\Z^n$ containing $\As$.
From the Furukawa-Ito classification Theorem \ref{dual_defect_classification_th} (and Remark \ref{dual_defect_classification_rem}) we obtain that there are integers $k>c$, two projections $\pi_k: \Z_\As^n \to \Z^k$ and $p: \Z_\As^n/\Z^k \to \Z^{n-k-c}$ such that:
\begin{enumerate}
    \item $\pi_k (\As) = Conv (O,q_1,\dots,q_k)$ is the unit simplex in $\Z^k$
    \item Define $\As_0 = (\pi_k^{-1} (O) \cap \As)/\Z^k$ and $\As_i = (\pi_k^{-1} (q_i) \cap \As)/\Z^k$. Then  $p(\As_0) \ast \dots \ast p(\As_k)$ is of join type.
\end{enumerate}

Without loss of generality we can assume that $\pi_k (O) = O$, where $O$ is the origin (otherwise we can compose $\pi$ with an appropriate affine automorphism of $\Z^k$). Consider the affine extension of $\pi_k$ on $\R^n$ and denote it also by $\pi_k$. Note that the image of the lattice $\pi_k(\Z^n)$ may not be contained in the lattice $\Z^k$.

\begin{remark}\label{to_O_rem}
    By Proposition \ref{no_cay_prop} we have $\pi_k(\R^{n-m}) = O$.
\end{remark}

\begin{proposition}\label{pk_map_type_prop}
    There are positive integers $a_i^j \in \Z_{>0}^n$ and a renumbering of the standard basis $e_i^{(j)}$ of $\Z^n$ so that the map $\pi_k$ can be written in the following way:
    $$
\pi_k:
\begin{cases}
e_0^{(1)}, \dots , e_0^{(j_0)} &  \to 0\\
a_1^{(1)} e_1^{(1)}, \dots , a_1^{(j_1)} e_1^{(j_1)} &  \to q_1\\
 \ \  \ \ \ \ \  \dots  & \dots \\
a_k^{(1)} e_k^{(1)}, \dots , a_k^{(j_k)} e_k^{(j_k)} &  \to q_k
\end{cases} $$

\end{proposition}

\begin{proof}
    By Remark \ref{to_O_rem} we have $\pi_k(\R^{n-m}) = O$, so the first $n-m$ elements $e_0^{(1)}, \dots, e_0^{(n-m)}$ are the standard basis of $\Z^{n-m}$. For each standard basis vector $v_i$ of $\Z^m_{\ge 0}$ there exists $a_i \in \Z_{>0}$ and a point of $\As$ whose projection along $\Z^{n-m}$ is $a_i v_i$, since $\conv (\As)$ is convenient in $C$. So $\pi_k(a_i v_i)$ is either the origin $O$ or a basis vector $q_j$. Considering this way all the coordinate rays of $\Z^{m}_{\ge 0}$, we obtain the required form.
\end{proof}



Denote by $\pi_K^O : C \to \R^{k+r}_{\ge 0}$ the projection along the vector subspace generated by $e_0^{(1)}, \dots , e_0^{(j_0)}$ (here $r = n-k-j_0$).

\begin{remark}
    The projection $\pi_k^O(\As)$ contains exactly one point on each coordinate ray of $\Z^{k+r}_{\ge 0}$ apart from the origin, and its coordinate is the corresponding $a_i^{(j)}$.
\end{remark}

First let us prove the $B_k$-theorem if all these points have unit coordinate.

\begin{lemma}\label{unit_bk_proof_lem}
    Suppose that $\pi_k^O(\As)$ is the set of vertices of the unit simplex $\Ds_{k+r}$ (equivalently, all $a_i^{(j)} = 1$). Then the polytope $\conv (\As)$ is a $B_k$-polytope based on some $\R^k_{\ge 0} \subset\R^{k+r}_{\ge 0}$.
\end{lemma}

\begin{proof}

Let us prove that instead of $\pi_k$ we can consider the following coordinate projection $\tl \pi_k$ (with the same $p$) so that the conditions of the Furukawa-Ito Theorem \ref{dual_defect_classification_th} are preserved:


$$\tl \pi_k:
\begin{cases}
 e_0^{(1)}, \dots , e_0^{(j_0)}, e_1^{(2)}, \dots , e_1^{(j_1)} , \dots , e_k^{(2)}, \dots , e_k^{(j_k)} &  \to 0\\
 e_1^{(1)} &  \to q_1\\
 \ \  \ \ \ \ \  \dots  & \dots \\
 e_k^{(1)} &  \to q_k
\end{cases} $$


Note that for any point $x\in \As$, at most one of coordinates $e_\alpha^{(\beta)}, \alpha \ge 1$ can be non-zero, and the non-zero coordinate must be equal to $1$. Denote the sets $\tl \As_i\subset \Z^n/\Z^k$ the same way as $\As_i$ but for projection $\tl \pi_k$. Denote the sets
$$\As_\alpha^{(\beta)} = \{ x \in \As: e_\alpha^{(\beta)} - \text{coordinate of $x$ is $1$} \} / \Z^k \subset \Z^n/\Z^k \quad\text{for } \alpha \ge 1$$

Note that:
\begin{align*}
\As_\alpha &= \bigcup\limits_{\beta = 1}^{j_\alpha} \As_{\alpha}^{(\beta)}, \quad \alpha = 1,\dots k\\
\tl \As_\alpha &= \As_{\alpha}^{(1)}, \quad \alpha = 1,\dots k\\
\tl \As_0 &= \As_0 \cup \bigcup\limits_{\alpha = 1}^{k}  \bigcup\limits_{\beta = 2}^{j_\alpha} 
 \As_{\alpha}^{(\beta)}
\end{align*}

Denote by $E_0$ the lattice spanned by $\{e_0^{(i)}/\Z^k, i = 1,\dots, j_0\}$. Note that $\langle \As_0-\As_0\rangle = E_0$ since $\conv (\As)$ is convenient, and that $\langle\As_\alpha^{(\beta)} - \As_\alpha^{(\beta)} \rangle \subset E_0$ for any $1\le \alpha\le k$ and $1\le \beta\le j_\alpha$. Recall that $p(\As_0) \ast \dots \ast p(\As_k)$ is of join type. So $p (\langle\As_\alpha^{(\beta)} - \As_\alpha^{(\beta)} \rangle) = 0$ for any $1\le \alpha\le k$ and $1\le \beta\le j_\alpha$. Thus $p(\tl \As_0) \ast \dots \ast p(\tl \As_k)$ is also of join type since $p(\tl \As_\alpha) = 0$ for all $\alpha = 1,\dots, k$.
\end{proof}

In what follows, we prove the $B_k$-theorem for arbitrary $a_i^{(j)} \in \Z_{\ge 0}$ by induction on the dimension $n$. 

\begin{proposition}
    Consider the cone $C^{(1)}$ spanned by $\{e_i^{(j)}| a_i^{(j)} = 1\}$. If the polytope $\conv (\As) \cap C^{(1)}$ is negligible in the cone $C^{(1)}$, then $\conv (\As)$ is a $B_k$-polytope.
\end{proposition}

\begin{proof}
    If all the $a_i^{(j)}$ are equal to $1$, then this case is already proved in Lemma \ref{unit_bk_proof_lem}. Otherwise, by the induction hypothesis, the polytope $\conv (\As) \cap C^{(1)}$ is a $B_k$-polytope. Note that (here we essentially use that the corresponding $a_i^{(j)}$ are equal to $1$) the coordinate projection of $\As \setminus C^{(1)}$ to $C^{(1)}$ is only the origin $O$. Then the polytope $\conv(\As)$ is also a $B_k$-polytope (different from  $\conv (\As) \cap C^{(1)}$ only in the first summand). 
\end{proof}

Thus the following proposition implies the $B_k$-theorem.

\begin{proposition}\label{final_bk_prop}
The polytope $\conv (\As) \cap C^{(1)}$ is negligible in the cone $C^{(1)}$.
\end{proposition}


Consider all pairs $i,j$ such that $a_i^{(j)} \ge 2$. Consider any points $D_i^{(j)}$ such that $\pi_k^O ( a_i^{(j)}  e_i^{(j)}) =  \pi_k^O( D_i^{(j)})$ if $i \ne j$; such points exist since $\conv(\As)$ is convenient. Consider the set $\mathbf D = \bigcup_{i,j} D_i^{(j)}\cup  (\As \cap C^{(1)})$ . Note that $\conv (\mathbf D)$ is convenient in the cone $C$ and 
$$\nu_C(\conv(\mathbf D)) = \prod\limits_{(i,j): a_i^{(j)} \ge 2} (a_i^{(j)} - 1) \nu_{C^{(1)}}(\conv(\As) \cap C^{(1)})$$

Recall that the Newton number is monotonous (see Remark \ref{mon_nu_rem}).  Thus, since $\conv (\As)$ is negligible, the convex hull $\conv(\mathbf D)$ is also negligible in $C$, hence $\conv (\As) \cap C^{(1)}$ is negligible in $C^{(1)}$.



