	\section{Preliminaries}
	%
	\label{sec:Preliminaries}
	%
	%\subsection{Scope \& Semidiscretization}
	\subsection{Scope}
	%
	In this work we consider \ac{PDE} systems of the form
	%
	\begin{subequations}
		\label{eq:BalanceLaw}
		\begin{align}
			\boldsymbol u(t_0) &= \boldsymbol u_0 \\
			\label{eq:BalanceLawPDE}
			\partial_t \boldsymbol u(t, \boldsymbol x) + \nabla \cdot \boldsymbol f\big(\boldsymbol u, \nabla \boldsymbol u\big) 
			+ \boldsymbol g(\boldsymbol u, \nabla \boldsymbol u)
			&= 
			%\boldsymbol 0
			\boldsymbol s\big(t, \boldsymbol x; \boldsymbol u \big)
			, \quad t \in \big [t_0, t_f \big ], \: \boldsymbol x \in \Omega \subset \mathbb R^{d}
		\end{align}
	\end{subequations}
	%
	where $\boldsymbol u \in \mathbb R^V$ denotes the vector of conserved variables and $\boldsymbol f \in \mathbb R^{V \times d}$ is a flux function which may contain diffusive terms.
	Nonconservative terms are collected in $\boldsymbol g$ and $\boldsymbol s$ is a source term.
	The classic theory of entropy conservation evolved around hypebolic conservation laws, i.e., system \eqref{eq:BalanceLaw} with $\boldsymbol f = \boldsymbol f(\boldsymbol u)$, $\boldsymbol g = \boldsymbol s = \boldsymbol 0$.
	Examples for entropy conservation problems with non-conservative terms, i.e., $\boldsymbol g \neq \boldsymbol 0$ are the shallow water equations \cite{GASSNER2016291} or the coupled Burgers equation \cite{castro2013entropy}.
	In the presence of viscous terms, i.e., $\boldsymbol f = \boldsymbol f(\boldsymbol u, \nabla \boldsymbol u)$ entropy is not conserved, but expected to decay monotonically/stable, assuming suitable boundary conditions.

	Here, we employ the \ac{DGSEM} \cite{hesthaven2007nodal, black1999conservative, kopriva2009implementing} to obtain the semidiscretization	of \eqref{eq:BalanceLaw}:
	%
	\begin{subequations}
		\label{eq:Semidiscretization}
		\begin{align}
			\boldsymbol U(t_0) &= \boldsymbol U_0 \\
			\label{eq:SemidiscretizationODE}
			\boldsymbol U'(t) &= \boldsymbol F\big(t, \boldsymbol U(t) \big), \quad \boldsymbol U \in \mathbb R^M \: .
		\end{align}
	\end{subequations}
	%
	The $M$ unknowns of \cref{eq:Semidiscretization} are the nodal \ac{DG} solution polynomial coefficients.
	Throughout this work we mainly consider convection-dominated problems, i.e., configurations for which the spectral radius $\rho_{\boldsymbol F}$ of the Jacobian of the fully discrete system \cref{eq:SemidiscretizationODE} $J_{\boldsymbol F}(\boldsymbol U) \coloneqq \pd{\boldsymbol F}{\boldsymbol U}$ scales as 
	%
	\begin{equation}
		\label{eq:Convection_Diffusion_Scaling}
		\rho \sim \frac{\vert a \vert}{h} \gg \frac{\vert d \vert}{h^2} \: ,
	\end{equation}
	%
	where $h$ denotes the smallest characteristic size of a grid cell, which is for the quadrilaterals and hexahedra considered in this work estimated based on the minimal distance between corner nodes.
	In \cref{eq:Convection_Diffusion_Scaling} $a, d$ are suitable quantifiers for the influence of convection and diffusion, respectively.
	%While this assumption is not strictly necessary for the overall applicability of the \ac{PERRK} schemes, it is necessary to render the optimized explicit schemes computationally efficient.
	%
	\subsection{Paired Explicit Runge-Kutta Methods}
	\label{subsec:PERKMs}
	%
	\ac{PERK} methods have been developed in \cite{vermeire2019paired} and consecutively extended to third- \cite{nasab2022third} and fourth-order \cite{doehring2024fourth} of consistency.
	Furthermore, an embedded scheme based on the second-order method has been proposed in \cite{vermeire2023embedded} which enables error-based timestep control.

	The central idea of the \ac{PERK} methods is to pair Runge-Kutta schemes with different domains of stability and computational cost in an efficient way.
	These schemes belong to the class of \acp{PRKM} \cite{rentrop1985partitioned, bruder1988partitioned, gunther2001multirate} and are naturally applicable to semidiscretizations \eqref{eq:Semidiscretization} which may be partitioned according to different characteristic timescales:
	%
	\begin{subequations}
		\label{eq:PartitionedODESys}
		\begin{align}
			\def\arraystretch{1.4}
			\boldsymbol U(t_0) &= \boldsymbol U_0, \\
			\label{eq:PartitionedODESys2}
			\boldsymbol U'(t) &= \begin{pmatrix} \boldsymbol U^{(1)}(t) \\ \vdots \\ \boldsymbol U^{(R)}(t) \end{pmatrix}' = \begin{pmatrix} \boldsymbol F^{(1)}\big(t, \boldsymbol U^{(1)}(t), \dots,  \boldsymbol U^{(R)}(t) \big) \\ \vdots \\ \boldsymbol F^{(R)}\big(t, \boldsymbol U^{(1)}(t), \dots, \boldsymbol U^{(R)}(t) \big) \end{pmatrix} = \boldsymbol F\big(t, \boldsymbol U(t) \big) \: .
		\end{align}
	\end{subequations}
	%
	Here, $R$ denotes the number of \textit{partitions/levels}.
	Based on the local characteristic speed 
	%
	\begin{equation}
		\label{eq:CharSpeed_DG}
		\nu(\boldsymbol x_m) \sim \max_{i = 1, \dots, d}\frac{(k+1) \cdot \rho_i(\boldsymbol x_m)}{h(\boldsymbol x_m)} > 0, \quad m = 1, \dots, M
	\end{equation}
	%
	the unknowns $\left \{ U_m \right \}_{m=1, \dots, M}$ are assigned to different partitions $r = 1, \dots, R$ which are integrated with different schemes.
	In \eqref{eq:CharSpeed_DG} $d$ denotes the number of spatial dimensions, $h$ is a measure for the smallest characteristic cell size,
	%in $i$-direction, 
	$k$ is the \ac{DG} solution polynomial degree, and $\rho_i$ is the spectral radius of the Jacobian of the directional flux $\boldsymbol f_i$:
	%
	\begin{equation}
		\label{eq:DirectionalFluxJacobian}
		J_i \coloneqq \pd{\boldsymbol f_i}{\boldsymbol u}
	\end{equation}
	%
	cf. \eqref{eq:BalanceLawPDE}.

	In the following, the superscript $(\cdot)^{(r)}$ denotes quantities corresponding to the $r$'th partition.
	These may be a subset of unknowns $\boldsymbol U^{(r)} \in \mathbb R^{M_r}$, or a method used for solving the corresponding system with \ac{RHS} $\boldsymbol F^{(r)}$.
	Note that for the sake of readability we oftentimes pad the vectors $\boldsymbol U^{(r)}, \boldsymbol K^{(r)} \in \mathbb R^{M^{(r)}}$ with zeros to match the dimensionality $\mathbb R^M$ of the full system \eqref{eq:Semidiscretization}.
	Evaluations of the corresponding \ac{RHS} $\boldsymbol F^{(r)}$ are, however, only performed on the actual index set $M^{(r)}$ with property $\cup_{r=1}^R M^{(r)} = M$.
	\ac{ODE} systems of the form \eqref{eq:PartitionedODESys} encourage the use of \acp{PRKM}, which, in Butcher form, are given by \cite[Chapter~II.15]{HairerWanner1}
	%
	\begin{subequations}
		\label{eq:PartitionedRKSystem}
		\begin{align}
			\label{eq:PartitionedRKFirstEq}
			\boldsymbol U_0 &= \boldsymbol U(t_0) \: , \\
			\label{eq:PartitionedRKSecondEq}
			\boldsymbol K_i^{(r) } &= \boldsymbol F^{(r) }\Biggl( \underbrace{t_n + c_i^{(r) } \Delta t}_{\eqqcolon t_{n,i}}, \underbrace{\boldsymbol U_n + \Delta t \sum_{j=1}^S \sum_{k=1}^R  a_{i,j}^{(k) } \boldsymbol K_j^{(k) }}_{\eqqcolon \boldsymbol U_{n,i}} \Biggr), \quad i = 1, \dots, S; \: \: r = 1, \dots, R \\
			\label{eq:PartitionedRKUpdateStep}
			\boldsymbol U_{n+1} & = \boldsymbol U_n + \Delta t  \sum_{i=1}^S  \sum_{r=1}^R   b_i^{(r) }  \boldsymbol K_i^{(r)} \: ,
		\end{align}
	\end{subequations}
	%
	where $S$ denotes the number of stages $\boldsymbol K_i \in \mathbb R^M$.

	When integrating \eqref{eq:Semidiscretization} with an explicit method, the maximum linearly stable timestep is restricted by some form of the \ac{CFL} condition:
	%
	\begin{equation}
		\label{eq:TimestepConstraintGlobal}
		\Delta t \overset{!}{\leq} \text{CFL} \cdot \min_{\boldsymbol x \in \Omega} \frac{1}{\nu (\boldsymbol x)} \: .
	\end{equation}
	%
	In contrast to local time-stepping methods \cite{berger1984adaptive, dawson2001high, lorcher2007discontinuous, dumbser2007arbitrary, krivodonova2010efficient, grote2015runge, luther2024adaptive},
	which reduce the timestep $\Delta t$ in regions with high characteristic speeds $\nu(\boldsymbol x)$ \eqref{eq:CharSpeed_DG}, \ac{PERK} schemes increase the $\text{CFL}$ stability bound locally to avoid reduction in the global timestep $\Delta t$:
	%
	\begin{equation}
		\label{eq:TimestepConstraintLocal}
		\Delta t = \text{CFL}^{(r)} \cdot \frac{1}{\nu^{(r)}} \, , \quad \forall \: r = 1, \dots, R \: .
	\end{equation}
	%
	This is achieved by optimizing the stability polynomials of the composing schemes $\left (A^{(r)}, b^{(r)} \right )$ to achieve larger $\text{CFL}^{(r)}$.
	In particular, equipped with the spectrum $\boldsymbol \sigma$ of the Jacobian of the fully-discrete system \eqref{eq:Semidiscretization} $J_{\boldsymbol F}$ the stability polynomials $P^{(r)}(z)$ can be optimized to yield the maximum timestep $\Delta t$ for this particular spectrum $\boldsymbol \sigma(J_{\boldsymbol F})$ \cite{ketcheson2013optimal, doehring2024manystage}.
	The key insight here is that the number of free coefficients of the $P^{(r)}(z)$ stability polynomial is equal to $E^{(r)} - p$, where $E^{(r)}$ denotes the number of stage \textit{evaluations} of the $r\text{-th}$ scheme and $p$ is the order of the method.
	Thus, computationally demanding methods with a higher number of stage evaluations $E^{(r)}$ \textit{and} larger domain of stability are applied in regions with higher characteristic speeds $\nu^{(r)}$, while less expensive methods with a smaller domain of stability are used in regions with lower characteristic speeds $\nu^{(r)}$.
	This concept is schematically illustrated in \cref{fig:ExampleMesh_StabDomains}.
	Standard, i.e., non-reducible \cite[Chapter~IV.12]{HairerWanner2} Runge-Kutta methods have $E = E^{(1)}= S$ stage evaluations, i.e., every stage present in e.g. the Butcher tableau is actually computed and utilized in the final update step or for the computation of subsequent stages.
